}

public void onLivingDeath(LivingDeathEvent event) {
	if (event.getEntity() instanceof Player && !event.getEntity().level().isClientSide) {
		Player player = (Player) event.getEntity();

		if (SuperpositionHandler.isTheBlessedOne(player)) {
			ItemStack scroll = SuperpositionHandler.getCurioStack(player, this);

			if (scroll != null && !this.hasCooldown(scroll)) {
				event.setCanceled(true);
				player.setHealth(player.getMaxHealth() / 2);

				player.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 1200, 2));
				player.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 1200, 1));
				player.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 1200, 0));
				player.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 1200, 1));

				this.setCooldown(scroll, deathProtectionCooldown.getValue() * 20);

				EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() ->
				new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128,
						player.level().dimension())), new PacketCosmicRevive(player.getId(), 0));
			}
		}
	}
}

public void curioTick(SlotContext context, ItemStack stack) {
	if (context.entity() instanceof ServerPlayer player && player.tickCount % 5 == 0
			&& SuperpositionHandler.isTheWorthyOne(player)) {
		List<LivingEntity> entities = SuperpositionHandler.getObservedEntities(player, player.level(), 3, 128, false);
		for (LivingEntity entity : entities) {
			if (entity instanceof ServerPlayer otherPlayer && SuperpositionHandler.hasCurio(otherPlayer, this)
					&& SuperpositionHandler.isTheWorthyOne(otherPlayer)) {
				continue;
			}

			entity.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, 10, 1));
			entity.addEffect(new MobEffectInstance(MobEffects.DIG_SLOWDOWN, 10, 1));
			entity.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 10, 1));
		}
	}
}

public InteractionResultHolder<ItemStack> use(Level world, Player player, InteractionHand hand) {
	ItemStack stack = player.getItemInHand(hand);

	if (hand == InteractionHand.MAIN_HAND) {
		ItemStack offhandStack = player.getOffhandItem();

		if (offhandStack.getItem().getUseAnimation(offhandStack) == UseAnim.BLOCK)
			return InteractionResultHolder.pass(stack);
	}

	if (SuperpositionHandler.isTheCursedOne(player)) {
		player.startUsingItem(hand);
		return InteractionResultHolder.consume(stack);
	} else
		return InteractionResultHolder.pass(stack);
}

public void onPlayerTick(TickEvent.PlayerTickEvent event) {
	if (event.phase == Phase.START) {
		ItemStack stack = null;
		AttributeInstance attribute = event.player.getAttribute(CaelusApi.getInstance().getFlightAttribute());
		attribute.removeModifier(ELYTRA_MODIFIER);

		if (!attribute.hasModifier(ELYTRA_MODIFIER)) {
			stack = SuperpositionHandler.getEnigmaticElytra(event.player);
			if (stack != null && stack.is(this) && ElytraItem.isFlyEnabled(stack)) {
				attribute.addTransientModifier(ELYTRA_MODIFIER);
			}
		}

		if (event.player instanceof ServerPlayer player)
			if (TransientPlayerData.get(player).isElytraBoosting()) {
				this.boostPlayer(player);

				if (stack != null && stack.is(this)) {
					int flightTicks = player.getFallFlyingTicks();
					int nextFlightTick = flightTicks + 1;
					if (nextFlightTick % 5 == 0) {
						stack.hurtAndBreak(1, player, e -> e.broadcastBreakEvent(EquipmentSlot.CHEST));
					}
				}
			}
	}
}

public void curioTick(SlotContext context, ItemStack stack) {
	if (context.entity().isOnFire()) {
		context.entity().clearFire();
	}

	List<MobEffectInstance> effects = new ArrayList<MobEffectInstance>(context.entity().getActiveEffects());

	for (MobEffectInstance effect : effects) {
		if (ForgeRegistries.MOB_EFFECTS.getKey(effect.getEffect()).equals(new ResourceLocation("mana-and-artifice", "chrono-exhaustion"))) {
			continue;
		}

		if (!effect.getEffect().isBeneficial()) {
			context.entity().removeEffect(effect.getEffect());
		}
	}

}

public void onUnequip(SlotContext context, ItemStack newStack, ItemStack stack) {
	if (context.entity() instanceof ServerPlayer player) {
		AttributeMap map = player.getAttributes();
		map.removeAttributeModifiers(this.attributesDefault);
		map.removeAttributeModifiers(this.attributesNoArmor);
	}
}

public void curioTick(SlotContext context, ItemStack stack) {
	if (context.entity() instanceof ServerPlayer player) {
		AttributeMap map = player.getAttributes();

		if (SuperpositionHandler.hasAnyArmor(player)) {
			// Removes attributes
			map.removeAttributeModifiers(this.attributesDefault);
			map.removeAttributeModifiers(this.attributesNoArmor);

			// Applies new attributes
			map.addTransientAttributeModifiers(this.attributesDefault);
		} else {
			// Removes attributes
			map.removeAttributeModifiers(this.attributesDefault);
			map.removeAttributeModifiers(this.attributesNoArmor);

			// Applies new attributes
			map.addTransientAttributeModifiers(this.attributesNoArmor);
		}

	}
}

public void inventoryTick(ItemStack stack, Level world, Entity entity, int itemSlot, boolean isSelected) {
	if (entity instanceof Player && !world.isClientSide) {
		Player player = (Player) entity;
		List<Monster> genericMobs = player.level().getEntitiesOfClass(Monster.class, SuperpositionHandler.getBoundingBoxAroundEntity(player, abilityRange.getValue()));

		if (SuperpositionHandler.isTheCursedOne(player) && Inventory.isHotbarSlot(itemSlot) && !player.getCooldowns().isOnCooldown(this)) {
			Monster oneWatched = null;

			for (Monster monster : genericMobs) {
				if (SuperpositionHandler.doesObserveEntity(player, monster) && !this.isExcluded(monster)) {
					oneWatched = monster;
					break;
				}
			}

			//System.out.println("The One: " + oneWatched);

			if (oneWatched != null && oneWatched.isAlive()) {
				final Monster theOne = oneWatched;
				Vector3 vec = Vector3.fromEntityCenter(theOne);
				List<Monster> surroundingMobs = player.level().getEntitiesOfClass(Monster.class, SuperpositionHandler.getBoundingBoxAroundEntity(theOne, enrageRange.getValue()), (living) -> { return living.isAlive() && theOne.hasLineOfSight(living); });
				Monster closestMonster = SuperpositionHandler.getClosestEntity(surroundingMobs, (monster) -> monster != theOne, vec.x, vec.y, vec.z);

				//System.out.println("Closest monster: " + closestMonster);

				if (closestMonster != null) {
					this.setAttackTarget(theOne, closestMonster);
					theOne.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 300, 0, false, true));
					theOne.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 300, 1, false, false));
					theOne.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 300, 1, false, false));
					//theOne.addPotionEffect(new MobEffectInstance(MobEffects., 400, 1, false, true));

					for (Monster otherMonster : surroundingMobs) {
						this.setAttackTarget(otherMonster, theOne);
					}

					player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.ELDER_GUARDIAN_CURSE, SoundSource.HOSTILE, 1.0F, 1.0F);

					if (player instanceof ServerPlayer) {
						ServerPlayer serverPlayer = (ServerPlayer) player;
						EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(theOne.getX(), theOne.getY(), theOne.getZ(), 64, theOne.level().dimension())), new PacketGenericParticleEffect(theOne.getX(), theOne.getEyeY(), theOne.getZ(), 0, false, Effect.GUARDIAN_CURSE));
					}

					player.getCooldowns().addCooldown(this, abilityCooldown.getValue());
				}
			}

		}

		for (Monster monster : genericMobs) {
			if (monster instanceof Guardian && monster.getClass() != ElderGuardian.class) {
				final Guardian guardian = (Guardian) monster;

				if (guardian.getTarget() == null) {
					List<Monster> surroundingMobs = player.level().getEntitiesOfClass(Monster.class, SuperpositionHandler.getBoundingBoxAroundEntity(guardian, 12), (living) -> { return living.isAlive() && guardian.hasLineOfSight(living); });
					Monster closestMonster = SuperpositionHandler.getClosestEntity(surroundingMobs, (checked) -> { return !(checked instanceof Guardian); }, guardian.getX(), guardian.getY(), guardian.getZ());

					if (closestMonster != null) {
						this.setAttackTarget(guardian, closestMonster);
					}
				}
			}
		}

	}
}

protected void handleFlight(Player player, boolean inRangeCheckedAndSucceeded) {
	//don't check in range every tick as it is expensive. Particularly for multiple people.
	//instead, check once per second, based on the player's tick count
	//If we're here from fabulous scroll, we automatically know we can skip this
	if (player.tickCount % 20 != 0)
		return;

	try {
		if (this.canFly(player, inRangeCheckedAndSucceeded)) {
			player.getAbilities().mayfly = true;
			//since we're only updating once per 20 ticks, we can leave this here as we won't be spamming update packets
			player.onUpdateAbilities();
			//reduced from 100 down to 5, as we now only run this code once per second.
			this.flyMap.put(player, 5);

		} else if (this.flyMap.get(player) > 1) {
			this.flyMap.put(player, this.flyMap.get(player)-1);
		} else if (this.flyMap.get(player) == 1) {
			if (!player.isCreative()) {
				player.getAbilities().mayfly = false;
				player.getAbilities().flying = false;
				player.onUpdateAbilities();
				player.addEffect(new MobEffectInstance(MobEffects.SLOW_FALLING, 200, 0, true, false));
			}

			this.flyMap.put(player, 0);
		}

	} catch (NullPointerException ex) {
		ex.printStackTrace();
		this.flyMap.put(player, 0);
	}
}

public void curioTick(SlotContext context, ItemStack stack) {
	if (context.entity() instanceof Player player && !player.level().isClientSide) {
		if (!player.getCooldowns().isOnCooldown(this)) {
			List<BlockPos> doomedWaterBlocks = new ArrayList<BlockPos>();
			BlockPos initialPos = this.getCollidedWater(FluidTags.WATER, player);
			BlockState initialState = initialPos != null ? player.level().getBlockState(initialPos) : null;

			if (initialPos != null && initialState != null)
				if (initialState.getFluidState() != null && initialState.getFluidState().is(FluidTags.WATER)) {

					doomedWaterBlocks.add(initialPos);
					List<BlockPos> processedBlocks = new ArrayList<BlockPos>();
					processedBlocks.add(initialPos);

					for (int counter = 0; counter <= radius.getValue(); counter++) {
						List<BlockPos> outputBlocks = new ArrayList<BlockPos>();

						for (BlockPos checkedPos : processedBlocks) {
							outputBlocks.addAll(this.getNearbyWater(player.level(), checkedPos));
						}

						processedBlocks.clear();

						for (BlockPos thePos : outputBlocks) {
							if (!doomedWaterBlocks.contains(thePos)) {
								processedBlocks.add(thePos);
								doomedWaterBlocks.add(thePos);
							}
						}

						outputBlocks.clear();
					}

					processedBlocks.clear();

					for (BlockPos exterminatedBlock : doomedWaterBlocks) {
						this.absorbWaterBlock(exterminatedBlock, player.level().getBlockState(exterminatedBlock), player.level());
					}

					doomedWaterBlocks.clear();

					player.level().playSound(null, player.blockPosition(), SoundEvents.BUCKET_FILL, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2)));
					EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 64, player.level().dimension())), new PacketPortalParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 40, 1.0D, false));
					player.getCooldowns().addCooldown(this, 20);

				}
		}
	}
}

public void removeNightVisionEffect(Player player, int duration) {
	if (player.getEffect(MobEffects.NIGHT_VISION) != null) {
		MobEffectInstance effect = player.getEffect(MobEffects.NIGHT_VISION);

		if (effect.getDuration() <= (duration - 1)) {
			player.removeEffect(MobEffects.NIGHT_VISION);
		}
	}
}

