	if (context.entity() instanceof Player player && !context.entity().level().isClientSide)
		if (SuperpositionHandler.hasCurio(player, EnigmaticItems.MINING_CHARM)) {
			if (ItemNBTHelper.getBoolean(stack, "nightVisionEnabled", true)) {
				if (enableNightVision.getValue()) {
					if (player.getY() < 50 && !player.level().dimension().equals(Level.NETHER)
							&& !player.level().dimension().equals(Level.END)
							&& !player.isEyeInFluid(FluidTags.WATER)
							&& !player.level().canSeeSkyFromBelowWater(player.blockPosition())
							/*&& player.level.getMaxLocalRawBrightness(player.blockPosition(), 0) <= 8*/) {

						EnigmaticEventHandler.isApplyingNightVision = true;
						player.addEffect(new MobEffectInstance(MobEffects.NIGHT_VISION, this.nightVisionDuration, 0, true, false));
						EnigmaticEventHandler.isApplyingNightVision = false;
					} else {
						//this.removeNightVisionEffect(player, this.nightVisionDuration);
					}
				} else {
					ItemNBTHelper.setBoolean(stack, "nightVisionEnabled", false);
				}
			}
		}
}

public void onUnequip(SlotContext context, ItemStack newStack, ItemStack stack) {
	if (context.entity() instanceof ServerPlayer player) {
		EnigmaticItems.MINING_CHARM.removeNightVisionEffect(player, this.nightVisionDuration);
		player.getAttributes().removeAttributeModifiers(this.createAttributeMap(player));
	}
}

public void curioTick(SlotContext context, ItemStack stack) {
	if (context.entity() instanceof ServerPlayer player)
		if (SuperpositionHandler.hasCurio(player, EnigmaticItems.OCEAN_STONE)) {
			if (player.isEyeInFluid(FluidTags.WATER)) {
				EnigmaticEventHandler.isApplyingNightVision = true;
				player.addEffect(new MobEffectInstance(MobEffects.NIGHT_VISION, this.nightVisionDuration, 0, true, false));
				EnigmaticEventHandler.isApplyingNightVision = false;
				player.setAirSupply(300);
			} else {
				EnigmaticItems.MINING_CHARM.removeNightVisionEffect(player, this.nightVisionDuration);
			}

			player.getAttributes().addTransientAttributeModifiers(this.createAttributeMap(player));
		}
}

public InteractionResultHolder<ItemStack> use(Level world, Player player, InteractionHand hand) {
	ItemStack stack = player.getItemInHand(hand);
	player.startUsingItem(hand);

	if (!RevelationTome.havePlayerRead(player, stack)) {
		RevelationTome.markRead(player, stack);

		int xp = ItemNBTHelper.getInt(stack, RevelationTome.xpPointsTag, random.nextInt(1000));
		int revelation = ItemNBTHelper.getInt(stack, RevelationTome.revelationPointsTag, 1);

		if (player instanceof ServerPlayer) {
			int currentPoints = SuperpositionHandler.getPersistentInteger(player, this.persistantPointsTag, 0);

			ExperienceHelper.addPlayerXP(player, xp);
			SuperpositionHandler.setPersistentInteger(player, this.persistantPointsTag, currentPoints + revelation);

			world.playSound(null, BlockPos.containing(player.position()), EnigmaticSounds.LEARN, SoundSource.PLAYERS, 0.75f, 1.0f);
			RevelationGainTrigger.INSTANCE.trigger((ServerPlayer) player, this.theType, currentPoints + revelation);
			RevelationGainTrigger.INSTANCE.trigger((ServerPlayer) player, TomeType.GENERIC, RevelationTome.getGenericPoints(player));
		} else {
			EnigmaticLegacy.PROXY.pushRevelationToast(stack, xp, revelation);
		}

		player.swing(hand);
		return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);
	}

	return new InteractionResultHolder<>(InteractionResult.PASS, stack);

}

public void updatePlayerSoulMap(Player player) {
	Multimap<Attribute, AttributeModifier> soulMap = this.getOrCreateSoulMap(player);
	AttributeMap attributeManager = player.getAttributes();

	// Removes former attributes
	attributeManager.removeAttributeModifiers(soulMap);

	soulMap.clear();

	int lostFragments = SuperpositionHandler.getPersistentInteger(player, "enigmaticlegacy.lostsoulfragments", 0);

	if (lostFragments > 0) {
		soulMap.put(Attributes.MAX_HEALTH, new AttributeModifier(UUID.fromString("66a2aa2d-7e3c-4af4-882f-bd2b2ded8e7b"), "Lost Soul Health Modifier", -0.1F * lostFragments, AttributeModifier.Operation.MULTIPLY_TOTAL));
	}

	// Applies new attributes
	attributeManager.addTransientAttributeModifiers(soulMap);

	this.attributeDispatcher.put(player, soulMap);
}

public boolean hurtEnemy(ItemStack stack, LivingEntity target, LivingEntity attacker) {
	if (attacker instanceof ServerPlayer player && SuperpositionHandler.isTheWorthyOne(player)) {
		target.addEffect(new MobEffectInstance(MobEffects.WITHER,            160, 3, false, true));
		target.addEffect(new MobEffectInstance(MobEffects.CONFUSION,         500, 3, false, true));
		target.addEffect(new MobEffectInstance(MobEffects.WEAKNESS,          300, 3, false, true));
		target.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, 300, 3, false, true));
		target.addEffect(new MobEffectInstance(MobEffects.DIG_SLOWDOWN,      300, 3, false, true));
		target.addEffect(new MobEffectInstance(MobEffects.BLINDNESS,         100, 3, false, true));
	}

	return false;
}

public InteractionResultHolder<ItemStack> use(Level world, Player player, InteractionHand hand) {
	if (EnigmaticLegacy.PROXY.isInVanillaDimension(player) && SuperpositionHandler.isTheCursedOne(player) && !player.getCooldowns().isOnCooldown(this)) {
		player.startUsingItem(hand);

		if (player instanceof ServerPlayer) {
			SuperpositionHandler.backToSpawn((ServerPlayer) player);
			player.getCooldowns().addCooldown(this, 200);
		}

		return new InteractionResultHolder<>(InteractionResult.SUCCESS, player.getItemInHand(hand));
	} else
		return new InteractionResultHolder<>(InteractionResult.PASS, player.getItemInHand(hand));
}

public ItemStack finishUsingItem(ItemStack stack, Level worldIn, LivingEntity entityLiving) {
	if (!(entityLiving instanceof Player))
		return stack;

	Player player = (Player) entityLiving;

	if (!worldIn.isClientSide) {
		boolean isTheWorthyOne = SuperpositionHandler.isTheCursedOne(player) && EnigmaticItems.FORBIDDEN_FRUIT.haveConsumedFruit(player);

		if (!isTheWorthyOne) {
			player.addEffect(new MobEffectInstance(MobEffects.WITHER, 100, 2, false, true));
			player.addEffect(new MobEffectInstance(MobEffects.POISON, 160, 1, false, true));
			player.addEffect(new MobEffectInstance(MobEffects.CONFUSION, 240, 0, false, true));
			player.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 200, 1, false, true));
			player.addEffect(new MobEffectInstance(MobEffects.HUNGER, 160, 2, false, true));
			player.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, 240, 0, false, true));

			UseUnholyGrailTrigger.INSTANCE.trigger((ServerPlayer) player, false);
		} else {
			player.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 1000 / 2, 2, false, true));
			player.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, 1600 / 2, 1, false, true));
			player.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 2400 / 2, 1, false, true));
			player.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 2000 / 2, 1, false, true));
			player.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED, 2400 / 2, 0, false, true));
			//player.addEffect(new MobEffectInstance(MobEffects.HEAL, 1, 0, false, true));

			UseUnholyGrailTrigger.INSTANCE.trigger((ServerPlayer) player, true);
		}
	}

	player.awardStat(Stats.ITEM_USED.get(this));

	return stack;
}

public void curioTick(SlotContext context, ItemStack stack) {
	if (context.entity() instanceof Player player) {
		/*
		FoodData stats = player.getFoodStats();
		stats.setFoodLevel(20);

		//((AccessorFoodStats) stats).setFoodSaturationLevel(0);


		try {
			ObfuscatedFields.foodSaturationField.setFloat(stats, 0F);
		} catch (Exception ex) {
			ex.printStackTrace();
		}

		 */

		if (player.getAirSupply() < 300) {
			player.setAirSupply(300);
		}

		if (player.isOnFire()) {
			player.clearFire();
		}

		for (MobEffectInstance effect : new ArrayList<>(player.getActiveEffects())) {
			if (effect.getEffect() == MobEffects.NIGHT_VISION) {
				if (effect.getDuration() >= EnigmaticItems.MINING_CHARM.nightVisionDuration-10 && effect.getDuration() <= EnigmaticItems.MINING_CHARM.nightVisionDuration) {
					continue;
				}
			} else if (ForgeRegistries.MOB_EFFECTS.getKey(effect.getEffect()).equals(new ResourceLocation("mana-and-artifice", "chrono-exhaustion"))) {
				continue;
			}

			player.removeEffect(effect.getEffect());
		}

		if (player.tickCount % 10 == 0) {
			List<LivingEntity> entities = player.level().getEntitiesOfClass(LivingEntity.class, new AABB(player.getX() - shadowRange.getValue(), player.getY() - shadowRange.getValue(), player.getZ() - shadowRange.getValue(), player.getX() + shadowRange.getValue(), player.getY() + shadowRange.getValue(), player.getZ() + shadowRange.getValue()));
			boolean hasAnimalGuide = SuperpositionHandler.hasItem(player, EnigmaticItems.ANIMAL_GUIDEBOOK);

			if (entities.contains(player)) {
				entities.remove(player);
			}

			for (LivingEntity victim : entities) {
				if (victim.level().getMaxLocalRawBrightness(victim.blockPosition(), 0) < 3 || (victim instanceof Phantom && !victim.isOnFire())) {
					if (hasAnimalGuide && EnigmaticItems.ANIMAL_GUIDEBOOK.isProtectedAnimal(victim)) {
						continue;
					}

					if (victim instanceof Player) {
						Player playerVictim = (Player) victim;
						if (SuperpositionHandler.hasCurio(playerVictim, EnigmaticItems.VOID_PEARL)) {
							playerVictim.addEffect(new MobEffectInstance(MobEffects.WITHER, 80, 1, false, true));
							continue;
						}
					}

					if (!(victim instanceof Player) || player.canHarmPlayer((Player) victim)) {
						boolean attack = victim.hurt(victim.damageSources().source(EnigmaticDamageTypes.DARKNESS, player), (float) baseDarknessDamage.getValue());

						if (attack) {
							player.level().playSound(null, victim.blockPosition(), SoundEvents.PHANTOM_BITE, SoundSource.PLAYERS, 1.0F, (float) (0.3F + (Math.random() * 0.4D)));

							victim.addEffect(new MobEffectInstance(MobEffects.WITHER, 80, 1, false, true));
							victim.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, 100, 2, false, true));
							victim.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 100, 0, false, true));
							victim.addEffect(new MobEffectInstance(MobEffects.HUNGER, 160, 2, false, true));
							victim.addEffect(new MobEffectInstance(MobEffects.DIG_SLOWDOWN, 100, 3, false, true));
						}
					}
				}
			}
		}
	}

}

public InteractionResultHolder<ItemStack> use(Level world, Player player, InteractionHand hand) {
	ItemStack stack = player.getItemInHand(hand);

	if (hand == InteractionHand.OFF_HAND || player.getOffhandItem().getUseAnimation() == UseAnim.BLOCK)
		return new InteractionResultHolder<>(InteractionResult.PASS, player.getItemInHand(hand));

	if (player.isCrouching()) {
		this.toggleAreaEffects(player, stack);

		return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);
	} else if (!player.level().isClientSide) {
		if (!player.getCooldowns().isOnCooldown(this) && this.areaEffectsEnabled(player, stack)) {
			Vector3 look = new Vector3(player.getLookAngle());
			Vector3 dir = look.multiply(1D);

			this.getConfig().knockBack(player, 1.0F, dir.x, dir.z);
			world.playSound(null, player.blockPosition(), SoundEvents.SKELETON_SHOOT, SoundSource.PLAYERS, 1.0F, (float) (0.6F + (Math.random() * 0.1D)));

			player.getCooldowns().addCooldown(this, this.getConfig().getSwordCooldown());

			player.startUsingItem(hand);
			return new InteractionResultHolder<>(InteractionResult.SUCCESS, player.getItemInHand(hand));
		}
	}

	player.startUsingItem(hand);
	return new InteractionResultHolder<>(InteractionResult.PASS, player.getItemInHand(hand));
}

public void onUseTick(Level worldIn, LivingEntity livingEntityIn, ItemStack stack, int count) {
    if(isUsable(stack)) {
        if (count % 2 == 0) {
            boolean left = false;
            if (livingEntityIn.getUsedItemHand() == InteractionHand.OFF_HAND && livingEntityIn.getMainArm() == HumanoidArm.RIGHT || livingEntityIn.getUsedItemHand() == InteractionHand.MAIN_HAND && livingEntityIn.getMainArm() == HumanoidArm.LEFT) {
                left = true;
            }
            EntityMosquitoSpit blood = new EntityMosquitoSpit(worldIn, livingEntityIn, !left);
            Vec3 vector3d = livingEntityIn.getViewVector(1.0F);
            RandomSource rand = worldIn.getRandom();
            livingEntityIn.gameEvent(GameEvent.ITEM_INTERACT_START);
            livingEntityIn.playSound(SoundEvents.LAVA_POP,1.0F, 1.2F + (rand.nextFloat() - rand.nextFloat()) * 0.2F);
            blood.shoot((double) vector3d.x(), (double) vector3d.y(), (double) vector3d.z(), 1F, 10);
            if (!worldIn.isClientSide) {
                worldIn.addFreshEntity(blood);
            }
            stack.hurtAndBreak(1, livingEntityIn, (player) -> {
                player.broadcastBreakEvent(livingEntityIn.getUsedItemHand());
            });
        }
    }else{
        if(livingEntityIn instanceof Player){
            ItemStack ammo = findAmmo((Player)livingEntityIn);
            boolean flag = ((Player) livingEntityIn).isCreative();
            if(!ammo.isEmpty()){
                ammo.shrink(1);
                flag = true;
            }
            if(flag){
                ((Player) livingEntityIn).getCooldowns().addCooldown(this, 20);
                stack.setDamageValue(0);
            }
            livingEntityIn.stopUsingItem();
        }
    }
}

public InteractionResultHolder<ItemStack> use(Level worldIn, Player playerIn, InteractionHand handIn) {
    ItemStack itemstack = playerIn.getItemInHand(handIn);
    if (itemstack.getDamageValue() >= itemstack.getMaxDamage()) {
        return InteractionResultHolder.fail(itemstack);
    } else {
        playerIn.startUsingItem(handIn);
        HitResult raytraceresult = rayTracePortal(worldIn, playerIn, ClipContext.Fluid.ANY);
        Direction dir = Direction.orderedByNearest(playerIn)[0];

        double x = raytraceresult.getLocation().x - dir.getNormal().getX() * 0.1F;
        double y = raytraceresult.getLocation().y - dir.getNormal().getY() * 0.1F;
        double z = raytraceresult.getLocation().z - dir.getNormal().getZ() * 0.1F;
        if (itemstack.getOrCreateTag().getBoolean("HASBLOCK")) {
            x = itemstack.getOrCreateTag().getDouble("BLOCKX");
            y = itemstack.getOrCreateTag().getDouble("BLOCKY");
            z = itemstack.getOrCreateTag().getDouble("BLOCKZ");
        } else {
            itemstack.getOrCreateTag().putBoolean("HASBLOCK", true);
            itemstack.getOrCreateTag().putDouble("BLOCKX", x);
            itemstack.getOrCreateTag().putDouble("BLOCKY", y);
            itemstack.getOrCreateTag().putDouble("BLOCKZ", z);
            itemstack.setTag(itemstack.getOrCreateTag());
        }
        worldIn.addParticle(AMParticleRegistry.INVERT_DIG.get(), x, y, z, playerIn.getId(), 0, 0);
        return InteractionResultHolder.consume(itemstack);
    }

}

public void onUseTick(Level level, LivingEntity player, ItemStack itemstack, int count) {
    player.swing(player.getUsedItemHand());
    RandomSource random = player.getRandom();
    if (count % 5 == 0) {
        player.gameEvent(GameEvent.ITEM_INTERACT_START);
        player.playSound(SoundEvents.NETHERITE_BLOCK_HIT, 1, 0.5F + random.nextFloat());
    }
    boolean flag = false;
    if (itemstack.getOrCreateTag().getBoolean("HASBLOCK")) {
        double x = itemstack.getOrCreateTag().getDouble("BLOCKX");
        double y = itemstack.getOrCreateTag().getDouble("BLOCKY");
        double z = itemstack.getOrCreateTag().getDouble("BLOCKZ");
        if (random.nextFloat() < 0.2) {
            player.level().addParticle(AMParticleRegistry.WORM_PORTAL.get(), x + random.nextGaussian() * 0.1F, y + random.nextGaussian() * 0.1F, z + random.nextGaussian() * 0.1F, random.nextGaussian() * 0.1F, -0.1F, random.nextGaussian() * 0.1F);
        }
        if (player.distanceToSqr(x, y, z) > 9) {
            flag = true;
            if (player instanceof Player) {
                ((Player) player).getCooldowns().addCooldown(this, 40);
            }
        }
        if (count == 1 && !player.level().isClientSide) {
            player.gameEvent(GameEvent.ITEM_INTERACT_START);
            player.playSound(SoundEvents.GLASS_BREAK, 1, 0.5F);
            EntityVoidPortal portal = new EntityVoidPortal(player.level(), this);
            portal.setPos(x, y, z);
            Direction dir = Direction.orderedByNearest(player)[0].getOpposite();
            if (dir == Direction.UP) {
                dir = Direction.DOWN;
            }
            portal.setAttachmentFacing(dir);
            player.level().addFreshEntity(portal);
            onPortalOpen(player.level(), player, portal, dir);
            itemstack.hurtAndBreak(1, player, (playerIn) -> {
                player.broadcastBreakEvent(playerIn.getUsedItemHand());
            });
            flag = true;
            if (player instanceof Player) {
                ((Player) player).getCooldowns().addCooldown(this, 200);
            }
        }
    }
    if (flag) {
        player.stopUsingItem();
        itemstack.getOrCreateTag().putBoolean("HASBLOCK", false);
        itemstack.getOrCreateTag().putDouble("BLOCKX", 0);
        itemstack.getOrCreateTag().putDouble("BLOCKY", 0);
        itemstack.getOrCreateTag().putDouble("BLOCKZ", 0);
        itemstack.setTag(itemstack.getOrCreateTag());
    }
}

