public void applyToEntity(LivingEntity target, @Nullable Player shooter, @Nullable Entity projectile, ItemStack thrower, FluidStack fluid)
{
	if(fluid.has(DataComponents.POTION_CONTENTS))
	{
		PotionContents potionContents = fluid.get(DataComponents.POTION_CONTENTS);
		for(MobEffectInstance e : potionContents.getAllEffects())
		{
			MobEffect effect = e.getEffect().value();
			if(effect.isInstantenous())
				effect.applyInstantenousEffect(projectile, shooter, target, e.getAmplifier(), 1);
			else
			{
				MobEffectInstance newEffect = new MobEffectInstance(e.getEffect(), (int)Math.ceil(e.getDuration()*.05), e.getAmplifier());
				target.addEffect(newEffect);
			}
		}
	}
}

public void inventoryTick(ItemStack stack, Level world, Entity ent, int slot, boolean inHand)
{
	super.inventoryTick(stack, world, ent, slot, inHand);
	if(world.isClientSide)
		return;

	if(ent instanceof LivingEntity)
		inHand |= ((LivingEntity)ent).getItemInHand(InteractionHand.OFF_HAND)==stack;

	boolean blocking = ent instanceof LivingEntity&&((LivingEntity)ent).isBlocking();
	IEnergyStorage energy = stack.getCapability(EnergyStorage.ITEM);
	if(!inHand||!blocking)//Don't recharge if in use, to avoid flickering
	{
		for(var cooldownKey : List.of(UpgradeEffect.FLASH, UpgradeEffect.SHOCK))
		{
			var upgrades = getUpgrades(stack);
			var cooldown = upgrades.get(cooldownKey);
			if(cooldown.isOnCooldown()&&energy.extractEnergy(10, true)==10)
			{
				energy.extractEnergy(10, false);
				if(cooldown.isOnCooldown())
					stack.set(IEDataComponents.UPGRADE_DATA, upgrades.with(cooldownKey, cooldown.tick()));
			}
		}
	}
}

public void hitShield(ItemStack stack, Player player, DamageSource source, float amount, LivingDamageEvent.Pre event)
{
	var upgrades = getUpgrades(stack);
	if(upgrades.has(UpgradeEffect.FLASH)&&!upgrades.get(UpgradeEffect.FLASH).isOnCooldown())
	{
		Vec3 look = player.getLookAngle();
		//Offsets Player position by look backwards, then truncates cone at 1
		List<LivingEntity> targets = Utils.getTargetsInCone(player.getCommandSenderWorld(), player.position().subtract(look), player.getLookAngle().scale(9), 1.57079f, .5f);
		for(LivingEntity t : targets)
			if(!player.equals(t))
			{
				t.addEffect(new MobEffectInstance(IEPotions.FLASHED, 100, 1));
				if(t instanceof Mob)
					((Mob)t).setTarget(null);
			}
		upgrades = upgrades.with(UpgradeEffect.FLASH, new Cooldown(40));
	}
	if(upgrades.has(UpgradeEffect.SHOCK)&&!upgrades.get(UpgradeEffect.SHOCK).isOnCooldown())
	{
		boolean b = false;
		if(event.getSource().is(DamageTypeTags.IS_PROJECTILE)&&event.getSource().getDirectEntity()!=null)
		{
			Entity projectile = event.getSource().getDirectEntity();
			projectile.discard();
			event.setNewDamage(0);
			b = true;
		}
		if(event.getSource().getEntity()!=null&&event.getSource().getEntity() instanceof LivingEntity&&event.getSource().getEntity().distanceToSqr(player) < 4)
		{
			ElectricDamageSource dmgsrc = IEDamageSources.causeTeslaDamage(event.getEntity().level(), 1, true);
			dmgsrc.apply(event.getSource().getEntity());
			b = true;
		}
		if(b)
		{
			upgrades = upgrades.with(UpgradeEffect.SHOCK, new Cooldown(40));
			player.level().playSound(null, player.getX(), player.getY(), player.getZ(), IESounds.spark.value(),
					SoundSource.BLOCKS, 2.5F, 0.5F+ApiUtils.RANDOM.nextFloat());
		}
	}
	stack.set(IEDataComponents.UPGRADE_DATA, upgrades);
}

public InteractionResultHolder<ItemStack> use(Level world, Player player, @Nonnull InteractionHand hand)
{
	ItemStack stack = player.getItemInHand(hand);
	int consumption = IEServerConfig.TOOLS.railgun_consumption.get();
	IEnergyStorage energy = Objects.requireNonNull(stack.getCapability(EnergyStorage.ITEM));
	if(energy.extractEnergy(consumption, true)==consumption&&!findAmmo(stack, player).isEmpty())
	{
		player.startUsingItem(hand);
		playChargeSound(player, stack);
		return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);
	}
	return new InteractionResultHolder<>(InteractionResult.PASS, stack);
}

public DamageSource getDamageSource(Level world, Entity target, @Nullable UUID shooter, Entity projectile)
{
	if(target instanceof EnderMan enderMan)
	{
		enderMan.addEffect(new MobEffectInstance(IEPotions.STUNNED, 200));
		final DamageSourcesAccess sources = (DamageSourcesAccess)world.damageSources();
		Player p;
		if(shooter!=null&&(p = world.getPlayerByUUID(shooter))!=null)
			return sources.invokeSource(DamageTypes.RAILGUN.turretType(), p, null);
		return sources.invokeSource(DamageTypes.RAILGUN.playerType(), null, null);
	}
	return null;
}

public InteractionResultHolder<ItemStack> use(Level world, Player player, @Nonnull InteractionHand hand)
{

	ItemStack stack = player.getItemInHand(hand);
	if(player.getCooldowns().isOnCooldown(this))
		return new InteractionResultHolder<>(InteractionResult.PASS, stack);
	if(player.isShiftKeyDown())
	{
		boolean limitSpeed = toggleSpeedLimit(stack);
		if(limitSpeed)
			player.displayClientMessage(Component.translatable("chat.immersiveengineering.info.skyhookLimited"), true);
		else
			player.displayClientMessage(Component.translatable("chat.immersiveengineering.info.skyhookUnlimited"), true);
	}
	else
	{
		SkyhookUserData data = player.getData(IEDataAttachments.SKYHOOK_USER.get());
		if(data.hook!=null&&!world.isClientSide)
		{
			data.dismount();
			IELogger.logger.info("Player left voluntarily");
		}
		else
		{
			data.startHolding();
			player.startUsingItem(hand);
		}
	}
	return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);
}

public void onHitTarget(Level world, HitResult target, UUID shooterUUID, Entity projectile, boolean headshot, Data bulletData)
{
	super.onHitTarget(world, target, shooterUUID, projectile, headshot, bulletData);
	RevolvershotEntity bullet = (RevolvershotEntity)projectile;
	if(bulletData.contents!=null&&bulletData.contents.hasEffects())
	{
		var effects = bulletData.contents.getAllEffects();
		LivingEntity shooter = null;
		if(shooterUUID!=null&&world instanceof ServerLevel serverLevel)
		{
			Entity e = serverLevel.getEntity(shooterUUID);
			if(e == null && projectile instanceof Projectile p)
				e = p.getOwner();
			if(e instanceof LivingEntity)
				shooter = (LivingEntity)e;
		}
		if(bulletData.type==PotionType.LINGERING)
		{
			AreaEffectCloud entityareaeffectcloud = new AreaEffectCloud(bullet.level(), bullet.getX(), bullet.getY(), bullet.getZ());
			entityareaeffectcloud.setOwner(shooter);
			entityareaeffectcloud.setRadius(3.0F);
			entityareaeffectcloud.setRadiusOnUse(-0.5F);
			entityareaeffectcloud.setWaitTime(10);
			entityareaeffectcloud.setRadiusPerTick(-entityareaeffectcloud.getRadius()/(float)entityareaeffectcloud.getDuration());
			entityareaeffectcloud.setPotionContents(bulletData.contents);
			for(MobEffectInstance potioneffect : effects)
				entityareaeffectcloud.addEffect(new MobEffectInstance(potioneffect.getEffect(), potioneffect.getDuration(), potioneffect.getAmplifier()));
			bullet.level().addFreshEntity(entityareaeffectcloud);
		}
		else if(bulletData.type==PotionType.SPLASH)
		{
			List<LivingEntity> livingEntities = bullet.level().getEntitiesOfClass(LivingEntity.class, bullet.getBoundingBox().inflate(4.0D, 2.0D, 4.0D));
			if(livingEntities!=null&&!livingEntities.isEmpty())
				for(LivingEntity living : livingEntities)
					if(living.isAffectedByPotions())
					{
						double dist = bullet.distanceToSqr(living);
						if(dist < 16D)
						{
							double dist2 = 1-Math.sqrt(dist)/4D;
							if(target instanceof EntityHitResult&&living==((EntityHitResult)target).getEntity())
								dist2 = 1D;
							for(MobEffectInstance p : effects)
								if(p.getEffect().value().isInstantenous())
									p.getEffect().value().applyInstantenousEffect(bullet, shooter, living, p.getAmplifier(), dist2);
								else
								{
									int j = (int)(dist2*p.getDuration()+.5D);
									if(j > 20)
										living.addEffect(new MobEffectInstance(p.getEffect(), j, p.getAmplifier()));
								}
						}
					}

		}
		else if(target instanceof EntityHitResult&&((EntityHitResult)target).getEntity() instanceof LivingEntity)
			for(MobEffectInstance p : effects)
			{
				if(p.getDuration() < 1)
					p = new MobEffectInstance(p.getEffect(), 1);
				((LivingEntity)((EntityHitResult)target).getEntity()).addEffect(p);
			}
		world.levelEvent(2002, bullet.blockPosition(), bulletData.contents.getColor());
	}
}

public static void empowerWolves(Level world, HitResult hitResult, Player player, @Nullable LivingEntity hitTarget)
{
	LivingEntity possibleTarget = hitTarget!=null?hitTarget: player.getLastHurtMob();
	AABB searchBox = new AABB(hitResult.getLocation(), hitResult.getLocation()).inflate(32);
	world.getEntitiesOfClass(Wolf.class, searchBox, wolf -> PlayerUtils.isAllied(player, wolf)).forEach(wolf -> {
		// target setting only works for owned wolves, but buffs are given to all allied wolves!
		if(player.equals(wolf.getOwner()) && possibleTarget!=null && wolf.getTarget()==null && !PlayerUtils.isAllied(player, possibleTarget))
			wolf.setTarget(possibleTarget);
		wolf.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED, 200));
		wolf.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 200, 1));
	});
}

public static void holdingExtendoGripIncreasesRange(EntityTickEvent.Pre event) {
	if (!(event.getEntity() instanceof Player player))
		return;

	CompoundTag persistentData = player.getPersistentData();
	boolean inOff = AllItems.EXTENDO_GRIP.isIn(player.getOffhandItem());
	boolean inMain = AllItems.EXTENDO_GRIP.isIn(player.getMainHandItem());
	boolean holdingDualExtendo = inOff && inMain;
	boolean holdingExtendo = inOff ^ inMain;
	holdingExtendo &= !holdingDualExtendo;
	boolean wasHoldingExtendo = persistentData.contains(EXTENDO_MARKER);
	boolean wasHoldingDualExtendo = persistentData.contains(DUAL_EXTENDO_MARKER);

	if (holdingExtendo != wasHoldingExtendo) {
		if (!holdingExtendo) {
			player.getAttributes()
				.removeAttributeModifiers(rangeModifier.get());
			persistentData.remove(EXTENDO_MARKER);
		} else {
			AllAdvancements.EXTENDO_GRIP.awardTo(player);
			player.getAttributes()
				.addTransientAttributeModifiers(rangeModifier.get());
			persistentData.putBoolean(EXTENDO_MARKER, true);
		}
	}

	if (holdingDualExtendo != wasHoldingDualExtendo) {
		if (!holdingDualExtendo) {
			player.getAttributes()
				.removeAttributeModifiers(doubleRangeModifier.get());
			persistentData.remove(DUAL_EXTENDO_MARKER);
		} else {
			AllAdvancements.EXTENDO_GRIP_DUAL.awardTo(player);
			player.getAttributes()
				.addTransientAttributeModifiers(doubleRangeModifier.get());
			persistentData.putBoolean(DUAL_EXTENDO_MARKER, true);
		}
	}

}

public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
	ItemStack heldStack = player.getItemInHand(hand);
	if (ShootableGadgetItemMethods.shouldSwap(player, heldStack, hand, s -> s.getItem() instanceof PotatoCannonItem)) {
		return InteractionResultHolder.fail(heldStack);
	}

	Ammo ammo = getAmmo(player, heldStack);
	if (ammo == null) {
		return InteractionResultHolder.pass(heldStack);
	}
	ItemStack ammoStack = ammo.stack();
	PotatoCannonProjectileType projectileType = ammo.type();

	if (level.isClientSide) {
		CreateClient.POTATO_CANNON_RENDER_HANDLER.dontAnimateItem(hand);
		return InteractionResultHolder.success(heldStack);
	}

	Vec3 barrelPos = ShootableGadgetItemMethods.getGunBarrelVec(player, hand == InteractionHand.MAIN_HAND,
		new Vec3(.75f, -0.15f, 1.5f));
	Vec3 correction =
		ShootableGadgetItemMethods.getGunBarrelVec(player, hand == InteractionHand.MAIN_HAND, new Vec3(-.05f, 0, 0))
			.subtract(player.position()
				.add(0, player.getEyeHeight(), 0));

	Vec3 lookVec = player.getLookAngle();
	Vec3 motion = lookVec.add(correction)
		.normalize()
		.scale(2)
		.scale(projectileType.velocityMultiplier());

	float soundPitch = projectileType.soundPitch() + (level.getRandom().nextFloat() - .5f) / 4f;

	boolean spray = projectileType.split() > 1;
	Vec3 sprayBase = VecHelper.rotate(new Vec3(0, 0.1, 0), 360 * level.getRandom().nextFloat(), Axis.Z);
	float sprayChange = 360f / projectileType.split();

	ItemStack ammoStackCopy = ammoStack.copy();

	for (int i = 0; i < projectileType.split(); i++) {
		PotatoProjectileEntity projectile = AllEntityTypes.POTATO_PROJECTILE.create(level);
		projectile.setItem(ammoStackCopy);
		projectile.setEnchantmentEffectsFromCannon(heldStack);

		Vec3 splitMotion = motion;
		if (spray) {
			float imperfection = 40 * (level.getRandom().nextFloat() - 0.5f);
			Vec3 sprayOffset = VecHelper.rotate(sprayBase, i * sprayChange + imperfection, Axis.Z);
			splitMotion = splitMotion.add(VecHelper.lookAt(sprayOffset, motion));
		}

		if (i != 0)
			projectile.recoveryChance = 0;

		projectile.setPos(barrelPos.x, barrelPos.y, barrelPos.z);
		projectile.setDeltaMovement(splitMotion);
		projectile.setOwner(player);
		level.addFreshEntity(projectile);
	}

	if (!player.isCreative()) {
		ammoStack.shrink(1);
		if (ammoStack.isEmpty())
			player.getInventory().removeItem(ammoStack);
	}

	if (!BacktankUtil.canAbsorbDamage(player, maxUses()))
		heldStack.hurtAndBreak(1, player, LivingEntity.getSlotForHand(hand));

	ShootableGadgetItemMethods.applyCooldown(player, heldStack, hand, s -> s.getItem() instanceof PotatoCannonItem, projectileType.reloadTicks());
	ShootableGadgetItemMethods.sendPackets(player,
		b -> new PotatoCannonPacket(barrelPos, lookVec.normalize(), ammoStack, hand, soundPitch, b));
	return InteractionResultHolder.success(heldStack);
}

public static void cardboardSwordsCannotHurtYou(AttackEntityEvent event) {
	Player attacker = event.getEntity();
	if (!(event.getTarget() instanceof LivingEntity target) || target.getType().is(EntityTypeTags.ARTHROPOD))
		return;
	ItemStack stack = attacker.getItemInHand(InteractionHand.MAIN_HAND);
	if (!(AllItems.CARDBOARD_SWORD.isIn(stack)))
		return;

	AllSoundEvents.CARDBOARD_SWORD.playFrom(attacker, 0.75f, 1.85f);

	event.setCanceled(true);

	// Reference player.attack()
	// This section replicates knockback behaviour without hurting the target

	float knockbackStrength = (float) (attacker.getAttributeValue(Attributes.ATTACK_KNOCKBACK) + 2);
	if (attacker.level() instanceof ServerLevel serverLevel)
		knockbackStrength = EnchantmentHelper.modifyKnockback(serverLevel, stack, target, serverLevel.damageSources().playerAttack(attacker), knockbackStrength);
	if (attacker.isSprinting() && attacker.getAttackStrengthScale(0.5f) > 0.9f)
		++knockbackStrength;

	if (knockbackStrength <= 0)
		return;

	float yRot = attacker.getYRot();
	knockback(target, knockbackStrength, yRot);

	boolean targetIsPlayer = target instanceof Player;
	MobCategory targetType = target.getClassification(false);

	if (target instanceof ServerPlayer sp)
		CatnipServices.NETWORK.sendToClient(sp, new KnockbackPacket(yRot, (float) knockbackStrength));

	if ((targetType == MobCategory.MISC || targetType == MobCategory.CREATURE) && !targetIsPlayer)
		target.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, 60, 9, true, false, false));

	attacker.setDeltaMovement(attacker.getDeltaMovement()
		.multiply(0.6D, 1.0D, 0.6D));
	attacker.setSprinting(false);
}

public static void applyCooldown(Player player, ItemStack item, InteractionHand hand, Predicate<ItemStack> predicate,
	int cooldown) {
	if (cooldown <= 0)
		return;

	boolean gunInOtherHand =
		predicate.test(player.getItemInHand(hand == InteractionHand.MAIN_HAND ? InteractionHand.OFF_HAND : InteractionHand.MAIN_HAND));
	player.getCooldowns()
		.addCooldown(item.getItem(), gunInOtherHand ? cooldown * 2 / 3 : cooldown);
}

public static boolean shouldSwap(Player player, ItemStack item, InteractionHand hand, Predicate<ItemStack> predicate) {
	boolean isSwap = item.has(AllDataComponents.SHAPER_SWAP);
	boolean mainHand = hand == InteractionHand.MAIN_HAND;
	boolean gunInOtherHand = predicate.test(player.getItemInHand(mainHand ? InteractionHand.OFF_HAND : InteractionHand.MAIN_HAND));

	// Pass To Offhand
	if (mainHand && isSwap && gunInOtherHand)
		return true;
	if (mainHand && !isSwap && gunInOtherHand)
		item.set(AllDataComponents.SHAPER_SWAP, true);
	if (!mainHand && isSwap)
		item.remove(AllDataComponents.SHAPER_SWAP);
	if (!mainHand && gunInOtherHand)
		player.getItemInHand(InteractionHand.MAIN_HAND).remove(AllDataComponents.SHAPER_SWAP);
	player.startUsingItem(hand);
	return false;
}

public void onPlayerStoppedUsing(ItemStack stack, World world, EntityLivingBase entity, int timeLeft) {
    if (!world.isRemote) {
        double charge = (Math.min(MAX_CHARGE, getMaxItemUseDuration(stack) - timeLeft)) / MAX_CHARGE;
        float spawnDistance = 2.0f;//Math.max(1.0f, (float)charge/5.0f);
        Vec3d eyesPos = entity.getPositionEyes(1.0f);
        RayTraceResult traceResult = this.rayTrace(world, (EntityPlayer) entity, false);
        if (traceResult != null && traceResult.typeOfHit == RayTraceResult.Type.BLOCK)
            spawnDistance = (float) Math.min(spawnDistance, traceResult.hitVec.distanceTo(eyesPos));
        Vec3d launchPos = eyesPos.add(entity.getLookVec().scale(spawnDistance));
        float damage = (float) Math.max(charge * DAMAGE, 0.5f);
        float size = (float) Math.max(charge * SIZE, 0.5f);
        float aoeSize = (float) charge * AOE_SIZE;
        int lifetime = charge * DAMAGE >= 1.0 ? LIFETIME : 5;
        EffectArea effect = new EffectArea(new EffectDamage(damage, DamageEmber.EMBER_DAMAGE_SOURCE_FACTORY, 1, 1.0), aoeSize, false);
        ProjectileFireball fireball = new ProjectileFireball(entity, launchPos, entity.getLookVec().scale(0.85), size, lifetime, effect);
        EmberProjectileEvent event = new EmberProjectileEvent(entity, stack, charge, fireball);
        MinecraftForge.EVENT_BUS.post(event);
        if (!event.isCanceled()) {
            for (IProjectilePreset projectile : event.getProjectiles()) {
                projectile.shoot(world);
            }
        }
        SoundEvent sound;
        if (charge * DAMAGE >= 10.0)
            sound = SoundManager.FIREBALL_BIG;
        else if (charge * DAMAGE >= 1.0)
            sound = SoundManager.FIREBALL;
        else
            sound = SoundManager.CINDER_STAFF_FAIL;
        world.playSound(null, launchPos.x, launchPos.y, launchPos.z, sound, SoundCategory.PLAYERS, 1.0f, 1.0f);
    }
    entity.swingArm(entity.getActiveHand());
    stack.getTagCompound().setInteger("cooldown", COOLDOWN);
}

