            Embers.proxy.playItemSound(player, this, SoundManager.CINDER_STAFF_CHARGE, SoundCategory.PLAYERS, false, 1.0f, 1.0f);
        }
        return new ActionResult<>(EnumActionResult.SUCCESS, stack);
