  int slowfallSeconds = WING_FALL_SLOWFALL_SECONDS == null ? FALLDISTANCESECONDS_DEFAULT : WING_FALL_SLOWFALL_SECONDS.get();
  if (this.wingCharm && living.fallDistance > fallLimit && !living.hasEffect(MobEffects.SLOW_FALLING)) {
