private void onImpactEntity(EntityHitResult entityRayTrace) {
  Entity entityHit = entityRayTrace.getEntity();
  if (entityHit == null || !entityHit.isAlive()) {
    return;
  }
  Entity owner = getOwner();
  if (owner == entityHit) {
    //player catch it on return 
    dropAsItem();
    return;
  }
  switch (this.boomerangType) {
    case CARRY:
      if (!entityHit.level().isClientSide) {
        entityHit.startRiding(this);
      }
    break;
    case DAMAGE:
      if (entityHit instanceof LivingEntity) {
        LivingEntity live = (LivingEntity) entityHit;
        float damage = Mth.nextFloat(level().random, ConfigRegistry.BOOMERANG_DAMAGE_MIN.get().floatValue(), ConfigRegistry.BOOMERANG_DAMAGE_MAX.get().floatValue());
        boolean attackSucc = live.hurt(level().damageSources().thrown(this, owner), damage);
        if (attackSucc && live.isAlive() == false) {
          //           ("killed one");
        }
      }
    break;
    case STUN:
      //!entityHit.getUniqueID().equals(owner.getUniqueID()) 
      if (entityHit != owner && entityHit instanceof LivingEntity
          && !(entityHit instanceof Player)) {
        LivingEntity live = (LivingEntity) entityHit;
        if (!live.hasEffect(PotionEffectRegistry.STUN)) {
          live.addEffect(new MobEffectInstance(PotionEffectRegistry.STUN, ConfigRegistry.BOOMERANG_STUN_SECONDS.get() * Const.TICKS_PER_SEC, 1, false, true, true));
          SoundUtil.playSound(live, SoundEvents.IRON_GOLEM_ATTACK);
        }
      }
    break;
    default:
    break;
  }
}

protected void onHit(HitResult result) {
  HitResult.Type type = result.getType();
  if (type == HitResult.Type.ENTITY) {
    //damage entity by zero
    //drop torch
    EntityHitResult entityRayTrace = (EntityHitResult) result;
    Entity target = entityRayTrace.getEntity();
    var level = level();
    if (target.isAlive()) {
      target.hurt(level.damageSources().thrown(this, this.getOwner()), Mth.nextInt(level.random, 2, 6));
      if (!level.isClientSide && target.isOnFire() == false
          && target instanceof LivingEntity) {
        target.hurt(level.damageSources().inFire(), Mth.nextInt(level.random, 3, 5));
        LivingEntity living = (LivingEntity) target;
        living.addEffect(new MobEffectInstance(PotionEffectRegistry.STUN, Const.TICKS_PER_SEC * 4, 1, false, false, false));
        living.igniteForSeconds(Mth.nextInt(level.random, 1, 5));
      }
    }
  }
  else if (type == HitResult.Type.BLOCK) {
    BlockHitResult ray = (BlockHitResult) result;
    //  set fire in the area here, small radius randomized, similar to lightning strike or tnt
    var level = this.level();
    if (!level.isClientSide && ray.getBlockPos() != null) {
      final int radius = 2;
      final BlockPos center = ray.getBlockPos().relative(ray.getDirection());
      final int attempts = Mth.nextInt(level.random, 3, 6); //range similar to lightning default
      for (int i = 0; i < attempts; i++) {
        BlockPos firePos = center.offset(
            Mth.nextInt(level.random, -radius, radius),
            Mth.nextInt(level.random, -1, 1),
            Mth.nextInt(level.random, -radius, radius));
        if (level.isEmptyBlock(firePos) && BaseFireBlock.canBePlacedAt(level, firePos, ray.getDirection())) {
          level.setBlockAndUpdate(firePos, BaseFireBlock.getState(level, firePos));
        }
      }
    }
  }
  this.remove(RemovalReason.DISCARDED);
}

private boolean curePotionEffects(LivingEntity entityLiving, ItemStack curativeItem) {
  boolean ret = false;
  java.util.List<Holder<MobEffect>> toRemove = new java.util.ArrayList<>();
  for (MobEffectInstance effect : entityLiving.getActiveEffects()) {
    if (!effect.getEffect().value().isInstantenous()) { // approximation for not beneficial since isBeneficial is gone or changed
      toRemove.add(effect.getEffect());
    }
  }
  for (Holder<MobEffect> e : toRemove) {
    entityLiving.removeEffect(e);
    ret = true;
  }
  return ret;
}

public InteractionResultHolder<ItemStack> use(Level worldIn, Player playerIn, InteractionHand handIn) {
  if (playerIn.getCooldowns().isOnCooldown(this)) {
    return super.use(worldIn, playerIn, handIn);
  }
  playerIn.getFoodData().eat(1, 4);
  AttributeInstance healthAttribute = playerIn.getAttribute(Attributes.MAX_HEALTH);
  if (healthAttribute.getValue() < MAX.get()) {
    //get attribute modif by id
    AttributesUtil.updateAttrModifierBy(Attributes.MAX_HEALTH, AttributesUtil.DEFAULT_ID, playerIn, 2);
    //finish up
    playerIn.getCooldowns().addCooldown(this, COOLDOWN);
    playerIn.getItemInHand(handIn).shrink(1);
    SoundUtil.playSound(playerIn, SoundRegistry.FILL.get());
  }
  return super.use(worldIn, playerIn, handIn);
}

public ItemStack finishUsingItem(ItemStack stack, Level worldIn, LivingEntity entityLiving) {
  if (entityLiving instanceof Player == false) {
    return super.finishUsingItem(stack, worldIn, entityLiving);
  }
  Player player = (Player) entityLiving;
  if (player.getCooldowns().isOnCooldown(stack.getItem())) {
    return super.finishUsingItem(stack, worldIn, entityLiving);
  }
  player.getCooldowns().addCooldown(stack.getItem(), 40); // 2seconds
  if (!worldIn.isClientSide) {
    PlayerCyclicAttachment data = player.getData(AttachmentRegistry.CYCLIC_PLAYER);
    data.toggleStepHeight();
    ChatUtil.addServerChatMessage(player, "cyclic.unlocks.stepheight." + data.stepHeight);
  }
  return super.finishUsingItem(stack, worldIn, entityLiving);
}

