        }
    }

public void tickItem(Player player, ItemStack stack, int level) {
    CompoundTag tag = stack.getOrCreateTag();
    boolean charged = tag.getBoolean(UtilBooster.chargedKey);
    if (!player.isInWater() && player.getVehicle() == null && UtilBooster.isActive(tag) && UtilBooster.hasFuel(tag, charged)) {
        if (charged) {
            UtilBooster.boostPlayerCharged(player, tag, level);
        } else {
            UtilBooster.boostPlayer(player, tag, level);
        }

        UtilBooster.consumeFuel(tag, charged);
    } else {
        UtilBooster.rechargeFuel(tag, stack);
    }

    if (charged) {
        tag.putBoolean(UtilBooster.chargedKey, false);
    }
}

public static void consumeFuel(CompoundTag tag, boolean charged) {
    if (charged) {
        tag.putInt(fuelKey, tag.getInt(fuelKey) - fuelCostCharged);
    } else {
        tag.putInt(fuelKey, tag.getInt(fuelKey) - fuelCost);
    }
    tag.putInt(cooldownKey, cooldownTicks);
}

public static void rechargeFuel(CompoundTag tag, ItemStack itemStack) {
    int fuel = tag.getInt(fuelKey);
    int buffer = tag.getInt(bufferKey);
    int cooldown = tag.getInt(cooldownKey);
    if (cooldown > 0) {
        tag.putInt(cooldownKey, cooldown - 1);
    } else if (fuel + fuelRecharge < fuelCapacity) {
        if (buffer > 0) {
            tag.putInt(fuelKey, fuel + fuelRecharge);
            tag.putInt(bufferKey, buffer - 1);
        } else {
            refuelBuffer(tag, itemStack);
        }
    }
}

private static void refuelBuffer(CompoundTag tag, ItemStack itemStack) {
    ToolbeltInventory inventory = new QuickslotInventory(itemStack);
    int index = inventory.getFirstIndexForItem(Items.GUNPOWDER);
    if (index != -1) {
        inventory.removeItem(index, 1);
        tag.putInt(bufferKey, gunpowderGain);
        return;
    }

    inventory = new StorageInventory(itemStack);
    index = inventory.getFirstIndexForItem(Items.GUNPOWDER);
    if (index != -1) {
        inventory.removeItem(index, 1);
        tag.putInt(bufferKey, gunpowderGain);
        return;
    }

    tag.putInt(cooldownKey, cooldownTicks);
}

public static void toggleSuspend(Player entity, boolean toggleOn) {
    if (toggleOn) {
        if (canSuspend(entity)) {
            Vec3 motion = entity.getDeltaMovement();
            entity.setDeltaMovement(motion.x, 0, motion.z);
            entity.hurtMarked = true;
            entity.addEffect(new MobEffectInstance(SuspendPotionEffect.instance, 100, 0, false, false));
        }
    } else {
        entity.removeEffect(SuspendPotionEffect.instance);
    }
}

public void applyEffectTick(LivingEntity entity, int amplifier) {
    entity.fallDistance = 0;
    if (entity.onGround()) {
        entity.removeEffect(this);
    } else {
        Vec3 motion = entity.getDeltaMovement();
        double dy = motion.y;
        if (entity.isCrouching()) {
            entity.setDeltaMovement(motion.x, Math.max(-0.3, dy - 0.05), motion.z);
        } else {
            entity.setDeltaMovement(motion.x, Math.abs(dy) > 0.02 ? dy * 0.9 : 0, motion.z);
        }

        MobEffectInstance effectInstance = entity.getEffect(this);
        if (effectInstance != null && effectInstance.getDuration() < 20) {
            if (entity instanceof Player player && SuspendEffect.canSuspend(player)) {
                entity.addEffect(new MobEffectInstance(SuspendPotionEffect.instance, 100, 0, false, false));
            } else {
                entity.removeEffect(this);
            }
        }
    }
}

public void tick(ItemStack stack, SlotReference slot, LivingEntity entity) {
	if (entity instanceof PlayerEntity player && !entity.getWorld().isClient && entity.age % 10 == 0 & entity.getWorld().getBlockState(entity.getBlockPos().down()).isIn(BWTags.NATURAL_TERRAIN)) {
		StatusEffectInstance speed = new StatusEffectInstance(StatusEffects.SPEED, 300, 0, true, false);
		StatusEffectInstance regeneration = new StatusEffectInstance(StatusEffects.REGENERATION, 300, 0, true, false);
		boolean canApply = entity.canHaveStatusEffect(speed) && !entity.hasStatusEffect(StatusEffects.SPEED);
		canApply |= entity.canHaveStatusEffect(regeneration) && !entity.hasStatusEffect(StatusEffects.REGENERATION);
		if (canApply && BewitchmentAPI.drainMagic(player, 1, false)) {
			entity.addStatusEffect(speed);
			entity.addStatusEffect(regeneration);
		}
	}
}

public ItemStack finishUsing(ItemStack stack, World world, LivingEntity user) {
	if (user instanceof PlayerEntity player) {
		if (!world.isClient && BewitchmentAPI.drainMagic(player, 2, false)) {
			PotionEntity potion = new PotionEntity(world, user);
			List<StatusEffectInstance> effects = PotionUtil.getCustomPotionEffects(stack);
			ItemStack potionStack = PotionUtil.setCustomPotionEffects(new ItemStack(Items.SPLASH_POTION), effects);
			potionStack.getOrCreateNbt().putInt("CustomPotionColor", PotionUtil.getColor(effects));
			if (stack.getOrCreateNbt().contains("PolymorphUUID")) {
				potionStack.getOrCreateNbt().putUuid("PolymorphUUID", stack.getOrCreateNbt().getUuid("PolymorphUUID"));
				potionStack.getOrCreateNbt().putString("PolymorphName", stack.getOrCreateNbt().getString("PolymorphName"));
			}
			potion.setItem(potionStack);
			potion.setVelocity(user, user.getPitch(), user.getYaw(), -20, 0.5f, 1);
			world.spawnEntity(potion);
			world.playSound(null, user.getBlockPos(), SoundEvents.ENTITY_SPLASH_POTION_THROW, SoundCategory.PLAYERS, 1, 1);
			if (!player.isCreative()) {
				stack.getOrCreateNbt().putInt("PotionUses", stack.getOrCreateNbt().getInt("PotionUses") - 1);
				if (stack.getOrCreateNbt().getInt("PotionUses") <= 0) {
					if (stack.getOrCreateNbt().contains("PolymorphUUID")) {
						potionStack.getOrCreateNbt().remove("PolymorphUUID");
						potionStack.getOrCreateNbt().remove("PolymorphName");
					}
					stack.getOrCreateNbt().put("CustomPotionEffects", new NbtList());
				}

				stack.damage(1, user, stackUser -> stackUser.sendToolBreakStatus(user.getActiveHand()));
			}
		}
	}
	return stack;
}

public void tick() {
	if (level().isClientSide) {
		return;
	}

	for (int i = 0; i < 2; i++) {
		EquipmentSlot equipmentSlot = EquipmentSlot.values()[i];

		ItemStack oldStack = fakePlayerHandInventory.get(equipmentSlot.getIndex());
		ItemStack newStack = getItemBySlot(equipmentSlot);

		if (!ItemStack.matches(newStack, oldStack)) {
			if (!oldStack.isEmpty()) {
				AttributeMap attributeMap = getAttributes();
				oldStack.forEachModifier(equipmentSlot, (attribute, attributeModifier) -> {
					AttributeInstance attributeinstance = attributeMap.getInstance(attribute);
					if (attributeinstance != null) {
						attributeinstance.removeModifier(attributeModifier);
					}

					EnchantmentHelper.stopLocationBasedEffects(oldStack, this, equipmentSlot);
				});
			}

			if (!newStack.isEmpty()) {
				AttributeMap attributeMap = getAttributes();
				newStack.forEachModifier(equipmentSlot, (attribute, attributeModifier) -> {
					AttributeInstance attributeinstance = attributeMap.getInstance(attribute);
					if (attributeinstance != null) {
						attributeinstance.removeModifier(attributeModifier.id());
						attributeinstance.addTransientModifier(attributeModifier);
					}

					if (level() instanceof ServerLevel serverlevel) {
						EnchantmentHelper.runLocationChangedEffects(serverlevel, newStack, this, equipmentSlot);
					}
				});
			}

			setItemSlot(equipmentSlot, newStack.isEmpty() ? ItemStack.EMPTY : newStack);
			break;
		}
	}

	// finish previous swing or cool down caused by change of weapons
	attackStrengthTicker = (int) getCurrentItemAttackStrengthDelay();
}

