public void tick() {
    LivingEntity livingentity = this.mob.getTarget();
    if (livingentity != null) {
        boolean canSeeEnemy = this.mob.getSensing().hasLineOfSight(livingentity);

        if (canSeeEnemy) {
            ++this.seeTime;
        } else {
            this.seeTime = 0;
        }

        double distanceSq = this.mob.distanceToSqr(livingentity);
        double distance = Mth.sqrt((float) distanceSq);
        if (distance <= 14.0F) {
            if (this.mob.getBlockStateOn().isFaceSturdy(this.mob.level, this.mob.blockPosition(), Direction.UP, SupportType.CENTER)) {
                this.mob.getMoveControl().strafe(mob.isUsingItem() ? -0.5F : -3.0F, 0);
            }
        }

        ItemStack activeStack = this.mob.getUseItem();
        boolean isFarAway = distanceSq > (double) this.attackRadiusSqr;
        boolean shouldMoveTowardsEnemy = (isFarAway || this.seeTime < 5);
        if (shouldMoveTowardsEnemy) {
            double speedChange = this.crossbowState != CrossbowState.CHARGING ? this.speedModifier : this.speedModifier * 0.5D;
            this.mob.getNavigation().moveTo(livingentity, speedChange);
        } else {
            this.mob.getNavigation().stop();
        }

        this.mob.getLookControl().setLookAt(livingentity, 30.0F, 30.0F);

        if (this.crossbowState == CrossbowState.UNCHARGED && !CrossbowItem.isCharged(activeStack)) {
            if (canSeeEnemy) {
                this.mob.startUsingItem(ProjectileUtil.getWeaponHoldingHand(this.mob, item -> item instanceof CrossbowItem));
                this.crossbowState = CrossbowState.CHARGING;
                this.mob.setChargingCrossbow(true);
            }
        } else if (this.crossbowState == CrossbowState.CHARGING) {
            if (!this.mob.isUsingItem()) {
                this.crossbowState = CrossbowState.UNCHARGED;
            }

            int i = this.mob.getTicksUsingItem();
            if (i >= CrossbowItem.getChargeDuration(activeStack) || CrossbowItem.isCharged(activeStack)) {
                this.mob.releaseUsingItem();
                this.crossbowState = CrossbowState.CHARGED;
                this.attackDelay = 20 + this.mob.getRandom().nextInt(20);
                if (this.mob.getOffhandItem().getItem() instanceof FireworkRocketItem) {
                    this.mob.startUsingItem(InteractionHand.OFF_HAND);
                }
                this.mob.setChargingCrossbow(false);
            }
        } else if (this.crossbowState == CrossbowState.CHARGED) {
            --this.attackDelay;
            if (this.attackDelay == 0) {
                this.crossbowState = CrossbowState.READY_TO_ATTACK;
            }
        } else if (this.crossbowState == CrossbowState.READY_TO_ATTACK && livingentity.distanceTo(this.mob) <= 20.0F && canSeeEnemy) {
            this.mob.performRangedAttack(livingentity, 1.0F);
            CrossbowItem.setCharged(this.mob.getItemInHand(ProjectileUtil.getWeaponHoldingHand(this.mob, item -> item instanceof CrossbowItem)), false);
            this.crossbowState = CrossbowState.UNCHARGED;
        }
    }
}

public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
    ItemStack itemstack = player.getItemInHand(hand);
    int random = Mth.nextInt(level.random, Math.min(6, itemstack.getCount()), Math.min(10, itemstack.getCount()));
    int used = random;
    for (int i = 0; i < random; ++i) {
        MobUtil.throwBlastFungus(player, level);
        if (CuriosFinder.hasWarlockRobe(player)){
            if (level.random.nextFloat() <= 0.1F){
                used -= 1;
            }
        }
    }
    if (!player.isSilent()) {
        level.playSound((Player) null, player.getX(), player.getY(), player.getZ(), ModSounds.BLAST_FUNGUS_THROW.get(), player.getSoundSource(), 2.0F, 0.8F + level.random.nextFloat() * 0.4F);
    }
    itemstack.shrink(used);
    player.getCooldowns().addCooldown(ModItems.BLAST_FUNGUS.get(), MathHelper.secondsToTicks(random));
    return InteractionResultHolder.sidedSuccess(itemstack, level.isClientSide());
}

public ItemStack finishUsingItem(ItemStack stack, Level worldIn, LivingEntity entityLiving) {
    super.finishUsingItem(stack, worldIn, entityLiving);
    if (worldIn instanceof ServerLevel serverWorld){
        boolean flag = serverWorld.isVillage(entityLiving.blockPosition());
        entityLiving.playSound(SoundEvents.RAID_HORN.get(), 16.0F, 1.0F);
        serverWorld.playSound(null, entityLiving.blockPosition(), SoundEvents.RAID_HORN.get(), SoundSource.NEUTRAL, 16.0F, 1.0F);
        if (entityLiving instanceof Player player) {
            if (SEHelper.getAllyEntityTypes(player).contains(EntityType.VILLAGER)) {
                flag = false;
            }
        }
        if (flag){
            int i = 0;
            for (RaiderServant servant : worldIn.getEntitiesOfClass(RaiderServant.class, entityLiving.getBoundingBox().inflate(16.0F))) {
                if (servant.getTrueOwner() == entityLiving) {
                    ++i;
                    servant.setRaidPos(entityLiving.blockPosition());
                    servant.setRaidDim(serverWorld.dimension());
                    if (servant.isStaying()) {
                        servant.setStaying(false);
                    }
                    if (servant.isGuardingArea()) {
                        servant.setBoundPos(null);
                    }
                    if (servant.isLeader()) {
                        for (RaiderServant servant1 : servant.getNearbyCompanions()) {
                            servant1.setRaidPos(entityLiving.blockPosition());
                            servant1.setRaidDim(serverWorld.dimension());
                            if (servant1.getLeader() == null) {
                                servant1.setLeader(servant);
                                servant1.setFollowing();
                            }
                        }
                    }
                }
            }
            if (i > 0) {
                if (entityLiving instanceof Player player) {
                    SEHelper.addCooldown(player, this, 300);
                }
            }
        }
    }
    return stack;
}

public ItemStack finishUsingItem(ItemStack pStack, Level pLevel, LivingEntity pEntityLiving) {
    super.finishUsingItem(pStack, pLevel, pEntityLiving);
    if (pEntityLiving instanceof Player player) {
        if (MainConfig.LichEnable.get()) {
            if (pLevel instanceof ServerLevel serverWorld) {
                ILichdom lichdom = LichdomHelper.getCapability(player);
                ISoulEnergy soulEnergy = SEHelper.getCapability(player);
                boolean isLich = lichdom.getLichdom();
                if (isLich) {
                    player.heal(20.0F);
                } else {
                    if (serverWorld.getMoonBrightness() > 0.9F && serverWorld.isNight()) {
                        if (soulEnergy.getSEActive() && soulEnergy.getArcaBlock() != null) {
                            if (pEntityLiving instanceof ServerPlayer serverPlayer) {
                                CriteriaTriggers.CONSUME_ITEM.trigger(serverPlayer, pStack);
                                serverPlayer.awardStat(Stats.ITEM_USED.get(this));
                            }
                            lichdom.setLichdom(true);
                            lichdom.setLichMode(true);
                            LichdomHelper.sendLichUpdatePacket(player);
                            player.displayClientMessage(Component.translatable("info.goety.lichdom.success"), true);
                            player.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 20, 1));
                            player.addEffect(new MobEffectInstance(MobEffects.CONFUSION, 20, 1));
                            player.playSound(SoundEvents.WITHER_DEATH, 1.0F, 0.5F);
                            player.playSound(SoundEvents.ZOMBIE_VILLAGER_CURE, 1.0F, 0.5F);
                            player.hurt(player.damageSources().wither(), 50.0F);
                        } else {
                            player.displayClientMessage(Component.translatable("info.goety.lichdom.fail"), true);
                            player.hurt(player.damageSources().wither(), 50.0F);
                        }
                    } else {
                        player.displayClientMessage(Component.translatable("info.goety.lichdom.fail"), true);
                        player.hurt(player.damageSources().wither(), 50.0F);
                    }
                }
                if (!player.getAbilities().instabuild) {
