            }
        } else {
            player.displayClientMessage(Component.translatable("info.goety.lichdom.disable").withStyle(ChatFormatting.DARK_RED), false);
        }
    }
    return pStack.isEmpty() ? new ItemStack(Items.GLASS_BOTTLE) : pStack;
}

