public static void warlockUse(Level level, Player player, ItemStack itemStack){
    if (level instanceof ServerLevel serverLevel) {
        Wartling wartling = new Wartling(ModEntityType.WARTLING.get(), level);
        wartling.setTrueOwner(player);
        wartling.setLimitedLife(MathHelper.secondsToTicks(9));
        wartling.moveTo(player.blockPosition(), player.getYRot(), player.getXRot());
        player.getActiveEffects().stream().filter(mobEffect -> mobEffect.getEffect().getCategory() == MobEffectCategory.HARMFUL && !mobEffect.getEffect().getCurativeItems().isEmpty()).findFirst().ifPresent(effect -> {
            wartling.setStoredEffect(effect);
            player.removeEffect(effect.getEffect());
        });
        wartling.finalizeSpawn(serverLevel, serverLevel.getCurrentDifficultyAt(player.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
        if (!CuriosFinder.hasCurio(player, itemStack1 -> itemStack1.getItem() instanceof WarlockGarmentItem)) {
            if (player.level.addFreshEntity(wartling)) {
                player.hurt(player.damageSources().generic(), 2.0F);
            }
        } else {
            player.level.addFreshEntity(wartling);
        }
    }
    if (!player.isSilent()) {
        level.playSound((Player) null, player.getX(), player.getY(), player.getZ(), SoundEvents.SCULK_BLOCK_SPREAD, player.getSoundSource(), 1.0F, 0.8F + level.random.nextFloat() * 0.4F);
    }
    if (!player.getAbilities().instabuild) {
        if (CuriosFinder.hasWarlockRobe(player)) {
            if (level.random.nextFloat() > 0.1F){
                itemStack.shrink(1);
            }
        } else {
            itemStack.shrink(1);
        }
    }
}

public InteractionResultHolder<ItemStack> use(Level worldIn, Player playerIn, InteractionHand handIn) {
    ItemStack itemstack = playerIn.getItemInHand(handIn);
    if (getThrowBrew(itemstack) != null){
        if (!worldIn.isClientSide) {
            ThrownBrew thrownBrew = new ThrownBrew(worldIn, playerIn);
            thrownBrew.setItem(itemstack);
            float velocity = 0.5F + BrewUtils.getVelocity(itemstack);
            thrownBrew.shootFromRotation(playerIn, playerIn.getXRot(), playerIn.getYRot(), -20.0F, velocity, 1.0F);
            if (worldIn.addFreshEntity(thrownBrew)) {
                SEHelper.addCooldown(playerIn, this, MathHelper.secondsToTicks(1));
            }
        }

        playerIn.awardStat(Stats.ITEM_USED.get(this));
        if (!playerIn.getAbilities().instabuild) {
            itemstack.shrink(1);
        }
        return InteractionResultHolder.sidedSuccess(itemstack, worldIn.isClientSide());
    } else if (getDrinkBrew(itemstack) != null){
        playerIn.startUsingItem(handIn);
    }

    return InteractionResultHolder.consume(itemstack);
}

public void activate(Level level, Player player, ItemStack itemStack) {
    if (itemStack.is(this)) {
        if (!level.isClientSide) {
            if (player.isShiftKeyDown()) {
                SimpleMenuProvider provider = new SimpleMenuProvider(
                        (id, inventory, playerIn) -> new EternalCauldronContainer(id, inventory, EternalCauldronItemHandler.get(itemStack), itemStack), getName(itemStack));
                NetworkHooks.openScreen((ServerPlayer) player, provider, (buffer) -> {});
            } else {
                if (!getBottle(itemStack).isEmpty() && !SEHelper.isOnCooldown(player, itemStack)) {
                    ItemStack bottle = getBottle(itemStack);
                    int duration = MathHelper.secondsToTicks(45);
                    int add = 1;
                    for(MobEffectInstance mobeffectinstance : PotionUtils.getMobEffects(bottle)) {
                        BrewEffect brewEffect = BrewEffects.INSTANCE.getBrewEffect(mobeffectinstance.getDescriptionId());
                        int amp = 1;
                        amp += mobeffectinstance.getAmplifier();
                        if (brewEffect != null) {
                            add += (brewEffect.getCapacityExtra() * amp);
                        } else if (amp > 1) {
                            add += amp - 1;
                        }
                        if (mobeffectinstance.getEffect().isInstantenous()) {
                            mobeffectinstance.getEffect().applyInstantenousEffect(player, player, player, mobeffectinstance.getAmplifier(), 1.0D);
                        } else {
                            player.addEffect(new MobEffectInstance(mobeffectinstance));
                        }
                    }
                    for (BrewEffectInstance brewEffectInstance : BrewUtils.getBrewEffects(bottle)){
                        brewEffectInstance.getEffect().drinkBlockEffect(player, player, player, brewEffectInstance.getAmplifier(), BrewUtils.getAreaOfEffect(bottle));
                    }
                    ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(ModSounds.POTION_DRINK.get(), 1.0F, 1.0F));
                    SEHelper.addCooldown(player, this, duration * add);
                }
            }
        }
    }
}

