                            }
                        }
                        player.addEffect(new MobEffectInstance(MobEffects.CONDUIT_POWER, duration * 2, 0, false, false));
                    }
                }
            }
        }
    }
    super.inventoryTick(stack, worldIn, entityIn, itemSlot, isSelected);
