public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
  ItemStack bow = player.getItemInHand(hand);
  ToolStack tool = ToolStack.from(bow);
  if (tool.isBroken()) {
    return InteractionResultHolder.fail(bow);
  }

  // locate ammo as requested by the item properties
  // if we have ballista capabilities, use the broader predicate
  boolean isBallista = isBallista(tool);
  ItemStack ammo = BowAmmoModifierHook.getAmmo(tool, bow, player, isBallista ? getSupportedBallistaAmmo() : getSupportedHeldProjectiles());
  // ask forge if it has any different opinions
  InteractionResultHolder<ItemStack> override = ForgeEventFactory.onArrowNock(bow, level, player, hand, !ammo.isEmpty());
  if (override != null) {
    return override;
  }
  // if no ammo, cannot fire
  // however, we can use a modifier if enabled
  if (!player.getAbilities().instabuild && ammo.isEmpty() && !tool.getModifiers().has(TinkerTags.Modifiers.CHARGE_EMPTY_BOW_WITH_DRAWTIME)) {
    // however, modifiers such as block can trigger for no drawtime
    if (tool.getModifiers().has(TinkerTags.Modifiers.CHARGE_EMPTY_BOW_WITHOUT_DRAWTIME)) {
      player.startUsingItem(hand);
      return InteractionResultHolder.consume(bow);
    }
    return InteractionResultHolder.fail(bow);
  }
  GeneralInteractionModifierHook.startDrawing(tool, player, 1);
  // store either ammo or boolean as requested
  if (!ammo.isEmpty()) {
    if (storeDrawingItem) {
      tool.getPersistentData().put(KEY_DRAWBACK_AMMO, ammo.save(new CompoundTag()));
    } else {
      // boolean is enough to get detected by the property override, but won't bother the model
      tool.getPersistentData().putBoolean(KEY_DRAWBACK_AMMO, true);
    }
    // if its ballista ammo, mark that in NBT
    if (isBallista) {
      int flag;
      if (ammo.is(TinkerTags.Items.BALLISTA_AMMO)) {
        flag = ammo == player.getMainHandItem() || ammo == player.getOffhandItem() ? FLAG_BALLISTA_HELD : FLAG_BALLISTA_QUIVER;
      } else {
        flag = FLAG_NO_BALLISTA;
      }
      tool.getPersistentData().putInt(KEY_BALLISTA, flag);
    }
  }
  player.startUsingItem(hand);
  if (!level.isClientSide) {
    level.playSound(null, player.getX(), player.getY(), player.getZ(), Sounds.LONGBOW_CHARGE.getSound(), SoundSource.PLAYERS, 0.75F, 1.0F);
  }
  return InteractionResultHolder.consume(bow);
}

public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
  ItemStack bow = player.getItemInHand(hand);

  ToolStack tool = ToolStack.from(bow);
  if (tool.isBroken()) {
    return InteractionResultHolder.fail(bow);
  }

  // yeah, its hardcoded, I cannot see a need to not hardcode this, request it if you need it
  boolean sinistral = hand == InteractionHand.MAIN_HAND && tool.getModifierLevel(TinkerModifiers.sinistral.getId()) > 0;

  // no ammo? not charged
  ModDataNBT persistentData = tool.getPersistentData();
  CompoundTag heldAmmo = persistentData.getCompound(KEY_CROSSBOW_AMMO);
  if (heldAmmo.isEmpty()) {
    // do not charge if sneaking and we have sinistral, gives you a way to activate the offhand when the crossbow is not charged
    if (sinistral && !player.getOffhandItem().isEmpty() && player.isCrouching()) {
      return InteractionResultHolder.pass(bow);
    }

    // if we have ammo, start charging
    ItemStack ammo = BowAmmoModifierHook.getAmmo(tool, bow, player, getSupportedHeldProjectiles());
    if (!ammo.isEmpty() || tool.getModifiers().has(TinkerTags.Modifiers.CHARGE_EMPTY_BOW_WITH_DRAWTIME)) {
      GeneralInteractionModifierHook.startDrawing(tool, player, 1);
      if (!ammo.isEmpty()) {
        if (storeDrawingItem) {
          persistentData.put(KEY_DRAWBACK_AMMO, ammo.save(new CompoundTag()));
        } else {
          // boolean is enough to get detected by the property override, but won't bother the model
          persistentData.putBoolean(KEY_DRAWBACK_AMMO, true);
        }
      }
      player.startUsingItem(hand);
      if (!level.isClientSide) {
        level.playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.CROSSBOW_QUICK_CHARGE_1, SoundSource.PLAYERS, 0.75F, 1.0F);
      }
      return InteractionResultHolder.consume(bow);
    }
    // can also block without ammo
    if (tool.getModifiers().has(TinkerTags.Modifiers.CHARGE_EMPTY_BOW_WITHOUT_DRAWTIME)) {
      player.startUsingItem(hand);
      return InteractionResultHolder.consume(bow);
    }
    return InteractionResultHolder.fail(bow);
  }

  // coming down here means we have ammo, try to use it

  // sinistral shoots on left click when in main hand, and lets us block instead of shooting if the offhand is empty
  if (sinistral) {
    ItemStack offhand = player.getOffhandItem();
    if (!offhand.isEmpty() && !offhand.is(Items.FIREWORK_ROCKET)) {
      return InteractionResultHolder.pass(bow);
    }
    // can block while filled with ammo
    if (ModifierUtil.canPerformAction(tool, ToolActions.SHIELD_BLOCK)) {
      player.startUsingItem(hand);
      return InteractionResultHolder.consume(bow);
    }
  }

  // ammo already loaded? time to fire
  fireCrossbow(tool, player, hand, heldAmmo);
  return InteractionResultHolder.consume(bow);
}

public static void removeRandomEffect(LivingEntity living) {
  if (!living.level().isClientSide) {
    Collection<MobEffectInstance> effects = living.getActiveEffects();
    if (!effects.isEmpty()) {
      // don't remove effects that are not milk removable
      List<MobEffect> removable = effects.stream().filter(effect -> effect.getCurativeItems().stream().anyMatch(item -> item.is(Items.MILK_BUCKET))).map(MobEffectInstance::getEffect).toList();
      if (!removable.isEmpty()) {
        living.removeEffect(removable.get(living.getRandom().nextInt(removable.size())));
      }
    }
  }
}

private static boolean handleStackOn(ItemStack stack, ItemStack toolItem, Player player, int amount) {
  SlotType slotType = getSlot(stack);
  if (slotType != null && !toolItem.isEmpty() && toolItem.is(TinkerTags.Items.MODIFIABLE)) {
    if (!player.level().isClientSide || (player.isCreative() && player.containerMenu.menuType == null)) {
      if (canApply(player)) {
        ToolStack tool = ToolStack.from(toolItem);
        // do nothing if the tool already has 0 slots and we are removing
        if (tool.getFreeSlots(slotType) + amount < 0) {
          return true;
        }

        // find the tool data
        ModDataNBT persistentData = tool.getPersistentData();
        CompoundTag slots;
        if (persistentData.contains(CreativeSlotModifier.KEY_SLOTS, Tag.TAG_COMPOUND)) {
          slots = persistentData.getCompound(CreativeSlotModifier.KEY_SLOTS);
        } else {
          slots = new CompoundTag();
          persistentData.put(CreativeSlotModifier.KEY_SLOTS, slots);
        }

        // add the slot
        String name = slotType.getName();
        int updated = slots.getInt(name) + amount;
        if (updated == 0) {
          slots.remove(name);
        } else {
          slots.putInt(name, updated);
        }

        // if no slot remain in the creative modifier, remove it
        ModifierId creative = TinkerModifiers.creativeSlot.getId();
        int currentLevel = tool.getModifierLevel(creative);
        if (slots.isEmpty()) {
          // if no slots exist anymore, remove the creative modifier
          persistentData.remove(CreativeSlotModifier.KEY_SLOTS);
          tool.removeModifier(creative, currentLevel);
        } else if (currentLevel == 0) {
          // add creative modifier if needed
          tool.addModifier(creative, 1);
        } else {
          // neither add or removing modifier, just build it
          tool.rebuildStats();
        }
        if (amount > 0) {
          FluidTransferHelper.playUISound(player, SoundEvents.ENCHANTMENT_TABLE_USE);
        } else {
          FluidTransferHelper.playUISound(player, SoundEvents.GRINDSTONE_USE);
        }
      } else if (!player.isCreative()) {
        player.displayClientMessage(CREATIVE_ONLY, false);
      }
    }
    return true;
  }
  return false;
}

public boolean overrideOtherStackedOnMe(ItemStack stack, ItemStack toolItem, Slot slot, ClickAction action, Player player, SlotAccess access) {
  // stacking a tool on a crystal attempts to remove the modifier in creative
  // see also - modifier removal command

  // must be op or in creative, right-clicking onto a modifiable slot with a tool
  if (action == ClickAction.SECONDARY && slot.allowModification(player) && !toolItem.isEmpty() && toolItem.is(TinkerTags.Items.MODIFIABLE) && (player.isCreative() || player.hasPermissions(MantleCommand.PERMISSION_GAME_COMMANDS))) {
    // NBT must be valid
    ModifierId modifier = getModifier(stack);
    if (modifier != null) {
      if (!player.level().isClientSide || (player.isCreative() && player.containerMenu.menuType == null)) {
        ToolStack original = ToolStack.from(toolItem);
        ToolStack tool = original.copy();

        // ensure we have something to remove
        ModifierEntry entry = tool.getUpgrades().getEntry(modifier);
        if (entry.getLevel() <= 0) {
          return true;
        }
        // call remove hook
        int newLevel = entry.getLevel() - stack.getCount();
        if (newLevel <= 0) {
          entry.getHook(ModifierHooks.RAW_DATA).removeRawData(tool, entry.getModifier(), tool.getRestrictedNBT());
        }
        tool.removeModifier(modifier, stack.getCount());

        // ensure no modifier problems after adding
        Component toolValidation = tool.tryValidate();
        if (toolValidation != null) {
          player.displayClientMessage(toolValidation, false);
          return true;
        }

        // ask modifiers if it's okay to remove them
        toolValidation = ModifierRemovalHook.onRemoved(original, tool);
        if (toolValidation != null) {
          player.displayClientMessage(toolValidation, false);
          return true;
        }

        // success, update tool
        tool.updateStack(toolItem);
        FluidTransferHelper.playUISound(player, SoundEvents.GRINDSTONE_USE);
      }
      return true;
    }
    return false;
  }
  return false;
}

public void onUpdate() {
    super.onUpdate();
    int level = getLevel();
    if (level > 0) {
        if (!isRemote()) {
            if (player.level().getGameTime() % 100 == 8) {
                if (Arrays.stream(EquipmentSlot.values()).filter(i -> i.getType() == EquipmentSlot.Type.HUMANOID_ARMOR).map(player::getItemBySlot).allMatch(i -> i.is(ModItemTags.HUNTER_COAT))) {
                    if (this.getSkillHandler().isSkillEnabled(HunterSkills.ARMOR_JUMP)) {
                        MobEffectInstance mobEffectInstance = new MobEffectInstance(MobEffects.JUMP_BOOST, -1, 0, false, false);
                        mobEffectInstance.factions$addProperty(HunterSkills.ARMOR_JUMP.getId());
                        player.addEffect(mobEffectInstance);
                    } else {
                        IEffectInstanceWithSource.removePotionEffect(player, MobEffects.JUMP_BOOST, HunterSkills.ARMOR_JUMP.getId());
                    }
                    if (this.getSkillHandler().isSkillEnabled(HunterSkills.ARMOR_SPEED)) {
                        MobEffectInstance mobEffectInstance = new MobEffectInstance(MobEffects.SPEED, -1, 0, false, false);
                        mobEffectInstance.factions$addProperty(HunterSkills.ARMOR_SPEED.getId());
                        player.addEffect(mobEffectInstance);
                    } else {
                        IEffectInstanceWithSource.removePotionEffect(player, MobEffects.SPEED, HunterSkills.ARMOR_SPEED.getId());
                    }
                } else {
                    IEffectInstanceWithSource.removePotionEffect(player, MobEffects.JUMP_BOOST, HunterSkills.ARMOR_JUMP.getId());
                    IEffectInstanceWithSource.removePotionEffect(player, MobEffects.SPEED, HunterSkills.ARMOR_SPEED.getId());
                }
            }
        } else {
            if (getSpecialAttributes().blessingSoundReference != null && !player.isUsingItem()) {
                //Make sure the blessing sound is stopped when player is not using {@link BlessableItem}. This is necessary because onReleaseUsing is not called for other client players.
                getSpecialAttributes().blessingSoundReference.stopPlaying();
                getSpecialAttributes().blessingSoundReference = null;
            }
            VampirismMod.proxy.handleSleepClient(player);

        }
    } else {
        if (this.player.level().getGameTime() % 100 == 16) {
            if (!OilUtils.getEquippedArmorOils(this.player).isEmpty()) {
                this.player.addEffect(new MobEffectInstance(ModEffects.TOXICANT, 120, 0, false, false));
            }
            IEffectInstanceWithSource.removePotionEffect(player, MobEffects.JUMP_BOOST, HunterSkills.ARMOR_JUMP.getId());
            IEffectInstanceWithSource.removePotionEffect(player, MobEffects.SPEED, HunterSkills.ARMOR_SPEED.getId());
        }
    }
    getSpecialAttributes().fullHunterCoat = level > 0 ? HunterCoatItem.isFullyEquipped(player) : null;

}

public void inventoryTick(ItemStack stack, ServerLevel level, Entity entity, @Nullable EquipmentSlot slot) {
    super.inventoryTick(stack, level, entity, slot);

    if (entity.tickCount % 45 == 3 && slot != null && slot.isArmor() && entity instanceof Player player) {
        Equippable equippable = components().get(DataComponents.EQUIPPABLE);
        if (equippable != null && equippable.slot() == EquipmentSlot.CHEST) {
            boolean flag = true;
            int boost = Integer.MAX_VALUE;

            for (var armorStack : Arrays.stream(EquipmentSlot.values()).filter(x -> x.getType() == EquipmentSlot.Type.HUMANOID_ARMOR).map(player::getItemBySlot).toList()) {
                if (!armorStack.isEmpty() && armorStack.getItem() instanceof ArmorOfSwiftnessItem) {
                    int b = getJumpBoost(getVampirismTier());
                    if (b < boost) {
                        boost = b;
                    }
                } else {
                    flag = false;
                    break;
                }
            }
            if (flag && boost > -1) {
                player.addEffect(new MobEffectInstance(MobEffects.JUMP_BOOST, 50, boost, false, false));
            }
        }
    }
}

