public int onTargetHit(Minigun minigun, ItemStack ammo, Entity target) {
    ItemStack potion = getPotionStack(ammo);
    if (!potion.isEmpty() && target instanceof LivingEntity entity) {
        Player shooter = minigun.getPlayer();
        if (minigun.dispenserWeightedPercentage(ConfigHelper.common().minigun.potionProcChance.get(), 0.25f)) {
            if (potion.getItem() == Items.POTION) {
                potion.getOrDefault(DataComponents.POTION_CONTENTS, PotionContents.EMPTY)
                        .forEachEffect(effect -> entity.addEffect(new MobEffectInstance(effect)));
                entity.level().playSound(null, entity.blockPosition(), SoundEvents.SPLASH_POTION_BREAK, SoundSource.PLAYERS, 1f, 1f);
            } else if (potion.getItem() == Items.SPLASH_POTION || potion.getItem() == Items.LINGERING_POTION) {
                ThrownPotion entityPotion = new ThrownPotion(shooter.level(), shooter);
                entityPotion.setItem(potion);
                entityPotion.setPos(entity.getX(), entity.getY(), entity.getZ());
                shooter.level().addFreshEntity(entityPotion);
            }
        }
        return getPotionAmmoCost(potion.getItem());
    } else {
        return super.onTargetHit(minigun, ammo, target);
    }
}

public void copyItemToFakePlayer(int slot) {
    if (!fakePlayerReady) return;

    FakePlayer fakePlayer = holder.getFakePlayer();

    // As it stands, drone inv can't go above 36 items (max 35 inv upgrades),
    // but let's be paranoid here
    if (slot >= fakePlayer.getInventory().items.size()) return;

    // not a copy: any changes to items in the fake player should also be reflected in the drone's item handler
    ItemStack newStack = getStackInSlot(slot);

    fakePlayer.getInventory().items.set(slot, newStack);
    if (slot == fakePlayer.getInventory().selected) {
        // currentItem is always 0 but we'll use that rather than a literal 0
        // maybe one day drones will be able to change their current held-item slot
        fakePlayer.setItemInHand(InteractionHand.MAIN_HAND, newStack);
        if (!prevHeldStack.isEmpty()) {
            prevHeldStack.forEachModifier(EquipmentSlot.MAINHAND, (holder, modifier) -> {
                AttributeInstance instance = fakePlayer.getAttributes().getInstance(holder);
                if (instance != null) {
                    instance.removeModifier(modifier);
                }
            });
        }
        if (!newStack.isEmpty()) {
            fakePlayer.getMainHandItem().forEachModifier(EquipmentSlot.MAINHAND, (holder, modifier) -> {
                AttributeInstance instance = fakePlayer.getAttributes().getInstance(holder);
                if (instance != null) {
                    instance.removeModifier(modifier.id());
                    instance.addTransientModifier(modifier);
                }
            });
        }
        prevHeldStack = newStack.copy();
    }
}

public InteractionResult use(Level level, Player player, InteractionHand hand) {
	ItemStack stack = player.getItemInHand(hand);

	if (stack.get(TFDataComponents.THROWN_PROJECTILE) != null || !level.getWorldBorder().isWithinBounds(player.blockPosition()))
		return InteractionResult.PASS;

	player.playSound(TFSounds.BLOCK_AND_CHAIN_FIRED.get(), 0.5F, 1.0F / (level.getRandom().nextFloat() * 0.4F + 1.2F));

	if (!level.isClientSide()) {
		ChainBlock launchedBlock = new ChainBlock(TFEntities.CHAIN_BLOCK.get(), level, player, hand, stack);
		launchedBlock.setOwner(player);
		level.addFreshEntity(launchedBlock);
		stack.set(TFDataComponents.THROWN_PROJECTILE, launchedBlock.getUUID());
	}

	player.startUsingItem(hand);
	return InteractionResult.SUCCESS;
}

public InteractionResult performScepterAction(Level level, ItemStack stack, Player player, InteractionHand hand) {
	if (!level.isClientSide()) {
		player.getData(TFDataAttachments.FORTIFICATION_SHIELDS).setShields(player, 5, true);
		if (!player.isCreative()) {
			stack.hurtWithoutBreaking(1, player);
		}
