		player.getCooldowns().addCooldown(stack, 1200);
	}
	return InteractionResult.SUCCESS;
}

public void onUseTick(Level level, LivingEntity living, ItemStack stack, int count) {
	if (stack.nextDamageWillBreak()) {
		// do not use
		living.stopUsingItem();
		return;
	}

	if (count % 5 == 0 && level instanceof ServerLevel serverLevel) {
		// is the player looking at an entity
		Entity pointedEntity = this.getPlayerLookTarget(level, living);

		if (pointedEntity instanceof LivingEntity target && !(target instanceof ArmorStand) && target.isPickable()) {
			if (!target.isDeadOrDying()) {
				PacketDistributor.sendToPlayersTrackingEntityAndSelf(living, new LifedrainParticlePacket(living.getId(), target.getEyePosition()));
				level.playSound(null, living.blockPosition(), TFSounds.LIFE_SCEPTER_DRAIN.get(), SoundSource.PLAYERS);
			}

			DamageSource damageSource = TFDamageTypes.getEntityDamageSource(level, TFDamageTypes.LIFEDRAIN, living);
			if (target.hurtServer(serverLevel, damageSource, 1)) {
				// make it explode
				if (target.getHealth() <= 1 && !target.is(Tags.EntityTypes.BOSSES)) {
					if (!target.is(TFEntityTypeTags.LIFEDRAIN_DROPS_NO_FLESH) && living instanceof Player player) {
						LootParams ctx = new LootParams.Builder(serverLevel)
							.withParameter(LootContextParams.THIS_ENTITY, target)
							.withParameter(LootContextParams.ORIGIN, target.getEyePosition())
							.withParameter(LootContextParams.DAMAGE_SOURCE, damageSource)
							.withParameter(LootContextParams.LAST_DAMAGE_PLAYER, player)
							.withParameter(LootContextParams.ATTACKING_ENTITY, player)
							.withParameter(LootContextParams.DIRECT_ATTACKING_ENTITY, player).create(LootContextParamSets.ENTITY);
						serverLevel.getServer().reloadableRegistries().getLootTable(TFLootTables.LIFEDRAIN_SCEPTER_KILL_BONUS).getRandomItems(ctx).forEach(stack1 -> target.spawnAtLocation(serverLevel, stack1));
						animateTargetShatter(serverLevel, target);
					}

					if (target instanceof Mob mob) {
						mob.spawnAnim();
					}
					SoundEvent deathSound = EntityUtil.getDeathSound(target);
					if (deathSound != null) {
						level.playSound(null, target.blockPosition(), deathSound, SoundSource.HOSTILE, 1.0F, target.getVoicePitch());
					}
					if (!target.isDeadOrDying()) {
						if (target instanceof Player) {
							target.hurtServer(serverLevel, TFDamageTypes.getEntityDamageSource(level, TFDamageTypes.LIFEDRAIN, living), Float.MAX_VALUE);
						} else {
							target.die(TFDamageTypes.getEntityDamageSource(level, TFDamageTypes.LIFEDRAIN, living));
							target.discard();
						}
					}
				} else {
					target.addEffect(new MobEffectInstance(MobEffects.SLOWNESS, 20, 2));
					if (count % 10 == 0) {
						// heal the player
						living.heal(1.0F);
						// and give foods
						if (living instanceof Player player)
							player.getFoodData().eat(1, 0.1F);
					}
				}

				if (living instanceof Player player && !player.isCreative() && (!player.getItemBySlot(EquipmentSlot.HEAD).is(TFItems.MYSTIC_CROWN) || level.getRandom().nextFloat() > 0.05f)) {
					stack.hurtWithoutBreaking(1, player);
				}
			}

			if (!level.isClientSide() && target.getHealth() <= living.getHealth()) {
				// only do lifting effect on creatures weaker than the player
				target.setDeltaMovement(0, 0.15D, 0);
			}
		}
	}
}

public InteractionResult use(Level level, Player player, InteractionHand hand) {
	ItemStack stack = player.getItemInHand(hand);

	boolean flag = !player.onGround() && !player.isSwimming() && !player.getData(TFDataAttachments.FEATHER_FAN);

	if (!level.isClientSide()) {
		int fanned = peacockFeatherFanAction.fan(level, player.getEyePosition(), player.getLookAngle(), player, stack);
		stack.hurtAndBreak(fanned + 1, player, hand);
		if (flag) {
			player.setData(TFDataAttachments.FEATHER_FAN, true);
		} else {
			peacockFeatherFanAction.spawnParticles(level, player.getEyePosition(), player.getLookAngle());
		}
		peacockFeatherFanAction.playWhoosh(level, player.blockPosition(), SoundSource.PLAYERS);
	} else {
		if (player.isFallFlying()) {
			Vec3 look = player.getLookAngle();
			Vec3 movement = player.getDeltaMovement();
			//add a directional boost similar to the rocket, but slightly faster and always add a little more upwards
			player.setDeltaMovement(movement.add(
				look.x() * 0.1D + (look.x() * 2.0D - movement.x()) * 0.5D,
				(look.y() * 0.1D + (look.y() * 2.0D - movement.y()) * 0.5D) + 1.25D,
				look.z() * 0.1D + (look.z() * 2.0D - movement.z()) * 0.5D
			));
		}
		// jump if the player is in the air
		if (flag) {
			player.setDeltaMovement(new Vec3(
				player.getDeltaMovement().x() * 1.05F,
				1.5F,
				player.getDeltaMovement().z() * 1.05F
			));
		}
		return InteractionResult.SUCCESS;
	}

	player.startUsingItem(hand);

	return InteractionResult.PASS;
}

public void inventoryTick(ItemStack itemStack, ServerLevel level, Entity owner, @Nullable EquipmentSlot slot) {
	if (!(owner instanceof Player player))
		return;

	if (slot == null) {
		for (int i = 0; i <= 8; i++) {
			if (!player.getInventory().getItem(i).is(this))
				continue;
			player.addEffect(new MobEffectInstance(MobEffects.SPEED, 5, 0, false, false, false));
			player.addEffect(new MobEffectInstance(MobEffects.JUMP_BOOST, 5, 0, false, false, false));
			break;
		}
	}

	if (player.isHolding(this)) {
		player.addEffect(new MobEffectInstance(MobEffects.SPEED, 5, 0, false, false, false));
		player.addEffect(new MobEffectInstance(MobEffects.JUMP_BOOST, 5, 0, false, false, false));
		player.addEffect(new MobEffectInstance(MobEffects.HASTE, 5, 0, false, false, false));
	}
}

private boolean applyOrStackEffect(StackableEffectInstance effect, LivingEntity user) {
	int currentDuration = 0;
	MobEffectInstance activeEffect = user.getEffect(effect.effect());
	if (activeEffect != null) {
		currentDuration = activeEffect.getDuration();
	}
	return user.addEffect(new MobEffectInstance(effect.effect(), currentDuration + effect.extraDurationTicks(), effect.amplifier()));
}

public static void travellersBootsStraightAhead(LivingEntity livingEntity) {
	ItemStack leggingsStack = livingEntity.getItemBySlot(EquipmentSlot.FEET);
	Double multiplier = leggingsStack.get(TFDataComponents.STRAIGHT_AHEAD_MULTIPLIER);
	AttributeInstance attributeInstance = livingEntity.getAttributes().getInstance(Attributes.MOVEMENT_SPEED);
	if (attributeInstance == null)
		return;
	if (multiplier == null)
		multiplier = 1D;
	boolean hasModifier = TravellersModifiersManager.isModifierActive(livingEntity, leggingsStack, TravellersModifiersManager.STRAIGHT_AHEAD_MODIFIER) && multiplier != 1;
	if (hasModifier == attributeInstance.hasModifier(TFAttributeModifiers.STRAIGHT_AHEAD_ATTRIBUTE_MODIFIER_LOCATION))
		return;
	if (hasModifier) {
		attributeInstance.addOrUpdateTransientModifier(new AttributeModifier(TFAttributeModifiers.STRAIGHT_AHEAD_ATTRIBUTE_MODIFIER_LOCATION, multiplier - 1, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));
	} else {
		attributeInstance.removeModifier(TFAttributeModifiers.STRAIGHT_AHEAD_ATTRIBUTE_MODIFIER_LOCATION);
	}

}

public static void travellersWingsHighJump(LivingEntity livingEntity) {
	ItemStack leggingsStack = livingEntity.getItemBySlot(EquipmentSlot.LEGS);
	Integer amplifier = leggingsStack.get(TFDataComponents.HIGH_JUMP_AMPLIFIER);
	if (TravellersModifiersManager.isModifierActive(livingEntity, leggingsStack, TravellersModifiersManager.HIGH_JUMP_ABILITY) && amplifier != null)
		livingEntity.addEffect(new MobEffectInstance(MobEffects.JUMP_BOOST, 2, amplifier, false, false, false));
}

public void removeModifier(ItemStack stack) {
	if (!this.builtin()) {
		List<ItemAttributeModifiers.Entry> newEntries = new ArrayList<>();
		var modifiers = stack.getAttributeModifiers();
		modifiers.modifiers().forEach(entry -> {
			if (!this.modifiers().contains(entry)) {
				newEntries.add(entry);
			}
		});
		stack.set(DataComponents.ATTRIBUTE_MODIFIERS, new ItemAttributeModifiers(newEntries));
		stack.remove(this.markerComponent());
	}
}

default void setCooldown(World world, @Nullable EntityPlayer player, @Nullable EnumHand hand, ItemStack stack, @Nonnull SpellData data) {
	int maxCooldown = 0;

	List<SpellRing> rings = SpellUtils.getAllSpellRings(stack);

	for (SpellRing ring : rings) {
		if (ring.isContinuous()) return;

		if (ring.getModule() != null && ring.getModule().getModuleClass() instanceof IOverrideCooldown) {

			maxCooldown = ring.getCooldownTime(world, data);
			break;
		}
		if (ring.getCooldownTime() > maxCooldown)
			maxCooldown = ring.getCooldownTime();
	}

	if (maxCooldown <= 0) return;

	if (player != null && hand != null) {
		player.stopActiveHand();
		player.swingArm(hand);
		if (!world.isRemote)
			if (hand == EnumHand.MAIN_HAND)
				PacketHandler.NETWORK.sendTo(new PacketSyncCooldown(true, false), (EntityPlayerMP) player);
			else PacketHandler.NETWORK.sendTo(new PacketSyncCooldown(false, true), (EntityPlayerMP) player);
	}

	NBTHelper.setInt(stack, NBTConstants.NBT.LAST_COOLDOWN, maxCooldown);
	NBTHelper.setLong(stack, NBTConstants.NBT.LAST_CAST, world.getTotalWorldTime());
}

