public static DamageSource onEntityAttacked(DamageSource source, float amount, Player player, LivingEntity entity) {
	if (hasTerraArmorSet(player)) {
		ItemStack stack = player.getItemBySlot(EquipmentSlot.HEAD);
		if (!stack.isEmpty() && stack.getItem() instanceof TerrasteelHelmItem) {
			if (hasAncientWill_(stack, AncientWillType.AHRIM)) {
				entity.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 20, 1));
			}
			if (hasAncientWill_(stack, AncientWillType.GUTHAN)) {
				player.heal(amount * 0.25F);
			}
			if (hasAncientWill_(stack, AncientWillType.TORAG)) {
				entity.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, 60, 1));
			}
			if (hasAncientWill_(stack, AncientWillType.VERAC)) {
				source = BotaniaDamageTypes.Sources.playerAttackArmorPiercing(player.level().registryAccess(), player);
			}
			if (hasAncientWill_(stack, AncientWillType.KARIL)) {
				entity.addEffect(new MobEffectInstance(MobEffects.WITHER, 60, 1));
			}
		}
	}
	return source;
}

public float onPlayerDamage(Player player, DamageSource src, float amount) {
	if (!src.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
		ItemStack stack = EquipmentHandler.findOrEmpty(this, player);

		if (!stack.isEmpty() && !isInEffect(stack)) {
			CloakOfVirtueItem cloak = (CloakOfVirtueItem) stack.getItem();
			int cooldown = getCooldown(stack);

			// Used to prevent StackOverflows with mobs that deal damage when damaged
			setInEffect(stack, true);
			MutableFloat mutAmount = new MutableFloat(amount);
			if (cooldown == 0 && cloak.effectOnDamage(src, mutAmount, player, stack)) {
				setCooldown(stack, cloak.getCooldownTime(stack));
			}
			setInEffect(stack, false);
			return mutAmount.getValue();
		}
	}
	return amount;
}

public void onWornTick(ItemStack stack, LivingEntity living) {
	if (living instanceof Player player) {
		boolean flying = player.getAbilities().flying;

		boolean wasSprting = ItemNBTHelper.getBoolean(stack, TAG_IS_SPRINTING, false);
		boolean isSprinting = player.isSprinting();
		if (isSprinting != wasSprting) {
			ItemNBTHelper.setBoolean(stack, TAG_IS_SPRINTING, isSprinting);
		}

		int time = ItemNBTHelper.getInt(stack, TAG_TIME_LEFT, MAX_FLY_TIME);
		int newTime = time;
		Vec3 look = player.getLookAngle().multiply(1, 0, 1).normalize();

		if (flying) {
			if (time > 0 && !player.isSpectator() && !player.isCreative()
					&& !ItemNBTHelper.getBoolean(stack, TAG_INFINITE_FLIGHT, false)) {
				newTime--;
			}
			final int maxCd = 80;
			int cooldown = ItemNBTHelper.getInt(stack, TAG_DASH_COOLDOWN, 0);
			if (!wasSprting && isSprinting && cooldown == 0 && !StoneOfTemperanceItem.hasTemperanceActive(player)) {
				player.setDeltaMovement(player.getDeltaMovement().add(look.x, 0, look.z));
				player.level().playSound(null, player.getX(), player.getY(), player.getZ(), BotaniaSounds.dash, SoundSource.PLAYERS, 1F, 1F);
				ItemNBTHelper.setInt(stack, TAG_DASH_COOLDOWN, maxCd);
				ItemNBTHelper.setBoolean(stack, TAG_BOOST_PENDING, true);
			} else if (cooldown > 0) {
				if (ItemNBTHelper.getBoolean(stack, TAG_BOOST_PENDING, false)) {
					living.moveRelative(5F, new Vec3(0F, 0F, 1F));
					ItemNBTHelper.removeEntry(stack, TAG_BOOST_PENDING);
				}
				ItemNBTHelper.setInt(stack, TAG_DASH_COOLDOWN, cooldown - 2);
			}
		} else {
			boolean wasGliding = ItemNBTHelper.getBoolean(stack, TAG_GLIDING, false);
			boolean doGlide = living.isShiftKeyDown() && !living.onGround() && (living.getDeltaMovement().y() < -.7F || wasGliding);
			if (time < MAX_FLY_TIME && living.tickCount % (doGlide ? 6 : 2) == 0) {
				newTime++;
			}

			if (doGlide) {
				float mul = 0.6F;
				living.setDeltaMovement(look.x * mul, Math.max(-0.15F, living.getDeltaMovement().y()), look.z * mul);
				living.fallDistance = 2F;
			}
			ItemNBTHelper.setBoolean(stack, TAG_GLIDING, doGlide);
		}

		ItemNBTHelper.setBoolean(stack, TAG_FLYING, flying);
		if (newTime != time) {
			ItemNBTHelper.setInt(stack, TAG_TIME_LEFT, newTime);
		}
	}
}

