public void onWornTick(ItemStack stack, LivingEntity living) {
	super.onWornTick(stack, living);

	if (living.isSpectator()) {
		return;
	}

	int cooldown = getCooldown(stack);

	if (BotaniaAPI.instance().hasSolegnoliaAround(living)) {
		if (cooldown < 0) {
			setCooldown(stack, 2);
		}
		return;
	}

	if (cooldown <= 0) {
		if (living.isShiftKeyDown() == BotaniaConfig.common().invertMagnetRing()) {
			double x = living.getX();
			double y = living.getY() + 0.75;
			double z = living.getZ();

			int range = ((RingOfMagnetizationItem) stack.getItem()).range;
			List<ItemEntity> items = living.level().getEntitiesOfClass(ItemEntity.class, new AABB(x - range, y - range, z - range, x + range, y + range, z + range));
			int pulled = 0;
			for (ItemEntity item : items) {
				if (((RingOfMagnetizationItem) stack.getItem()).canPullItem(item)) {
					if (pulled > 200) {
						break;
					}

					MathHelper.setEntityMotionFromVector(item, new Vec3(x, y, z), 0.45F);
					if (living.level().isClientSide) {
						boolean red = living.level().random.nextBoolean();
						float r = red ? 1F : 0F;
						float b = red ? 0F : 1F;
						SparkleParticleData data = SparkleParticleData.sparkle(1F, r, 0F, b, 3);
						living.level().addParticle(data, item.getX(), item.getY(), item.getZ(), 0, 0, 0);
					}
					pulled++;
				}
			}
		}
	} else {
		setCooldown(stack, cooldown - 1);
	}
}

public static void tickBelt(Player player) {
	ItemStack belt = EquipmentHandler.findOrEmpty(s -> s.getItem() instanceof SojournersSashItem, player);

	var stepHeight = XplatAbstractions.INSTANCE.getStepHeightAttribute();
	AttributeInstance attrib = player.getAttribute(stepHeight);
	boolean hasBoost = attrib.hasModifier(STEP_BOOST);

	if (tryConsumeMana(player)) {
		if (player.level().isClientSide) {
			SojournersSashItem beltItem = (SojournersSashItem) belt.getItem();
			if ((player.onGround() || player.getAbilities().flying) && player.zza > 0F && !player.isInWaterOrBubble()) {
				float speed = beltItem.getSpeed(belt);
				player.moveRelative(player.getAbilities().flying ? speed : speed, new Vec3(0, 0, 1));
				beltItem.onMovedTick(belt, player);

				if (player.tickCount % COST_INTERVAL == 0) {
					ManaItemHandler.instance().requestManaExact(belt, player, COST, true);
				}
			} else {
				beltItem.onNotMovingTick(belt, player);
			}
		} else {
			if (player.isShiftKeyDown()) {
				if (hasBoost) {
					attrib.removeModifier(STEP_BOOST);
				}
			} else {
				if (!hasBoost) {
					attrib.addTransientModifier(STEP_BOOST);
				}
			}
		}
	} else if (!player.level().isClientSide && hasBoost) {
		attrib.removeModifier(STEP_BOOST);
	}
}

public void onWornTick(ItemStack stack, LivingEntity living) {
	Brew brew = ((BrewItem) stack.getItem()).getBrew(stack);
	if (brew != BotaniaBrews.fallbackBrew && living instanceof Player player && !living.level().isClientSide) {
		MobEffectInstance effect = brew.getPotionEffects(stack).get(0);
		float cost = (float) brew.getManaCost(stack) / effect.getDuration() / (1 + effect.getAmplifier()) * 2.5F;
		boolean doRand = cost < 1;
		if (ManaItemHandler.instance().requestManaExact(stack, player, (int) Math.ceil(cost), false)) {
			MobEffectInstance currentEffect = living.getEffect(effect.getEffect());
			boolean nightVision = effect.getEffect() == MobEffects.NIGHT_VISION;
			if (currentEffect == null || currentEffect.getDuration() < (nightVision ? 305 : 3)) {
				MobEffectInstance applyEffect = new MobEffectInstance(effect.getEffect(), nightVision ? 385 : 80, effect.getAmplifier(), true, true);
				living.addEffect(applyEffect);
			}

			if (!doRand || Math.random() < cost) {
				ManaItemHandler.instance().requestManaExact(stack, player, (int) Math.ceil(cost), true);
			}
		}
	}
}

