public void inventoryTick(ItemStack stack, Level world, Entity entity, int slot, boolean selected) {
	super.inventoryTick(stack, world, entity, slot, selected);
	if (!(entity instanceof Player player)) {
		return;
	}

	// Initialize timer for new items
	if (!ItemNBTHelper.verifyExistance(stack, TAG_LAST_TRIGGER)) {
		ItemNBTHelper.setLong(stack, TAG_LAST_TRIGGER, world.getGameTime());
	}

	MobEffectInstance haste = player.getEffect(MobEffects.DIG_SPEED);
	float check = haste == null ? 0.16666667F : haste.getAmplifier() == 1 ? 0.5F : 0.4F;

	long timeSinceLast = world.getGameTime() - ItemNBTHelper.getLong(stack, TAG_LAST_TRIGGER, world.getGameTime());
	if (timeSinceLast > INTERVAL && player.getMainHandItem() == stack && player.attackAnim == check && !world.isClientSide) {
		ItemNBTHelper.setLong(stack, TAG_LAST_TRIGGER, world.getGameTime());
		summonFallingStar(stack, world, player);
	}
}

public InteractionResult useOn(UseOnContext ctx) {
	Player player = ctx.getPlayer();

	if (player != null) {
		if (ctx.getHand() == InteractionHand.MAIN_HAND && player.getOffhandItem().getItem() instanceof BlockItem) {
			return InteractionResult.PASS;
		}

		for (int i = 0; i < player.getInventory().getContainerSize(); i++) {
			ItemStack stackAt = player.getInventory().getItem(i);
			if (!stackAt.isEmpty() && TORCH_PATTERN.matcher(stackAt.getItem().getDescriptionId()).find()) {
				ItemStack displayStack = stackAt.copy();
				InteractionResult did = PlayerHelper.substituteUse(ctx, stackAt);
				if (did.consumesAction()) {
					if (!ctx.getLevel().isClientSide) {
						ItemsRemainingRenderHandler.send(player, displayStack, TORCH_PATTERN);
					}
					player.getCooldowns().addCooldown(this, TIME);
					return did;
				}
			}
		}
	}
	return InteractionResult.PASS;
}

public InteractionResult useOn(UseOnContext ctx) {
	Level world = ctx.getLevel();
	Player player = ctx.getPlayer();
	ItemStack stack = ctx.getItemInHand();
	BlockPos pos = ctx.getClickedPos();

	if (player != null && ManaItemHandler.instance().requestManaExactForTool(stack, player, COST, false)) {
		if (!world.isClientSide()) {
			FlameRingEntity entity = BotaniaEntities.FLAME_RING.create(world);
			entity.setPos(pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5);
			world.addFreshEntity(entity);

			if (!player.isCreative()) {
				player.getCooldowns().addCooldown(this, ManaItemHandler.instance().hasProficiency(player, stack) ? COOLDOWN / 2 : COOLDOWN);
			}
			ManaItemHandler.instance().requestManaExactForTool(stack, player, COST, true);

			world.gameEvent(player, GameEvent.PROJECTILE_SHOOT, pos);
			ctx.getLevel().playSound(null, pos.getX(), pos.getY(), pos.getZ(), BotaniaSounds.fireRod, SoundSource.PLAYERS, 1F, 1F);
		}
	}

	return InteractionResult.sidedSuccess(world.isClientSide());
}

public InteractionResultHolder<ItemStack> use(Level world, Player player, @NotNull InteractionHand hand) {
	ItemStack stack = player.getItemInHand(hand);
	int targetID = ItemNBTHelper.getInt(stack, TAG_TARGET, -1);
	int ticksCooldown = ItemNBTHelper.getInt(stack, TAG_TICKS_COOLDOWN, 0);
	double length = ItemNBTHelper.getDouble(stack, TAG_DIST, -1);

	if (ticksCooldown == 0) {
		Entity target = null;
		if (targetID != -1 && player.level().getEntity(targetID) != null) {
			Entity taritem = player.level().getEntity(targetID);

			boolean found = false;
			Vec3 targetVec = VecHelper.fromEntityCenter(player);
			List<Entity> entities = new ArrayList<>();
			int distance = 1;
			while (entities.size() == 0 && distance < 25) {
				targetVec = targetVec.add(player.getLookAngle().scale(distance)).add(0, 0.5, 0);
				entities = player.level().getEntities(player, VecHelper.boxForRange(targetVec, RANGE), CAN_TARGET);
				distance++;
				if (entities.contains(taritem)) {
					found = true;
				}
			}

			if (found) {
				target = player.level().getEntity(targetID);
			}
		}

		if (target == null) {
			Vec3 targetVec = VecHelper.fromEntityCenter(player);
			List<Entity> entities = new ArrayList<>();
			int distance = 1;
			while (entities.size() == 0 && distance < 25) {
				targetVec = targetVec.add(player.getLookAngle().scale(distance)).add(0, 0.5, 0);
				entities = player.level().getEntities(player, VecHelper.boxForRange(targetVec, RANGE), CAN_TARGET);
				distance++;
			}

			if (entities.size() > 0) {
				target = entities.get(0);
				length = 5.5D;
				if (target instanceof ItemEntity) {
					length = 2.0D;
				}
			}
		}

		if (target != null) {
			if (target.getType().is(BLACKLIST)) {
				return InteractionResultHolder.fail(stack);
			}

			if (ManaItemHandler.instance().requestManaExactForTool(stack, player, COST, true)) {
				boolean targetIsPlayer = target instanceof Player;

				if (target instanceof ItemEntity item) {
					item.setPickUpDelay(5);
				}

				if (target instanceof LivingEntity living) {
					living.fallDistance = 0.0F;
					if (living.getEffect(MobEffects.MOVEMENT_SLOWDOWN) == null) {
						living.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN,
								targetIsPlayer ? 20 : 2, targetIsPlayer ? 1 : 3, true, true));
					}
				}

				Vec3 target3 = VecHelper.fromEntityCenter(player)
						.add(player.getLookAngle().scale(length)).add(0, 0.5, 0);
				if (target instanceof ItemEntity) {
					target3 = target3.add(0, 0.25, 0);
				}

				for (int i = 0; i < 4; i++) {
					float r = 0.5F + (float) Math.random() * 0.5F;
					float b = 0.5F + (float) Math.random() * 0.5F;
					float s = 0.2F + (float) Math.random() * 0.1F;
					float m = 0.1F;
					float xm = ((float) Math.random() - 0.5F) * m;
					float ym = ((float) Math.random() - 0.5F) * m;
					float zm = ((float) Math.random() - 0.5F) * m;
					WispParticleData data = WispParticleData.wisp(s, r, 0F, b);
					world.addParticle(data, target.getX() + target.getBbWidth() / 2, target.getY() + target.getBbHeight() / 2, target.getZ() + target.getBbWidth() / 2, xm, ym, zm);
				}

				MathHelper.setEntityMotionFromVector(target, target3, 0.3333333F);
				if (targetIsPlayer && target instanceof ServerPlayer p) {
					p.connection.send(new ClientboundSetEntityMotionPacket(p));
				}

				ItemNBTHelper.setInt(stack, TAG_TARGET, target.getId());
				ItemNBTHelper.setDouble(stack, TAG_DIST, length);
			}

			ItemNBTHelper.setInt(stack, TAG_TICKS_TILL_EXPIRE, 5);
			return InteractionResultHolder.consume(stack);
		}
	}
	return InteractionResultHolder.pass(stack);
}

public InteractionResultHolder<ItemStack> use(Level worldIn, Player playerIn, @NotNull InteractionHand handIn) {
	ItemStack itemstack = playerIn.getItemInHand(handIn);
	playerIn.setItemInHand(handIn, ItemStack.EMPTY);
	Holder<Enchantment> enchantment = playerIn.level().registryAccess().registry(Registries.ENCHANTMENT).get().getHolderOrThrow(Enchantments.EFFICIENCY);
	int eff = Quark.ZETA.itemExtensions.get(itemstack).getEnchantmentLevelZeta(itemstack, enchantment);
	Vec3 pos = playerIn.position();
	worldIn.playSound(null, pos.x, pos.y, pos.z, QuarkSounds.ENTITY_PICKARANG_THROW, SoundSource.NEUTRAL, 0.5F + eff * 0.14F, 0.4F / (worldIn.random.nextFloat() * 0.4F + 0.8F));

	if(!worldIn.isClientSide) {
		Inventory inventory = playerIn.getInventory();
		int slot = handIn == InteractionHand.OFF_HAND ? inventory.getContainerSize() - 1 : inventory.selected;
		AbstractPickarang<?> entity = type.makePickarang(worldIn, playerIn);
		entity.setThrowData(slot, itemstack);
		entity.shoot(playerIn, playerIn.getXRot(), playerIn.getYRot(), 0.0F, 1.5F + eff * 0.325F, 0F);
		entity.setOwner(playerIn);

		worldIn.addFreshEntity(entity);

		if(playerIn instanceof ServerPlayer sp)
			PickarangModule.throwPickarangTrigger.trigger(sp);
	}

	if(!playerIn.getAbilities().instabuild && type.cooldown > 0) {
		int cooldown = type.cooldown - eff;
		if(cooldown > 0)
			playerIn.getCooldowns().addCooldown(this, cooldown);
	}

	playerIn.awardStat(Stats.ITEM_USED.get(this));

	return InteractionResultHolder.sidedSuccess( itemstack, worldIn.isClientSide);
}

public void cast(ItemStack stack, PsiArmorEvent event) {
	PlayerData data = PsiPlayerData.get(event.getEntity());
	ItemStack playerCad = PsiAPI.getPlayerCAD(event.getEntity());

	if(IPsimetalTool.isEnabled(stack) && !playerCad.isEmpty()) {
		int timesCast = stack.getOrDefault(ModDataComponents.TIMES_CAST.get(), 0);

		ItemStack bullet = ISocketable.socketable(stack).getSelectedBullet();
		ItemCAD.cast(event.getEntity().getCommandSenderWorld(), event.getEntity(), data, bullet, playerCad, getCastCooldown(stack), 0, getCastVolume(), (SpellContext context) -> {
			context.tool = stack;
			context.attackingEntity = event.attacker;
			context.damageTaken = event.damage;
			context.loopcastIndex = timesCast;
		}, (int) (data.calculateDamageDeduction((float) event.damage) * 0.75));

		stack.set(ModDataComponents.TIMES_CAST.get(), timesCast + 1);
	}
}

static void regen(ItemStack stack, Entity entityIn) {
	if(isItemValidForRegen(stack, entityIn)) {
		Player player = (Player) entityIn;
		PlayerData data = PsiPlayerData.get(player);
		int regenTime = stack.getOrDefault(ModDataComponents.REGEN_TIME.get(), 0);

		if(!data.overflowed && regenTime % 16 == 0 && (float) data.getAvailablePsi() / (float) data.getTotalPsi() > 0.5F) {
			data.deductPsi(150, 0, true);
			stack.setDamageValue(stack.getDamageValue() - 1);
		}
		stack.set(ModDataComponents.REGEN_TIME.get(), regenTime + 1);
	}
}

public int getBurnTime(ItemStack stack)
{
	Binding binding = getBinding(stack);
	if (binding == null)
		return -1;

	if (EffectiveSide.get().isServer())
	{
		if (NetworkHelper.canSyphonFromContainer(stack, 50))
			return 200;
		else
		{
			Player player = PlayerHelper.getPlayerFromUUID(binding.getOwnerId());
			if (player != null)
			{
				player.addEffect(new MobEffectInstance(MobEffects.CONFUSION, 99));
			}
		}
	} else
	{
		return 200;
	}

	return -1;
}

	public InteractionResultHolder<ItemStack> use(Level world, Player player, InteractionHand hand)
	{
		ItemStack stack = player.getItemInHand(hand);
		if (PlayerHelper.isFakePlayer(player))
			return super.use(world, player, hand);

		if (this.canUseForSacrifice(stack))
		{
			player.startUsingItem(hand);
			return InteractionResultHolder.success(stack);
		}

		int lpAdded = ConfigManager.COMMON.sacrificialDaggerConversion.get() * 2;

//		RayTraceResult rayTrace = rayTrace(world, player, false);
//		if (rayTrace != null && rayTrace.typeOfHit == RayTraceResult.Type.BLOCK)
//		{
//			TileEntity tile = world.getTileEntity(rayTrace.getBlockPos());
//
//			if (tile != null && tile instanceof TileAltar && stack.getItemDamage() == 1)
//				lpAdded = ((TileAltar) tile).getCapacity();
//		}

		if (!player.getAbilities().instabuild)
		{
			SacrificeKnifeUsedEvent evt = new SacrificeKnifeUsedEvent(player, true, true, 2, lpAdded);
			if (MinecraftForge.EVENT_BUS.post(evt))
				return super.use(world, player, hand);

			if (evt.shouldDrainHealth)
			{
				player.invulnerableTime = 0;

				player.hurt(player.damageSources().source(BloodMagicDamageTypes.SACRIFICE), 0.001F);
				player.setHealth(Math.max(player.getHealth() - 1.998F, 0.0001f));
				if (player.getHealth() <= 0.001f && !world.isClientSide)
				{
					player.invulnerableTime = 0;
					player.hurt(player.damageSources().source(BloodMagicDamageTypes.SACRIFICE), 10);
				}
			}

			if (!evt.shouldFillAltar)
				return super.use(world, player, hand);

			lpAdded = evt.lpAdded;
		} else if (player.isShiftKeyDown())
		{
			lpAdded = Integer.MAX_VALUE;
		}

		double posX = player.getX();
		double posY = player.getY();
		double posZ = player.getZ();
		world.playSound(player, posX, posY, posZ, SoundEvents.FIRE_EXTINGUISH, SoundSource.BLOCKS, 0.5F, 2.6F + (world.random.nextFloat() - world.random.nextFloat()) * 0.8F);

		for (int l = 0; l < 8; ++l)
			world.addParticle(DustParticleOptions.REDSTONE, posX + Math.random() - Math.random(), posY + Math.random() - Math.random(), posZ + Math.random() - Math.random(), 0, 0, 0);

		if (!world.isClientSide && PlayerHelper.isFakePlayer(player))
			return super.use(world, player, hand);

		// TODO - Check if SoulFray is active
		PlayerSacrificeHelper.findAndFillAltar(world, player, lpAdded, false);

		return super.use(world, player, hand);
	}

public InteractionResultHolder<ItemStack> use(Level world, Player player, InteractionHand hand)
{
	ItemStack stack = player.getItemInHand(hand);
	if (stack.getItem() instanceof ISigil.Holding)
		stack = ((Holding) stack.getItem()).getHeldItem(stack, player);
	if (PlayerHelper.isFakePlayer(player))
		return InteractionResultHolder.fail(stack);

	HitResult mop = getPlayerPOVHitResult(world, player, ClipContext.Fluid.NONE);

	if (getCooldownRemainder(stack) > 0)
		return super.use(world, player, hand);

	if (mop != null && mop.getType() == HitResult.Type.BLOCK)
	{
		BlockHitResult blockRayTrace = (BlockHitResult) mop;
		BlockPos blockPos = blockRayTrace.getBlockPos().relative(blockRayTrace.getDirection());

		if (world.isEmptyBlock(blockPos))
		{
			if (BlockProtectionHelper.tryPlaceBlock(world, blockPos, BloodMagicBlocks.BLOOD_LIGHT.get().defaultBlockState(), player))
			{
				if (!world.isClientSide)
				{
					SoulNetwork network = NetworkHelper.getSoulNetwork(getBinding(stack));
					network.syphonAndDamage(player, SoulTicket.item(stack, world, player, getLpUsed()));
				}
				resetCooldown(stack);
				player.swing(hand);
			}
			return super.use(world, player, hand);
		}
	} else
	{
		if (!world.isClientSide)
		{
			SoulNetwork network = NetworkHelper.getSoulNetwork(getBinding(stack));
			EntityBloodLight light = new EntityBloodLight(world, player);
			light.shootFromRotation(player, player.getXRot(), player.getYRot(), 0.0F, 1.5F, 1.0F);
			world.addFreshEntity(light);
			network.syphonAndDamage(player, SoulTicket.item(stack, world, player, getLpUsed()));
		}
		resetCooldown(stack);
	}

	return super.use(world, player, hand);
}

