public @NotNull InteractionResultHolder<ItemStack> use(Level pLevel, Player pPlayer, @NotNull InteractionHand pHand) {
    ItemStack itemstack = pPlayer.getItemInHand(pHand);
    PotionLauncherData potionLauncherData = itemstack.get(DataComponentRegistry.POTION_LAUNCHER);
    if (pLevel.isClientSide)
        return InteractionResultHolder.consume(itemstack);
    ItemStack selectedPotion = potionLauncherData.getSelectedStack(pPlayer);
    IPotionProvider potionData = potionLauncherData.getPotionDataFromSlot(pPlayer);
    if (potionData == null || PotionUtil.isEmpty(potionData.getPotionData(selectedPotion)) || potionData.usesRemaining(selectedPotion) <= 0) {
        PortUtil.sendMessage(pPlayer, Component.translatable("ars_nouveau.flask_cannon.no_potion"));
        return InteractionResultHolder.sidedSuccess(itemstack, pLevel.isClientSide());
    }

    ThrownPotion thrownpotion = new ThrownPotion(pLevel, pPlayer);
    ItemStack stckToThrow = getThrownStack(pLevel, pPlayer, pHand, itemstack);
    PotionContents contents = stckToThrow.get(DataComponents.POTION_CONTENTS);
    if (contents == PotionContents.EMPTY)
        return InteractionResultHolder.success(itemstack);
    thrownpotion.setItem(stckToThrow);
    thrownpotion.shootFromRotation(pPlayer, pPlayer.getXRot(), pPlayer.getYRot(), -20.0F, 0.5F, 1.0F);
    pLevel.addFreshEntity(thrownpotion);
    pPlayer.getCooldowns().addCooldown(this, 10);
    itemstack.set(DataComponentRegistry.POTION_LAUNCHER, new PotionLauncherData(contents, potionLauncherData.lastSlot()));
    return new InteractionResultHolder<>(InteractionResult.CONSUME, itemstack);
}

public @NotNull InteractionResultHolder<ItemStack> use(@NotNull Level worldIn, Player playerIn, @NotNull InteractionHand handIn) {
    ItemStack itemstack = playerIn.getItemInHand(handIn);
    AbstractCaster<?> caster = getSpellCaster(playerIn.getItemInHand(handIn));
    boolean hasAmmo = !findAmmo(playerIn, itemstack).isEmpty();

    InteractionResultHolder<ItemStack> ret = EventHooks.onArrowNock(itemstack, worldIn, playerIn, handIn, hasAmmo);
    if (ret != null) return ret;

    if (hasAmmo || (caster.getSpell().isValid() && new SpellResolver(new SpellContext(worldIn, caster.getSpell(), playerIn, new PlayerCaster(playerIn), itemstack)).withSilent(true).canCast(playerIn))) {
        playerIn.startUsingItem(handIn);
        return InteractionResultHolder.consume(itemstack);
    }

    if (!playerIn.hasInfiniteMaterials() && !hasAmmo) {
        return InteractionResultHolder.fail(itemstack);
    } else {
        playerIn.startUsingItem(handIn);
        return InteractionResultHolder.consume(itemstack);
    }
}

private boolean tryLoadProjectiles(LivingEntity pShooter, ItemStack pCrossbowStack) {
    if (pShooter.level().isClientSide) {
        return true;
    }

    AbstractCaster<?> caster = getSpellCaster(pCrossbowStack);
    SpellContext context = new SpellContext(pShooter.level, caster.modifySpellBeforeCasting((ServerLevel) pShooter.level, pShooter, InteractionHand.MAIN_HAND, caster.getSpell()), pShooter, LivingCaster.from(pShooter), pCrossbowStack);
    SpellResolver resolver = new SpellResolver(context);
    int cost = resolver.getExpendedCost();
    if (!(pShooter instanceof Player player && player.isCreative()) && !context.getCaster().enoughMana(cost)) {
        if (pShooter instanceof ServerPlayer player) {
            PortUtil.sendMessageNoSpam(player, Component.translatable("ars_nouveau.spell.no_mana"));
            Networking.sendToPlayerClient(new NotEnoughManaPacket(cost), player);
        }
        return false;
    }

    int multishotLevel = EnchantmentHelper.getTagEnchantmentLevel(pShooter.level.holderOrThrow(Enchantments.MULTISHOT), pCrossbowStack);
    int numProjectiles = multishotLevel == 0 ? 1 : 3;
    boolean hasInfiniteMaterials = pShooter instanceof Player player && player.hasInfiniteMaterials();
    ItemStack ammoStack = pShooter.getProjectile(pCrossbowStack);
    ItemStack ammoCopy = ammoStack.copy();

    boolean consumedMana = false;
    if (!(pShooter instanceof Player) || resolver.withSilent(true).canCast(pShooter)) {
        resolver.expendMana();
        consumedMana = true;
        numProjectiles += resolver.spell.getBuffsAtIndex(0, pShooter, AugmentSplit.INSTANCE);
    }

    if (ammoStack.getItem() instanceof FormSpellArrow formSpellArrow && formSpellArrow.part == AugmentSplit.INSTANCE) {
        numProjectiles += formSpellArrow.numParts;
    }

    List<ItemStack> stacks = new ArrayList<>();
    for (int k = 0; k < numProjectiles; ++k) {
        if (k > 0) {
            ammoStack = ammoCopy.copy();
        }

        if (ammoStack.isEmpty() && hasInfiniteMaterials) {
            ammoStack = new ItemStack(Items.ARROW);
            ammoCopy = ammoStack.copy();
        }
        ItemStack checkedAmmo = useAmmo(pCrossbowStack, ammoStack, pShooter, k > 0);
        if (!checkedAmmo.isEmpty()) {
            stacks.add(checkedAmmo);
        }
    }

    if (!stacks.isEmpty()) {
        pCrossbowStack.set(DataComponents.CHARGED_PROJECTILES, ChargedProjectiles.of(stacks));
        CompoundTag tag = new CompoundTag();
        tag.putBoolean("isSpell", true);
        pCrossbowStack.set(DataComponents.CUSTOM_DATA, CustomData.of(tag));
    }

    return true;
}

public void performShooting(@NotNull Level pLevel, @NotNull LivingEntity pShooter, @NotNull InteractionHand pUsedHand, @NotNull ItemStack pCrossbowStack, float pVelocity, float pInaccuracy, @Nullable LivingEntity pTarget) {
    if (pShooter instanceof Player player && net.neoforged.neoforge.event.EventHooks.onArrowLoose(pCrossbowStack, pShooter.level, player, 1, true) < 0)
        return;
    ChargedProjectiles chargedprojectiles = pCrossbowStack.set(DataComponents.CHARGED_PROJECTILES, ChargedProjectiles.EMPTY);
    if (chargedprojectiles == null)
        return;
    var customData = pCrossbowStack.get(DataComponents.CUSTOM_DATA);
    CompoundTag tag = customData != null ? customData.getUnsafe() : new CompoundTag();
    boolean isSpell = tag.getBoolean("isSpell");
    for (int i = 0; i < chargedprojectiles.getItems().size(); ++i) {
        ItemStack itemstack = chargedprojectiles.getItems().get(i);
        boolean flag = pShooter instanceof Player player && player.hasInfiniteMaterials();
        if (!itemstack.isEmpty()) {
            float offset = 10.0f * (float) ((i > 0 ? 1 + i : 0) / 2);
            boolean isOdd = i % 2 == 1;
            if (isOdd) {
                offset *= -1;
            }
            shootOne(pLevel, pShooter, pUsedHand, pCrossbowStack, itemstack, i == 0 ? 1 : getRandomShotPitch(isOdd == pShooter.getRandom().nextBoolean(), pShooter.getRandom()), flag, pVelocity, pInaccuracy, offset, isSpell);
        }
    }

    if (pShooter instanceof ServerPlayer serverplayer) {
        if (!pLevel.isClientSide) {
            CriteriaTriggers.SHOT_CROSSBOW.trigger(serverplayer, pCrossbowStack);
        }

        serverplayer.awardStat(Stats.ITEM_USED.get(pCrossbowStack.getItem()));
    }
}

public void curioTick(SlotContext context, ItemStack stack) {
    if (context.entity() instanceof Player player && !player.abilities.flying) {
        Level world = player.getCommandSenderWorld();

        if (!player.onGround() && player.isShiftKeyDown() && !world.isClientSide()) {
            boolean isTooHigh = true;
            for (int i = 1; i < 6; i++) {
                if (!world.getBlockState(player.blockPosition().below(i)).isAir()) {
                    isTooHigh = false;
                    break;
                }
            }

            if (isTooHigh) {
                player.addEffect(new MobEffectInstance(MobEffects.SLOW_FALLING, 5, 2));
            } else {
                player.addEffect(new MobEffectInstance(MobEffects.LEVITATION, 5, 2));
            }
            player.fallDistance = 0.0f;
        }

        if (world.isClientSide()) {
            Vec3 oldMotion = player.getDeltaMovement();
            double y = oldMotion.y();
            Vec3 motion = player.getDeltaMovement().scale(1.1);
            if (Math.sqrt(motion.length()) > 0.6) {
                return;
            }
            player.lerpMotion(motion.x, y, motion.z);
            player.hurtMarked = true;
        }
    }
}

