public void updateElytraFlight(Player player) {
    AttributeInstance attributeInstance = player.getAttribute(NeoForgeMod.GLIDING_FLIGHT);
    if (attributeInstance != null) {
        boolean shouldDisableElytra = false;
        if (player.isShiftKeyDown() && player.isFallFlying()) {
            ItemStack stack = player.getItemBySlot(EquipmentSlot.CHEST);
            if (IModuleHelper.INSTANCE.isEnabled(stack, MekanismModules.ELYTRA_UNIT) && LivingEntity.canGlideUsing(stack, EquipmentSlot.CHEST)) {
                //If the elytra unit is providing flight, allow disabling the flight by pressing shift
                shouldDisableElytra = true;
            }
        }
        AttributeModifier existing = attributeInstance.getModifier(DISABLE_ELYTRA_MODIFIER_ID);
        if (existing != null) {
            if (!shouldDisableElytra) {
                attributeInstance.removeModifier(DISABLE_ELYTRA_MODIFIER);
            }
        } else if (shouldDisableElytra) {
            attributeInstance.addTransientModifier(DISABLE_ELYTRA_MODIFIER);
        }
    }
}

public InteractionResult use(Level worldIn, Player player, InteractionHand hand) {
    if (player.canEat(false)) {
        ResourceHandler<FluidResource> fluidHandler = AutomatedResourceHandler.manual(Capabilities.FLUID.getCapability(ItemAccessUtils.playerHandAccess(player, hand)));
        if (fluidHandler != null) {
            //Protect against any mods that might be doing transactional logic, such as if an auto clicker validates it has enough energy before calling this method
            try (Transaction simulation = TransactionHelper.openTransactionSafe()) {
                int pastePerFood = MekanismConfig.general.nutritionalPasteMBPerFood.get();
                int extracted = fluidHandler.extract(MekanismFluids.NUTRITIONAL_PASTE.asResource(), pastePerFood, simulation);
                if (extracted == pastePerFood) {
                    //Only allow to start drinking if we have at least enough paste to provide a single point of food
                    player.startUsingItem(hand);
                    return InteractionResult.CONSUME;
                }
            }
        }
    }
    return InteractionResult.FAIL;
}

protected void onHitEntity(EntityHitResult hitResult) {
    super.onHitEntity(hitResult);
    hitResult.getEntity().hurt(damageSources().thrown(this, this.getOwner()), 0F);
    if (hitResult.getEntity() instanceof SubmarineEntity submarine) {
        submarine.setLightsOn(false);
        if (submarine.getFirstPassenger() instanceof Player player) {
            player.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 100));
            if (isGlowingBomb()) {
                player.addEffect(new MobEffectInstance(MobEffects.GLOWING, 300));
            }
            if (!player.isCreative()) {
                player.removeEffect(MobEffects.NIGHT_VISION);
                player.removeEffect(MobEffects.CONDUIT_POWER);
            }
        }
    }
    if (hitResult.getEntity() instanceof LivingEntity living) {
        living.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 100));
        if (!(living instanceof Player player && player.isCreative())) {
            living.removeEffect(MobEffects.NIGHT_VISION);
            living.removeEffect(MobEffects.CONDUIT_POWER);
        }
    }
}

private void damageMobs() {
    Entity owner = this.getOwner();
    DamageSource source = damageSources().mobProjectile(this, (owner instanceof LivingEntity living1 ? living1 : null));
    AABB bashBox = this.getBoundingBox().inflate(2.0D, 2, 2.0D);
    Entity lastHitMob = null;
    for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, bashBox)) {
        if (!isAlliedTo(entity) && !(entity instanceof DeepOneBaseEntity) && (owner == null || !entity.is(owner) && !entity.isAlliedTo(owner))) {
            lastHitMob = entity;
            if (entity.hurt(source, 3.0F) && this.isBubbling()) {
                entity.addEffect(new MobEffectInstance(ACEffectRegistry.BUBBLED.get(), 200));
                if (!entity.level().isClientSide) {
                    AlexsCaves.sendMSGToAll(new UpdateEffectVisualityEntityMessage(entity.getId(), this.getId(), 1, 200));
                }
            }
        }
    }
    if(ricochet && lastHitMob != null){
        ricochet = false;
        onRicochetHit(lastHitMob);
    }
}

private Map<EquipmentSlot, ItemStack> collectEquipmentChanges() {
    Map<EquipmentSlot, ItemStack> map = null;

    for (EquipmentSlot equipmentslottype : EquipmentSlot.values()) {
        ItemStack itemstack;
        switch (equipmentslottype.getType()) {
            case HAND -> itemstack = this.getItemInHand(equipmentslottype);
            case ARMOR -> itemstack = this.getArmorInSlot(equipmentslottype);
            default -> {
                continue;
            }
        }

        ItemStack itemstack1 = this.getItemBySlot(equipmentslottype);
        if (!ItemStack.matches(itemstack1, itemstack)) {
            net.minecraftforge.common.MinecraftForge.EVENT_BUS.post(new net.minecraftforge.event.entity.living.LivingEquipmentChangeEvent(this, equipmentslottype, itemstack, itemstack1));
            if (map == null) {
                map = Maps.newEnumMap(EquipmentSlot.class);
            }

            map.put(equipmentslottype, itemstack1);
            if (!itemstack.isEmpty()) {
                this.getAttributes().removeAttributeModifiers(itemstack.getAttributeModifiers(equipmentslottype));
            }

            if (!itemstack1.isEmpty()) {
                this.getAttributes().addTransientAttributeModifiers(itemstack1.getAttributeModifiers(equipmentslottype));
            }
        }
    }

    return map;
}

public void tick() {
    LivingEntity livingentity = this.entity.getTarget();
    if(crossbowCooldown > 0){
        crossbowCooldown--;
    }
    if (livingentity != null) {
        double d0 = this.entity.distanceToSqr(livingentity.getX(), livingentity.getY(), livingentity.getZ());
        boolean flag = this.entity.hasLineOfSight(livingentity);
        boolean flag1 = this.seeTime > 0;
        if (flag != flag1) {
            this.seeTime = 0;
        }

        if (flag) {
            ++this.seeTime;
        } else {
            --this.seeTime;
        }

        if (!(d0 > (double)this.maxAttackDistance) && this.seeTime >= 20) {
            this.entity.getNavigation().stop();
            ++this.strafingTime;
        } else {
            this.entity.getNavigation().moveTo(livingentity, this.moveSpeedAmp);
            this.strafingTime = -1;
        }

        if (this.strafingTime >= 20) {
            if ((double)this.entity.getRandom().nextFloat() < 0.3D) {
                this.strafingClockwise = !this.strafingClockwise;
            }

            if ((double)this.entity.getRandom().nextFloat() < 0.3D) {
                this.strafingBackwards = !this.strafingBackwards;
            }

            this.strafingTime = 0;
        }

        if (this.strafingTime > -1) {
            if (d0 > (double)(this.maxAttackDistance * 0.75F)) {
                this.strafingBackwards = false;
            } else if (d0 < (double)(this.maxAttackDistance * 0.25F)) {
                this.strafingBackwards = true;
            }

            this.entity.getMoveControl().strafe(this.strafingBackwards ? -0.5F : 0.5F, this.strafingClockwise ? 0.5F : -0.5F);
            this.entity.lookAt(livingentity, 30.0F, 30.0F);
        } else {
            this.entity.getLookControl().setLookAt(livingentity, 30.0F, 30.0F);
        }
        boolean crossbow = this.entity.getMainHandItem().getItem() instanceof CrossbowItem;
        if (this.entity.isUsingItem() || crossbow) {
            if (!flag && this.seeTime < -60) {
                this.entity.stopUsingItem();
            } else if (flag) {
                int i = this.entity.getTicksUsingItem();
                if (i >= 20 || crossbow && crossbowCooldown == 0) {
                    this.entity.stopUsingItem();
                    this.entity.performRangedAttack(livingentity, BowItem.getPowerForTime(i));
                    this.attackTime = this.attackCooldown;
                    crossbowCooldown = 20;
                }
            }
        } else if (--this.attackTime <= 0 && this.seeTime >= -60) {
            this.entity.startUsingItem(ProjectileUtil.getWeaponHoldingHand(this.entity, Items.BOW));
        }

    }
}

protected void updateAttributes() {
    prevArmorResLoc = armorResLoc;
    final int armorHead = this.getArmorOrdinal(this.getItemBySlot(EquipmentSlot.HEAD));
    final int armorNeck = this.getArmorOrdinal(this.getItemBySlot(EquipmentSlot.CHEST));
    final int armorLegs = this.getArmorOrdinal(this.getItemBySlot(EquipmentSlot.LEGS));
    final int armorFeet = this.getArmorOrdinal(this.getItemBySlot(EquipmentSlot.FEET));
    armorResLoc = dragonType.getName() + "|" + armorHead + "|" + armorNeck + "|" + armorLegs + "|" + armorFeet;
    IceAndFire.PROXY.updateDragonArmorRender(armorResLoc);

    double age = 125F;
    if (this.getAgeInDays() <= 125) age = this.getAgeInDays();
    final double healthStep = (maximumHealth - minimumHealth) / 125F;
    final double attackStep = (maximumDamage - minimumDamage) / 125F;
    final double speedStep = (maximumSpeed - minimumSpeed) / 125F;
    final double armorStep = (maximumArmor - minimumArmor) / 125F;

    this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(Math.round(minimumHealth + (healthStep * age)));
    this.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(Math.round(minimumDamage + (attackStep * age)));
    this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(minimumSpeed + (speedStep * age));
    final double baseValue = minimumArmor + (armorStep * this.getAgeInDays());
    this.getAttribute(Attributes.ARMOR).setBaseValue(baseValue);
    if (!this.level.isClientSide) {
        this.getAttribute(Attributes.ARMOR).removeModifier(ARMOR_MODIFIER_UUID);
        this.getAttribute(Attributes.ARMOR).addPermanentModifier(new AttributeModifier(ARMOR_MODIFIER_UUID, "Dragon armor bonus", calculateArmorModifier(), AttributeModifier.Operation.ADDITION));
    }
    this.getAttribute(Attributes.FOLLOW_RANGE).setBaseValue(Math.min(2048, IafConfig.dragonTargetSearchLength));
}

public void roar() {
    if (EntityGorgon.isStoneMob(this) || this.isModelDead()) {
        return;
    }
    if (random.nextBoolean()) {
        if (this.getAnimation() != ANIMATION_EPIC_ROAR) {
            this.setAnimation(ANIMATION_EPIC_ROAR);
            this.playSound(this.getRoarSound(), this.getSoundVolume() + 3 + Math.max(0, this.getDragonStage() - 2), this.getVoicePitch() * 0.7F);
        }
        if (this.getDragonStage() > 3) {
            final int size = (this.getDragonStage() - 3) * 30;
            final List<Entity> entities = level.getEntities(this, this.getBoundingBox().expandTowards(size, size, size));
            for (final Entity entity : entities) {
                final boolean isStrongerDragon = entity instanceof EntityDragonBase && ((EntityDragonBase) entity).getDragonStage() >= this.getDragonStage();
                if (entity instanceof LivingEntity living && !isStrongerDragon) {
                    if (this.isOwnedBy(living) || this.isOwnersPet(living)) {
                        living.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 50 * size));
                    } else {
                        if (living.getItemBySlot(EquipmentSlot.HEAD).getItem() != IafItemRegistry.EARPLUGS.get()) {
                            living.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 50 * size));
                        }
                    }
                }
            }
        }
    } else {
        if (this.getAnimation() != ANIMATION_ROAR) {
            this.setAnimation(ANIMATION_ROAR);
            this.playSound(this.getRoarSound(), this.getSoundVolume() + 2 + Math.max(0, this.getDragonStage() - 3), this.getVoicePitch());
        }
        if (this.getDragonStage() > 3) {
            final int size = (this.getDragonStage() - 3) * 30;
            final List<Entity> entities = level.getEntities(this, this.getBoundingBox().expandTowards(size, size, size));
            for (final Entity entity : entities) {
                final boolean isStrongerDragon = entity instanceof EntityDragonBase && ((EntityDragonBase) entity).getDragonStage() >= this.getDragonStage();
                if (entity instanceof LivingEntity living && !isStrongerDragon) {
                    if (this.isOwnedBy(living) || this.isOwnersPet(living)) {
                        living.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 30 * size));
                    } else {
                        living.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 30 * size));
                    }
                }
            }
        }
    }
}

public static boolean useStandardAttack(EntityLiving attacker, Entity target, float attackDamage, boolean knockback, @Nullable DamageSource damageSource) {
	int knockBackModifier = 0;

	if (target instanceof EntityLivingBase) {
		attackDamage += EnchantmentHelper.getModifierForCreature(attacker.getHeldItemMainhand(), ((EntityLivingBase)target).getCreatureAttribute());
		knockBackModifier += EnchantmentHelper.getKnockbackModifier(attacker);
	}

	double prevMotionX = target.motionX;
	double prevMotionY = target.motionY;
	double prevMotionZ = target.motionZ;

	boolean attacked = target.attackEntityFrom(damageSource != null ? damageSource : DamageSource.causeMobDamage(attacker), attackDamage);

	if(!knockback) {
		target.motionX = prevMotionX;
		target.motionY = prevMotionY;
		target.motionZ = prevMotionZ;
	}

	if (attacked) {
		if (knockback && knockBackModifier > 0 && target instanceof EntityLivingBase) {
			((EntityLivingBase)target).knockBack(attacker, (float)knockBackModifier * 0.5F, (double)MathHelper.sin(attacker.rotationYaw * 0.017453292F), (double)(-MathHelper.cos(attacker.rotationYaw * 0.017453292F)));
			attacker.motionX *= 0.6D;
			attacker.motionZ *= 0.6D;
		}

		int fireAspectModifier = EnchantmentHelper.getFireAspectModifier(attacker);

		if (fireAspectModifier > 0) {
			target.setFire(fireAspectModifier * 4);
		}

		if (target instanceof EntityPlayer) {
			EntityPlayer entityplayer = (EntityPlayer)target;
			ItemStack attackerItem = attacker.getHeldItemMainhand();
			ItemStack defenderItem = entityplayer.isHandActive() ? entityplayer.getActiveItemStack() : ItemStack.EMPTY;

			if (!attackerItem.isEmpty() && !defenderItem.isEmpty() && attackerItem.getItem().canDisableShield(attackerItem, defenderItem, entityplayer, attacker) && defenderItem.getItem().isShield(defenderItem, entityplayer)) {
				float efficiencyModifier = 0.25F + (float)EnchantmentHelper.getEfficiencyModifier(attacker) * 0.05F;

				if (attacker.world.rand.nextFloat() < efficiencyModifier) {
					entityplayer.getCooldownTracker().setCooldown(Items.SHIELD, 100);
					attacker.world.setEntityState(entityplayer, (byte)30);
				}
			}
		}
	}

	return attacked;
}

public void onLivingUpdate() {
	if(this.isBlocking() && !this.getHeldItemOffhand().isEmpty() && this.getHeldItemOffhand().getItem().isShield(this.getHeldItemOffhand(), this)) {
		this.setActiveHand(EnumHand.OFF_HAND);

		//"Fix" for janky item pose
		if(this.world.isRemote) {
			this.activeItemStack = this.getHeldItemOffhand();
		}
	} else if(this.isHandActive() && this.getActiveHand() == EnumHand.OFF_HAND) {
		this.stopActiveHand();
	}

	if (getEntityWorld().isRemote) {
		if (isChief())
			setSize(1.2F, 1.9F);
		if (!isChief() && isBiped())
			setSize(0.75F, 1.5F);
		if (!isChief() && !isBiped())
			setSize(0.95F - standingAngle * 0.2F, 1F + standingAngle * 0.75F);
	}

	if (!getEntityWorld().isRemote && !isBiped()) {
		if (getAttackTarget() != null) {
			double distance = getDistance(getAttackTarget().posX, getAttackTarget().getEntityBoundingBox().minY, getAttackTarget().posZ);

			setIsStanding(distance <= 3.0D);
		}

		if (getAttackTarget() == null) {
			setIsStanding(false);
		}
	}

	if (getEntityWorld().isRemote && !isBiped()) {
		prevStandingAngle = standingAngle;

		if (standingAngle > 0 && !isStanding()) {
			standingAngle -= 0.1F;
		}

		if (isStanding() && standingAngle <= 1F) {
			standingAngle += 0.1F;
		}

		if (standingAngle < 0 && !isStanding()) {
			standingAngle = 0F;
		}

		if (isStanding() && standingAngle > 1F) {
			standingAngle = 1F;
		}

		standingAngle = MathHelper.clamp(standingAngle, 0, 1);
	}

	super.onLivingUpdate();
}

public void attackTargetEntityWithCurrentItem(Entity targetEntity, Player player, float damageMult, float knockbackMult) {
    if (!CommonHooks.onPlayerAttackTarget(player, targetEntity) || !targetEntity.isAttackable()) {
        return;
    }

    ItemStack oldStack = player.getMainHandItem();
    ItemStack newStack = getAxeStack();
    resetModifiers(player, oldStack, newStack);
    player.setItemInHand(InteractionHand.MAIN_HAND, newStack);

    // Check this after swapping main hand in cases the main hand item impacts the result
    if (targetEntity.skipAttackInteraction(player)) {
        resetModifiers(player, newStack, oldStack);
        player.setItemInHand(InteractionHand.MAIN_HAND, oldStack);
        return;
    }

    if (targetEntity.getType().is(EntityTypeTags.REDIRECTABLE_PROJECTILE) && targetEntity instanceof Projectile projectile && projectile.deflect(ProjectileDeflection.AIM_DEFLECT, this, this, true)) {
        this.level().playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.PLAYER_ATTACK_NODAMAGE, this.getSoundSource());
        resetModifiers(player, newStack, oldStack);
        player.setItemInHand(InteractionHand.MAIN_HAND, oldStack);
        return;
    }

    DamageSource damageSource = damageSources().playerAttack(player);

    float attackDamage = (float) player.getAttributeValue(Attributes.ATTACK_DAMAGE) * damageMult;
    float enchantedDamage = player.getEnchantedDamage(targetEntity, attackDamage, damageSource);

    if (attackDamage > 0 || enchantedDamage > 0) {
        boolean wasSprinting = false;

        if (player.isSprinting()) {
            player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.PLAYER_ATTACK_KNOCKBACK, player.getSoundSource(), 1.0F, 1.0F);
            wasSprinting = true;
        }

        attackDamage += newStack.getItem().getAttackDamageBonus(targetEntity, attackDamage, damageSource);
        float damage = attackDamage + enchantedDamage;
        float targetHealth = targetEntity instanceof LivingEntity livingTarget ? livingTarget.getHealth() : 0;

        Vec3 targetMovement = targetEntity.getDeltaMovement();
        boolean wasHurt = targetEntity.hurt(damageSource, damage);

        if (wasHurt) {
            float knockback = player.getKnockback(targetEntity, damageSource) + (wasSprinting ? 1 : 0);

            if (knockback > 0) {
                if (targetEntity instanceof LivingEntity livingTarget) {
                    livingTarget.knockback(knockback * 0.5F * knockbackMult, Mth.sin(player.getYRot() * ((float) Math.PI / 180F)), -Mth.cos(player.getYRot() * ((float) Math.PI / 180F)));
                } else {
                    targetEntity.push(-Mth.sin(player.getYRot() * ((float) Math.PI / 180F)) * knockback * 0.5F * knockbackMult, 0.1D, Mth.cos(player.getYRot() * ((float) Math.PI / 180F)) * knockback * 0.5F * knockbackMult);
                }

                player.setDeltaMovement(player.getDeltaMovement().multiply(0.6D, 1.0D, 0.6D));
                player.setSprinting(false);
            }

            if (targetEntity instanceof ServerPlayer && targetEntity.hurtMarked) {
                ((ServerPlayer) targetEntity).connection.send(new ClientboundSetEntityMotionPacket(targetEntity));
                targetEntity.hurtMarked = false;
                targetEntity.setDeltaMovement(targetMovement);
            }

            player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.PLAYER_ATTACK_STRONG, player.getSoundSource(), 1.0F, 1.0F);

            if (enchantedDamage > 0) {
                player.magicCrit(targetEntity);
            }

            player.setLastHurtMob(targetEntity);
            Entity entity = targetEntity;

            if (targetEntity instanceof PartEntity<?> part) {
                entity = part.getParent();
            }

            ItemStack copy = newStack.copy();
            boolean hurtEnemy = false;

            if (level() instanceof ServerLevel serverLevel) {
                if (entity instanceof LivingEntity livingEntity) {
                    hurtEnemy = newStack.hurtEnemy(livingEntity, player);
                }

                EnchantmentHelper.doPostAttackEffects(serverLevel, targetEntity, damageSource);
            }

            if (!level().isClientSide() && !copy.isEmpty() && entity instanceof LivingEntity livingEntity) {
                if (hurtEnemy) {
                    newStack.postHurtEnemy(livingEntity, player);
                }

                if (newStack.isEmpty()) {
                    EventHooks.onPlayerDestroyItem(player, copy, InteractionHand.MAIN_HAND);
                    player.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
                }
            }

            if (targetEntity instanceof LivingEntity livingTarget) {
                float healthDifference = targetHealth - livingTarget.getHealth();
                player.awardStat(Stats.DAMAGE_DEALT, Math.round(healthDifference * 10));

                if (level() instanceof ServerLevel serverLevel && healthDifference > 2) {
                    int particleCount = (int) ((double) healthDifference * 0.5);
                    serverLevel.sendParticles(ParticleTypes.DAMAGE_INDICATOR, targetEntity.getX(), targetEntity.getY(0.5), targetEntity.getZ(), particleCount, 0.1, 0.0, 0.1, 0.2);
                }
            }

            player.causeFoodExhaustion(0.1F);
        } else {
            player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.PLAYER_ATTACK_NODAMAGE, player.getSoundSource(), 1.0F, 1.0F);
        }
    }

    resetModifiers(player, newStack, oldStack);
    player.setItemInHand(InteractionHand.MAIN_HAND, oldStack);
}

public void applyEffectTick(LivingEntity livingEntity, int amplify) {
    Level world = livingEntity.level;
    if (this == GoetyEffects.PRESSURE.get()){
        int count = 0;
        for (LivingEntity other : world.getEntitiesOfClass(LivingEntity.class, livingEntity.getBoundingBox().inflate(8.0F + amplify))){
            if (livingEntity.hasLineOfSight(other)){
                ++count;
            }
        }
        if (count >= 3){
            livingEntity.hurt(ModDamageSource.getDamageSource(livingEntity.level, ModDamageSource.PHOBIA), 1.0F);
        }
    }
    if (this == GoetyEffects.NYCTOPHOBIA.get()){
        if (world.getLightLevelDependentMagicValue(livingEntity.blockPosition()) < 0.1 || livingEntity.hasEffect(MobEffects.DARKNESS)) {
            livingEntity.hurt(ModDamageSource.getDamageSource(livingEntity.level, ModDamageSource.PHOBIA), 1.0F);
        }
    }
    if (this == GoetyEffects.SUN_ALLERGY.get()){
        boolean burn = MobUtil.isInSunlight(livingEntity);

        if (burn){
            ItemStack helmet = livingEntity.getItemBySlot(EquipmentSlot.HEAD);
            if (!helmet.isEmpty()) {
                if (MobUtil.validEntity(livingEntity)) {
                    if (helmet.isDamageableItem()) {
                        helmet.setDamageValue(helmet.getDamageValue() + world.random.nextInt(2));
                        if (helmet.getDamageValue() >= helmet.getMaxDamage()) {
                            livingEntity.broadcastBreakEvent(EquipmentSlot.HEAD);
                            livingEntity.setItemSlot(EquipmentSlot.HEAD, ItemStack.EMPTY);
                        }
                    }
                }
                burn = false;
            }
            if (burn){
                livingEntity.setSecondsOnFire(8);
            }
        }
    }
    if (this == GoetyEffects.STORMS_WRATH.get()){
        float chance = 0.1F;
        chance += amplify / 10.0F;
        if (livingEntity.level.isRainingAt(livingEntity.blockPosition())){
            chance += 0.1F;
            if (livingEntity.level.isThundering()){
                chance += 0.25F;
            }
        }
        if (livingEntity.level.canSeeSky(livingEntity.blockPosition())){
            if (livingEntity.getRandom().nextFloat() <= chance){
                LightningBolt lightningBolt = new LightningBolt(EntityType.LIGHTNING_BOLT, livingEntity.level);
                lightningBolt.moveTo(Vec3.atBottomCenterOf(livingEntity.blockPosition()));
                livingEntity.level.addFreshEntity(lightningBolt);
            }
        }
    }
    if (this == GoetyEffects.PHOTOSYNTHESIS.get()){
        if (MobUtil.isInSunlightNoChance(livingEntity)) {
            if (livingEntity.getHealth() < livingEntity.getMaxHealth()) {
                livingEntity.heal(1.0F);
            }
        }
    }
    if (this == GoetyEffects.TRIPPING.get()) {
        if (world.random.nextFloat() <= 0.25F + (amplify / 10.0F) && MobUtil.isMoving(livingEntity)) {
            double d0 = world.random.nextDouble() * world.random.nextIntBetweenInclusive(-1, 1);
            double d1 = (world.random.nextDouble() * world.random.nextIntBetweenInclusive(-1, 1)) / 2.0D;
            double d2 = world.random.nextDouble() * world.random.nextIntBetweenInclusive(-1, 1);
            MobUtil.push(livingEntity, d0, d1, d2);
        }
    }
    if (this == GoetyEffects.ARROWMANTIC.get()){
        for (AbstractArrow abstractArrow : world.getEntitiesOfClass(AbstractArrow.class, livingEntity.getBoundingBox().inflate(2.0F + amplify))){
            if (!abstractArrow.onGround()){
                double d0 = livingEntity.getX() - abstractArrow.getX();
                double d1 = livingEntity.getY(0.3333333333333333D) - abstractArrow.getY();
                double d2 = livingEntity.getZ() - abstractArrow.getZ();
                double d3 = Mth.sqrt((float) (d0 * d0 + d2 * d2));
                abstractArrow.shoot(d0, d1 + d3 * (double)0.2F, d2, 1.0F + (amplify / 5.0F), 10);
            }
        }
    }
    if (this == GoetyEffects.FIERY_AURA.get()){
        if (world instanceof ServerLevel serverLevel) {
            float f = 2.0F + amplify;
            ServerParticleUtil.addAuraParticles(serverLevel, ParticleTypes.FLAME, livingEntity, f);
            for (LivingEntity living : world.getEntitiesOfClass(LivingEntity.class, livingEntity.getBoundingBox().inflate(f))) {
                if (!living.isOnFire() && !living.hasEffect(MobEffects.FIRE_RESISTANCE) && !living.fireImmune() && !MobUtil.areAllies(livingEntity, living) && MobUtil.validEntity(living) && living != livingEntity) {
                    living.setSecondsOnFire(5 * (amplify + 1));
                    if (living.getRemainingFireTicks() > 0) {
                        ServerParticleUtil.addParticlesAroundSelf(serverLevel, ParticleTypes.FLAME, living);
                        ModNetwork.sendToALL(new SPlayWorldSoundPacket(livingEntity.blockPosition(), SoundEvents.FIRECHARGE_USE, 1.0F, 0.75F));
                    }
                }
            }
        }
    }
    if (this == GoetyEffects.FROSTY_AURA.get()){
        if (world instanceof ServerLevel serverLevel) {
            float f = 2.0F + amplify;
            ServerParticleUtil.addAuraParticles(serverLevel, ParticleTypes.SNOWFLAKE, livingEntity, f);
            for (LivingEntity living : world.getEntitiesOfClass(LivingEntity.class, livingEntity.getBoundingBox().inflate(f))) {
                if (!living.isFreezing() && living.canFreeze() && !MobUtil.areAllies(livingEntity, living) && MobUtil.validEntity(living) && living != livingEntity) {
                    if (living.addEffect(new MobEffectInstance(GoetyEffects.FREEZING.get(), 100, amplify))) {
                        ServerParticleUtil.addParticlesAroundSelf(serverLevel, ParticleTypes.SNOWFLAKE, living);
                        ModNetwork.sendToALL(new SPlayWorldSoundPacket(livingEntity.blockPosition(), SoundEvents.PLAYER_HURT_FREEZE, 1.0F, 0.75F));
                    }
                }
            }
        }
    }
    if (this == GoetyEffects.CHILL_HIDE.get()){
        if (world instanceof ServerLevel serverLevel) {
            if (livingEntity.tickCount % 5 == 0) {
                float f = livingEntity.getBbWidth();
                ServerParticleUtil.windParticle(serverLevel, CHILL_HIDE, f, livingEntity.getBbHeight() / 2.0F, livingEntity.getId(), livingEntity.position());
            }
            if (livingEntity.tickCount % 15 == 0) {
                serverLevel.sendParticles(new AuraParticleOption(livingEntity.getId(), livingEntity.getBbHeight(), CHILL_HIDE_AURA), livingEntity.getX(), livingEntity.getY() + (livingEntity.getBbHeight() / 2.0F), livingEntity.getZ(), 1, 0, 0, 0, 0.5F);
            }
        }
    }
    if (this == GoetyEffects.FIRE_TRAIL.get()){
        BlockState blockState = world.getBlockState(livingEntity.blockPosition());
        if (MobUtil.isMoving(livingEntity)){
            if (blockState.canBeReplaced(new DirectionalPlaceContext(world, livingEntity.blockPosition(), Direction.DOWN, ItemStack.EMPTY, Direction.UP))
                    && world.getFluidState(livingEntity.blockPosition()).isEmpty()
                    && world.getBlockState(livingEntity.blockPosition().below()).isSolidRender(world, livingEntity.blockPosition().below())){
                world.setBlockAndUpdate(livingEntity.blockPosition(), BaseFireBlock.getState(world, livingEntity.blockPosition()));
            }
        }
    }
    if (this == GoetyEffects.GRAVITY_PULSE.get()) {
        if (livingEntity.tickCount % MathHelper.secondsToTicks(10) == 0) {
            if (world instanceof ServerLevel serverLevel) {
                double area = Mth.square(livingEntity.getBoundingBox().getSize()) * 2.0F;
                area *= ((amplify / 2.0D) + 1.0D);
                ColorUtil colorUtil = GRAVITY_PULSE;
                serverLevel.sendParticles(new ShockwaveParticleOption(colorUtil.red(), colorUtil.green(), colorUtil.blue(), (float) area, 1, true), livingEntity.getX(), livingEntity.getY() + 0.25F, livingEntity.getZ(), 0, 0, 0, 0, 0.5F);
                for (LivingEntity target : livingEntity.level.getEntitiesOfClass(LivingEntity.class, livingEntity.getBoundingBox().inflate(area))) {
                    if (target != livingEntity && !MobUtil.areAllies(livingEntity, target) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(target) && target != livingEntity.getVehicle()) {
                        Vec3 vec3 = target.position().subtract(livingEntity.position());
                        vec3 = vec3.scale(2.0D).normalize();
                        target.level.playSound(null, target.getX(), target.getY(), target.getZ(), ModSounds.GRAVITY.get(), livingEntity.getSoundSource(), 0.65F, 0.9F + (livingEntity.getRandom().nextFloat() * 0.4F));
                        MobUtil.pull(target, vec3.x, vec3.y, vec3.z);
                    }
                }
            }
        }
    }
    if (this == GoetyEffects.PLUNGE.get()){
        if (!livingEntity.hasEffect(MobEffects.LEVITATION)){
            if (MobUtil.validEntity(livingEntity)) {
                if (livingEntity instanceof Player player) {
                    player.getAbilities().flying &= player.isCreative();
                }
                if (livingEntity.isInFluidType()) {
                    livingEntity.setDeltaMovement(livingEntity.getDeltaMovement().subtract(0, 0.05D + (amplify / 100.0D), 0));
                } else if (BlockFinder.distanceFromGround(livingEntity) > 4) {
                    livingEntity.setDeltaMovement(livingEntity.getDeltaMovement().subtract(0, 0.2D + (amplify / 10.0D), 0));
                }
                livingEntity.setSwimming(false);
            }
        }
    }
    if (this == GoetyEffects.NECROSIS.get()){
        if (livingEntity.getMobType() == MobType.UNDEAD) {
            if (livingEntity.tickCount % 50 == 0) {
                if (livingEntity.getHealth() < livingEntity.getMaxHealth()) {
                    livingEntity.heal(1.0F);
                }
            }
        } else {
            if (livingEntity.tickCount % 25 == 0) {
                if (!CuriosFinder.hasUndeadSet(livingEntity)) {
                    livingEntity.hurt(ModDamageSource.getDamageSource(world, ModDamageSource.ROT), 1.0F);
                } else {
                    if (!CuriosFinder.hasNamelessSet(livingEntity)) {
                        livingEntity.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 5, 0, false, false));
                    }
                }
            }
        }
    }
    if (this == GoetyEffects.SOUL_BURN.get()){
        if (livingEntity.tickCount % 20 == 0) {
            boolean flag = livingEntity.hurt(ModDamageSource.getDamageSource(world, ModDamageSource.SOUL_BURN), 2.0F);
            if (livingEntity instanceof Player player && flag) {
                int amount;
                if (ISoulContainer.MAX_SOULS <= 100) {
                    amount = 2;
                } else {
                    amount = (ISoulContainer.MAX_SOULS / 100) * 2;
                }
                SEHelper.decreaseSoulsNoDiscount(player, amount);
            }

        }
    }
    if (this == GoetyEffects.ENCHANTED.get()) {
        /*if (livingEntity.tickCount % 4 == 0) {
            livingEntity.heal(livingEntity.getMaxHealth() * 0.01F);
        }*/
        if (!world.isClientSide) {
            if (world instanceof ServerLevel serverLevel) {
                serverLevel.sendParticles(new MagicSmokeParticleOption(0xffecff, 0x9f34cd, 10 + world.getRandom().nextInt(10), 0.2F, -0.01F), livingEntity.getRandomX(0.5D), livingEntity.getRandomY(), livingEntity.getRandomZ(0.5D), 0, 0.0F, 0.0F, 0.0F, 1.0F);
            }
            Entity entity = MiscCapHelper.getEnchanter(livingEntity);
            if (entity == null || !entity.isAlive() || (entity instanceof LivingEntity living && living.isDeadOrDying())) {
                livingEntity.removeEffect(GoetyEffects.ENCHANTED.get());
            } else if (entity instanceof LivingEntity living) {
                MiscCapHelper.setEnchanterTime(living, 5);
            }
        }
    }
    if (this == GoetyEffects.WOUNDED.get()) {
        if (livingEntity.tickCount % 10 == 0) {
            if (world instanceof ServerLevel serverLevel) {
                ServerParticleUtil.addParticlesAroundMiddleSelf(serverLevel, ParticleTypes.CRIT, livingEntity);
            }
        }
    }
    if (this == GoetyEffects.CRIPPLED.get()) {
        if (livingEntity.getHealth() >= livingEntity.getMaxHealth() * 0.75F) {
            livingEntity.removeEffect(GoetyEffects.CRIPPLED.get());
        }
    }
    if (this == GoetyEffects.STUNNED.get()){
        if (livingEntity.level instanceof ServerLevel serverLevel){
            if (livingEntity.tickCount % 15 == 0) {
                serverLevel.sendParticles(ModParticleTypes.STUN.get(), livingEntity.getX(), livingEntity.getY() + livingEntity.getBbHeight() + 0.5F, livingEntity.getZ(), 1, 0, 0, 0, 0.5F);
            }
        }
    }
    if (this == GoetyEffects.WILD_RAGE.get()){
        if (!livingEntity.level.isClientSide){
            if (livingEntity instanceof Mob mob && (mob.getAttribute(Attributes.ATTACK_DAMAGE) != null || mob instanceof RangedAttackMob) && mob.getAttribute(Attributes.FOLLOW_RANGE) != null){
                double follow = mob.getAttributeValue(Attributes.FOLLOW_RANGE);
                LivingEntity target = world.getNearestEntity(world.getEntitiesOfClass(LivingEntity.class, mob.getBoundingBox().inflate(follow, 4.0D, follow), (p_148152_) -> {
                    return true;
                }), TargetingConditions.forCombat(), mob, mob.getX(), mob.getEyeY(), mob.getZ());
                if (target != null && mob != target && mob.getTarget() != target){
                    mob.setTarget(target);
                    mob.setLastHurtByMob(target);
                    mob.getBrain().setMemoryWithExpiry(MemoryModuleType.ANGRY_AT, target.getUUID(), 600L);
                    mob.getBrain().setMemoryWithExpiry(MemoryModuleType.ATTACK_TARGET, target, 600L);
                }
                if (mob.getTarget() != null && mob.getTarget().isRemoved()){
                    mob.setTarget(null);
                    mob.setLastHurtByMob(null);
                    mob.getBrain().eraseMemory(MemoryModuleType.ANGRY_AT);
                    mob.getBrain().eraseMemory(MemoryModuleType.ATTACK_TARGET);
                }
            }
        }
    }
}

public int tick(ServerLevel pLevel) {
    if (!MobsConfig.IllagerAssault.get()) {
        return 0;
    } else {
        RandomSource random = pLevel.random;
        --this.nextTick;
        if (this.nextTick > 0) {
            return 0;
        } else {
            this.nextTick += MobsConfig.IllagerAssaultSpawnFreq.get();
            if (random.nextInt(MobsConfig.IllagerAssaultSpawnChance.get()) != 0) {
                return 0;
            } else {
                int j = pLevel.players().size();
                if (j < 1) {
                    return 0;
                } else {
                    ServerPlayer pPlayer = pLevel.players().get(random.nextInt(j));
                    int soulEnergy = Mth.clamp(SEHelper.getSoulAmountInt(pPlayer), 0, MobsConfig.IllagerAssaultSELimit.get());
                    if (pPlayer.isSpectator() || pPlayer.isCreative()) {
                        return 0;
                    } else if (SEHelper.getRestPeriod(pPlayer) > 0){
                        return 0;
                    } else if (pLevel.isCloseToVillage(pPlayer.blockPosition(), 2)) {
                        return 0;
                    } else if (soulEnergy >= MobsConfig.IllagerAssaultSEThreshold.get()) {
                        int k = (24 + random.nextInt(24)) * (random.nextBoolean() ? -1 : 1);
                        int l = (24 + random.nextInt(24)) * (random.nextBoolean() ? -1 : 1);
                        BlockPos.MutableBlockPos blockpos$mutable = pPlayer.blockPosition().mutable().move(k, 0, l);
                        if (!pLevel.isLoaded(blockpos$mutable)) {
                            return 0;
                        } else if (!pLevel.dimensionType().hasRaids()){
                            return 0;
                        } else {
                            Holder<Biome> holder = pLevel.getBiome(blockpos$mutable);
                            if (holder.is(BiomeTags.WITHOUT_PATROL_SPAWNS) || holder.is(ModTags.Biomes.ILLAGER_ASSAULT_BLACKLIST)) {
                                return 0;
                            } else if (pPlayer.blockPosition().getY() < pLevel.getHeightmapPos(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES, blockpos$mutable).getY() - 32 && !pLevel.canSeeSky(pPlayer.blockPosition())){
                                return 0;
                            } else if (BlockFinder.findIllagerWard(pLevel, pPlayer, soulEnergy)){
                                return 0;
                            } else if (!pLevel.getEntitiesOfClass(LivingEntity.class,
                                    pPlayer.getBoundingBox().inflate(64.0D),
                                    entity -> entity.getType().is(Tags.EntityTypes.BOSSES)
                                            || entity.getType().is(ModTags.EntityTypes.MINI_BOSSES)).isEmpty()) {
                                return 0;
                            } else if (!IllagerAssaultListener.ILLAGER_LIST.isEmpty()) {
                                int i1 = 0;
                                for (IllagerDataType data : IllagerAssaultListener.ILLAGER_LIST.values()){
                                    if (data != null){
                                        EntityType<?> entityType = ForgeRegistries.ENTITY_TYPES.getValue(data.raider);
                                        if (entityType != null && entityType != EntityType.PIG) {
                                            if (soulEnergy >= MobsConfig.IllagerAssaultSEThreshold.get() * data.thresholdTimes && pLevel.random.nextFloat() <= data.chance) {
                                                ++i1;
                                                int cost = (int) (soulEnergy / data.thresholdTimes);
                                                int total = Mth.clamp(cost / MobsConfig.IllagerAssaultSEThreshold.get(), 1, data.maxExtraAmount) + 1;
                                                int randomTotal = pLevel.random.nextInt(total) + data.initExtraAmount;
                                                for (int k1 = 0; k1 < randomTotal; ++k1) {
                                                    blockpos$mutable.setY(pLevel.getHeightmapPos(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES, blockpos$mutable).getY());
                                                    if (k1 == 0) {
                                                        if (!this.spawnRaider(data, entityType, pLevel, blockpos$mutable, random, soulEnergy, pPlayer)) {
                                                            break;
                                                        }
                                                    } else {
                                                        this.spawnRaider(data, entityType, pLevel, blockpos$mutable, random, soulEnergy, pPlayer);
                                                    }

                                                    blockpos$mutable.setX(blockpos$mutable.getX() + random.nextInt(5) - random.nextInt(5));
                                                    blockpos$mutable.setZ(blockpos$mutable.getZ() + random.nextInt(5) - random.nextInt(5));
                                                }
                                            }
                                        }
                                    }
                                }
                                if (soulEnergy >= MobsConfig.IllagerAssaultSELimit.get() && MobsConfig.SoulEnergyBadOmen.get()) {
                                    ItemStack itemStack = CuriosFinder.findCurioInAll(pPlayer, ModItems.OMINOUS_CHARM.get());
                                    if (itemStack.is(ModItems.OMINOUS_CHARM.get())) {
                                        OminousCharmItem.increaseOmenLevel(itemStack, 1);
                                    } else if (!pPlayer.hasEffect(MobEffects.BAD_OMEN)) {
                                        pPlayer.addEffect(new MobEffectInstance(MobEffects.BAD_OMEN, 120000, 0, false, false));
                                    }
                                }
                                if (CuriosFinder.hasCurio(pPlayer, ModItems.ALARMING_CHARM.get())){
                                    ModNetwork.sendToClient(pPlayer, new SPlayPlayerSoundPacket(SoundEvents.RAID_HORN.get(), 64.0F, 1.0F));
                                }
                                return i1;
                            } else {
                                return 0;
                            }
                        }
                    } else {
                        return 0;
                    }
                }
            }
        }
    }
}

public boolean spawnRaider(IllagerDataType dataType, EntityType<?> entityType, ServerLevel worldIn, BlockPos pos, RandomSource random, int soulAmount, ServerPlayer player){
    BlockState blockstate = worldIn.getBlockState(pos);
    if (entityType == null){
        return false;
    } else {
        Entity entity = entityType.create(worldIn);
        if (!(entity instanceof PathfinderMob illager)){
            return false;
        } else if (!NaturalSpawner.isValidEmptySpawnBlock(worldIn, pos, blockstate, blockstate.getFluidState(), entityType)) {
            return false;
        } else if (!PatrollingMonster.checkPatrollingMonsterSpawnRules(EntityType.RAVAGER, worldIn, MobSpawnType.PATROL, pos, random)) {
            return false;
        } else {
            illager.setPos(pos.getX(), pos.getY(), pos.getZ());
            ForgeEventFactory.onFinalizeSpawn(illager, worldIn, worldIn.getCurrentDifficultyAt(pos), MobSpawnType.PATROL, null, null);
            illager.goalSelector.addGoal(0, new HuntDownPlayerGoal<>(illager));
            if (illager instanceof HuntingIllagerEntity huntingIllager){
                float rawPercent = (float) SEHelper.getSoulAmountInt(player) / MainConfig.MaxArcaSouls.get();
                int sePercent = (int) (rawPercent * 100);
                huntingIllager.upgradeAssault(sePercent);
                if (random.nextInt(4) == 0) {
                    huntingIllager.setRider(true);
                }
            }
            if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(player)) {
                illager.setTarget(player);
            }
            this.upgradeIllagers(illager, soulAmount);
            if (dataType.riding != null){
                if (worldIn.random.nextFloat() <= dataType.rideChance){
                    EntityType<?> entityType1 = ForgeRegistries.ENTITY_TYPES.getValue(dataType.riding);
                    if (entityType1 != null){
                        Entity entity1 = entityType1.create(worldIn);
                        if (entity1 instanceof PathfinderMob mount) {
                            mount.setPos(pos.getX(), pos.getY(), pos.getZ());
                            ForgeEventFactory.onFinalizeSpawn(mount, worldIn, worldIn.getCurrentDifficultyAt(pos), MobSpawnType.PATROL, null, null);
                            illager.startRiding(mount);
                            if (CuriosFinder.hasCurio(player, ModItems.ALARMING_CHARM.get())){
                                mount.addEffect(new MobEffectInstance(MobEffects.GLOWING, 60));
                            }
                            worldIn.addFreshEntityWithPassengers(mount);
                        }
                    }
                }
            }
            if (CuriosFinder.hasCurio(player, ModItems.ALARMING_CHARM.get())){
                illager.addEffect(new MobEffectInstance(MobEffects.GLOWING, 60));
            }
            worldIn.addFreshEntityWithPassengers(illager);
            return true;
        }
    }
}

public static void PlayerTick(TickEvent.PlayerTickEvent event){
    Player player = event.player;
    if (event.phase == TickEvent.Phase.END) {
        if (ItemHelper.findHelmet(player, ModItems.DARK_HELMET.get())){
            if (ItemConfig.DarkHelmetDarkness.get()) {
                if (player.getEffect(MobEffects.DARKNESS) != null) {
                    player.removeEffect(MobEffects.DARKNESS);
                }
            }
            if (ItemConfig.DarkHelmetBlindness.get()) {
                if (player.getEffect(MobEffects.BLINDNESS) != null) {
                    player.removeEffect(MobEffects.BLINDNESS);
                }
            }
        }

        Inventory inventory = player.getInventory();

        List<NonNullList<ItemStack>> compartments = ImmutableList.of(inventory.items, inventory.armor, inventory.offhand);

        for (NonNullList<ItemStack> nonnulllist : compartments) {
            for (int i = 0; i < nonnulllist.size(); ++i) {
                if (!nonnulllist.get(i).isEmpty()) {
                    ItemStack itemStack = nonnulllist.get(i);
                    Item item = itemStack.getItem();
                    if (!(item instanceof IPersist persist) || !persist.isBroken(itemStack)) {
                        if (itemStack.getItem() instanceof ISoulRepair soulRepair) {
                            soulRepair.repairTick(nonnulllist.get(i), player, inventory.selected == i);
                        } else if (itemStack.getItem() instanceof TieredItem tieredItem && tieredItem.getTier() == ModTiers.DARK){
                            ItemHelper.repairTick(itemStack, player, inventory.selected == i);
                        }
                    }
                }
            }
        }

        if (ItemHelper.armorSet(player, ModArmorMaterials.DARK)){
            if (player.getFoodData().needsFood()){
                if (player.tickCount % 40 == 0){
                    player.heal(1.0F);
                }
            }
        }
    }

    AttributeInstance attackSpeed = player.getAttribute(Attributes.ATTACK_SPEED);
    boolean scythe = player.getMainHandItem().getItem() instanceof DarkScytheItem;

    boolean flag0 = scythe && player.getOffhandItem().isEmpty();
    if (attackSpeed != null){
        if (flag0){
            if (!attackSpeed.hasModifier(TWO_HAND_SCYTHE_SPEED_MOD)){
                attackSpeed.addPermanentModifier(TWO_HAND_SCYTHE_SPEED_MOD);
            }
        } else {
            if (attackSpeed.hasModifier(TWO_HAND_SCYTHE_SPEED_MOD)){
                attackSpeed.removeModifier(TWO_HAND_SCYTHE_SPEED_MOD);
            }
        }
    }

    boolean flag = CuriosFinder.hasCurio(player, ModItems.GRAVE_GLOVE.get()) && (scythe || player.getMainHandItem().is(ModTags.Items.GRAVE_GLOVE_BOOST));
    if (attackSpeed != null){
        if (flag){
            if (!attackSpeed.hasModifier(GLOVE_SCYTHE_SPEED_MOD)){
                attackSpeed.addPermanentModifier(GLOVE_SCYTHE_SPEED_MOD);
            }
        } else {
            if (attackSpeed.hasModifier(GLOVE_SCYTHE_SPEED_MOD)){
                attackSpeed.removeModifier(GLOVE_SCYTHE_SPEED_MOD);
            }
        }
    }

    boolean hammer = player.getMainHandItem().getItem() instanceof HammerItem;

    boolean flag1 = hammer && player.getOffhandItem().isEmpty();
    if (attackSpeed != null){
        if (flag1){
            if (!attackSpeed.hasModifier(TWO_HAND_HAMMER_SPEED_MOD)){
                attackSpeed.addPermanentModifier(TWO_HAND_HAMMER_SPEED_MOD);
            }
        } else {
            if (attackSpeed.hasModifier(TWO_HAND_HAMMER_SPEED_MOD)){
                attackSpeed.removeModifier(TWO_HAND_HAMMER_SPEED_MOD);
            }
        }
    }

    boolean flag2 = CuriosFinder.hasCurio(player, ModItems.THRASH_GLOVE.get()) && (hammer || player.getMainHandItem().is(ModTags.Items.THRASH_GLOVE_BOOST));
    if (attackSpeed != null){
        if (flag2){
            if (!attackSpeed.hasModifier(GLOVE_HAMMER_SPEED_MOD)){
                attackSpeed.addPermanentModifier(GLOVE_HAMMER_SPEED_MOD);
            }
        } else {
            if (attackSpeed.hasModifier(GLOVE_HAMMER_SPEED_MOD)){
                attackSpeed.removeModifier(GLOVE_HAMMER_SPEED_MOD);
            }
        }
    }

    boolean staff = player.getOffhandItem().getItem() instanceof DarkStaff && ItemConfig.StaffOffhandBuff.get();

    AttributeInstance attackDamage = player.getAttribute(Attributes.ATTACK_DAMAGE);

    if (attackDamage != null){
        if (staff){
            if (!attackDamage.hasModifier(STAFF_ATTACK_BOOST_MOD)){
                attackDamage.addPermanentModifier(STAFF_ATTACK_BOOST_MOD);
            }
        } else {
            if (attackDamage.hasModifier(STAFF_ATTACK_BOOST_MOD)){
                attackDamage.removeModifier(STAFF_ATTACK_BOOST_MOD);
            }
        }
    }
    if (MobUtil.starAmuletActive(player)){
        player.getAbilities().flying &= player.isCreative();
    }
}

public static void LivingEffects(LivingEvent.LivingTickEvent event){
    LivingEntity livingEntity = event.getEntity();
    if (livingEntity != null && livingEntity.isAlive()){
        AttributeInstance armor = livingEntity.getAttribute(Attributes.ARMOR);
        AttributeInstance toughness = livingEntity.getAttribute(Attributes.ARMOR_TOUGHNESS);
        if (armor != null){
            if (ItemHelper.armorSet(livingEntity, ModArmorMaterials.CURSED_KNIGHT) || ItemHelper.armorSet(livingEntity, ModArmorMaterials.CURSED_PALADIN)){
                if (!armor.hasModifier(ARMOR_INCREASE_MOD)){
                    armor.addPermanentModifier(ARMOR_INCREASE_MOD);
                }
            } else {
                if (armor.hasModifier(ARMOR_INCREASE_MOD)){
                    armor.removeModifier(ARMOR_INCREASE_MOD);
