public int getArmourCooldown(Player player) {
	ItemCooldowns cooldowns = player.getCooldowns();
	ItemCooldowns.CooldownInstance cooldown = cooldowns.cooldowns.get(this);

	if (cooldown == null)
		return 0;

	return cooldown.endTime - cooldowns.tickCount;
}

