public void tickArmorPiece(EquipmentSlot slot) {
    ItemStack armorStack = player.getItemBySlot(slot);
    boolean armorActive = false;
    if (armorStack.getItem() instanceof PneumaticArmorItem) {
        airHandlers.set(slot.getIndex(), armorStack.getCapability(PNCCapabilities.AIR_HANDLER_ITEM));
        if (ticksSinceEquip[slot.getIndex()] == 0) {
            initArmorInventory(slot);
        }
        ticksSinceEquip[slot.getIndex()]++;
        if (isArmorEnabled() && getArmorPressure(slot) > 0F) {
            armorActive = true;
            if (!player.level().isClientSide && isArmorReady(slot) && !player.isCreative()) {
                // use up air in the armor piece
                float airUsage = getIdleAirUsage(slot, false);
                if (airUsage != 0) {
                    addAir(slot, (int) -airUsage);
                }
            }
            doArmorActions(slot);
        }
    } else {
        airHandlers.set(slot.getIndex(), null);
    }
    if (!armorActive) {
        if (ticksSinceEquip[slot.getIndex()] > 1) {
            onArmorRemoved(slot);
        }
        ticksSinceEquip[slot.getIndex()] = 0;
    }
}

public Multimap<Attribute,AttributeModifier> getAttributeModifiers(IToolStackView tool, EquipmentSlot slot) {
  if (slot != getEquipmentSlot()) {
    return ImmutableMultimap.of();
  }

  ImmutableMultimap.Builder<Attribute, AttributeModifier> builder = ImmutableMultimap.builder();
  if (!tool.isBroken()) {
    // base stats
    StatsNBT statsNBT = tool.getStats();
    UUID uuid = ARMOR_MODIFIER_UUID_PER_TYPE.get(type);
    float armor = statsNBT.get(ToolStats.ARMOR);
    if (armor > 0) {
      builder.put(Attributes.ARMOR, new AttributeModifier(uuid, "tconstruct.armor.armor", armor, AttributeModifier.Operation.ADDITION));
    }
    float toughness = statsNBT.get(ToolStats.ARMOR_TOUGHNESS);
    if (toughness > 0) {
      builder.put(Attributes.ARMOR_TOUGHNESS, new AttributeModifier(uuid, "tconstruct.armor.toughness", toughness, AttributeModifier.Operation.ADDITION));
    }
    double knockbackResistance = statsNBT.get(ToolStats.KNOCKBACK_RESISTANCE);
    if (knockbackResistance > 0) {
      builder.put(Attributes.KNOCKBACK_RESISTANCE, new AttributeModifier(uuid, "tconstruct.armor.knockback_resistance", knockbackResistance, AttributeModifier.Operation.ADDITION));
    }
    // grab attributes from modifiers
    BiConsumer<Attribute,AttributeModifier> attributeConsumer = builder::put;
    for (ModifierEntry entry : tool.getModifierList()) {
      entry.getHook(ModifierHooks.ATTRIBUTES).addAttributes(tool, entry, slot, attributeConsumer);
    }
  }

  return builder.build();
}

public static void applyEffect(Level world, double x, double y, double z) {
	int range = 8;
	List<ThrowableProjectile> entities = world.getEntitiesOfClass(ThrowableProjectile.class, new AABB(x - range, y - range, z - range, x + range, y + range, z + range), Predicates.instanceOf(ManaBurst.class));
	for (ThrowableProjectile entity : entities) {
		ManaBurst burst = (ManaBurst) entity;
		ItemStack lens = burst.getSourceLens();
		if (lens != null && lens.getItem() instanceof TinyPlanetExcempt excempt && !excempt.shouldPull(lens)) {
			continue;
		}

		int orbitTime = burst.getOrbitTime();
		if (orbitTime == 0) {
			burst.setMinManaLoss(burst.getMinManaLoss() * 3);
		}

		float radius = Math.min(7.5F, (Math.max(40, orbitTime) - 40) / 40F + 1.5F);
		int angle = orbitTime % 360;

		float xTarget = (float) (x + Math.cos(angle * 10 * Math.PI / 180F) * radius);
		float yTarget = (float) y;
		float zTarget = (float) (z + Math.sin(angle * 10 * Math.PI / 180F) * radius);

		Vec3 targetVec = new Vec3(xTarget, yTarget, zTarget);
		Vec3 currentVec = entity.position();
		Vec3 moveVector = targetVec.subtract(currentVec);

		entity.setDeltaMovement(moveVector);

		burst.setOrbitTime(burst.getOrbitTime() + 1);
	}
}

