	}
	if (player.isInWaterOrBubble()) {
		// only activate for one ring at a time
		ItemStack result = EquipmentHandler.findOrEmpty(BotaniaItems.waterRing, living);
		if (result != stack) {
			return;
		}

		boolean hasMana = ManaItemHandler.instance().requestManaExact(stack, player, MANA_COST, false);
		if (hasMana) {
			EntityHelper.addStaticEffect(living, MobEffects.CONDUIT_POWER, CONDUIT_POWER_AMPLIFIER);

			if (StoneOfTemperanceItem.hasTemperanceActive(player)) {
				EntityHelper.removeStaticEffect(living, MobEffects.DOLPHINS_GRACE, DOLPHINS_GRACE_AMPLIFIER);
			} else {
				EntityHelper.addStaticEffect(living, MobEffects.DOLPHINS_GRACE, DOLPHINS_GRACE_AMPLIFIER);
			}
			ManaItemHandler.instance().requestManaExact(stack, player, MANA_COST, true);
		} else {
			// convert to short finite duration to prevent flickering and other weird behavior in cases where the
			// player is out of mana and an aura band causes the ring to temporarily turn one in short intervals
			EntityHelper.convertStaticEffectToFinite(living, MobEffects.CONDUIT_POWER, CONDUIT_POWER_AMPLIFIER,
					OUT_OF_MANA_DURATION);
			EntityHelper.convertStaticEffectToFinite(living, MobEffects.DOLPHINS_GRACE,
					DOLPHINS_GRACE_AMPLIFIER, OUT_OF_MANA_DURATION);
		}
	} else {
		onUnequipped(stack, living);
	}
}

public static void handleAbility(LivingIncomingDamageEvent event) {
    var RING = ((ExpulsionRing) ItemRegistry.EXPULSION_RING.get());
    if (event.getEntity() instanceof ServerPlayer serverPlayer) {
        if (event.getSource().getEntity() != null && RING.isEquippedBy(serverPlayer) && RING.tryProcCooldown(serverPlayer)) {
            var vec = serverPlayer.getBoundingBox().getCenter();
            //Visual Explosion
            serverPlayer.level.explode(
                    null,
                    null,
                    null,
                    vec.x,
                    vec.y,
                    vec.z,
                    0,
                    false,
                    Level.ExplosionInteraction.NONE,
                    ParticleTypes.GUST_EMITTER_SMALL,
                    ParticleTypes.GUST_EMITTER_LARGE,
                    SoundEvents.WIND_CHARGE_BURST
            );
            //Knockback effect
            serverPlayer.level.getEntities(serverPlayer, serverPlayer.getBoundingBox().inflate(3)).forEach(entity -> {
                var d = Math.max(entity.distanceToSqr(serverPlayer), .2);
                if (d < RADIUS_SQR && !DamageSources.isFriendlyFireBetween(serverPlayer, entity)) {
                    var f = 1 - d / (RADIUS_SQR) + .6f * (entity instanceof LivingEntity living ? 1 - living.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE) : 1);
                    var impulse = entity.getBoundingBox().getCenter().subtract(serverPlayer.getBoundingBox().getCenter()).normalize().add(0, 0.1, 0).scale(f);
                    entity.setDeltaMovement(entity.getDeltaMovement().add(impulse));
                    entity.hurtMarked = true;
                }
            });
        }
    }
}

static void handleFlight(LivingEntity entity) {
    if (EquipmentUtil.hasFullValkyrieSet(entity)) {
        if (entity instanceof Player player && !player.getAbilities().flying) { // The player can't have creative flight enabled, otherwise it causes issues.
            var data = player.getData(AetherDataAttachments.AETHER_PLAYER);
            Vec3 deltaMovement = player.getDeltaMovement();
            // Updates the flight modifier and timer values.
            if (data.isJumping() && !onGround(player)) { // Checks if the player is off the ground and holding the jump key (space bar by default).
                if (data.getFlightModifier() >= data.getFlightModifierMax()) { // Limits the flight modifier to a maximum value.
                    data.setFlightModifier(data.getFlightModifierMax());
                }
                if (data.getFlightTimer() > 2) { // Starts allowing the player to fly after a 2 tick delay of being off the ground.
                    if (data.getFlightTimer() < data.getFlightTimerMax()) { // Allows the player to fly until the maximum value is hit.
                        data.setFlightModifier(data.getFlightModifier() + 0.25F);
                        data.setFlightTimer(data.getFlightTimer() + 1);
                    }
                } else {
                    data.setFlightTimer(data.getFlightTimer() + 1);
                }
            } else if (!data.isJumping()) {
                // Resets only the modifier if the player stops holding the jump key midair. The timer doesn't reset though and remains frozen, and will continue where it left off when the key is held again, preventing infinite flight.
                data.setFlightModifier(1.0F);
            }
            if (onGround(player)) { // Resets both timer and modifier if the player is on the ground.
                data.setFlightTimer(0);
                data.setFlightModifier(1.0F);
            }
            // Modifies the player's upwards movement based on the set flight modifier and timer values.
            if (data.isJumping() && !onGround(player) && data.getFlightTimer() > 2 && data.getFlightTimer() < data.getFlightTimerMax() && data.getFlightModifier() > 1.0F) {
                player.setDeltaMovement(deltaMovement.x(), 0.025F * data.getFlightModifier(), deltaMovement.z());
            }
            if (player instanceof ServerPlayer serverPlayer) { // Prevents the player from being kicked for flying.
                ServerGamePacketListenerImplAccessor serverGamePacketListenerImplAccessor = (ServerGamePacketListenerImplAccessor) serverPlayer.connection;
                serverGamePacketListenerImplAccessor.aether$setAboveGroundTickCount(0);
            }
        }
    }
}

public void tick() {
	super.tick();
	if (getSpeed() == 0)
		return;

	BlockState state = getBlockState();
	BooleanProperty waterProperty = BlockStateProperties.WATERLOGGED;
	if (state.hasProperty(waterProperty) && state.getValue(waterProperty))
		return;

	if (airLevelTimer > 0) {
		airLevelTimer--;
		return;
	}

	int max = BacktankUtil.maxAir(capacityEnchantLevel);
	if (level.isClientSide) {
		Vec3 centerOf = VecHelper.getCenterOf(worldPosition);
		Vec3 v = VecHelper.offsetRandomly(centerOf, level.random, .65f);
		Vec3 m = centerOf.subtract(v);
		if (airLevel != max)
			level.addParticle(new AirParticleData(1, .05f), v.x, v.y, v.z, m.x, m.y, m.z);
		return;
	}

	if (airLevel == max)
		return;

	int prevComparatorLevel = getComparatorOutput();
	float abs = Math.abs(getSpeed());
	int increment = Mth.clamp(((int) abs - 100) / 20, 1, 5);
	airLevel = Math.min(max, airLevel + increment);
	if (getComparatorOutput() != prevComparatorLevel && !level.isClientSide)
		level.updateNeighbourForOutputSignal(worldPosition, state.getBlock());
	if (airLevel == max)
		sendData();
	airLevelTimer = Mth.clamp((int) (128f - abs / 5f) - 108, 0, 20);
}

public InteractionResultHolder<ItemStack> use(Level pLevel, Player pPlayer, InteractionHand pHand) {
    ItemStack itemstack = pPlayer.getItemInHand(pHand);
    if (!pLevel.isClientSide) {
        if (pPlayer.getCooldowns().isOnCooldown(this) || SEHelper.isOnCooldown(pPlayer, itemstack)) {
            return InteractionResultHolder.pass(itemstack);
        }
        if (getOwnerID(itemstack) != null && getOwner(pLevel, getOwnerID(itemstack)) != pPlayer) {
            return InteractionResultHolder.pass(itemstack);
        }
        HitResult hitResult = getPlayerPOVHitResult(pLevel, pPlayer, ClipContext.Fluid.ANY);
        if (hitResult.getType() == HitResult.Type.MISS) {
            return InteractionResultHolder.pass(itemstack);
        } else {
            Vec3 vector3d = pPlayer.getViewVector(1.0F);
            double d0 = 5.0D;
            List<Entity> list = pLevel.getEntities(pPlayer, pPlayer.getBoundingBox().expandTowards(vector3d.scale(d0)).inflate(1.0D), ENTITY_PREDICATE);
            if (!list.isEmpty()) {
                Vec3 vector3d1 = pPlayer.getEyePosition(1.0F);

                for(Entity entity : list) {
                    AABB axisalignedbb = entity.getBoundingBox().inflate((double)entity.getPickRadius());
                    if (axisalignedbb.contains(vector3d1)) {
                        return InteractionResultHolder.pass(itemstack);
                    }
                }
            }

            if (hitResult.getType() == HitResult.Type.BLOCK) {
                HauntedBroom broom = new HauntedBroom(itemstack, pLevel, hitResult.getLocation().x, hitResult.getLocation().y, hitResult.getLocation().z);
                broom.setYRot(pPlayer.getYRot());
                if (itemstack.getEnchantmentLevel(ModEnchantments.FEALTY.get()) > 0) {
                    broom.setOwner(pPlayer);
                }
                int hardy = itemstack.getEnchantmentLevel(ModEnchantments.HARDY.get());
                if (hardy > 0) {
                    broom.setDamageThreshold(broom.getDamageThreshold() + (hardy * 20));
                }
                if (!pLevel.noCollision(broom, broom.getBoundingBox().inflate(-0.1D))) {
                    return InteractionResultHolder.fail(itemstack);
                } else {
                    pLevel.addFreshEntity(broom);
                    if (!pPlayer.getAbilities().instabuild) {
                        itemstack.shrink(1);
                    }

                    pPlayer.awardStat(Stats.ITEM_USED.get(this));
                    return InteractionResultHolder.success(itemstack);
                }
            }
        }
    }
    return InteractionResultHolder.consume(itemstack);
}

public static void updatePlayerFlyStatus(Player player) {
	ItemStack tiara = EquipmentHandler.findOrEmpty(BotaniaItems.flightTiara, player);
	int left = ItemNBTHelper.getInt(tiara, TAG_TIME_LEFT, MAX_FLY_TIME);

	if (playersWithFlight.contains(playerStr(player))) {
		if (shouldPlayerHaveFlight(player)) {
			player.getAbilities().mayfly = true;
			if (player.getAbilities().flying) {
				if (!player.level().isClientSide) {
					if (!player.isCreative() && !player.isSpectator()) {
						ManaItemHandler.instance().requestManaExact(tiara, player, getCost(tiara, left), true);
					}
				} else if (Math.abs(player.getDeltaMovement().x()) > 0.1 || Math.abs(player.getDeltaMovement().z()) > 0.1) {
					double x = player.getX() - 0.5;
					double y = player.getY() - 0.5;
					double z = player.getZ() - 0.5;

					float r = 1F;
					float g = 1F;
					float b = 1F;

					int variant = getVariant(tiara);
					switch (variant) {
						case 2 -> {
							r = 0.1F;
							g = 0.1F;
							b = 0.1F;
						}
						case 3 -> {
							r = 0F;
							g = 0.6F;
						}
						case 4 -> {
							g = 0.3F;
							b = 0.3F;
						}
						case 5 -> {
							r = 0.6F;
							g = 0F;
							b = 0.6F;
						}
						case 6 -> {
							r = 0.4F;
							g = 0F;
							b = 0F;
						}
						case 7 -> {
							r = 0.2F;
							g = 0.6F;
							b = 0.2F;
						}
						case 8 -> {
							r = 0.85F;
							g = 0.85F;
							b = 0F;
						}
						case 9 -> {
							r = 0F;
							b = 0F;
						}
					}

					for (int i = 0; i < 2; i++) {
						SparkleParticleData data = SparkleParticleData.sparkle(2F * (float) Math.random(), r, g, b, 20);
						player.level().addParticle(data, x + Math.random() * player.getBbWidth(), y + Math.random() * 0.4, z + Math.random() * player.getBbWidth(), 0, 0, 0);
					}
				}
			}
		} else {
			if (!player.isSpectator() && !player.getAbilities().instabuild) {
				player.getAbilities().mayfly = false;
				player.getAbilities().flying = false;
				player.getAbilities().invulnerable = false;
			}
			playersWithFlight.remove(playerStr(player));
		}
	} else if (shouldPlayerHaveFlight(player)) {
		playersWithFlight.add(playerStr(player));
		player.getAbilities().mayfly = true;
	}
}

protected void onHitEntity(EntityHitResult ray) {
	super.onHitEntity(ray);

	if (getStuckEntity() != null)
		return;

	Vec3 hit = ray.getLocation();
	Entity target = ray.getEntity();
	float damage = type.damage() * additionalDamageMult;
	float knockback = type.knockback() + additionalKnockback;
	Entity owner = this.getOwner();

	if (!target.isAlive())
		return;
	if (owner instanceof LivingEntity livingEntity)
		livingEntity.setLastHurtMob(target);

	if (target instanceof PotatoProjectileEntity ppe) {
		if (tickCount < 10 && target.tickCount < 10)
			return;
		if (ppe.getProjectileType() != getProjectileType()) {
			if (owner instanceof Player p)
				AllAdvancements.POTATO_CANNON_COLLIDE.awardTo(p);
			if (ppe.getOwner() instanceof Player p)
				AllAdvancements.POTATO_CANNON_COLLIDE.awardTo(p);
		}
	}

	pop(hit);

	if (target instanceof WitherBoss && ((WitherBoss) target).isPowered())
		return;
	if (type.preEntityHit(stack, ray))
		return;

	boolean targetIsEnderman = target.getType() == EntityType.ENDERMAN;
	int k = target.getRemainingFireTicks();
	if (this.isOnFire() && !targetIsEnderman)
		target.igniteForSeconds(5);

	boolean onServer = !level().isClientSide;
	DamageSource damageSource = causePotatoDamage();
	if (onServer && !target.hurt(damageSource, damage)) {
		target.setRemainingFireTicks(k);
		kill();
		return;
	}

	if (targetIsEnderman)
		return;

	if (!type.onEntityHit(stack, ray) && onServer) {
		if (random.nextDouble() <= recoveryChance) {
			recoverItem();
		} else {
			spawnAtLocation(type.dropStack());
		}
	}

	if (!(target instanceof LivingEntity livingentity)) {
		playHitSound(level(), position());
		kill();
		return;
	}

	if (type.reloadTicks() < 10)
		livingentity.invulnerableTime = type.reloadTicks() + 10;

	if (onServer && knockback > 0) {
		Vec3 appliedMotion = this.getDeltaMovement()
			.multiply(1.0D, 0.0D, 1.0D)
			.normalize();
		if (appliedMotion.lengthSqr() > 0.0D)
			livingentity.knockback(knockback * 0.6, -appliedMotion.x, -appliedMotion.z);
	}

	if (onServer && owner instanceof LivingEntity) {
		EnchantmentHelper.doPostAttackEffects((ServerLevel) level(), livingentity, damageSource);
	}

	if (livingentity != owner && livingentity instanceof Player && owner instanceof ServerPlayer
		&& !this.isSilent()) {
		((ServerPlayer) owner).connection
			.send(new ClientboundGameEventPacket(ClientboundGameEventPacket.ARROW_HIT_PLAYER, 0.0F));
	}

	if (onServer && owner instanceof ServerPlayer serverplayerentity) {
		if (!target.isAlive() && target.getType()
			.getCategory() == MobCategory.MONSTER || (target instanceof Player && target != owner))
			AllAdvancements.POTATO_CANNON.awardTo(serverplayerentity);
	}

	if (type.sticky() && target.isAlive()) {
		setStuckEntity(target);
	} else {
		kill();
	}

}

public void tick(ICommonArmorHandler commonArmorHandler, boolean enabled) {
    if (commonArmorHandler.isOnCooldown(EquipmentSlot.FEET)) {
        // putting the boots on cooldown is a way for other mods to temporarily suppress jet boots
        return;
    }

    int jetbootsCount = commonArmorHandler.getUpgradeCount(EquipmentSlot.FEET, ModUpgrades.JET_BOOTS.get());
    if (jetbootsCount == 0) return;

    int jetbootsAirUsage = 0;

    Player player = commonArmorHandler.getPlayer();
    JetBootsStateTracker.JetBootsState jbState = JetBootsStateTracker.getTracker(player).getJetBootsState(player);
    JetBootsLocalState jbLocal = commonArmorHandler.getExtensionData(this);

    if (commonArmorHandler.hasMinPressure(EquipmentSlot.FEET)) {
        boolean vibration = !player.level().isClientSide() && player.tickCount % 10 == 0;
        if (jbState.isActive()) {
            if (jbState.isBuilderMode() && jetbootsCount >= BUILDER_MODE_LEVEL) {
                // builder mode - rise vertically (or hover if sneaking and firing)
                setYMotion(player, player.isShiftKeyDown() ? 0 : 0.15 + 0.15 * (jetbootsCount - 3));
                jetbootsAirUsage = (int) (ConfigHelper.common().armor.jetBootsAirUsage.get() * jetbootsCount / 2.5F);
                if (vibration) {
                    player.gameEvent(ModGameEvents.JET_BOOTS_FLY_BUILDER);
                }
            } else {
                // jetboots firing - move in direction of looking
                Vec3 lookVec = player.getLookAngle().scale(0.3 * jetbootsCount);
                jbLocal.updateAccel(lookVec);
                lookVec = jbLocal.getEffectiveMotion(lookVec, player.isFallFlying());
                player.setDeltaMovement(lookVec.x, player.onGround() ? 0 : lookVec.y, lookVec.z);
                jetbootsAirUsage = jbLocal.calcAirUsage(jetbootsCount);
                if (vibration) {
                    player.gameEvent(ModGameEvents.JET_BOOTS_FLY);
                }
            }
            if (player.isInWater()) jetbootsAirUsage *= 4;
            jbLocal.tickActive();
        } else if (jbState.isEnabled() && !isOnGround(player) && !player.isFallFlying()) {
            // jetboots not firing, but enabled - slowly descend (or hover if enough upgrades)
            // and bring player to complete halt if flight stabilizers and not actively moving forward/sideways
            boolean reallyHovering = jbLocal.canHover() && (!jbLocal.isSmartHover() || jbLocal.isHovering());
            boolean stopped = jbLocal.isFlightStabilizers()
                    && jetbootsCount >= STABILIZERS_LEVEL
                    && PneumaticCraftUtils.epsilonEquals(player.zza, 0f)
                    && PneumaticCraftUtils.epsilonEquals(player.xxa, 0f);
            double xMotion = stopped ? 0 : player.getDeltaMovement().x;
            double yMotion = reallyHovering ? (player.isShiftKeyDown() ? -0.45 : -0.1 + 0.02 * jetbootsCount) : player.getDeltaMovement().y;
            double zMotion = stopped ? 0 : player.getDeltaMovement().z;
            player.setDeltaMovement(new Vec3(xMotion, yMotion, zMotion));
            if (vibration && player.getKnownMovement().lengthSqr() > 0.03) {
                player.gameEvent(jbState.isBuilderMode() ? ModGameEvents.JET_BOOTS_FLY_BUILDER : ModGameEvents.JET_BOOTS_FLY);
            }
            if (reallyHovering) player.fallDistance = 0;
            jetbootsAirUsage = reallyHovering ? (int) (ConfigHelper.common().armor.jetBootsAirUsage.get() * (player.isShiftKeyDown() ? 0.25F : 0.5F)) : 0;
            jbLocal.resetAccel();
        } else if (isOnGround(player)) {
            jbLocal.setHovering(false);
        } else {
            jbLocal.resetAccel();
        }
    } else {
        // insufficient pressure!
        if (jbState.isEnabled() && !player.onGround() && !player.isFallFlying() && jbLocal.isHovering()) {
            // still active and in the air: using minimal air here keeps the boots running
            // and thus avoids triggering multiple looping sounds (see "jet boots starting up" code below)
            jetbootsAirUsage = 1;
        }
        setJetBootsActive(commonArmorHandler,false);
    }

    if (jetbootsAirUsage != 0 && !player.level().isClientSide) {
        if (jbLocal.getPrevJetBootsAirUsage() == 0) {
            // jet boots starting up
            NetworkHandler.sendToAllTracking(new PacketPlayMovingSound(MovingSounds.Sound.JET_BOOTS, MovingSoundFocus.of(player)), player.level(), player.blockPosition());
            ModCriterionTriggers.FLIGHT.get().trigger((ServerPlayer) player);
        }
        if (player.horizontalCollision) {
            double vel = player.getDeltaMovement().length();
            if (player.level().getDifficulty() == Difficulty.HARD) {
                vel *= 2;
            } else if (player.level().getDifficulty() == Difficulty.NORMAL) {
                vel *= 1.5;
            }
            if (vel > 2) {
                player.playSound(vel > 2.5 ? SoundEvents.GENERIC_BIG_FALL : SoundEvents.GENERIC_SMALL_FALL, 1.0F, 1.0F);
                player.hurt(player.damageSources().flyIntoWall(), (float) vel);
                ModCriterionTriggers.FLY_INTO_WALL.get().trigger((ServerPlayer) player);
            }
        }
        commonArmorHandler.addAir(EquipmentSlot.FEET, -jetbootsAirUsage);

        if (player.position().y > player.level().getMaxBuildHeight() + ConfigHelper.common().armor.jetBootsHeightLimit.get()) {
            player.getCooldowns().addCooldown(ModItems.PNEUMATIC_BOOTS.get(), 20);
        }
    }
    jbLocal.setPrevJetBootsAirUsage(jetbootsAirUsage);

}

