public static void handleUpgradeModifiers(ItemAttributeModifierEvent event) {
    UpgradeData upgradeData = UpgradeData.getUpgradeData(event.getItemStack());
    if (upgradeData != UpgradeData.NONE) {
        var equipmentSlot = UpgradeUtils.SLOTS_BY_NAME.get(upgradeData.getUpgradedSlot());
        if (equipmentSlot == null) {
            return;
        }
        var groupSlot = EquipmentSlotGroup.bySlot(equipmentSlot);
        UpgradeUtils.handleAttributeEvent(event.getModifiers(), upgradeData, (atr, mod) -> event.addModifier(atr, mod, groupSlot), (atr, mod) -> event.removeModifier(atr, mod.id()), upgradeData.getUpgradedSlot());
    }
}

public ItemMode getCurrentItemMode(ItemStack stack) {
    int mode = this.getItemMode(stack);

    // sanity check.
    // here to prevent crashes if old system has invalid mode
    if (mode < 0 || mode >= this.getItemModes().size()) {
        mode = 0;
        this.setItemMode(stack, mode);
    }
    return this.getItemModes().get(mode);
}

public void setSpellstoneCooldown(int spellstoneCooldown) {
	int newValue = Math.max(spellstoneCooldown, 0);

	if (this.spellstoneCooldown != newValue) {
		this.needsSync = true;
		this.spellstoneCooldown = newValue;

		for (Item spellstone : EnigmaticItems.SPELLSTONES) {
			this.player.get().getCooldowns().addCooldown(spellstone, this.spellstoneCooldown);
		}
	}
}

