public void addModifiers(AffixInstance inst, StackAttributeModifiersEvent event) {
    LootCategory cat = inst.category();
    if (cat.isNone()) {
        Apotheosis.LOGGER.debug("Attempted to apply the attributes of affix {} on item {}, but it is not an affix-compatible item!", this.id(), inst.stack().getHoverName().getString());
        return;
    }
    ModifierInst modif = this.modifiers.get(inst.getRarity());
    if (modif.attr == null) {
        Apotheosis.LOGGER.debug("The affix {} has attempted to apply a null attribute modifier to {}!", this.id(), inst.stack().getHoverName().getString());
        return;
    }
    event.addModifier(this.attribute, modif.build(inst), cat.getSlots());
}

private boolean chargeCrossbows(Level level, LivingEntity entity, ItemStack stack, InteractionHand hand, int elapsed) {
    int chargeDuration = getChargeDurationMod(stack, level);
    boolean loaded = !CrossbowItem.isCharged(stack) && elapsed >= chargeDuration && tryLoadProjectiles(entity, stack);

    if (CrossbowItem.isCharged(stack) && canUseDoubleCrossbow(entity)) {
        ItemStack otherStack = entity.getItemInHand(hand == InteractionHand.MAIN_HAND ? InteractionHand.OFF_HAND : InteractionHand.MAIN_HAND);
        if (otherStack.getItem() instanceof HunterCrossbowItem otherCrossbow && !CrossbowItem.isCharged(otherStack) && !entity.getProjectile(otherStack).isEmpty() && elapsed - chargeDuration >= otherCrossbow.getChargeDurationMod(otherStack, level) && otherCrossbow.tryLoadProjectiles(entity, otherStack)) {
            loaded = true;
        }
    }

    return loaded;
}

public void onSpellCast(SpellCastEvent spellCastEvent, PerkInstance perkInstance) {
    LivingEntity caster = spellCastEvent.context.getUnwrappedCaster();
    int level = PerkUtil.countForPerk(INSTANCE, caster);

    if (caster.isOnFire()) {
        caster.extinguishFire();
        caster.addEffect(new MobEffectInstance(ModPotions.IMMOLATE_EFFECT, 20 * 5, level - 1));
    }
    if (caster.level.getBlockState(caster.blockPosition()).is(BlockTags.FIRE)) {
        caster.level.removeBlock(caster.blockPosition(), false);
        caster.addEffect(new MobEffectInstance(ModPotions.IMMOLATE_EFFECT, 20 * 5, level - 1));
    }
}

