public void onResolve(HitResult rayTraceResult, Level world, @Nullable LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    if (!canSummon(shooter))
        return;

    Vec3 vector3d = safelyGetHitPos(rayTraceResult);
    int ticks = (int) (20 * (GENERIC_INT.get() + EXTEND_TIME.get() * spellStats.getDurationMultiplier()));
    BlockPos pos = BlockPos.containing(vector3d);
    if (ticks <= 0) return;
    for (int i = 0; i < 3; ++i) {
        BlockPos blockpos = pos.offset(-2 + shooter.getRandom().nextInt(5), 2, -2 + shooter.getRandom().nextInt(5));
        EntityAllyVex vexentity = new EntityAllyVex(world, shooter);
        vexentity.moveTo(blockpos, 0.0F, 0.0F);
        vexentity.finalizeSpawn((ServerLevelAccessor) world, world.getCurrentDifficultyAt(blockpos), MobSpawnType.MOB_SUMMONED, null);
        vexentity.setOwner(shooter);
        vexentity.setBoundOrigin(blockpos);
        vexentity.setLimitedLife(ticks);
        summonLivingEntity(rayTraceResult, world, shooter, spellStats, spellContext, resolver, vexentity);
    }
    shooter.addEffect(new MobEffectInstance(ModPotions.SUMMONING_SICKNESS_EFFECT, ticks));
}

private void updateAttribute(Player player, Holder<Attribute> attribute, Identifier id, ToFloatFunction<Player> additionalSupplier) {
    AttributeInstance attributeInstance = player.getAttribute(attribute);
    if (attributeInstance != null) {
        AttributeModifier existing = attributeInstance.getModifier(id);
        float additional = additionalSupplier.applyAsFloat(player);
        if (existing != null) {
            if (existing.amount() == additional) {
                //If we already have it set to the correct value just exit
                //Note: We don't need to check for if it is equal to zero as we should never have the attribute applied then
                return;
            }
            //Otherwise, remove the no longer valid value, so we can add it again properly
            attributeInstance.removeModifier(id);
        }
        if (additional > 0) {
            //If we should have the attribute, but we don't have it set yet, or our stored amount was different, update
            attributeInstance.addTransientModifier(new AttributeModifier(id, additional, Operation.ADD_VALUE));
        }
    }
}

public boolean canCast(ItemStack stack, Spell spell, EntityPlayer caster, EnumHand hand, int castingTick, SpellModifiers modifiers){

	// Spells can only be cast if the casting events aren't cancelled...
	if(castingTick == 0){
		if(MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Pre(Source.WAND, spell, caster, modifiers))) return false;
	}else{
		if(MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Tick(Source.WAND, spell, caster, modifiers, castingTick))) return false;
	}

	int cost = (int)(spell.getCost() * modifiers.get(SpellModifiers.COST) + 0.1f); // Weird floaty rounding

	// As of wizardry 4.2 mana cost is only divided over two intervals each second
	if(spell.isContinuous) cost = getDistributedCost(cost, castingTick);

	// ...and the wand has enough mana to cast the spell...
	return cost <= this.getMana(stack) // This comes first because it changes over time
			// ...and the wand is the same tier as the spell or higher...
			&& spell.getTier().level <= this.tier.level
			// ...and either the spell is not in cooldown or the player is in creative mode
			&& (WandHelper.getCurrentCooldown(stack) == 0 || caster.isCreative());
}

protected boolean addPartialCharge(ItemStack containerStack, int slot, int chargeToAdd, int pointLimit, ItemStack chargeStack) {
	int worth = getSlotWorth(slot);
	int storedCharge = getMigratedStoredCharge(containerStack, slot);
	int currentCharge = getPartialCharge(containerStack, slot);
	long totalCharge = (long) storedCharge * worth + currentCharge;
	int remainingCapacity = Math.toIntExact(Math.max(pointLimit - totalCharge, 0));
	int acceptedCharge = Math.min(Math.max(chargeToAdd, 0), remainingCapacity);
	int updatedPartialCharge = currentCharge + acceptedCharge;
	if (updatedPartialCharge >= worth) {
		int maxPhysicalCharge = pointLimit / worth;
		int fullCharges = Math.min(updatedPartialCharge / worth, Math.max(maxPhysicalCharge - storedCharge, 0));
		if (fullCharges > 0) {
			ItemStack storedChargeStack = chargeStack.copy();
			storedChargeStack.setCount(fullCharges);
			addStoredCharge(containerStack, slot, fullCharges, storedChargeStack);
			updatedPartialCharge -= fullCharges * worth;
		}
	}
	setPartialCharge(containerStack, slot, updatedPartialCharge);
	return acceptedCharge > 0;
}

