public static void totemEvent(final LivingDeathEvent event) {
    LivingEntity entity = event.getEntity();
    if (!(entity instanceof Player player))
        return;
    var holder = PerkUtil.getHolderForPerk(TotemPerk.INSTANCE, entity);
    if (holder == null)
        return;
    CompoundTag tag = holder.getB().getTagForPerk(TotemPerk.INSTANCE);
    if (tag == null || !tag.getBoolean("isActive")) {
        return;
    }
    entity.setHealth(1.0F);
    entity.removeAllEffects();
    entity.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 900, 1));
    entity.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, 100, 1));
    entity.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 800, 0));
    entity.level.broadcastEntityEvent(entity, (byte) 35);
    tag.putBoolean("isActive", false);
    holder.getA().set(DataComponentRegistry.ARMOR_PERKS, holder.getB().setTagForPerk(TotemPerk.INSTANCE, tag));
    PortUtil.sendMessage(entity, Component.translatable("ars_nouveau.totem_perk.trigger"));
    event.setCanceled(true);
}

public void triggerActiveAbility(Level world, ServerPlayer player, ItemStack stack) {
	if (SuperpositionHandler.hasSpellstoneCooldown(player))
		return;

	Vector3 accelerationVec = new Vector3(player.getLookAngle());
	Vector3 motionVec = new Vector3(player.getDeltaMovement());

	if (player.isFallFlying()) {
		accelerationVec = accelerationVec.multiply(accelerationModifierElytra.getValue());
		accelerationVec = accelerationVec.multiply(1 / (Math.max(0.15D, motionVec.mag()) * 2.25D));
	} else {
		accelerationVec = accelerationVec.multiply(accelerationModifier.getValue());
	}

	Vector3 finalMotion = new Vector3(motionVec.x + accelerationVec.x, motionVec.y + accelerationVec.y, motionVec.z + accelerationVec.z);

	EnigmaticLegacy.packetInstance.send(PacketDistributor.PLAYER.with(() -> player), new PacketPlayerMotion(finalMotion.x, finalMotion.y, finalMotion.z));
	player.setDeltaMovement(finalMotion.x, finalMotion.y, finalMotion.z);

	world.playSound(null, player.blockPosition(), SoundEvents.ENDER_EYE_LAUNCH, SoundSource.PLAYERS, 1.0F, (float) (0.6F + (Math.random() * 0.1D)));

	SuperpositionHandler.setSpellstoneCooldown(player, this.getCooldown(player));
}

public void releaseUsing(ItemStack stack, Level world, LivingEntity entity, int chargeTimer) {
  if (!(entity instanceof Player)) {
    return;
  }
  float percentageCharged = getChargedPercent(stack, chargeTimer, entity);
  if (percentageCharged >= 0.98) { //full charge with a bit of buffer room
    Player player = (Player) entity;
    HitResult trace = player.pick(RANGE.get(), 0, true);
    if (trace.getType() == HitResult.Type.BLOCK) {
      BlockHitResult blockRayTraceResult = (BlockHitResult) trace;
      Direction face = blockRayTraceResult.getDirection();
      BlockPos newPos = blockRayTraceResult.getBlockPos().relative(face);
      BlockPos oldPos = player.blockPosition();
      if (EntityUtil.enderTeleportEvent(player, world, newPos)) { // && player.getPosition() != currentPlayerPos    
        ItemStackUtil.damageItem(player, stack);
        if (world.isClientSide) {
          ParticleUtil.spawnParticleBeam(world, ParticleTypes.PORTAL, oldPos, newPos, RANGE.get());
          SoundUtil.playSound(player, SoundRegistry.WARP_ECHO.get());
        }
      }
    }
  }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int amount = SpellConfig.BulwarkShieldAmount.get();
    int duration = SpellConfig.BulwarkShieldTime.get();
    if (WandUtil.enchantedFocus(caster)) {
        amount += WandUtil.getPotencyLevel(caster);
        duration *= Math.min(4, WandUtil.getLevels(ModEnchantments.DURATION.get(), caster) + 1);
    }
    amount += spellStat.getPotency();
    if (spellStat.getDuration() > 0){
        duration = spellStat.getDuration();
    }
    LivingEntity target = this.getTarget(caster);
    if (isShifting(caster) && target != null){
        if (MobUtil.areAllies(target, caster)){
            MiscCapHelper.setShields(target, amount);
            MiscCapHelper.setShieldTime(target, duration);
        }
    } else {
        MiscCapHelper.setShields(caster, amount);
        MiscCapHelper.setShieldTime(caster, duration);
    }
    this.playSound(worldIn, caster, ModSounds.SHIELD_UP.get(), 3.0F, caster.getVoicePitch());
