private void doAction(ItemStack stack, Level world, Player player) {
  BlockPos p = player.blockPosition();
  final int r = RANGE.get();
  List<Mob> all = world.getEntitiesOfClass(Mob.class, new AABB(p.getX() - r, p.getY() - r, p.getZ() - r, p.getX() + r, p.getY() + r, p.getZ() + r));
  List<Mob> trimmedTargets = new ArrayList<Mob>();
  for (Mob target : all) {
    MobCategory type = target.getClassification(false);
    if (target.getUUID().compareTo(player.getUUID()) != 0
        && !type.isFriendly()) {
      //not friendly and not me
      trimmedTargets.add(target);
    }
  }
  if (!world.isClientSide) {
    IEnergyStorage storage = CapabilityUtil.energy(stack);//stack.getCapability(Capabilities.ENERGY, null).orElse(null);
    final int cost = COST.get();
    if (storage != null && storage.extractEnergy(cost, true) == cost) {
      //we can afford it
      storage.extractEnergy(cost, false);
      MagicMissileEntity projectile = new MagicMissileEntity(player, world);
      projectile.setTarget(EntityUtil.getClosestEntity(world, player, trimmedTargets));
      shootMe(world, player, projectile, 0, ItemBaseCyclic.VELOCITY_MAX);
    }
  }
}

protected void passivePush(ServerLevel level, LivingEntity entity, ItemStack stack, boolean reducedStrength) {
    for (LivingEntity nearbyEntity : level.getNearbyEntities(LivingEntity.class, TargetingConditions.forCombat().selector(this::affectsEntity), entity, entity.getBoundingBox().inflate(getRange(stack)))) {
        Vec3 baseVector = entity.position().subtract(nearbyEntity.position()).multiply(1, 0, 1).normalize(); //Normalized horizontal (xz) vector giving the direction towards the holder of this crucifix
        Vec3 oldDelta = nearbyEntity.getDeltaMovement();
        Vec3 horizontalDelta = oldDelta.multiply(1, 0, 1);
        double parallelScale = baseVector.dot(horizontalDelta);
        if (parallelScale > 0) {
            Vec3 parallelPart = baseVector.scale(parallelScale); //Part of delta that is parallel to baseVector
            double scale = determineSlowdown(determineEntityTier(nearbyEntity), reducedStrength);
            Vec3 newDelta = oldDelta.subtract(parallelPart.scale(scale)); //Substract parallel part from old Delta (scaled to still allow some movement)
            if (newDelta.lengthSqr() > oldDelta.lengthSqr()) { //Just to make sure we do not speed up the movement even though this should not be possible
                newDelta = Vec3.ZERO;
            }
            //Unfortunately, Vanilla converts y-collision with ground into forward movement later on (in #move)
            //Therefore, we check for collision here and remove any y component if entity would collide with ground
            Vec3 collisionDelta = ((EntityAccessor) nearbyEntity).invokeCollide(newDelta);
            if (collisionDelta.y != newDelta.y && newDelta.y < 0) {
                newDelta = newDelta.multiply(1, 0, 1);
            }

            nearbyEntity.setDeltaMovement(newDelta);
        }
        applyEffect(entity, level, nearbyEntity, stack);
    }
}

protected void applyEffect(LivingEntity owner, ServerLevel level, LivingEntity entity, ItemStack stack) {
    if (entity instanceof Player player && Helper.isVampire(player)) {
        Tier tier = getVampirismTier();
        if (IRefinementHandler.get(player).filter(s -> s.isRefinementEquipped(ModRefinements.CRUCIFIX_RESISTANT)).isPresent()) {
            int i = UtilLib.indexOf(Tier.values(), tier);
            if (i > 0) {
                tier = Tier.values()[i - 1];
            } else if(i == 0) {
                return;
            }
        }
        var viewVector = owner.getViewVector(1.0F).normalize();
        var targetVector = owner.position().subtract(entity.position());
        double distance = targetVector.lengthSqr();
        double degrees = Math.toDegrees(Math.cos(viewVector.dot(targetVector.normalize())));
        boolean effect = switch (tier) {
            case ULTIMATE -> (distance < 100 && degrees < 20) || (distance < 56 && degrees < 55) || (distance < 25 && degrees < 70);
            case ENHANCED -> (distance < 56 && degrees < 45) || (distance < 25 && degrees < 55);
            case NORMAL -> (distance < 25 && degrees < 45);
        };
        if (effect) {
            VampirePlayer.get(player).effectCrucifixSuppression();
        }
    }
}

public boolean applyEffectTick(LivingEntity entity, int amp) {
    int multiplier = 0;
    for (ItemStack i : entity.getArmorSlots()) {
        IEnergyStorage energyStorage = i.getCapability(Capabilities.EnergyStorage.ITEM);
        if (energyStorage != null) {
            multiplier++;
        }
    }

    IEnergyStorage energyStorage = entity.getMainHandItem().getCapability(Capabilities.EnergyStorage.ITEM);
    if (energyStorage != null)
        multiplier++;
    energyStorage = entity.getOffhandItem().getCapability(Capabilities.EnergyStorage.ITEM);
    if (energyStorage != null)
        multiplier++;
    if (multiplier > 0) {
        int numTicks = 0;
        if (entity instanceof Player) {
            CompoundTag tag = entity.getPersistentData().getCompound(Player.PERSISTED_NBT_TAG);
        }
        entity.hurt(entity.level.damageSources().lightningBolt(), 20 * multiplier * (amp + 1));

    }
    return true;
}

public InteractionResultHolder<ItemStack> use(Level pLevel, Player player, InteractionHand pHand) {
    ItemStack itemstack = player.getItemInHand(pHand);
    //If we are charged, shoot.
    if (isCharged(itemstack)) {
        performShooting(pLevel, player, pHand, itemstack, 3f/*getShootingPower(itemstack)*/, 1.0F, null);
        //If we have an additional ammo item, begin autoloading. If not, play a sound cue. (We do not save or reserve this item, so even though we begin loading, it could still fail)
        if (!player.getProjectile(itemstack).isEmpty()) {
            startLoading(player, itemstack);
        } else {
            player.playSound(SoundEvents.ITEM_BREAK, 0.75f, 1.5f);
        }
        return InteractionResultHolder.consume(itemstack);
    } else if (isLoading(itemstack)) {
        if (player.isCrouching()) {
            setLoadingTicks(itemstack, 0);
            setLoading(itemstack, false);
        }
    } else if (!player.getProjectile(itemstack).isEmpty()) {
        startLoading(player, itemstack);
        return InteractionResultHolder.consume(itemstack);
    } else {
        return InteractionResultHolder.fail(itemstack);
    }
    return InteractionResultHolder.pass(itemstack);
}

public static void onPlayerRespawn(PlayerEvent.PlayerRespawnEvent event) {
    if (event.getEntity() instanceof ServerPlayer serverPlayer) {

        //Clear fire and frozen
        serverPlayer.clearFire();
        serverPlayer.setTicksFrozen(0);
        var data = serverPlayer.getEntityData().packDirty();
        if (data != null) {
            serverPlayer.connection.send(new ClientboundSetEntityDataPacket(serverPlayer.getId(), data));
        }

        //Cancel casting
        Utils.serverSideCancelCast(serverPlayer);

        //Sync effects
        serverPlayer.getActiveEffects().forEach((effect -> {
            if (effect.getEffect() instanceof SummonTimer) {
                serverPlayer.server.getPlayerList().sendActivePlayerEffects(serverPlayer);
            }
        }));

        //Set respawn mana
        MagicData.getPlayerMagicData(serverPlayer).setMana((int) (serverPlayer.getAttributeValue(AttributeRegistry.MAX_MANA) * ServerConfigs.MANA_SPAWN_PERCENT.get()));
    }
}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
    int potency = spellStat.getPotency();
    int duration = spellStat.getDuration();
    if (WandUtil.enchantedFocus(caster)){
        duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
        potency += WandUtil.getPotencyLevel(caster);
    }
    LivingEntity target = this.getTarget(caster);
    AABB aabb = caster.getBoundingBox().inflate(4.0D);
    if (isShifting(caster) && target != null){
        if (MobUtil.areAllies(target, caster)){
            target.addEffect(new MobEffectInstance(GoetyEffects.CHILL_HIDE.get(), MathHelper.secondsToTicks(45 * duration), potency));
            aabb = target.getBoundingBox().inflate(4.0D);
        }
    } else {
        caster.addEffect(new MobEffectInstance(GoetyEffects.CHILL_HIDE.get(), MathHelper.secondsToTicks(45 * duration), potency));
    }
    if (this.rightStaff(staff)){
        for (LivingEntity livingEntity : worldIn.getEntitiesOfClass(LivingEntity.class, aabb)) {
            if (MobUtil.areAllies(livingEntity, caster) && livingEntity != caster) {
                livingEntity.addEffect(new MobEffectInstance(GoetyEffects.CHILL_HIDE.get(), MathHelper.secondsToTicks(45 * duration), potency));
            }
        }
    }
    this.playSound(worldIn, caster, ModSounds.ICE_SPIKE_HIT.get(), 1.0F, 0.5F);
}

