public static IHackableEntity<?> getHackableForEntity(Entity entity, Player player) {
    HackManager manager = getInstance(player.level());

    // prune the tracked entities map every 60 ticks, removing dead or no-longer-hackable entities
    if (player.level().getGameTime() - 60 > manager.lastEntityPrune) {
        manager.hackableEntities.entrySet().removeIf(
                entry -> !entry.getKey().isAlive()
                        || !entry.getValue().canHack(entry.getKey(), player) && !isInDisplayCooldown(entry.getValue(), entry.getKey())
        );
        manager.lastEntityPrune = player.level().getGameTime();
    }

    // entities which implement IHackableEntity directly
    if (entity instanceof IHackableEntity<?> h && h.canHack(entity, player))
        return h;

    // entities which have been registered with the hack manager
    IHackableEntity<?> hackable = manager.hackableEntities.get(entity);
    if (hackable == null) {
        hackable = CommonArmorRegistry.getInstance().getHackable(entity, player);
        if (hackable != null) {
            manager.hackableEntities.put(entity, hackable);
        }
    }
    return hackable;
}

static void deflectProjectile(ProjectileImpactEvent event, HitResult hitResult, Projectile projectile) {
    if (hitResult.getType() == HitResult.Type.ENTITY && hitResult instanceof EntityHitResult entityHitResult) {
        if (entityHitResult.getEntity() instanceof LivingEntity impactedLiving) {
            if (projectile.getType().is(AetherTags.Entities.DEFLECTABLE_PROJECTILES)) {
                SlotEntryReference slotResult = EquipmentUtil.getAccessory(impactedLiving, AetherItems.SHIELD_OF_REPULSION.get());
                if (slotResult != null) {
                    Vec3 motion = impactedLiving.getDeltaMovement();
                    if (impactedLiving instanceof Player player) {
                        var data = player.getData(AetherDataAttachments.AETHER_PLAYER);
                        if (!data.isMoving() || (data.isMoving() && motion.x() == 0.0 && (motion.y() == ConstantsUtil.DEFAULT_DELTA_MOVEMENT_Y || motion.y() == 0.0) && motion.z() == 0.0)) {
                            if (player.level().isClientSide()) { // Values used by the Shield of Repulsion screen overlay vignette.
                                data.setProjectileImpactedMaximum(150);
                                data.setProjectileImpactedTimer(150);
                            }
                            handleDeflection(event, projectile, player, slotResult);
                        }
                    } else {
                        if (motion.x() == 0.0 && (motion.y() == ConstantsUtil.DEFAULT_DELTA_MOVEMENT_Y || motion.y() == 0.0) && motion.z() == 0.0) {
                            handleDeflection(event, projectile, impactedLiving, slotResult);
                        }
                    }
                }
            }
        }
    }
}

public ItemStack finishUsingItem(ItemStack stack, Level worldIn, LivingEntity entityLiving) {
  if (!worldIn.isClientSide && entityLiving instanceof Player player) { // && !player.isCrouching()
    IItemHandler handler = stack.getCapability(Capabilities.ItemHandler.ITEM);
    if (handler != null) {
      int foundSlot = -1;
      ItemStack found = ItemStack.EMPTY;
      //just go left to right and eat in order
      for (int i = 0; i < handler.getSlots(); i++) {
        ItemStack test = handler.getStackInSlot(i);
        if (test.has(DataComponents.FOOD) && !player.getCooldowns().isOnCooldown(test.getItem())) {
          found = test;
          foundSlot = i;
          break;
        }
      }
      if (!found.isEmpty()) {
        ChatUtil.addServerChatMessage(player, found.getDisplayName());
        // forward to the food's finishUsingItem so mods can apply their own effects (e.g. artifacts' everlasting beef);
        // pass a copy so vanilla LivingEntity.eat's in-place shrink doesn't bypass the handler's onContentsChanged
        found.getItem().finishUsingItem(found.copy(), worldIn, entityLiving);
        // route the actual consumption through the handler so onContentsChanged fires and the slot persists
        handler.extractItem(foundSlot, 1, false);
      }
    }
  }
  return super.finishUsingItem(stack, worldIn, entityLiving);
}

public void onUseTick(Level level, LivingEntity livingEntity, ItemStack rendingGale, int remainingUseDuration) {
	if (!(livingEntity instanceof Player player)) {
		return;
	}

	Mode mode = getMode(rendingGale);
	int chargeCost = mode == Mode.BOLT ? getBoltChargeCost() : getChargeCost();
	if (getTotalCharge(rendingGale) < chargeCost) {
		player.releaseUsingItem();
		return;
	}

	if (mode == Mode.BOLT) {
		if (remainingUseDuration % 8 == 0) {
			spawnBolt(rendingGale, player);
		}
	} else if (player.level().isClientSide || useCharge(rendingGale, FIRST_SLOT, chargeCost)) {
		if (mode == Mode.FLIGHT) {
			attemptFlight(player);
			spawnFlightParticles(player.level(), player.getX(), player.getY() + player.getEyeHeight(), player.getZ(), player);
		} else if (mode == Mode.PUSH) {
			doRadialPush(player.level(), player.getX(), player.getY(), player.getZ(), player, false);
		} else if (mode == Mode.PULL) {
			doRadialPush(player.level(), player.getX(), player.getY(), player.getZ(), player, true);
		}
	}
}

public static double getManaRegen(Player e) {
    IManaCap mana = CapabilityRegistry.getMana(e);

    if (mana == null) return 0;
    double regen = 0;

    int tier = mana.getBookTier();
    double numGlyphs = mana.getGlyphBonus();
    regen += numGlyphs * ServerConfig.GLYPH_REGEN_BONUS.get();
    regen += tier * ServerConfig.TIER_REGEN_BONUS.get();
    regen += ServerConfig.INIT_MANA_REGEN.get();

    var manaAttribute = e.getAttribute(PerkAttributes.MANA_REGEN_BONUS);
    if (manaAttribute != null) {
        var manaCache = manaAttribute.getModifier(MANA_REGEN_MODIFIER);
        if (manaCache == null || manaCache.amount() != regen) {
            if (manaCache != null) manaAttribute.removeModifier(manaCache);
            manaAttribute.addTransientModifier(new AttributeModifier(MANA_REGEN_MODIFIER, regen, AttributeModifier.Operation.ADD_VALUE));
        }
        regen = manaAttribute.getValue();
    }

    ManaRegenCalcEvent event = new ManaRegenCalcEvent(e, regen);
    NeoForge.EVENT_BUS.post(event);
    regen = event.getRegen();
    return regen;
}

public static boolean revive(ItemStack itemStack, LivingEntity victim){
    if (!itemStack.isEmpty()) {
        if (itemStack.getTag() != null) {
            if (itemStack.getTag().getInt(ITotem.SOULS_AMOUNT) == ITotem.MAX_SOULS) {
                if (!victim.level.isClientSide) {
                    victim.setHealth(1.0F);
                    victim.removeAllEffects();
                    victim.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 900, 1));
                    victim.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, 100, 1));
                    victim.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 800, 0));
                    if (victim instanceof Player) {
                        ModNetwork.sendTo((Player) victim, new TotemDeathPacket(victim.getUUID()));
                    } else {
                        ServerLevel serverWorld = (ServerLevel) victim.level;
                        serverWorld.getChunkSource().broadcast(victim, new ClientboundEntityEventPacket(victim, (byte)35));
                    }
                    ITotem.setSoulsAmount(itemStack, 0);
                    if (victim instanceof Mob){
                        itemStack.shrink(1);
                        victim.spawnAtLocation(new ItemStack(ModItems.SPENT_TOTEM.get()));
                    }
                }
                return true;
            }
        }
    }
    return false;
}

public void releaseUsing(ItemStack stack, Level level, LivingEntity livingEntity, int useTimeRemaining) {
    if (level instanceof ServerLevel serverLevel) {
        int CastTime = stack.getUseDuration() - useTimeRemaining;
        ISpell spell = GoetyEventFactory.onStopSpell(livingEntity, stack, this.getSpell(stack), CastTime, useTimeRemaining);
        if (spell != null) {
            spell.stopSpell(serverLevel, livingEntity, stack, IWand.getFocus(stack), CastTime, WandUtil.getStats(livingEntity, spell));
            if (livingEntity instanceof Player player) {
                if (spell instanceof IChargingSpell chargeSpell) {
                    if (chargeSpell.shotsNumber(player, stack) > 0) {
                        if (this.ShotsFired(stack) > 0) {
                            float coolPercent = (float) this.ShotsFired(stack) / chargeSpell.shotsNumber(player, stack);
                            this.setShots(stack, 0);
                            if (!spell.hasCustomCooldown(player, stack, IWand.getFocus(stack), Mth.floor(chargeSpell.spellCooldown(player) * coolPercent))) {
                                SEHelper.addSpellCooldown(player, spell, Mth.floor(chargeSpell.spellCooldown(player) * coolPercent));
                            }
                        }
                    } else {
                        if (!spell.hasCustomCooldown(player, stack, IWand.getFocus(stack), Mth.floor(chargeSpell.spellCooldown(player)))) {
                            if (CastTime > chargeSpell.castUp(player, stack)) {
                                SEHelper.addSpellCooldown(player, spell, Mth.floor(chargeSpell.spellCooldown(player)));
                            }
                        }
                    }
                }
            }
        }
    }
}

public void onResolveEntity(@NotNull EntityHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    var dispelEvent = NeoForge.EVENT_BUS.post(new DispelEvent.Pre(rayTraceResult, world, shooter, spellStats, spellContext));
    if (dispelEvent.isCanceled())
        return;
    if (rayTraceResult.getEntity() instanceof LivingEntity entity) {
        Collection<MobEffectInstance> effects = entity.getActiveEffects();
        MobEffectInstance[] array = effects.toArray(new MobEffectInstance[0]);
        Optional<HolderSet.Named<MobEffect>> blacklist = world.registryAccess().registryOrThrow(Registries.MOB_EFFECT).getTag(PotionEffectTags.DISPEL_DENY);
        Optional<HolderSet.Named<MobEffect>> whitelist = world.registryAccess().registryOrThrow(Registries.MOB_EFFECT).getTag(PotionEffectTags.DISPEL_ALLOW);
        for (MobEffectInstance e : array) {
            if (e.getCures().contains(EffectCures.MILK)) {
                if (blacklist.isPresent() && blacklist.get().stream().anyMatch(effect -> effect.value() == e.getEffect()))
                    continue;
                entity.removeEffect(e.getEffect());
            } else if (whitelist.isPresent() && whitelist.get().stream().anyMatch(effect -> effect.value() == e.getEffect())) {
                entity.removeEffect(e.getEffect());
            }
        }
        if (!entity.isAlive() || entity.getHealth() <= 0 || entity.isRemoved()) {
            //TODO dispel loot table?
            return;
        }
        if (entity instanceof IDispellable iDispellable) {
            iDispellable.onDispel(shooter);
        }
        NeoForge.EVENT_BUS.post(new DispelEvent.Post(rayTraceResult, world, shooter, spellStats, spellContext));
    }
}

public void triggerActiveAbility(Level world, ServerPlayer player, ItemStack stack) {
	if (SuperpositionHandler.hasSpellstoneCooldown(player))
		return;

	LivingEntity target = SuperpositionHandler.getObservedEntity(player, world, 3.0F, (int) phaseRange.getValue());

	if (target != null) {
		Vector3 targetPos = Vector3.fromEntityCenter(target);
		Vector3 chaserPos = Vector3.fromEntityCenter(player);

		Vector3 dir = targetPos.subtract(chaserPos);
		dir = dir.normalize();
		dir = dir.multiply(1.5D);

		dir = targetPos.add(dir);

		world.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
		EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketPortalParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 72, 1.0F, false));

