public boolean canCastTouch(ItemStack stack, Level worldIn, LivingEntity caster, @Nullable LivingEntity target){
    Player playerEntity = (Player) caster;
    if (worldIn instanceof ServerLevel serverLevel) {
        ISpell spell = GoetyEventFactory.onTouchBasedSpell(caster, stack, this.getSpell(stack));
        if (spell != null && !this.cannotCast(caster, stack, spell)) {
            if (spell instanceof ITouchSpell touchSpell) {
                if (!touchSpell.targetConditions(serverLevel, caster, target, stack, WandUtil.getStats(caster, touchSpell))) {
                    return false;
                }
            }
            if (playerEntity.isCreative()){
                if (!spell.hasCustomCooldown(caster, stack, IWand.getFocus(stack), spell.spellCooldown(playerEntity))) {
                    SEHelper.addSpellCooldown(playerEntity, spell, spell.spellCooldown(playerEntity));
                }
                return stack.getTag() != null;
            } else if (SEHelper.getSoulsAmount(playerEntity, SoulUse(caster, stack))) {
                if (stack.getTag() != null) {
                    SEHelper.decreaseSouls(playerEntity, SoulUse(caster, stack));
                    if (!spell.hasCustomCooldown(caster, stack, IWand.getFocus(stack), spell.spellCooldown(playerEntity))) {
                        SEHelper.addSpellCooldown(playerEntity, spell, spell.spellCooldown(playerEntity));
                    }
                    SEHelper.sendSEUpdatePacket(playerEntity);
                    return true;
                }
            }
        }
    }
    return false;
}

public boolean spawnServant(Player player, ItemStack stack, Level level, BlockPos blockPos) {
    if (!level.isClientSide) {
        if (level.getBlockState(blockPos).is(Blocks.BLUE_ICE)) {
            if (conditionsMet(level, player)) {
                if (canSpawn(level, blockPos)) {
                    IceGolem iceGolem = ModEntityType.ICE_GOLEM.get().create(level);
                    if (iceGolem != null) {
                        iceGolem.setTrueOwner(player);
                        iceGolem.finalizeSpawn((ServerLevelAccessor) level, level.getCurrentDifficultyAt(iceGolem.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
                        iceGolem.moveTo((double) blockPos.getX() + 0.5D, (double) blockPos.below().getY() + 0.05D, (double) blockPos.getZ() + 0.5D, 0.0F, 0.0F);
                        if (level.addFreshEntity(iceGolem)) {
                            removeBlocks(level, blockPos);
                            stack.shrink(1);
                            if (player instanceof ServerPlayer serverPlayer) {
                                CriteriaTriggers.SUMMONED_ENTITY.trigger(serverPlayer, iceGolem);
