public void releaseUsing(ItemStack bow, Level level, LivingEntity living, int chargeRemaining) {
  ToolStack tool = ToolStack.from(bow);

  // call the stop using modifier hook
  int duration = getUseDuration(bow);
  for (ModifierEntry entry : tool.getModifiers()) {
    entry.getHook(ModifierHooks.TOOL_USING).beforeReleaseUsing(tool, entry, living, duration, chargeRemaining, ModifierEntry.EMPTY);
  }

  // any reason we shouldn't load?
  // specifically: broken, not fully charged, already have ammo
  ModDataNBT persistentData = tool.getPersistentData();
  if (tool.isBroken() || getUseDuration(bow) - chargeRemaining < persistentData.getInt(KEY_DRAWTIME) || persistentData.contains(KEY_CROSSBOW_AMMO, Tag.TAG_COMPOUND)) {
    return;
  }

  // find ammo and store it on the bow
  Player player = living instanceof Player p ? p : null;
  ItemStack ammo = BowAmmoModifierHook.consumeAmmo(tool, bow, living, player, getSupportedHeldProjectiles());
  if (!ammo.isEmpty()) {
    level.playSound(null, living.getX(), living.getY(), living.getZ(), SoundEvents.CROSSBOW_LOADING_END, SoundSource.PLAYERS, 1.0F, 1.0F / (level.getRandom().nextFloat() * 0.5F + 1.0F) + 0.2F);
    if (!level.isClientSide) {
      CompoundTag ammoNBT = ammo.save(new CompoundTag());
      persistentData.put(KEY_CROSSBOW_AMMO, ammoNBT);
      // if the crossbow broke during loading, fire immediately
      if (tool.isBroken()) {
        fireCrossbow(tool, living, player != null && player.getAbilities().instabuild, living.getUsedItemHand(), ammoNBT);
      }
    }
  }
}

public static DigMode cycleDigMode(ItemStack stack, boolean forward) {
    if (stack.getItem() instanceof JackHammerItem jackHammer) {
        DrillBitType ourBit = getDrillBit(stack);
        DigMode currentMode = getDigMode(stack);
        DigMode newMode = currentMode;
        if (forward) {
            if (currentMode == DigMode.MODE_VEIN_PLUS) {
                newMode = DigMode.MODE_1X1;
            } else {
                newMode = DigMode.values()[currentMode.ordinal() + 1];
                newMode = newMode.getBitType().getBitQuality() <= ourBit.getBitQuality() ? newMode : DigMode.MODE_1X1;
            }
        } else {
            if (currentMode == DigMode.MODE_1X1) {
                // search backward to find the highest dig mode our bit supports
                for (int i = DigMode.values().length - 1; i >= 0; i--) {
                    if (DigMode.values()[i].getBitType().getBitQuality() <= ourBit.getBitQuality()) {
                        newMode = DigMode.values()[i];
                        break;
                    }
                }
            } else {
                newMode = DigMode.values()[currentMode.ordinal() - 1];
            }
        }

        setDigMode(stack, newMode);
        return newMode;
    }
    return null;
}

public void releaseUsing(ItemStack stack, Level level, LivingEntity shooter, int timeLeft) {
	boolean infiniteAmmo = (shooter instanceof Player pl && pl.hasInfiniteMaterials()) || EnchantmentUtil.hasEnchantment(level, stack, Enchantments.INFINITY);
	ItemStack ammoStack = findAmmo(shooter, stack, infiniteAmmo);

	if (ammoStack.isEmpty())
		return;

	int charge = (int)((getUseDuration(stack, shooter) - timeLeft) * getDrawSpeedMultiplier(stack));

	if (shooter instanceof Player pl)
		charge = EventHooks.onArrowLoose(stack, level, pl, charge, true);

	if (charge < 0)
		return;

	float power = getPowerForTime(charge);

	if (power < 0.1f)
		return;

	List<ItemStack> projectileItems = drawProjectileItems(stack, ammoStack, shooter, power, false);

	if (!projectileItems.isEmpty() && level instanceof ServerLevel serverLevel)
		fireArrows(stack, this, ammoStack, projectileItems, serverLevel, shooter, power, getBowDamage(stack), infiniteAmmo);

	if (!level.isClientSide)
		SoundBuilder.at(SoundEvents.ARROW_SHOOT, shooter).pitch(1f / RandomUtil.valueBetween(1.2f, 1.6f) + power * 0.5F).play();

	if (shooter instanceof Player pl)
		pl.awardStat(Stats.ITEM_USED.get(this));
}

public void onRewind(RewindEvent event) {
    var entity = event.entity;
    if (!(entity instanceof IRewindable rewindable) || entity.isRemoved() || (entity instanceof LivingEntity living && living.isDeadOrDying())) {
        return;
    }
    entity.hurtMarked = true;
    // Disable the flag that prevents the entity from moving and reenable
    rewindable.setRewinding(false);

    if (event.respectsGravity) {
        if (entity instanceof LivingEntity le) {
            var weightless = le.getAttribute(PerkAttributes.WEIGHT);
            var modifierId = ArsNouveau.prefix("rewind");
            if (weightless != null) {
                weightless.addOrUpdateTransientModifier(new AttributeModifier(modifierId, -1, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL));
            }
        } else {
            entity.setNoGravity(true);
        }
    }
    entity.setPos(position);
    entity.setDeltaMovement(deltaMovement.scale(-1));
    entity.fallDistance = 0;
    rewindable.setRewinding(true);

    if (event.serverSide) {
        if (entity instanceof LivingEntity living) {
            living.setHealth(health);
        }
    }
}

private static void guardianUltimateSacrifice(LivingDeathEvent event) {
    if (event.getSource().is(DamageTypeTags.BYPASSES_INVULNERABILITY) || !(event.getEntity() instanceof Player player))
        return;

    if (!FamiliarUtil.isFamiliarEnabled(player, OccultismEntities.GUARDIAN_FAMILIAR.get()))
        return;

    GuardianFamiliarEntity guardian = FamiliarUtil.getFamiliar(player, OccultismEntities.GUARDIAN_FAMILIAR.get());
    if (guardian == null)
        return;

    if (!guardian.isAddedToLevel() && player.hasEffect(OccultismEffects.OCCULT_UNDYING_COOLDOWN)) {
        return;
    }

    if (!guardian.sacrifice())
        return;

    event.setCanceled(true);
    player.setHealth(1);
    player.removeAllEffects();
    player.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 20 * 10, 1));
    player.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, 20 * 5, 1));
    player.invulnerableTime = 30;
    if (!guardian.isAddedToLevel()) {
        int i = guardian.hasBlacksmithUpgrade() ? 6 : 7;
        int t = guardian.hasIesniumUpgrade() ? 10 : 20;
        i -= guardian.getLives();
        player.addEffect(new MobEffectInstance(OccultismEffects.OCCULT_UNDYING_COOLDOWN, i * 60 * t, 0, true, true));
    }
}

public void onPlayerStoppedUsing(ItemStack stack, World world, EntityLivingBase user, int timeLeft){

	if(user instanceof EntityPlayer){

		EntityPlayer player = (EntityPlayer)user;

		Spell spell = WandHelper.getCurrentSpell(stack);

		SpellModifiers modifiers;

		if(WizardData.get(player) != null){
			modifiers = WizardData.get(player).itemCastingModifiers;
		}else{
			modifiers = this.calculateModifiers(stack, (EntityPlayer)user, spell); // Fallback to the old way, should never be used
		}

		int castingTick = stack.getMaxItemUseDuration() - timeLeft; // Might as well include this

		int cost = getDistributedCost((int)(spell.getCost() * modifiers.get(SpellModifiers.COST) + 0.1f), castingTick);

		// Still need to check there's enough mana or the spell will finish twice, since running out of mana is
		// handled separately.
		if(spell.isContinuous && spell.getTier().level <= this.tier.level && cost <= this.getMana(stack)){

			MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Finish(Source.WAND, spell, player, modifiers, castingTick));
			spell.finishCasting(world, player, Double.NaN, Double.NaN, Double.NaN, null, castingTick, modifiers);

			if(!player.isCreative()){ // Spells only have a cooldown in survival
				WandHelper.setCurrentCooldown(stack, (int)(spell.getCooldown() * modifiers.get(WizardryItems.cooldown_upgrade)));
			}
		}
	}
}

public boolean mineBlock(ItemStack itemStack, Level world, BlockState state, BlockPos pos, LivingEntity entity) {
    if (state.getDestroySpeed(world, pos) > 0) {
        applyDamage(blockDestroyDamage, itemStack, entity);

        if (!isBroken(itemStack)) {
            applyUsageEffects(entity, itemStack, 1);
        }
    }

    applyBlockBreakEffects(itemStack, world, state, pos, entity);

    if (!world.isClientSide && !isBroken(itemStack)) {
        // todo (destabilization): apply chaotic effect here
        if (getEffectLevel(itemStack, ItemEffect.piercingHarvest) > 0) {
            PiercingEffect.pierceBlocks(this, itemStack, getEffectLevel(itemStack, ItemEffect.piercing), (ServerLevel) world, state, pos, entity);
        }

        int extractorLevel = getEffectLevel(itemStack, ItemEffect.extraction);
        if (extractorLevel > 0) {
            ExtractionEffect.breakBlocks(this, itemStack, extractorLevel, (ServerLevel) world, state, pos, entity);
        }

        int unboundExtractionLevel = getEffectLevel(itemStack, ItemEffect.unboundExtraction);
        if (unboundExtractionLevel > 0) {
            UnboundExtractionEffect.breakBlocks(this, itemStack, unboundExtractionLevel, (ServerLevel) world, state, pos, entity);
        }

        CritEffect.onBlockBreak(entity);
        DataEffectsHandler.applyMineBlockEffects(itemStack, entity, pos);
    }

    return true;
}

public boolean hurtEnemy(ItemStack itemStack, LivingEntity target, LivingEntity attacker) {
    applyDamage(entityHitDamage, itemStack, attacker);

    if (!isBroken(itemStack)) {
        float attackStrength = CastOptional.cast(attacker, Player.class)
                .map(EffectHelper::getCooledAttackStrength)
                .orElse(1f);

        if (attackStrength > 0.9) {
            int sweepingLevel = SweepingEffect.getSweepingLevel(itemStack);
            if (sweepingLevel > 0 && attacker.onGround() && !EffectHelper.getSprinting(attacker)) {
                SweepingEffect.sweepAttack(itemStack, target, attacker, sweepingLevel);
            }

            int howlingLevel = EffectHelper.getEffectLevel(itemStack, ItemEffect.howling);
            if (howlingLevel > 0) {
                HowlingEffect.trigger(itemStack, attacker, howlingLevel);
            }

            ItemEffectHandler.applyHitEffects(itemStack, target, attacker);
            applyPositiveUsageEffects(attacker, itemStack, 1);
        }

        int skulkTaintLevel = getEffectLevel(itemStack, ItemEffect.sculkTaint);
        if (skulkTaintLevel > 0) {
            SculkTaintEffect.perform((ServerLevel) target.level(), target.blockPosition(), skulkTaintLevel, getEffectEfficiency(itemStack, ItemEffect.sculkTaint));
        }

        applyNegativeUsageEffects(attacker, itemStack, 1);
    }

    return true;
}

public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
    ItemStack itemstack = player.getItemInHand(hand);
    if (itemstack.getItem() == this){
        if (hasSummon(itemstack)){
            LivingEntity summon = getSummon(itemstack);
            if (itemstack.getTag() != null) {
                if (summon instanceof IOwned owned) {
                    if (!level.isClientSide) {
                        if (owned.getTrueOwner() == player) {
                            if (player.isShiftKeyDown() || player.isCrouching()){
                                itemstack.getTag().remove(TAG_ENTITY);
                                return InteractionResultHolder.success(itemstack);
                            }
                        } else if (RitualRequirements.canSummon(level, player, summon.getType())){
                            owned.setTrueOwner(player);
                            if (summon instanceof RaiderServant servant && servant.isLeader()) {
                                ItemStack newBanner = servant.getLeaderBannerWithNameInstance();
                                if (!newBanner.isEmpty()) {
                                    servant.setItemSlot(EquipmentSlot.HEAD, newBanner);
                                }
                            }
                            player.playSound(SoundEvents.RESPAWN_ANCHOR_SET_SPAWN, 1.0F, 1.0F);
                            ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(SoundEvents.RESPAWN_ANCHOR_SET_SPAWN, 1.0F, 1.0F));
                            itemstack.shrink(1);
                            return InteractionResultHolder.success(itemstack);
                        }
                    }
                }
            }
        }
    }
    return InteractionResultHolder.pass(itemstack);
}

public void useSpell(ServerLevel worldIn, LivingEntity caster, ItemStack staff, int castTime, SpellStat spellStat) {
    if (rightStaff(staff)) {
        int potency = spellStat.getPotency();
        double radius = spellStat.getRadius();
        int duration = spellStat.getDuration();
        if (WandUtil.enchantedFocus(caster)){
            potency += WandUtil.getPotencyLevel(caster);
            radius += WandUtil.getLevels(ModEnchantments.RADIUS.get(), caster) / 2.0F;
            duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
        }
        int time = MathHelper.secondsToTicks(5.15F - 1) / 14;
        if (castTime % time == 0) {
            BlockPos blockPos = caster.blockPosition();
            blockPos = blockPos.offset(-8 + worldIn.random.nextInt(16), 0, -8 + worldIn.random.nextInt(16));
            BlockPos blockPos2 = caster.blockPosition().offset(-8 + worldIn.random.nextInt(16), 0, -8 + worldIn.random.nextInt(16));
            Vec3 vec3 = Vec3.atBottomCenterOf(blockPos);
            Vec3 vec32 = Vec3.atBottomCenterOf(blockPos2);
            ScatterMine scatterMine = new ScatterMine(worldIn, caster, vec3);
            scatterMine.setExtraDamage(potency);
            scatterMine.setExtraRadius((float) radius);
            scatterMine.lifeTicks = MathHelper.secondsToTicks(duration);
            if (!worldIn.getEntitiesOfClass(ScatterMine.class, new AABB(blockPos)).isEmpty()) {
                scatterMine.setPos(vec32.x(), vec32.y(), vec32.z());
            }
            if (worldIn.addFreshEntity(scatterMine)) {
                if (worldIn.random.nextBoolean()) {
                    SoundUtil.playRedstoneMineLoad(scatterMine);
                }
            }
        }
    }
    super.useSpell(worldIn, caster, staff, castTime, spellStat);
}

private void applyRegen(Player player, int max, ItemStack cadStack) {
	RegenPsiEvent event = new RegenPsiEvent(player, this, cadStack);

	if(!PsiEvents.post(event).isCanceled()) {
		if(!cadStack.isEmpty()) {
			ICAD cad = (ICAD) cadStack.getItem();
			cad.regenPsi(cadStack, event.getCadRegen());
		}

		boolean anyChange = availablePsi != max && event.getPlayerRegen() > 0;

		int prevPsi = availablePsi;
		availablePsi = Math.min(max, availablePsi + event.getPlayerRegen());

		if(overflowed && event.willHealOverflow()) {
			anyChange = true;
			overflowed = false;
		}

		if(regenCooldown != event.getRegenCooldown()) {
			anyChange = true;
		}
		regenCooldown = event.getRegenCooldown();

		if(anyChange) {
			if(player instanceof ServerPlayer) {
				PsiPlayerDataSync.sendDeduction((ServerPlayer) player, prevPsi, availablePsi, regenCooldown, false);
			}

			save();
		}
	}
}

public void curioTick(SlotContext context, ItemStack stack) {
	if (context.entity() instanceof Player player) {
		if (player.getAirSupply() < 300) {
			player.setAirSupply(300);
		}

		if (player.isOnFire()) {
			player.clearFire();
		}

		AttributeMap map = player.getAttributes();
		map.addTransientAttributeModifiers(this.getCurrentModifiers(player));

		if (context.entity() instanceof ServerPlayer) {
			if (!this.locationCache.containsKey(player)) {
				this.generateCachedLocation((ServerPlayer) player);
			} else {
				Future<CachedTeleportationLocation> future = this.locationCache.get(player);

				if (future.isDone() && !future.isCancelled()) {
					try {
						CachedTeleportationLocation location = future.get();

						if (location.dimension() == player.level().dimension()) {
							this.generateCachedLocation((ServerPlayer) player);
						}
					} catch (Exception ex) {
						throw new RuntimeException(ex);
					}
				}
			}
		}
	}
}

private static void fairySave(LivingDeathEvent event) {
    LivingEntity entity = event.getEntity();

    if (event.getSource().is(DamageTypeTags.BYPASSES_INVULNERABILITY) || !(entity instanceof IFamiliar familiar)
            || entity.getType() == OccultismEntities.GUARDIAN_FAMILIAR.get()
            || entity.getType() == OccultismEntities.FAIRY_FAMILIAR.get())
        return;

    LivingEntity owner = familiar.getFamiliarOwner();

    if (owner == null || !FamiliarUtil.isFamiliarEnabled(owner, OccultismEntities.FAIRY_FAMILIAR.get()))
        return;

    FairyFamiliarEntity fairy = FamiliarUtil.getFamiliar(owner, OccultismEntities.FAIRY_FAMILIAR.get());

    if (fairy == null || !fairy.saveFamiliar(familiar))
        return;

    if (!fairy.isAddedToLevel()) {
        if (entity.hasEffect(OccultismEffects.OCCULT_UNDYING_COOLDOWN)) {
            return;
        } else {
            int i = fairy.hasBlacksmithUpgrade() ? 1 : 2;
            entity.addEffect(new MobEffectInstance(OccultismEffects.OCCULT_UNDYING_COOLDOWN, i * 20 * 20, 0));
        }
    }

    event.setCanceled(true);
    entity.setHealth(2);
    entity.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, 20 * 5, 2));

    if (!owner.level().isClientSide())
        OccultismAdvancements.FAMILIAR.get().trigger(owner, Type.FAIRY_SAVE);
}

public InteractionResult useOn(UseOnContext ctx) {
	Level world = ctx.getLevel();
	BlockPos pos = ctx.getClickedPos();
	Player player = ctx.getPlayer();
	ItemStack stack = ctx.getItemInHand();
	BlockState wstate = world.getBlockState(pos);
	Block block = wstate.getBlock();

	if (player != null && player.isSecondaryUseActive()) {
		if (world.getBlockEntity(pos) == null && block.asItem() != Items.AIR
				&& (wstate.isSolidRender(world, pos) || wstate.getRenderShape() == RenderShape.MODEL)
				&& (wstate.canOcclude() || block instanceof AbstractGlassBlock || block instanceof IronBarsBlock)
				&& block.asItem() instanceof BlockItem) {
			setItemToPlace(stack, block.asItem());
			setSwapTemplateDirection(stack, ctx.getClickedFace());
			setHitPos(stack, ctx.getClickLocation());

			displayRemainderCounter(player, stack);
			return InteractionResult.sidedSuccess(world.isClientSide());
		}
	} else if (canExchange(stack) && !ItemNBTHelper.getBoolean(stack, TAG_SWAPPING, false)) {
		Item replacement = getItemToPlace(stack);
		List<BlockPos> swap = getTargetPositions(world, stack, replacement, pos, block, ctx.getClickedFace());
		if (swap.size() > 0) {
			ItemNBTHelper.setBoolean(stack, TAG_SWAPPING, true);
			ItemNBTHelper.setInt(stack, TAG_SELECT_X, pos.getX());
			ItemNBTHelper.setInt(stack, TAG_SELECT_Y, pos.getY());
			ItemNBTHelper.setInt(stack, TAG_SELECT_Z, pos.getZ());
			setSwapClickDirection(stack, ctx.getClickedFace());
			setTarget(stack, block);
		}
	}

	return InteractionResult.sidedSuccess(world.isClientSide());
}

public void perform(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, LivingEntity target, Vec3 hitVec, int chargedTicks) {

    if (!target.level().isClientSide) {
        int amplifier = item.getEffectLevel(itemStack, ItemEffect.pry);
        amplifier += (int) (getOverchargeBonus(item, itemStack, chargedTicks) * item.getEffectEfficiency(itemStack, ItemEffect.abilityOvercharge));

        double damageMultiplier = PryEffect.damageMultiplier;
        damageMultiplier += getOverchargeBonus(item, itemStack, chargedTicks) * item.getEffectLevel(itemStack, ItemEffect.abilityOvercharge) / 100d;

        int comboPoints = ComboPoints.get(attacker);
        boolean isSatiated = !attacker.getFoodData().needsFood();

        AbilityUseResult result = PryEffect.performRegular(attacker, item, itemStack, damageMultiplier, amplifier, target, isSatiated, comboPoints);
        item.tickProgression(attacker, itemStack, result == AbilityUseResult.fail ? 1 : 2);

        int echoLevel = item.getEffectLevel(itemStack, ItemEffect.abilityEcho);
        if (echoLevel > 0) {
            PryEffect.performEcho(attacker, item, itemStack, damageMultiplier, amplifier, target, isSatiated, comboPoints);
        }
    }

    attacker.causeFoodExhaustion(1f);
    attacker.swing(hand, false);
    attacker.getCooldowns().addCooldown(item, getCooldown(item, itemStack));

    if (ComboPoints.canSpend(item, itemStack)) {
        ComboPoints.reset(attacker);
    }

    int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);
    if (revengeLevel > 0) {
        RevengeTracker.removeEnemy(attacker, target);
    }

    item.applyDamage(2, itemStack, attacker);
}

public boolean useCharge(ItemStack containerStack, int slot, int chargeToUse) {
	int charge = getMigratedStoredCharge(containerStack, slot);
	int partialCharge = getPartialCharge(containerStack, slot);

	if (partialCharge >= chargeToUse) {
		if (partialCharge == chargeToUse) {
			removePartialCharge(containerStack, slot);
		} else {
			setPartialCharge(containerStack, slot, partialCharge - chargeToUse);
		}
		return true;
	}

	int worth = getSlotWorth(slot);

	if ((long) charge * worth + partialCharge >= chargeToUse) {
		long additionalPartialChargeNeeded = (long) chargeToUse - partialCharge;
		int actualChargeToRemove = (int) (additionalPartialChargeNeeded / worth + (additionalPartialChargeNeeded % worth > 0 ? 1 : 0));
		int partialChargeToAdd = (int) ((long) actualChargeToRemove * worth - chargeToUse);
		if (actualChargeToRemove == charge && removeSlotWhenEmpty(slot)) {
			removeSlot(containerStack, slot);
		} else {
			extractStoredCharge(containerStack, slot, actualChargeToRemove);
		}

		int newPartialCharge = partialCharge + partialChargeToAdd;
		if (newPartialCharge > 0) {
			setPartialCharge(containerStack, slot, newPartialCharge);
		} else {
			removePartialCharge(containerStack, slot);
		}
		return true;
	}

	return false;
}

public static void TargetEvents(LivingChangeTargetEvent event){
    LivingEntity attacker = event.getEntity();
    LivingEntity target = event.getOriginalTarget();
    if (attacker instanceof Mob mobAttacker) {
        if (target != null) {
            if (attacker instanceof IOwned){
                if (target instanceof ArmorStand || target instanceof HauntedArmorStand){
                    if (event.getTargetType() == MOB_TARGET) {
                        event.setNewTarget(null);
                    } else {
                        event.setCanceled(true);
                    }
                }
            }
            if ((mobAttacker.getMobType() == MobType.UNDEAD && !(mobAttacker instanceof IOwned) && mobAttacker.getMaxHealth() < 100.0F) || mobAttacker instanceof Creeper) {
                if (event.getNewTarget() instanceof Apostle) {
                    event.setCanceled(true);
                }
            }
            if (mobAttacker.getType().is(ModTags.EntityTypes.CREEPERS) && CuriosFinder.hasCurio(target, ModItems.FELINE_AMULET.get())){
                if (event.getTargetType() == MOB_TARGET) {
                    event.setNewTarget(null);
                } else {
                    event.setCanceled(true);
                }
            }
            if (mobAttacker instanceof Phantom && CuriosFinder.hasCurio(target, ModItems.FELINE_AMULET.get())){
                if (event.getTargetType() == MOB_TARGET) {
                    event.setNewTarget(null);
                } else {
                    event.setCanceled(true);
                }
            }
        }
    }
}

public AbilityUseResult hitEntity(ItemStack itemStack, Player player, LivingEntity target, double damageMultiplier, double damageBonus,
        float knockbackBase, float knockbackMultiplier) {
    float targetModifier = EnchantmentHelper.getDamageBonus(itemStack, target.getMobType());
    float critMultiplier = Optional.ofNullable(ForgeHooks.getCriticalHit(player, target, false, 1.5f))
            .map(CriticalHitEvent::getDamageModifier)
            .orElse(1f);

    double damage = (1 + getAbilityBaseDamage(player, itemStack) + targetModifier) * critMultiplier * damageMultiplier + damageBonus;

    boolean success = target.hurt(player.damageSources().playerAttack(player), (float) damage);
    if (success) {
        // applies enchantment effects on both parties
        EnchantmentHelper.doPostHurtEffects(target, player);
        EffectHelper.applyEnchantmentHitEffects(itemStack, target, player);

        // tetra item effects
        ItemEffectHandler.applyHitEffects(itemStack, target, player);

        // knocks back the target based on effect level + knockback enchantment level
        float knockbackFactor = knockbackBase + EnchantmentHelper.getItemEnchantmentLevel(Enchantments.KNOCKBACK, itemStack);
        target.knockback(knockbackFactor * knockbackMultiplier,
                player.getX() - target.getX(), player.getZ() - target.getZ());

        if (targetModifier > 1) {
            player.magicCrit(target);
            return AbilityUseResult.magicCrit;
        }

        if (critMultiplier > 1) {
            player.crit(target);
            return AbilityUseResult.crit;
        }

        return AbilityUseResult.hit;
    }

    return AbilityUseResult.fail;
}

public void updateNaturalArmor(int lvl) {
    AttributeInstance armorAtt = player.getAttribute(Attributes.ARMOR);
    AttributeInstance toughnessAtt = player.getAttribute(Attributes.ARMOR_TOUGHNESS);
    if (armorAtt != null && toughnessAtt != null) {
        if (lvl == 0) {
            armorAtt.removeModifier(NATURAL_ARMOR_UUID);
            toughnessAtt.removeModifier(NATURAL_ARMOR_UUID);
        } else {
            AttributeModifier modArmor = armorAtt.getModifier(NATURAL_ARMOR_UUID);
            AttributeModifier modToughness = toughnessAtt.getModifier(NATURAL_ARMOR_UUID);
            double naturalArmor = getNaturalArmorValue(lvl);
            MobEffectInstance armorRegen = player.getEffect(ModEffects.ARMOR_REGENERATION);
            double armorRegenerationMod = armorRegen == null ? 0 : armorRegen.getDuration() / ((double) ModConfig.balance().vpNaturalArmorRegenDuration.get() * 20);
            naturalArmor *= (1 - 0.75 * armorRegenerationMod); //Modify natural armor between 25% and 100% depending on the armor regen state
            double naturalToughness = getNaturalArmorToughnessValue(lvl);
            double baseArmor = armorAtt.invokeGetModifiersOrEmpty(AttributeModifier.Operation.ADD_VALUE).stream().filter(pair -> ArmorModifier.ARMOR_IDS.contains(pair.id())).map(AttributeModifier::amount).mapToDouble(Double::doubleValue).sum();
            double baseToughness = toughnessAtt.invokeGetModifiersOrEmpty(AttributeModifier.Operation.ADD_VALUE).stream().filter(m -> ArmorModifier.ARMOR_IDS.contains(m.id())).map(AttributeModifier::amount).mapToDouble(Double::doubleValue).sum();
            double targetArmor = Math.max(0, naturalArmor - baseArmor);
            double targetToughness = Math.max(0, naturalToughness - baseToughness);
            if (modArmor != null && targetArmor != modArmor.amount()) {
                armorAtt.removeModifier(modArmor);
                modArmor = null;
            }
            if (targetArmor != 0 && modArmor == null) {
                armorAtt.addTransientModifier(new AttributeModifier(NATURAL_ARMOR_UUID, targetArmor, AttributeModifier.Operation.ADD_VALUE));
            }
            if (modToughness != null && targetToughness != modToughness.amount()) {
                toughnessAtt.removeModifier(modToughness);
                modToughness = null;
            }
            if (targetToughness != 0 && modToughness == null) {
                toughnessAtt.addTransientModifier(new AttributeModifier(NATURAL_ARMOR_UUID, targetToughness, AttributeModifier.Operation.ADD_VALUE));
            }
            applyLevelModifiersB(lvl, ModConfig.balance().vpArmorPenalty.get() && baseArmor > 7);

        }
    }
}

