public void onPlayerStoppedUsing(ItemStack stack, World world, EntityLivingBase entity, int timeLeft){
	// Decreases the timer by the amount it should have been decreased while the bow was in use.
	if(!world.isRemote) stack.setItemDamage(stack.getItemDamage() + (this.getMaxItemUseDuration(stack) - timeLeft));

	if(entity instanceof EntityPlayer){

		EntityPlayer player = (EntityPlayer)entity;

		int charge = this.getMaxItemUseDuration(stack) - timeLeft;
		charge = net.minecraftforge.event.ForgeEventFactory.onArrowLoose(stack, world, (EntityPlayer)entity, charge, true);
		if(charge < 0) return;

		float velocity = (float)charge / DRAW_TIME;
		velocity = (velocity * velocity + velocity * 2) / 3;

		if(velocity > 1) velocity = 1;

		if((double)velocity >= 0.1D){

			if(stack.getTagCompound() != null){
				int shotsLeft = stack.getTagCompound().getInteger(Flamecatcher.SHOTS_REMAINING_NBT_KEY) - 1;
				stack.getTagCompound().setInteger(Flamecatcher.SHOTS_REMAINING_NBT_KEY, shotsLeft);
				if(shotsLeft == 0 && !world.isRemote){
					stack.setItemDamage(getMaxDamage(stack) - getAnimationFrames());
				}
			}

			if(!world.isRemote){
				EntityFlamecatcherArrow arrow = new EntityFlamecatcherArrow(world);
				arrow.aim(player, EntityFlamecatcherArrow.SPEED * velocity);
				world.spawnEntity(arrow);
			}

			world.playSound(null, player.posX, player.posY, player.posZ,
					WizardrySounds.ITEM_FLAMECATCHER_SHOOT, WizardrySounds.SPELLS, 1, 1);

			world.playSound(null, player.posX, player.posY, player.posZ,
					WizardrySounds.ITEM_FLAMECATCHER_FLAME, WizardrySounds.SPELLS, 1, 1);
		}
	}
}

public void onUsingTick(ItemStack stack, EntityLivingBase user, int count){

	if(user instanceof EntityPlayer){

		EntityPlayer player = (EntityPlayer)user;

		Spell spell = WandHelper.getCurrentSpell(stack);

		SpellModifiers modifiers;

		if(WizardData.get(player) != null){
			modifiers = WizardData.get(player).itemCastingModifiers;
		}else{
			modifiers = this.calculateModifiers(stack, (EntityPlayer)user, spell); // Fallback to the old way, should never be used
		}

		int useTick = stack.getMaxItemUseDuration() - count;
		int chargeup = (int)(spell.getChargeup() * modifiers.get(SpellModifiers.CHARGEUP));

		if(spell.isContinuous){
			// Continuous spell charge-up is simple, just don't do anything until it's charged
			if(useTick >= chargeup){
				// castingTick needs to be relative to when the spell actually started
				int castingTick = useTick - chargeup;
				// Continuous spells (these must check if they can be cast each tick since the mana changes)
				// Don't call canCast when castingTick == 0 because we already did it in onItemRightClick - even
				// with charge-up times, because we don't want to trigger events twice
				if(castingTick == 0 || canCast(stack, spell, player, player.getActiveHand(), castingTick, modifiers)){
					cast(stack, spell, player, player.getActiveHand(), castingTick, modifiers);
				}else{
					// Stops the casting if it was interrupted, either by events or because the wand ran out of mana
					player.stopActiveHand();
				}
			}
		}else{
			// Non-continuous spells need to check they actually have a charge-up since ALL spells call setActiveHand
			if(chargeup > 0 && useTick == chargeup){
				// Once the spell is charged, it's exactly the same as in onItemRightClick
				cast(stack, spell, player, player.getActiveHand(), 0, modifiers);
			}
		}
	}
}

public InteractionResult interactLivingEntity(ItemStack itemStack, Player player, LivingEntity target, InteractionHand hand) {
    if (!player.getCooldowns().isOnCooldown(this) && !isBroken(itemStack)) {
        if (getUseDuration(itemStack) == 0 || player.isCrouching()) {
            int bashingLevel = getEffectLevel(itemStack, ItemEffect.bashing);
            if (bashingLevel > 0) {
                bashEntity(itemStack, bashingLevel, player, target);

                tickProgression(player, itemStack, 2);
                applyDamage(2, itemStack, player);
                return InteractionResult.sidedSuccess(player.level().isClientSide);
            }

            int pryLevel = getEffectLevel(itemStack, ItemEffect.pry);
            if (pryLevel > 0) {
                PryEffect.perform(player, hand, this, itemStack, pryLevel, target);
                return InteractionResult.sidedSuccess(player.level().isClientSide);
            }

            if (InteractionHand.OFF_HAND.equals(hand)) {
                int jabLevel = getEffectLevel(itemStack, ItemEffect.jab);
                if (jabLevel > 0) {
                    jabEntity(itemStack, jabLevel, player, target);

                    if (!player.level().isClientSide) {
                        if (getEffectLevel(itemStack, ItemEffect.truesweep) > 0 && player.onGround() && !player.isSprinting()) {
                            SweepingEffect.truesweep(itemStack, player, true);
                        }

                        int howlingLevel = getEffectLevel(itemStack, ItemEffect.howling);
                        if (howlingLevel > 0) {
                            HowlingEffect.trigger(itemStack, player, howlingLevel);
                        }
                    }

                    tickProgression(player, itemStack, 2);
                    applyDamage(2, itemStack, player);
                    return InteractionResult.sidedSuccess(player.level().isClientSide);
                }
            }
        }
    }

    return InteractionResult.PASS;
}

public static boolean performDoubleJump(Player player) {
	boolean hasDoubleJump = player.getData(TFDataAttachments.HAS_DOUBLE_JUMP);
	if (!hasDoubleJump || player.isFallFlying() || player.onClimbable() || player.onGround() || player.isSwimming() || player.getAbilities().flying || player.isInLiquid() || player.isPassenger())
		return false;
	player.jumpFromGround();
	Vec3 velocity = player.getDeltaMovement();
	double boostVelocity = player.getData(TFDataAttachments.SLIMY_SOLES_BOUNCE_INFO).doubleJumpBoostVelocity;
	if (boostVelocity != 0) {
		player.setDeltaMovement(velocity.x(), Math.sqrt(Math.pow(velocity.y(), 2) + Math.pow(boostVelocity, 2)), velocity.z());
		player.getData(TFDataAttachments.SLIMY_SOLES_BOUNCE_INFO).doubleJumpBoostVelocity = 0;
	}
	player.resetFallDistance();
	float pitchShift = 0.1F;
	player.playSound(TFSounds.DOUBLE_JUMP.get(), 1.5F, (player.getVoicePitch() - 1) * (1 + pitchShift) + (1 - pitchShift * 0.2F));
	player.setData(TFDataAttachments.HAS_DOUBLE_JUMP, false);
	player.setData(TFDataAttachments.DOUBLE_JUMP_VALIDATOR, 0);
	AttributeInstance instance = player.getAttribute(Attributes.SAFE_FALL_DISTANCE);
	if (instance != null) // Increase safe fall distance so the player can land up to 2 blocks below their starting height after performing a double jump at peak height without taking fall damage
		instance.addOrUpdateTransientModifier(TFAttributeModifiers.TRAVELLERS_DOUBLE_JUMP_SAFE_FALL_DISTANCE);

	if (player.getItemBySlot(EquipmentSlot.LEGS).is(TFItems.TRAVELLERS_WINGS)) {
		TravellersWingsAttachment attachment = player.getData(TFDataAttachments.TRAVELLERS_WINGS);
		attachment.state = TravellersWingsAttachment.WingState.DOUBLE_JUMP;
		attachment.doubleJumpTimer = 0;
	}

	if (player.level() instanceof ServerLevel serverLevel && player.getItemBySlot(EquipmentSlot.LEGS).is(TFItems.TRAVELLERS_WINGS)) {
		ParticlePacket particlePacket = new ParticlePacket();
		Vec3 deltaMovement = player.getDeltaMovement();
		for (int particleNumber = 0; particleNumber < 10; particleNumber++) {
			Vec3 particleVelocity = new Vec3(
				(serverLevel.getRandom().nextDouble() - 0.5),
				serverLevel.getRandom().nextDouble() + 1,
				(serverLevel.getRandom().nextDouble() - 0.5)
			);
			ParticleOptions type = TFParticleType.DOUBLE_JUMP.get();
			Vec3 wingsPosition = player.position().add(Math.sin(Math.toRadians(player.yBodyRot)) / 3, 1.2, -Math.cos(Math.toRadians(player.yBodyRot)) / 3);
			particlePacket.queueParticle(type, false, false, wingsPosition, particleVelocity.multiply(0.25, -0.5, 0.25).add(deltaMovement));
		}
		PacketDistributor.sendToPlayersTrackingEntityAndSelf(player, particlePacket);
		TravellersWingsAttachment attachment = player.getData(TFDataAttachments.TRAVELLERS_WINGS);
		PacketDistributor.sendToPlayersTrackingEntityAndSelf(player, new TravellersWingsStatePacket(player.getId(), TravellersWingsAttachment.WingState.DOUBLE_JUMP, attachment.sidestepLeft, attachment.doubleJumpTimer, attachment.sidestepTimer));
	}
	return true;
}

public void triggerActiveAbility(Level world, ServerPlayer player, ItemStack stack) {
	if (SuperpositionHandler.hasSpellstoneCooldown(player))
		return;

	CachedTeleportationLocation location = null;

	if (this.locationCache.containsKey(player)) {
		try {
			var future = this.locationCache.get(player);

			if (future.isDone()) {
				location = this.locationCache.get(player).get();
			} else {
				future.cancel(true);
			}

			this.locationCache.remove(player);
		} catch (Exception ex) {
			ex.printStackTrace();
		}
	}

	if (location == null) {
		EnigmaticLegacy.LOGGER.getInternal().info("No cached location found for {}, generating new one synchronously.", player.getGameProfile().getName());
		location = this.findRandomLocation(player);
	}

	ResourceKey<Level> key = location.dimension();

	world.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
	EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketRecallParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 48, false));
	player.teleportTo(location.x(), location.y(), location.z());

	if (player.level().dimension() != key) {
		SuperpositionHandler.sendToDimension(player, key);
		player.teleportTo(location.x(), location.y(), location.z());
	}

	world.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
	EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketRecallParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 48, false));

	SuperpositionHandler.setSpellstoneCooldown(player, this.getCooldown(player));

	EnigmaticLegacy.LOGGER.getInternal().info("Player {} triggered active ability of Non-Euclidean Cube. Teleported to D: {}, X: {}, Y: {}, Z: {}.",
			player.getGameProfile().getName(), player.level().dimension(), player.getX(), player.getY(), player.getZ());
}

public void hurtEnemy(ItemStack stack, LivingEntity target, LivingEntity attacker) {
    //Vampire Finisher skill
    if (attacker instanceof Player player && !Helper.isVampire(target) && !target.typeHolder().is(ModEntityTags.IGNORE_VAMPIRE_SWORD_FINISHER)) {
        double relTh = 0;
        ISkillHandler<IVampirePlayer> skillHandler = VampirePlayer.get(player).getSkillHandler();
        IRefinementAccess refinementHandler = VampirePlayer.get(player).getRefinementHandler();
        if (skillHandler.isSkillEnabled(VampireSkills.SWORD_FINISHER) && !(target instanceof Player) || ModConfig.balance().vsSwordFinisherOnPlayer.get()) {
            relTh = ModConfig.balance().vsSwordFinisherMaxHealth.get() * (refinementHandler.isRefinementEquipped(ModRefinements.SWORD_FINISHER) ? ModConfig.balance().vrSwordFinisherThresholdMod.get() : 1d);
        }
        List<IItemWithTier.Tier> hunterCoatArmor = Arrays.stream(EquipmentSlot.values()).filter(EquipmentSlot::isArmor).map(target::getItemBySlot).filter(s -> s.getItem() instanceof HunterCoatItem).map(s -> ((HunterCoatItem) s.getItem()).getVampirismTier()).toList();
        if (hunterCoatArmor.size() == 4) {
            var level = hunterCoatArmor.stream().min(Comparator.comparingInt(IItemWithTier.Tier::ordinal)).orElse(IItemWithTier.Tier.NORMAL);
            relTh *= (1- switch (level) {
                case NORMAL -> 0.25f;
                case ENHANCED -> 0.3f;
                case ULTIMATE -> 0.35f;
            });
        }
        if (relTh > 0 && target.getHealth() <= target.getMaxHealth() * relTh) {
            if (player.level() instanceof ServerLevel level) {
                DamageHandler.hurtModded(level, target, s -> s.getPlayerAttackWithBypassArmor(player), 10000f);
            }
            Vec3 center = Vec3.atLowerCornerOf(target.blockPosition());
            center.add(0, target.getBbHeight() / 2d, 0);
            ModParticles.spawnParticlesServer(target.level(), new GenericParticleOptions(VIdentifier.mc("effect_4"), 12, 0xE02020), center.x, center.y, center.z, 15, 0.5, 0.5, 0.5, 0);
        }
    }
    //Update training on kill
    if (target.getHealth() <= 0.0f && Helper.isVampire(attacker)) {
        float trained = getTrained(stack, attacker);
        int exp = target instanceof Player ? 10 : (attacker instanceof Player && attacker.level() instanceof ServerLevel serverLevel ? target.getExperienceReward(serverLevel, attacker) : 5);
        float newTrained = exp / 5f * (1.0f - trained) / 15f;
        if (attacker instanceof Player && VampirePlayer.get((Player) attacker).getRefinementHandler().isRefinementEquipped(ModRefinements.SWORD_TRAINED_AMOUNT)) {
            newTrained *= ModConfig.balance().vrSwordTrainingSpeedMod.get();
        }
        trained += newTrained;
        setTrained(stack, attacker, trained);
    }
    //Consume blood
    float charged = getChargePercentage(stack);
    charged -= getChargeUsage(stack);
    setCharged(stack, charged);
    attacker.setItemInHand(InteractionHand.MAIN_HAND, stack);

    super.hurtEnemy(stack, target, attacker);
}

