public void onUsingTick(ItemStack stack, LivingEntity player, int count) {
    if (player instanceof Player) {
        double dist = 32;
        Vec3 playerEyePosition = player.getEyePosition(1.0F);
        Vec3 playerLook = player.getViewVector(1.0F);
        Vec3 Vector3d2 = playerEyePosition.add(playerLook.x * dist, playerLook.y * dist, playerLook.z * dist);
        Entity pointedEntity = null;
        List<Entity> nearbyEntities = player.level.getEntities(player, player.getBoundingBox().expandTowards(playerLook.x * dist, playerLook.y * dist, playerLook.z * dist).inflate(1.0D, 1.0D, 1.0D), new Predicate<Entity>() {
            @Override
            public boolean test(Entity entity) {
                boolean blindness = entity instanceof LivingEntity && ((LivingEntity) entity).hasEffect(MobEffects.BLINDNESS) || (entity instanceof IBlacklistedFromStatues && !((IBlacklistedFromStatues) entity).canBeTurnedToStone());
                return entity != null && entity.isPickable() && !blindness && (entity instanceof Player || (entity instanceof LivingEntity && DragonUtils.isAlive((LivingEntity) entity)));
            }
        });
        double d2 = dist;
        for (Entity nearbyEntity : nearbyEntities) {
            AABB axisalignedbb = nearbyEntity.getBoundingBox().inflate(nearbyEntity.getPickRadius());
            Optional<Vec3> optional = axisalignedbb.clip(playerEyePosition, Vector3d2);

            if (axisalignedbb.contains(playerEyePosition)) {
                if (d2 >= 0.0D) {
                    pointedEntity = nearbyEntity;
                    d2 = 0.0D;
                }
            } else if (optional.isPresent()) {
                double d3 = playerEyePosition.distanceTo(optional.get());

                if (d3 < d2 || d2 == 0.0D) {
                    if (nearbyEntity.getRootVehicle() == player.getRootVehicle() && !player.canRiderInteract()) {
                        if (d2 == 0.0D) {
                            pointedEntity = nearbyEntity;
                        }
                    } else {
                        pointedEntity = nearbyEntity;
                        d2 = d3;
                    }
                }
            }

        }
        if (pointedEntity instanceof LivingEntity) {
            if (!pointedEntity.isAlive())
                return;
            MiscProperties.addScepterTargetData(player, (LivingEntity) pointedEntity);
        }
        attackTargets(player);
    }
}

public void inventoryTick(ItemStack stack, @NotNull Level world, @NotNull Entity entity, int itemSlot, boolean isSelected) {
    boolean hitMob = false;
    if (stack.getTag() == null) {
        stack.setTag(new CompoundTag());
    } else {
        if (!(entity instanceof LivingEntity))
            return;
        int tempLungeTicks = MiscProperties.getLungeTicks((LivingEntity) entity);
        if (deathwormReceded) {
            if (tempLungeTicks > 0) {
                tempLungeTicks = tempLungeTicks - 4;
            }
            if (tempLungeTicks <= 0) {
                tempLungeTicks = 0;
                deathwormReceded = false;
                deathwormLaunched = false;
            }
        } else if (deathwormLaunched) {
            tempLungeTicks = 4 + tempLungeTicks;
            if (tempLungeTicks > 20 && !deathwormReceded) {
                deathwormReceded = true;
            }
        }

        if (MiscProperties.getLungeTicks((LivingEntity) entity) == 20) {
            if (entity instanceof Player) {
                Player player = (Player) entity;
                Vec3 Vector3d = player.getViewVector(1.0F).normalize();
                double range = 5;
                for (LivingEntity livingEntity : world.getEntitiesOfClass(LivingEntity.class, new AABB(player.getX() - range, player.getY() - range, player.getZ() - range, player.getX() + range, player.getY() + range, player.getZ() + range))) {
                    //Let's not pull/hit ourselves
                    if (livingEntity == entity)
                        continue;
                    Vec3 Vector3d1 = new Vec3(livingEntity.getX() - player.getX(), livingEntity.getY() - player.getY(), livingEntity.getZ() - player.getZ());
                    double d0 = Vector3d1.length();
                    Vector3d1 = Vector3d1.normalize();
                    double d1 = Vector3d.dot(Vector3d1);
                    boolean canSee = d1 > 1.0D - 0.5D / d0 && player.hasLineOfSight(livingEntity);
                    if (canSee) {
                        specialDamage++;
                        livingEntity.hurt(DamageSource.playerAttack((Player) entity), 3F);
                        livingEntity.knockback(0.5F, livingEntity.getX() - player.getX(), livingEntity.getZ() - player.getZ());
                    }
                }
            }
        }
        MiscProperties.setLungeTicks((LivingEntity) entity, tempLungeTicks);
    }
}

public void inventoryTick(ItemStack stack, Level world, Entity ent, int slot, boolean active) {
	if (ent instanceof Player player) {
		boolean damaged = getFlyCounter(stack) > 0;
		boolean held = player.getMainHandItem() == stack || player.getOffhandItem() == stack;

		if (damaged && !isFlying(stack)) {
			setFlyCounter(stack, getFlyCounter(stack) - 1);
		}

		if (getFlyCounter(stack) >= MAX_COUNTER) {
			setFlying(stack, false);
		} else if (isFlying(stack)) {
			if (held) {
				player.fallDistance = 0F;
				double my = ManaItemHandler.instance().hasProficiency(player, stack) ? 1.6 : 1.25;
				Vec3 oldMot = player.getDeltaMovement();
				if (player.isFallFlying()) {
					double boost = my * 1.2;
					Vec3 lookDir = player.getLookAngle();
					player.setDeltaMovement(oldMot.add(
							lookDir.x * 0.1 + (lookDir.x * boost - oldMot.x) * 0.5,
							lookDir.y * 0.1 + (lookDir.y * boost - oldMot.y) * 0.5,
							lookDir.z * 0.1 + (lookDir.z * boost - oldMot.z) * 0.5));
				} else {
					player.setDeltaMovement(new Vec3(oldMot.x(), my, oldMot.z()));
				}

				player.playSound(BotaniaSounds.airRod, 1F, 1F);
				if (getFlyCounter(stack) % 3 == 0) {
					player.gameEvent(GameEvent.FLAP);
				}
				for (int i = 0; i < 5; i++) {
					WispParticleData data = WispParticleData.wisp(0.35F + (float) Math.random() * 0.1F, 0.25F, 0.25F, 0.25F);
					world.addParticle(data, player.getX(), player.getY(), player.getZ(),
							0.2F * (float) (Math.random() - 0.5),
							-0.01F * (float) Math.random(),
							0.2F * (float) (Math.random() - 0.5));
				}
			}

			setFlyCounter(stack, getFlyCounter(stack) + FALL_MULTIPLIER);
			if (getFlyCounter(stack) == MAX_COUNTER) {
				setFlying(stack, false);
			}
		}

		if (damaged) {
			player.fallDistance = 0;
		}
	}
}

public void onEntityAttacked(LivingIncomingDamageEvent event) {
    LivingEntity entity = event.getEntity();
    DamageContainer damageContainer = event.getContainer();
    float damage = damageContainer.getNewDamage();
    if (damage <= 0 || !entity.isAlive()) {
        //If some mod does weird things and causes the damage value to be negative or zero then exit
        // as our logic assumes there is actually damage happening and can crash if someone tries to
        // use a negative number as the damage value. We also check to make sure that we don't do
        // anything if the entity is dead as living attack is still fired when the entity is dead
        // for things like fall damage if the entity dies before hitting the ground, and then energy
        // would be depleted regardless if keep inventory is on even if no damage was stopped as the
        // entity can't take damage while dead
        return;
    }
    DamageSource source = damageContainer.getSource();
    //Gas Mask checks
    if (source.is(MekanismAPITags.DamageTypes.IS_PREVENTABLE_MAGIC)) {
        ItemStack headStack = entity.getItemBySlot(EquipmentSlot.HEAD);
        if (!headStack.isEmpty() && headStack.getItem() instanceof ItemScubaMask) {
            ItemAccess chestAccess = ItemAccessUtils.forEntitySlot(entity, EquipmentSlot.CHEST);
            if (chestAccess.getResource().getItem() instanceof ItemScubaTank tank && tank.getMode(chestAccess) && tank.hasChemical(chestAccess)) {
                event.setCanceled(true);
                return;
            }
        }
    }
    for (EquipmentSlot slot : EquipmentSlotGroup.ARMOR) {
        if (entity.getItemBySlot(slot).is(MekanismAPITags.Items.MODULE_CONTAINERS_ARMOR)) {
            //Only add the reduction modifier if at least one module container armor is being worn
            event.addReductionModifier(Reduction.ARMOR, (container, reduction) -> {
                float newDamage = container.getNewDamage();
                if (newDamage > reduction) {
                    //Note: This acts on the damage after the reduction from armor has been performed
                    float toReduce = newDamage - reduction;
                    float ratioAbsorbed = Math.max(0, ItemMekaSuitArmor.getDamageAbsorbed(entity, container.getSource(), toReduce));
                    if (ratioAbsorbed > 0) {
                        if (ratioAbsorbed >= 1) {
                            //If we fully absorbed the damage, mark that we don't want side effects to be performed
                            container.setShouldCauseSideEffects(false);
                            //And just return that we reduced all the damage so that we don't have to worry about floating point nonsense
                            return newDamage;
                        }
                        return reduction + toReduce * ratioAbsorbed;
                    }
                }
                return reduction;
            });
            break;
        }
    }
}

public void onUseTick(Level level, LivingEntity player, ItemStack stack, int remainingUseDuration)
{
	FluidStack fs = this.getFluid(stack);
	if(!fs.isEmpty())
	{
		int duration = getUseDuration(stack, player)-remainingUseDuration;
		int consumed = IEServerConfig.TOOLS.chemthrower_consumption.get();
		if(consumed*duration <= fs.getAmount())
		{
			Vec3 v = player.getLookAngle();
			int split = 8;
			boolean isGas = fs.getFluid().is(Fluids.GASEOUS);

			float scatter = isGas?.25f: .15f;
			float range = isGas?.5f: 1f;
			if(getUpgrades(stack).has(UpgradeEffect.FOCUS))
			{
				range += .25f;
				scatter = .025f;
			}

			boolean ignite = ChemthrowerHandler.isFlammable(fs.getFluid())&&isIgniteEnable(stack);
			for(int i = 0; i < split; i++)
			{
				Vec3 vecDir = v.add(player.getRandom().nextGaussian()*scatter, player.getRandom().nextGaussian()*scatter, player.getRandom().nextGaussian()*scatter);
				ChemthrowerShotEntity chem = new ChemthrowerShotEntity(player.level(), player, vecDir.x*0.25, vecDir.y*0.25, vecDir.z*0.25, fs);

				// Apply momentum from the player.
				chem.setDeltaMovement(player.getDeltaMovement().add(vecDir.scale(range)));

				// Apply a small amount of backforce.
				if(!player.onGround())
					player.setDeltaMovement(player.getDeltaMovement().subtract(vecDir.scale(0.0025*range)));
				if(ignite)
					chem.igniteForSeconds(10);
				if(!player.level().isClientSide)
					player.level().addFreshEntity(chem);
			}
			if(remainingUseDuration%4==0)
			{
				if(ignite)
					player.level().playSound(null, player.getX(), player.getY(), player.getZ(), IESounds.sprayFire.value(), SoundSource.PLAYERS, .5f, 1.5f);
				else
					player.level().playSound(null, player.getX(), player.getY(), player.getZ(), IESounds.spray.value(), SoundSource.PLAYERS, .5f, .75f);
			}
		}
		else
			player.releaseUsingItem();
	}
	else
		player.releaseUsingItem();
}

public void deductPsi(int psi, int cd, boolean sync, boolean shatter) {
	int currentPsi = availablePsi;

	Player player = playerWR.get();
	if(player == null) {
		return;
	}

	ItemStack cadStack = getCAD();

	if(!cadStack.isEmpty()) {
		ICAD cad = (ICAD) cadStack.getItem();
		int storedPsi = cad.getStoredPsi(cadStack);
		if(storedPsi == -1) {
			return;
		}
	}

	availablePsi -= psi;
	if(regenCooldown < cd) {
		regenCooldown = cd;
	}

	if(availablePsi < 0) {
		int overflow = -availablePsi;
		availablePsi = 0;

		if(!cadStack.isEmpty()) {
			ICAD cad = (ICAD) cadStack.getItem();
			overflow = cad.consumePsi(cadStack, overflow);
		}

		if(!shatter && overflow > 0) {
			float dmg = (float) overflow / (loopcasting ? 50 : 125);
			if(!client) {
				Registry<DamageType> types = player.registryAccess().registryOrThrow(Registries.DAMAGE_TYPE);
				DamageSource overloadSource = new DamageSource(types.getHolderOrThrow(LibResources.PSI_OVERLOAD));
				player.hurt(overloadSource, dmg);
			}
			overflowed = true;
			if(sync && player instanceof ServerPlayer) {
				PsiPlayerDataSync.sendOverflow((ServerPlayer) player, true);
			}
		}
	}

	if(sync && player instanceof ServerPlayer) {
		PsiPlayerDataSync.sendDeduction((ServerPlayer) player, currentPsi, availablePsi, regenCooldown, shatter);
	}

	save();
}

public static void onUseItem(PlayerInteractEvent.RightClickItem event) {
    var player = event.getEntity();
    if (player.level.isClientSide) {
        MinecraftInstanceHelper.ifPlayerPresent(localPlayer -> {
            if (ClientMagicData.isCasting() && player.getUUID().equals(localPlayer.getUUID())) {
                event.setCanceled(true);
            }
        });
    } else {
        var magicData = MagicData.getPlayerMagicData(player);
        if (magicData.isCasting() && event.getItemStack() != magicData.getPlayerCastingItem()) {
            event.setCanceled(true);
        }
    }
    if (event.isCanceled()) {
        return;
    }

    var level = player.level;
    var hand = event.getHand();
    ItemStack itemStack = player.getItemInHand(hand);
    if (itemStack.has(ComponentRegistry.CASTING_IMPLEMENT)) {
        SpellSelectionManager spellSelectionManager = new SpellSelectionManager(player);
        SpellSelectionManager.SelectionOption selectionOption = spellSelectionManager.getSelection();
        if (selectionOption == null || selectionOption.spellData.equals(SpellData.EMPTY)) {
            //IronsSpellbooks.LOGGER.debug("CastingItem.Use.1 {} {}", level.isClientSide, hand);
            return;
        }
        SpellData spellData = selectionOption.spellData;
        int spellLevel = spellData.getSpell().getLevelFor(spellData.getLevel(), player);
        if (level.isClientSide()) {
            if (ClientMagicData.isCasting()) {
                //IronsSpellbooks.LOGGER.debug("CastingItem.Use.2 {} {}", level.isClientSide, hand);
                event.setCancellationResult(InteractionResult.CONSUME);
            } else if (ClientMagicData.getPlayerMana() < spellData.getSpell().getManaCost(spellLevel)
                    || ClientMagicData.getCooldowns().isOnCooldown(spellData.getSpell())
                    || !ClientMagicData.getSyncedSpellData(player).isSpellLearned(spellData.getSpell())) {
                //IronsSpellbooks.LOGGER.debug("CastingItem.Use.3 {} {}", level.isClientSide, hand);
                return;
            } else {
                //IronsSpellbooks.LOGGER.debug("CastingItem.Use.4 {} {}", level.isClientSide, hand);
                event.setCancellationResult(InteractionResult.CONSUME);
            }
        }

        var castingSlot = hand.ordinal() == 0 ? SpellSelectionManager.MAINHAND : SpellSelectionManager.OFFHAND;

        if (spellData.getSpell().attemptInitiateCast(itemStack, spellLevel, level, player, selectionOption.getCastSource(), true, castingSlot)) {
            event.setCancellationResult(InteractionResult.CONSUME);
        } else {
            //IronsSpellbooks.LOGGER.debug("CastingItem.Use.6 {} {}", level.isClientSide, hand);
            event.setCancellationResult(InteractionResult.FAIL);
        }
        event.setCanceled(true);
    }
}

protected void fireProjectiles(ItemStack itemStack, Level world, LivingEntity entity) {
    if (entity instanceof Player player && !world.isClientSide) {
        ItemStack advancementCopy = itemStack.copy();

        List<ItemStack> list = takeProjectiles(itemStack, 1);
        if (!list.isEmpty()) {
            int multishotEnchantLevel = EnchantmentHelper.getItemEnchantmentLevel(Enchantments.MULTISHOT, itemStack) * 3;
            int count = Math.max(getEffectLevel(itemStack, ItemEffect.multishot) + multishotEnchantLevel, 1);
            double strength = getAttributeValue(itemStack, TetraAttributes.drawStrength.get());
            float velocityBonus = getEffectLevel(itemStack, ItemEffect.velocity) / 100f;
            float projectileVelocity = getProjectileVelocity(strength, velocityBonus);
            double spread = getEffectEfficiency(itemStack, ItemEffect.multishot);

            if (spread == 0 && multishotEnchantLevel > 0) {
                spread = multishotDefaultSpread;
            }

            ModularLooseProjectilesEvent looseProjectilesEvent = new ModularLooseProjectilesEvent(itemStack, list.get(0), player, world, 1,
                    strength,
                    false,
                    projectileVelocity,
                    spread,
                    1,
                    player.getAbilities().instabuild,
                    count,
                    player.getXRot(),
                    player.getYRot());
            MinecraftForge.EVENT_BUS.post(looseProjectilesEvent);

            count = looseProjectilesEvent.getCount();
            spread = looseProjectilesEvent.getMultishotSpread();
            for (int i = 0; i < count; i++) {
                double yaw = looseProjectilesEvent.getBaseYaw() - spread * (count - 1) / 2f + spread * i;
                boolean isDupe = looseProjectilesEvent.isInfiniteAmmo() || count > 1 && i != count / 2;
                fireProjectile(world, looseProjectilesEvent.getFiringStack(),
                        looseProjectilesEvent.getAmmoStack(),
                        looseProjectilesEvent.getProjectileRemappers(),
                        player,
                        looseProjectilesEvent.getStrength(),
                        looseProjectilesEvent.getProjectileVelocity(),
                        (float) looseProjectilesEvent.getBasePitch(),
                        (float) yaw,
                        isDupe);
            }

            // todo: needs to apply 3 points of damage if it's firework
            itemStack.hurtAndBreak(1, player, p -> p.broadcastBreakEvent(p.getUsedItemHand()));
            applyUsageEffects(entity, itemStack, 1);

            world.playSound(null, player.getX(), player.getY(), player.getZ(),
                    SoundEvents.CROSSBOW_SHOOT, SoundSource.PLAYERS, 1, 1);

            if (player instanceof ServerPlayer) {
                CriteriaTriggers.SHOT_CROSSBOW.trigger((ServerPlayer) player, advancementCopy);

                player.awardStat(Stats.ITEM_USED.get(this));
            }
        }
    }
}

public void curioTick(SlotContext context, ItemStack stack) {
	if (context.entity().level().isClientSide || !(context.entity() instanceof Player))
		return;

	Player player = (Player) context.entity();

	if (player.isCreative() || player.isSpectator())
		return;

	List<LivingEntity> genericMobs = player.level().getEntitiesOfClass(LivingEntity.class, SuperpositionHandler.getBoundingBoxAroundEntity(player, neutralAngerRange.getValue()));
	List<EnderMan> endermen = player.level().getEntitiesOfClass(EnderMan.class, SuperpositionHandler.getBoundingBoxAroundEntity(player, endermenRandomportRange.getValue()));

	for (EnderMan enderman : endermen) {
		if (random.nextDouble() <= (0.002 * endermenRandomportFrequency.getValue())) {
			if (enderman.teleportTowards(player) && player.hasLineOfSight(enderman)) {
				enderman.setTarget(player);
			}
		}
	}

	for (LivingEntity checkedEntity : genericMobs) {
		double visibility = player.getVisibilityPercent(checkedEntity);
		double angerDistance = Math.max(neutralAngerRange.getValue() * visibility, neutralXRayRange.getValue());

		if (checkedEntity.distanceToSqr(player.getX(), player.getY(), player.getZ()) > angerDistance * angerDistance) {
			continue;
		}

		if (checkedEntity instanceof Piglin && !SuperpositionHandler.hasCurio(player, EnigmaticItems.AVARICE_SCROLL)) {
			Piglin piglin = (Piglin) checkedEntity;

			if (piglin.getTarget() == null || !piglin.getTarget().isAlive()) {
				if (player.hasLineOfSight(checkedEntity) || player.distanceTo(checkedEntity) <= neutralXRayRange.getValue()) {
					PiglinAi.wasHurtBy(piglin, player);
				} else {
					continue;
				}
			}

		} else if (checkedEntity instanceof NeutralMob) {
			NeutralMob neutral = (NeutralMob) checkedEntity;

			if (neutralAngerBlacklist.contains(ForgeRegistries.ENTITY_TYPES.getKey(checkedEntity.getType()))) {
				continue;
			}

			if (neutral instanceof TamableAnimal tamable && tamable.isTame()) {
				continue;
			} else if (SuperpositionHandler.hasItem(player, EnigmaticItems.ANIMAL_GUIDEBOOK)) {
				if (EnigmaticItems.ANIMAL_GUIDEBOOK.isTamableAnimal(checkedEntity)) {
					continue;
				}
			} else if (neutral instanceof IronGolem golem && golem.isPlayerCreated()) {
				continue;
			} else if (neutral instanceof Bee) {
				if (saveTheBees.getValue() || SuperpositionHandler.hasItem(player, EnigmaticItems.ANIMAL_GUIDEBOOK)) {
					continue;
				}
			}

			if (neutral.getTarget() == null || !neutral.getTarget().isAlive()) {
				if (player.hasLineOfSight(checkedEntity) || player.distanceTo(checkedEntity) <= neutralXRayRange.getValue()) {
					neutral.setTarget(player);
				} else {
					continue;
				}
			}
		}
	}

}

public static void fireCrossbow(IToolStackView tool, LivingEntity living, boolean creative, InteractionHand hand, CompoundTag heldAmmo) {
  // ammo already loaded? time to fire
  Level level = living.level();
  if (!level.isClientSide) {
    // shoot the projectile
    int damage = 0;

    // don't need to calculate these multiple times
    float velocity = ConditionalStatModifierHook.getModifiedStat(tool, living, ToolStats.VELOCITY);
    float inaccuracy = ModifierUtil.getInaccuracy(tool, living);

    // the ammo has a stack size that may be greater than 1 (meaning multishot)
    // when creating the ammo stacks, we use split, so its getting smaller each time
    ItemStack ammo = ItemStack.of(heldAmmo);
    float startAngle = getAngleStart(ammo.getCount());
    int primaryIndex = ammo.getCount() / 2;
    for (int arrowIndex = 0; arrowIndex < ammo.getCount(); arrowIndex++) {
      // setup projectile
      AbstractArrow arrow = null;
      Projectile projectile;
      float speed;
      if (ammo.is(Items.FIREWORK_ROCKET)) {
        // TODO: don't hardcode fireworks, perhaps use a map or a JSON behavior list
        projectile = new FireworkRocketEntity(level, ammo, living, living.getX(), living.getEyeY() - 0.15f, living.getZ(), true);
        speed = 1.5f;
        damage += 3;
      } else {
        ArrowItem arrowItem = ammo.getItem() instanceof ArrowItem a ? a : (ArrowItem)Items.ARROW;
        arrow = arrowItem.createArrow(level, ammo, living);
        projectile = arrow;
        arrow.setCritArrow(true);
        arrow.setSoundEvent(SoundEvents.CROSSBOW_HIT);
        arrow.setShotFromCrossbow(true);
        speed = 3f;
        damage += 1;

        // vanilla arrows have a base damage of 2, cancel that out then add in our base damage to account for custom arrows with higher base damage
        float baseArrowDamage = (float)(arrow.getBaseDamage() - 2 + tool.getStats().get(ToolStats.PROJECTILE_DAMAGE));
        arrow.setBaseDamage(ConditionalStatModifierHook.getModifiedStat(tool, living, ToolStats.PROJECTILE_DAMAGE, baseArrowDamage));

        // fortunately, don't need to deal with vanilla infinity here, our infinity was dealt with during loading
        if (creative) {
          arrow.pickup = Pickup.CREATIVE_ONLY;
        }
      }

      // TODO: can we get piglins/illagers to use our crossbow?

      // setup projectile
      Vec3 upVector = living.getUpVector(1.0f);
      float angle = startAngle + (10 * arrowIndex);
      Vector3f targetVector = living.getViewVector(1.0f).toVector3f().rotate((new Quaternionf()).setAngleAxis(angle * Math.PI / 180F, upVector.x, upVector.y, upVector.z));
      projectile.shoot(targetVector.x(), targetVector.y(), targetVector.z(), velocity * speed, inaccuracy);

      // add modifiers to the projectile, will let us use them on impact
      ModifierNBT modifiers = tool.getModifiers();
      EntityModifierCapability.getCapability(projectile).addModifiers(modifiers);

      // fetch the persistent data for the arrow as modifiers may want to store data
      ModDataNBT projectileData = PersistentDataCapability.getOrWarn(projectile);

      // let modifiers set properties
      for (ModifierEntry entry : modifiers.getModifiers()) {
        entry.getHook(ModifierHooks.PROJECTILE_LAUNCH).onProjectileLaunch(tool, entry, living, ammo, projectile, arrow, projectileData, arrowIndex == primaryIndex);
      }

      // finally, fire the projectile
      level.addFreshEntity(projectile);
      level.playSound(null, living.getX(), living.getY(), living.getZ(), SoundEvents.CROSSBOW_SHOOT, SoundSource.PLAYERS, 1.0F, getRandomShotPitch(angle, living.getRandom()));
    }

    // clear the ammo, damage the bow
    tool.getPersistentData().remove(KEY_CROSSBOW_AMMO);
    ToolDamageUtil.damageAnimated(tool, damage, living, hand);

    // stats
    if (living instanceof ServerPlayer serverPlayer) {
      CriteriaTriggers.SHOT_CROSSBOW.trigger(serverPlayer, living.getItemInHand(hand));
      serverPlayer.awardStat(Stats.ITEM_USED.get(tool.getItem()));
    }
  }
}

public static Optional<ArrayList<Entity>> cast(Level world, Player player, PlayerData data, ItemStack bullet, ItemStack cad, int cd, int particles, float sound, Consumer<SpellContext> predicate, int reservoir) {
	if(!data.overflowed && data.getAvailablePsi() > 0 && !cad.isEmpty() && !bullet.isEmpty() && ISpellAcceptor.hasSpell(bullet) && isTruePlayer(player)) {
		ISpellAcceptor spellContainer = ISpellAcceptor.acceptor(bullet);
		Spell spell = spellContainer.getSpell();
		SpellContext context = new SpellContext().setPlayer(player).setSpell(spell);
		if(predicate != null) {
			predicate.accept(context);
		}

		if(context.isValid()) {
			if(context.cspell.metadata.evaluateAgainst(cad)) {
				int cost = Math.max(getRealCost(cad, bullet, context.cspell.metadata.getStat(EnumSpellStat.COST)) - reservoir, 0);
				PreSpellCastEvent event = new PreSpellCastEvent(cost, sound, particles, cd, spell, context, player, data, cad, bullet);
				if(PsiEvents.post(event).isCanceled()) {
					String cancelMessage = event.getCancellationMessage();
					if(cancelMessage != null && !cancelMessage.isEmpty()) {
						player.sendSystemMessage(Component.translatable(cancelMessage).setStyle(Style.EMPTY.withColor(ChatFormatting.RED)));
					}
					return Optional.empty();
				}

				cd = event.getCooldown();
				particles = event.getParticles();
				sound = event.getSound();
				cost = event.getCost();

				spell = event.getSpell();
				context = event.getContext();

				if(cost > 0) {
					data.deductPsi(cost, cd, true);
				}

				if(cost != 0 && sound > 0) {
					if(!world.isClientSide) {
						world.playSound(null, player.getX(), player.getY(), player.getZ(), PsiSoundHandler.cadShoot.get(), SoundSource.PLAYERS, sound, (float) (0.5 + Math.random() * 0.5));
					} else {
						int color = ((ICAD) cad.getItem()).getSpellColor(cad);
						float r = PsiRenderHelper.r(color) / 255F;
						float g = PsiRenderHelper.g(color) / 255F;
						float b = PsiRenderHelper.b(color) / 255F;
						for(int i = 0; i < particles; i++) {
							double x = player.getX() + (Math.random() - 0.5) * 2.1 * player.getBbWidth();
							double y = player.getY() + 0.35D;
							double z = player.getZ() + (Math.random() - 0.5) * 2.1 * player.getBbWidth();
							float grav = -0.15F - (float) Math.random() * 0.03F;
							PsiClientRuntime.sparkle(world, x, y, z, r, g, b, 0, -grav, 0, 0.25F, 15);
						}

						double x = player.getX();
						double y = player.getY() + player.getEyeHeight() - 0.1;
						double z = player.getZ();
						Vector3 lookOrig = new Vector3(player.getLookAngle());
						for(int i = 0; i < 25; i++) {
							Vector3 look = lookOrig.copy();
							double spread = 0.25;
							look.x += (Math.random() - 0.5) * spread;
							look.y += (Math.random() - 0.5) * spread;
							look.z += (Math.random() - 0.5) * spread;
							look.normalize().multiply(0.15);

							PsiClientRuntime.sparkle(world, x, y, z, r, g, b,
									(float) look.x, (float) look.y, (float) look.z, 0.3F, 5);
						}
					}
				}
				ArrayList<Entity> SpellEntities = new ArrayList<>();
				if(world.isClientSide) {
					spellContainer.predictSpell(context);
				} else {
					SpellEntities = spellContainer.castSpell(context);
				}
				PsiEvents.post(new SpellCastEvent(spell, context, player, data, cad, bullet));
				return Optional.of(SpellEntities);
			} else if(!world.isClientSide) {
				player.sendSystemMessage(Component.translatable("psimisc.weak_cad").setStyle(Style.EMPTY.withColor(ChatFormatting.RED)));
			}
		}
	}

	return Optional.empty();
}

public void MagicResults(ItemStack stack, Level worldIn, LivingEntity caster, ISpell spell) {
    if (spell != null && caster instanceof Player playerEntity) {
        if (!worldIn.isClientSide) {
            ServerLevel serverWorld = (ServerLevel) worldIn;
            if (playerEntity.isCreative()) {
                if (stack.getTag() != null) {
                    spell.SpellResult(serverWorld, caster, stack, WandUtil.getStats(caster, spell));
                    boolean flag = false;
                    if (spell instanceof IChargingSpell chargingSpell) {
                        if (chargingSpell.shotsNumber(playerEntity, stack) > 0 && this.ShotsFired(stack) >= chargingSpell.shotsNumber(playerEntity, stack)) {
                            flag = true;
                        }
                    } else {
                        flag = true;
                    }
                    if (flag) {
                        this.setShots(stack, 0);
                        if (!spell.hasCustomCooldown(caster, stack, IWand.getFocus(stack), spell.spellCooldown(playerEntity))) {
                            SEHelper.addSpellCooldown(playerEntity, spell, spell.spellCooldown(playerEntity));
                        }
                    }
                }
            } else if (SEHelper.getSoulsAmount(playerEntity, SoulUse(caster, stack))) {
                boolean spent = true;
                if (spell instanceof IChargingSpell spell1 && spell1.everCharge()) {
                    if (stack.getTag() != null) {
                        stack.getTag().putInt(SECONDS, stack.getTag().getInt(SECONDS) + 1);
                        if (stack.getTag().getInt(SECONDS) != 20) {
                            spent = false;
                        } else {
                            stack.getTag().putInt(SECONDS, 0);
                        }
                    }
                }
                if (spent) {
                    SEHelper.decreaseSouls(playerEntity, SoulUse(caster, stack));
                    SEHelper.sendSEUpdatePacket(playerEntity);
                    if (MobsConfig.VillagerHateSpells.get() > 0) {
                        for (Villager villager : caster.level.getEntitiesOfClass(Villager.class, caster.getBoundingBox().inflate(16.0D))) {
                            if (villager.hasLineOfSight(caster)) {
                                villager.getGossips().add(caster.getUUID(), GossipType.MINOR_NEGATIVE, MobsConfig.VillagerHateSpells.get());
                            }
                        }
                    }
                }
                if (stack.getTag() != null) {
                    spell.SpellResult(serverWorld, caster, stack, WandUtil.getStats(caster, spell));
                    boolean flag = false;
                    if (spell instanceof IChargingSpell chargingSpell) {
                        if (chargingSpell.shotsNumber(playerEntity, stack) > 0 && this.ShotsFired(stack) >= chargingSpell.shotsNumber(playerEntity, stack)) {
                            flag = true;
                        }
                    } else {
                        flag = true;
                    }
                    if (flag) {
                        this.setShots(stack, 0);
                        if (!spell.hasCustomCooldown(caster, stack, IWand.getFocus(stack), spell.spellCooldown(playerEntity))) {
                            SEHelper.addSpellCooldown(playerEntity, spell, spell.spellCooldown(playerEntity));
                        }
                    }
                }
            } else {
                worldIn.playSound(null, caster.getX(), caster.getY(), caster.getZ(), SoundEvents.FIRE_EXTINGUISH, SoundSource.NEUTRAL, 1.0F, 1.0F);
            }
        }
        if (worldIn.isClientSide) {
            if (playerEntity.isCreative()) {
                if (spell instanceof IBreathingSpell breathingSpells) {
                    breathingSpells.showWandBreath(caster, stack, WandUtil.getStats(caster, spell));
                }
            } else if (SEHelper.getSoulsAmount(playerEntity, SoulUse(caster, stack))) {
                if (spell instanceof IBreathingSpell breathingSpells) {
                    breathingSpells.showWandBreath(caster, stack, WandUtil.getStats(caster, spell));
                }
            } else {
                this.failParticles(worldIn, caster);
            }
        }
    } else {
        this.failParticles(worldIn, caster);
        worldIn.playSound(null, caster.getX(), caster.getY(), caster.getZ(), SoundEvents.FIRE_EXTINGUISH, SoundSource.NEUTRAL, 1.0F, 1.0F);
    }
}

public ItemStack applyUpgrade(@Nullable EntityPlayer player, ItemStack wand, ItemStack upgrade){

	// Upgrades wand if necessary. Damage is copied, preserving remaining durability,
	// and also the entire NBT tag compound.
	if(upgrade.getItem() == WizardryItems.arcane_tome){

		Tier tier = Tier.values()[upgrade.getItemDamage()];

		// Checks the wand upgrade is for the tier above the wand's tier, and that either the wand has enough
		// progression or the player is in creative mode.
		if((player == null || player.isCreative() || Wizardry.settings.legacyWandLevelling
				|| WandHelper.getProgression(wand) >= tier.getProgression())
				&& tier == this.tier.next() && this.tier != Tier.MASTER){

			if(Wizardry.settings.legacyWandLevelling){
				// Progression has little meaning with legacy upgrade mechanics so just reset it
				// In theory, you can get 'free' progression when upgrading since progression can't be negative,
				// so the flipside of that is you lose any excess
				WandHelper.setProgression(wand, 0);
			}else{
				// Carry excess progression over to the new stack
				WandHelper.setProgression(wand, WandHelper.getProgression(wand) - tier.getProgression());
			}

			if(player != null) WizardData.get(player).setTierReached(tier);

			ItemStack newWand = new ItemStack(getWand(tier, this.element));
			newWand.setTagCompound(wand.getTagCompound());
			// This needs to be done after copying the tag compound so the mana capacity for the new wand
			// takes storage upgrades into account
			// Note the usage of the new wand item and not 'this' to ensure the correct capacity is used
			((IManaStoringItem)newWand.getItem()).setMana(newWand, this.getMana(wand));

			upgrade.shrink(1);

			return newWand;
		}

	}else if(WandHelper.isWandUpgrade(upgrade.getItem())){

		// Special upgrades
		Item specialUpgrade = upgrade.getItem();

		int maxUpgrades = this.tier.upgradeLimit;
		if(this.element == null) maxUpgrades += Constants.NON_ELEMENTAL_UPGRADE_BONUS;

		if(WandHelper.getTotalUpgrades(wand) < maxUpgrades
				&& WandHelper.getUpgradeLevel(wand, specialUpgrade) < Constants.UPGRADE_STACK_LIMIT){

			// Used to preserve existing mana when upgrading storage rather than creating free mana.
			int prevMana = this.getMana(wand);

			WandHelper.applyUpgrade(wand, specialUpgrade);

			// Special behaviours for specific upgrades
			if(specialUpgrade == WizardryItems.storage_upgrade){

				this.setMana(wand, prevMana);

			}else if(specialUpgrade == WizardryItems.attunement_upgrade){

				int newSlotCount = BASE_SPELL_SLOTS + WandHelper.getUpgradeLevel(wand,
						WizardryItems.attunement_upgrade);

				Spell[] spells = WandHelper.getSpells(wand);
				Spell[] newSpells = new Spell[newSlotCount];

				for(int i = 0; i < newSpells.length; i++){
					newSpells[i] = i < spells.length && spells[i] != null ? spells[i] : Spells.none;
				}

				WandHelper.setSpells(wand, newSpells);

				int[] cooldowns = WandHelper.getCooldowns(wand);
				int[] newCooldowns = new int[newSlotCount];

				if(cooldowns.length > 0){
					System.arraycopy(cooldowns, 0, newCooldowns, 0, cooldowns.length);
				}

				WandHelper.setCooldowns(wand, newCooldowns);
			}

			upgrade.shrink(1);

			if(player != null){

				WizardryAdvancementTriggers.special_upgrade.triggerFor(player);

				if(WandHelper.getTotalUpgrades(wand) == Tier.MASTER.upgradeLimit){
					WizardryAdvancementTriggers.max_out_wand.triggerFor(player);
				}
			}

		}
	}

	return wand;
}

protected void fireArrow(ItemStack itemStack, Level world, LivingEntity entity, int timeLeft) {
    if (entity instanceof Player) {
        Player player = (Player) entity;
        ItemStack ammoStack = player.getProjectile(vanillaBow);

        boolean playerInfinite = isInfinite(player, itemStack, ammoStack);

        // multiply by 20 to align progress with vanilla bow (fully drawn at 1sec/20ticks)
        int drawProgress = Math.round(getProgress(itemStack, entity) * 20);
        drawProgress = net.minecraftforge.event.ForgeEventFactory.onArrowLoose(itemStack, world, player, drawProgress,
                !ammoStack.isEmpty() || playerInfinite);

        if (drawProgress < 0) {
            return;
        }

        if (!ammoStack.isEmpty() || playerInfinite) {
            if (ammoStack.isEmpty()) {
                ammoStack = new ItemStack(Items.ARROW);
            }

            double strength = getDrawStrength(entity, itemStack);
            float velocityBonus = getEffectLevel(itemStack, ItemEffect.velocity) / 100f;
            int suspendLevel = getEffectLevel(itemStack, ItemEffect.suspend);
            ArrowItem ammoItem = CastOptional.cast(ammoStack.getItem(), ArrowItem.class)
                    .orElse((ArrowItem) Items.ARROW);
            boolean infiniteAmmo = player.getAbilities().instabuild || ammoItem.isInfinite(ammoStack, itemStack, player);

            ModularLooseProjectilesEvent looseProjectilesEvent = new ModularLooseProjectilesEvent(itemStack, ammoStack, player, world,
                    drawProgress, strength, suspendLevel > 0,
                    getArrowVelocity(drawProgress, strength, getEffectLevel(itemStack, ItemEffect.velocity) / 100f, suspendLevel > 0),
                    getEffectEfficiency(itemStack, ItemEffect.multishot),
                    Math.max(0, 100 - getEffectEfficiency(itemStack, ItemEffect.spread) - FocusEffect.getSpreadReduction(player, itemStack)),
                    player.getAbilities().instabuild || ammoItem.isInfinite(ammoStack, itemStack, player),
                    Mth.clamp(getEffectLevel(itemStack, ItemEffect.multishot), 1, infiniteAmmo ? 64 : ammoStack.getCount()),
                    player.getXRot(),
                    player.getYRot());
            MinecraftForge.EVENT_BUS.post(looseProjectilesEvent);

            ammoStack = looseProjectilesEvent.getAmmoStack();
            ImmutableList<Function<AbstractArrow, AbstractArrow>> projectileRemappers = looseProjectilesEvent.getProjectileRemappers();

            strength = looseProjectilesEvent.getStrength();
            boolean hasSuspend = looseProjectilesEvent.isHasSuspend();
            float projectileVelocity = looseProjectilesEvent.getProjectileVelocity();
            double multishotSpread = looseProjectilesEvent.getMultishotSpread();
            float accuracy = looseProjectilesEvent.getAccuracy();
            infiniteAmmo = looseProjectilesEvent.isInfiniteAmmo();
            int count = looseProjectilesEvent.getCount();
            double basePitch = looseProjectilesEvent.getBasePitch();
            double baseYaw = looseProjectilesEvent.getBaseYaw();

            if (projectileVelocity > 0.1f) {
                if (!world.isClientSide) {
                    int powerLevel = EnchantmentHelper.getTagEnchantmentLevel(Enchantments.POWER_ARROWS, itemStack);
                    int punchLevel = EnchantmentHelper.getTagEnchantmentLevel(Enchantments.PUNCH_ARROWS, itemStack);
                    int flameLevel = EnchantmentHelper.getTagEnchantmentLevel(Enchantments.FLAMING_ARROWS, itemStack);
                    int piercingLevel = getEffectLevel(itemStack, ItemEffect.piercing)
                            + EnchantmentHelper.getTagEnchantmentLevel(Enchantments.PIERCING, itemStack);

                    for (int i = 0; i < count; i++) {
                        double yaw = baseYaw - multishotSpread * (count - 1) / 2f + multishotSpread * i;
                        fireProjectile(itemStack, world, (ArrowItem) ammoStack.getItem(), ammoStack, projectileRemappers, player,
                                (float) basePitch, (float) yaw, projectileVelocity, accuracy, drawProgress, strength, powerLevel, punchLevel,
                                flameLevel, piercingLevel, hasSuspend, infiniteAmmo);
                    }


                    applyDamage(1, itemStack, player);
                    applyNegativeUsageEffects(entity, itemStack, 1);

                    // max draw at 20, has to be drawn at least 3/4th for positive effects
                    if (drawProgress > 15) {
                        applyPositiveUsageEffects(entity, itemStack, 1);
                    }
                }

                float pitchBase = projectileVelocity;
                if (velocityBonus > 0) {
                    pitchBase -= pitchBase * velocityBonus;
                } else if (hasSuspend) {
                    pitchBase = pitchBase / 2;
                }
                world.playSound(null, player.getX(), player.getY(), player.getZ(),
                        SoundEvents.ARROW_SHOOT, SoundSource.PLAYERS,
                        0.8F + projectileVelocity * 0.2f,
                        1.9f + world.random.nextFloat() * 0.2F - pitchBase * 0.8F);

                if (!infiniteAmmo && !player.getAbilities().instabuild) {
                    ammoStack.shrink(count);
                    if (ammoStack.isEmpty()) {
                        player.getInventory().removeItem(ammoStack);
                    }
                }

                FocusEffect.onFireArrow(player, itemStack);

                player.awardStat(Stats.ITEM_USED.get(this));
            }
        }
    }
}

protected void onHitEntity(EntityHitResult raytrace) {
    Entity target = raytrace.getEntity();
    Entity shooter = getOwner();
    Player playerShooter = CastOptional.cast(shooter, Player.class).orElse(null);

    DamageSource damagesource = level().damageSources().trident(this, (shooter == null ? this : shooter));
    SoundEvent soundevent = SoundEvents.TRIDENT_HIT;

    int pierceLevel = getEffectLevel(ItemEffect.piercing);
    int ricochetLevel = getEffectLevel(ItemEffect.ricochet);

    if (pierceLevel > 0 || ricochetLevel > 0) {
        if (hitEntities == null) {
            hitEntities = new IntOpenHashSet(5);
        }

        if (hitEntities.contains(target.getId())) {
            return;
        }

        if (hitEntities.size() < pierceLevel || hitEntities.size() < ricochetLevel) {
            hitEntities.add(target.getId());
        } else {
            dealtDamage = true;
        }
    } else {
        dealtDamage = true;
    }

    ItemStack heldTemp = null;
    if (playerShooter != null) {
        heldTemp = playerShooter.getMainHandItem();
        playerShooter.setItemInHand(InteractionHand.MAIN_HAND, thrownStack);
    }

    if (target instanceof LivingEntity && thrownStack.getItem() instanceof ItemModularHandheld) {
        LivingEntity targetLivingEntity = (LivingEntity) target;
        ItemModularHandheld item = (ItemModularHandheld) thrownStack.getItem();

        double abilityDamage = item.getAbilityBaseDamage(shooter instanceof LivingEntity living ? living : null, thrownStack);

        double critModifier = CritEffect.rollMultiplier(targetLivingEntity.getRandom(), item, thrownStack);
        double damage = abilityDamage * item.getEffectEfficiency(thrownStack, ItemEffect.throwable);

        damage += EnchantmentHelper.getDamageBonus(thrownStack, targetLivingEntity.getMobType());
        damage *= critModifier;

        if (target.hurt(damagesource, (float) damage)) {
            if (shooter instanceof LivingEntity livingShooter) {
                EnchantmentHelper.doPostHurtEffects(targetLivingEntity, shooter);
                EffectHelper.applyEnchantmentHitEffects(getPickupItem(), targetLivingEntity, livingShooter);
                ItemEffectHandler.applyHitEffects(thrownStack, targetLivingEntity, livingShooter);

                item.tickProgression(livingShooter, thrownStack, 1);
            }

            doPostHurtEffects(targetLivingEntity);

            if (critModifier != 1d && !level().isClientSide) {
                Vec3 hitVec = raytrace.getLocation();
                ((ServerLevel) level()).sendParticles(ParticleTypes.ENCHANTED_HIT,
                        hitVec.x(), hitVec.y(), hitVec.z(), 15, 0.2D, 0.2D, 0.2D, 0.0D);
            }
        }
    }

    float f1 = 1.0F;
    if (!level().isClientSide && level().isThundering() && EnchantmentHelper.hasChanneling(thrownStack)) {
        BlockPos blockpos = target.blockPosition();
        if (level().canSeeSky(blockpos)) {
            LightningBolt lightning = EntityType.LIGHTNING_BOLT.create(this.level());
            lightning.moveTo(Vec3.atBottomCenterOf(blockpos));
            lightning.setCause(shooter instanceof ServerPlayer ? (ServerPlayer) shooter : null);
            this.level().addFreshEntity(lightning);
            soundevent = SoundEvents.TRIDENT_THUNDER;
            f1 = 5.0F;
        }
    }

    if (playerShooter != null) {
        playerShooter.setItemInHand(InteractionHand.MAIN_HAND, heldTemp);
    }

    playSound(soundevent, f1, 1.0F);

    if (dealtDamage) {
        setDeltaMovement(getDeltaMovement().multiply(-0.01D, -0.1D, -0.01D));
    } else if (ricochetLevel > 0 && !level().isClientSide) {
        Vec3 hitPos = raytrace.getLocation();
        setPosRaw(hitPos.x(), hitPos.y(), hitPos.z());
        setDeltaMovement(level().getEntities(shooter, new AABB(target.blockPosition()).inflate(8d), entity ->
                        !hitEntities.contains(entity.getId())
                                && entity instanceof LivingEntity
                                && !entity.isInvulnerableTo(damagesource)
                                && (shooter == null || !entity.isAlliedTo(shooter)))
                .stream()
                .map(entity -> entity.position().add(0, entity.getBbHeight() * 0.8, 0))
                .map(pos -> pos.subtract(position()))
                .min(Comparator.comparing(Vec3::lengthSqr))
                .map(Vec3::normalize)
                .map(direction -> direction.multiply(1, 0.5, 1))
                .map(direction -> direction.scale(Math.max(getDeltaMovement().length() * 0.5, 0.3)))
                .orElse(getDeltaMovement().multiply(-0.01D, -0.1D, -0.01D)));
    }
}

public void onUpdate() {
    Level world = player.level();
    if (wasDBNO) {
        wasDBNO = false;
        if (world instanceof ServerLevel level) {
            DamageHandler.kill(level, player, 100000);
        }
        return;
    } else if (this.dbnoTimer >= 0) {
        if (dbnoTimer > 0) {
            this.setDBNOTimer(dbnoTimer - 1);
            if (dbnoTimer == 0) {
                sync();
            }
        }
        player.setAirSupply(300);
        player.setDeltaMovement(0, Math.min(0, player.getDeltaMovement().y()), 0);
        player.removeAllEffects();
        return;
    }
    super.onUpdate();
    int level = getLevel();
    if (level > 0) {
        if (player.tickCount % REFERENCE.REFRESH_SUNDAMAGE_TICKS == 0) {
            isGettingSundamage(world, true);
        }
        if (player.tickCount % REFERENCE.REFRESH_GARLIC_TICKS == 0) {
            isGettingGarlicDamage(world, true);
        }
    } else {
        sunDamageCache = false;
        garlicCache = EnumStrength.NONE;
    }
    this.vision.tick();

    if (!isRemote()) {
        if (level > 0) {

            if (isGettingSundamage(world)) {
                handleSunDamage(false);
            } else if (ticksInSun > 0) {
                ticksInSun--;
            }
            if (isGettingGarlicDamage(world) != EnumStrength.NONE) {
                DamageHandler.affectVampireGarlicAmbient(this, isGettingGarlicDamage(world), player.tickCount);
            }
            if (player.isAlive()) {
                player.setAirSupply(300);
                if (player.tickCount % 16 == 4 && !getSkillProperties().waterResistance && !player.getAbilities().instabuild) {
                    if (player.isInWater()) {
                        FluidState state1 = world.getFluidState(player.blockPosition());
                        FluidState state2 = world.getFluidState(player.blockPosition().above());
                        if ((state1.is(FluidTags.WATER) && (state1.getFlow(world, player.blockPosition()).lengthSqr() > 0)) || (state2.is(FluidTags.WATER) && (state2.getFlow(world, player.blockPosition().above()).lengthSqr() > 0))) {
                            player.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 80, (int) (getLevel() / (float) getMaxLevel() * 3)));
                        }
                    }
                }
            }

            if (player.tickCount % 9 == 3 && ModConfig.balance().vpFireResistanceReplace.get() && player.hasEffect(MobEffects.FIRE_RESISTANCE)) {
                MobEffectInstance fireResistance = player.getEffect(MobEffects.FIRE_RESISTANCE);
                player.addEffect(new MobEffectInstance(ModEffects.FIRE_PROTECTION, fireResistance.getDuration(), fireResistance.getAmplifier()));
                player.removeEffect(MobEffects.FIRE_RESISTANCE);
            }
            if (feed_victim != -1 && feedBiteTickCounter++ >= FEED_TIMER) {
                updateFeeding();
                feedBiteTickCounter = 0;
            }

            if (forceNaturalArmorUpdate || player.tickCount % 128 == 0) {
                updateNaturalArmor(getLevel());
                forceNaturalArmorUpdate = false;
            }
        } else {
            ticksInSun = 0;
        }
    } else {
        if (level > 0) {
            if (isGettingSundamage(world)) {
                handleSunDamage(true);
            } else if (ticksInSun > 0) {
                ticksInSun--;
            }
        } else {
            ticksInSun = 0;
        }

        if (feed_victim != -1 && feedBiteTickCounter++ % 5 == 0) {
            Entity e = VampirismMod.proxy.getMouseOverEntity();
            if (e == null || e.getId() != feed_victim) {
                VampirismMod.proxy.sendToServer(new ServerboundSimpleInputEvent(ServerboundSimpleInputEvent.Event.FINISH_SUCK_BLOOD));
                feedBiteTickCounter = 0;
                feed_victim = -1;
                return;
            }
            if (feedBiteTickCounter >= FEED_TIMER) {
                feedBiteTickCounter = 0;
            }
        }
    }
    if (feed_victim == -1) {
        feedBiteTickCounter = 0;
    }
    if (remainingBarkTicks > 0) {
        --remainingBarkTicks;
    }
    if (crucifixTicks > 0) {
        --crucifixTicks;
        if (this.player.tickCount % 10 == 8 && crucifixTicks > 30) {
            this.player.addEffect(new MobEffectInstance(ModEffects.CRUCIFIX_SUPPRESSION, 20));
        }
    }
}

public void releaseUsing(ItemStack bow, Level level, LivingEntity living, int timeLeft) {
  // call the stop using hook
  ToolStack tool = ToolStack.from(bow);
  int duration = getUseDuration(bow);
  for (ModifierEntry entry : tool.getModifiers()) {
    entry.getHook(ModifierHooks.TOOL_USING).beforeReleaseUsing(tool, entry, living, duration, timeLeft, ModifierEntry.EMPTY);
  }

  // no broken
  if (tool.isBroken()) {
    return;
  }

  // just not handling vanilla infinity at all, we have our own hooks which someone could use to mimic infinity if they wish with a bit of effort
  Player player = living instanceof Player p ? p : null;
  boolean creative = player != null && player.getAbilities().instabuild;
  // its a little redundant to search for ammo twice, but otherwise we risk shrinking the stack before we know if we can fire
  // also helps blocking, as you can block without ammo
  Predicate<ItemStack> ammoPredicate = switch (tool.getPersistentData().getInt(KEY_BALLISTA)) {
    case FLAG_BALLISTA_HELD -> null; // main hand comes via an event, we just call the hook for merging
    case FLAG_BALLISTA_QUIVER -> BALLISTA_ONLY;
    case FLAG_NO_BALLISTA -> getSupportedHeldProjectiles();
    default -> isBallista(tool) ? getSupportedBallistaAmmo() : getSupportedHeldProjectiles();
  };
  ItemStack foundAmmo = BowAmmoModifierHook.getAmmo(tool, bow, living, ammoPredicate);
  boolean hasAmmo = !foundAmmo.isEmpty() || creative && !tool.getVolatileData().getBoolean(BowAmmoModifierHook.SKIP_INVENTORY_AMMO);

  // ask forge its thoughts on shooting
  int chargeTime = duration - timeLeft;
  if (player != null) {
    chargeTime = ForgeEventFactory.onArrowLoose(bow, level, player, chargeTime, hasAmmo);
  }

  // no ammo? no charge? nothing to do
  if (!hasAmmo || chargeTime < 0) {
    return;
  }

  // calculate arrow power
  float charge = GeneralInteractionModifierHook.getToolCharge(tool, chargeTime);
  float velocity = ConditionalStatModifierHook.getModifiedStat(tool, living, ToolStats.VELOCITY);
  float power = charge * velocity;
  if (power < 0.1f) {
    return;
  }

  // launch the arrow
  if (!level.isClientSide) {
    int originalSlot = -1;
    int desiredProjectiles = 1;
    // if it's a ballista shot, locate the original slot so we can store it on the entity
    if (foundAmmo.is(TinkerTags.Items.BALLISTA_AMMO)) {
      if (player != null) {
        if (foundAmmo == living.getOffhandItem()) {
          originalSlot = Inventory.SLOT_OFFHAND;
        } else {
          Inventory inventory = player.getInventory();
          // does not use the inventory method as we want instance match, not deep compare
          for (int i = 0; i < Inventory.INVENTORY_SIZE; i++) {
            if (inventory.getItem(i) == foundAmmo) {
              originalSlot = i;
              break;
            }
          }
        }
      }
    } else {
      // TODO: remove multishot logic? or keep it around for addons?
      desiredProjectiles = BowAmmoModifierHook.getDesiredProjectiles(tool);
    }
    // filter ammo based on request from current ballista settings
    ItemStack ammo = BowAmmoModifierHook.consumeAmmo(tool, bow, living, player, ammoPredicate, desiredProjectiles);
    // could only be empty at this point if we are creative, as hasAmmo returned true above
    if (ammo.isEmpty()) {
      ammo = new ItemStack(Items.ARROW);
    }

    // prepare the arrows
    ArrowItem arrowItem = ammo.getItem() instanceof ArrowItem arrow ? arrow : (ArrowItem)Items.ARROW;
    // shenanigans: if the ammo is a melee tool, fire that using the thrown tool projectile
    boolean thrownTool = ammo.is(TinkerTags.Items.BALLISTA_AMMO);
    float waterInertia = 0.6f;
    SoundEvent sound = SoundEvents.ARROW_SHOOT;
    if (thrownTool) {
      sound = SoundEvents.TRIDENT_THROW;
      IToolStackView thrown = ToolStack.from(ammo);
      float thrownVelocity = ConditionalStatModifierHook.getModifiedStat(thrown, living, ToolStats.VELOCITY);
      power *= thrownVelocity * ConditionalStatModifierHook.getModifiedStat(thrown, living, ToolStats.DRAW_SPEED) / 1.5f;
      if (ammo.is(TinkerTags.Items.MELEE_WEAPON)) {
        power *= thrown.getStats().get(ToolStats.ATTACK_SPEED);
      }
      velocity *= thrownVelocity;
      waterInertia = ConditionalStatModifierHook.getModifiedStat(thrown, living, ToolStats.WATER_INERTIA);
    }
    float inaccuracy = ModifierUtil.getInaccuracy(tool, living);
    float startAngle = getAngleStart(ammo.getCount());
    int primaryIndex = ammo.getCount() / 2;
    for (int arrowIndex = 0; arrowIndex < ammo.getCount(); arrowIndex++) {
      AbstractArrow arrow;
      if (thrownTool) {
        ThrownTool thrown = new ThrownTool(level, living, ammo, charge, velocity, waterInertia);
        thrown.setOriginalSlot(originalSlot);
        arrow = thrown;
      } else {
        arrow = arrowItem.createArrow(level, ammo, living);
      }
      float angle = startAngle + (10 * arrowIndex);
      arrow.shootFromRotation(living, living.getXRot() + angle, living.getYRot(), 0, power * 3.0F, inaccuracy);
      if (charge == 1.0F) {
        arrow.setCritArrow(true);
      }

      // vanilla arrows have a base damage of 2, cancel that out then add in our base damage to account for custom arrows with higher base damage
      // calculate it just once as all four arrows are the same item, they should have the same damage
      float baseArrowDamage = (float)(arrow.getBaseDamage() - 2 + tool.getStats().get(ToolStats.PROJECTILE_DAMAGE));
      arrow.setBaseDamage(ConditionalStatModifierHook.getModifiedStat(tool, living, ToolStats.PROJECTILE_DAMAGE, baseArrowDamage));

      // just store all modifiers on the tool for simplicity
      ModifierNBT modifiers = tool.getModifiers();
      EntityModifierCapability.getCapability(arrow).addModifiers(modifiers);

      // fetch the persistent data for the arrow as modifiers may want to store data
      ModDataNBT arrowData = PersistentDataCapability.getOrWarn(arrow);

      // if infinite, skip pickup
      if (creative) {
        arrow.pickup = AbstractArrow.Pickup.CREATIVE_ONLY;
      }

      // let modifiers such as fiery and punch set properties
      for (ModifierEntry entry : modifiers.getModifiers()) {
        entry.getHook(ModifierHooks.PROJECTILE_LAUNCH).onProjectileLaunch(tool, entry, living, ammo, arrow, arrow, arrowData, arrowIndex == primaryIndex);
      }

      // allow ballista to run a few remaining hooks if present
      if (thrownTool) {
        // know the cast is valid as we created the instance above
        ((ThrownTool) arrow).onRelease(living, arrowData);
      }

      level.addFreshEntity(arrow);
      level.playSound(null, living.getX(), living.getY(), living.getZ(), sound, SoundSource.PLAYERS, 1.0F, 1.0F / (level.getRandom().nextFloat() * 0.4F + 1.2F) + charge * 0.5F + (angle / 10f));
    }
    int damage = ammo.getCount();
    if (thrownTool) {
      damage *= 3;
    }
    ToolDamageUtil.damageAnimated(tool, damage, living, living.getUsedItemHand());
  }

  // stats and sounds
  if (player != null) {
    player.awardStat(Stats.ITEM_USED.get(this));
  }
}

public void tick() {
    super.tick();
    prevStrikeProgress = strikeProgress;
    prevReturnProgress = returnProgress;
    Entity controller = getController();
    Entity target = getTarget();
    if (!level().isClientSide) {
        if (this.comingBack || controller instanceof TeletorEntity && (target == null || !target.isAlive())) {
            this.noPhysics = true;
        } else {
            this.noPhysics = false;
        }
        if (controller == null && this.tickCount > 20 || this.getItemStack().isEmpty()) {
            if(hadPlayerController){
                this.plopItem();
                hadPlayerController = false;
            }
            this.remove(RemovalReason.DISCARDED);
        }
    }
    if ((this.getTarget() == null || comingBack || playerUseCooldown > 0) && strikeProgress > 0) {
        strikeProgress = Math.max(0, strikeProgress - 0.1F);
    }
    if (controller instanceof TeletorEntity teletor) {
        this.entityData.set(CONTROLLER_ID, teletor.getId());
        teletor.setWeaponUUID(this.getUUID());
        if (!level().isClientSide) {
            Entity e = teletor.getTarget();
            this.entityData.set(TARGET_ID, e != null && e.isAlive() ? e.getId() : -1);
        }
        boolean attacking = !comingBack && target != null && target.isAlive();
        Vec3 vec3 = attacking ? target.getEyePosition() : teletor.getWeaponPosition();
        Vec3 want = vec3.subtract(this.position());
        if (target != null && !comingBack) {
            this.entityData.set(IDLING, false);
            if (want.length() < target.getBbWidth() + 1F) {
                if (strikeProgress < 1F) {
                    strikeProgress = Math.max(0, strikeProgress + 0.35F);
                } else {
                    hurtEntity(teletor, target);
                    this.comingBack = true;
                }
            } else if (want.length() > 32) {
                this.comingBack = true;
            }
        }
        directMovementTowards(vec3, 0.1F);
        if (this.distanceTo(controller) < 2.5F && this.getY() > controller.getY()) {
            this.entityData.set(IDLING, true);
            if (this.comingBack) {
                this.comingBack = false;
            }
        }
    } else if (controller instanceof Player player) {
        Vec3 moveTo = null;
        this.entityData.set(CONTROLLER_ID, controller.getId());
        this.entityData.set(IDLING, false);
        this.comingBack = !isOwnerWearingGauntlet();
        float speed = 0.1F;
        boolean haste = false;
        if (isOwnerWearingGauntlet()) {
            hadPlayerController = true;
            float maxDist = 30F;
            if(getController() instanceof LivingEntity living && living.getUseItem().is(ACItemRegistry.GALENA_GAUNTLET.get())){
                ItemStack useItem = living.getUseItem();
                haste = useItem.getEnchantmentLevel(ACEnchantmentRegistry.FERROUS_HASTE.get()) > 0;
                int fieldExtension = useItem.getEnchantmentLevel(ACEnchantmentRegistry.FIELD_EXTENSION.get());
                maxDist += fieldExtension * 5F;
            }
            BlockPos miningBlock = null;
            HitResult hitresult = ProjectileUtil.getHitResultOnViewVector(player, Entity::canBeHitByProjectile, maxDist);
            if (hitresult instanceof EntityHitResult entityHitResult && playerUseCooldown == 0) {
                Entity entity = entityHitResult.getEntity();
                moveTo = entity.position().add(0, entity.getBbHeight() * 0.5F, 0);
                speed = 0.2F;
                if (this.distanceTo(entity) < entity.getBbWidth() + 1.5F) {
                    if (strikeProgress < 1F) {
                        strikeProgress = Math.max(0, strikeProgress + 0.35F);
                    } else {
                        hurtEntity(player, entity);

                        playerUseCooldown = haste ? 3 : 5 + random.nextInt(5);
                    }
                }
            } else {
                moveTo = player.getEyePosition().add(player.getViewVector(1.0F).scale(maxDist - 20F));
                if (hitresult.getType() == HitResult.Type.BLOCK || hitresult.getLocation().subtract(player.getEyePosition()).length() < maxDist) {
                    if (hitresult instanceof BlockHitResult blockHitResult) {
                        if (this.distanceToSqr(Vec3.atCenterOf(blockHitResult.getBlockPos())) < 2.25F) {
                            miningBlock = blockHitResult.getBlockPos();
                        }
                        if (!level().getBlockState(blockHitResult.getBlockPos()).isAir()) {
                            moveTo = hitresult.getLocation();
                        }
                    }
                }
            }
            if (miningBlock != null) {
                if (lastSelectedBlock == null || !lastSelectedBlock.equals(miningBlock)) {
                    if (lastSelectedBlock != null) {
                        this.level().destroyBlockProgress(player.getId(), lastSelectedBlock, -1);
                    }
                    lastSelectedBlock = miningBlock;
                    destroyBlockProgress = 0.0F;
                }
                BlockState miningState = level().getBlockState(miningBlock);
                SoundType soundType = miningState.getSoundType();
                float f = miningState.getDestroySpeed(level(), miningBlock);
                float itemDestroySpeed = getDigSpeed(player, miningState, miningBlock);
                if (itemDestroySpeed > 1.0F) {
                    if (totalMiningTime % 4 == 0) {
                        this.playSound(soundType.getHitSound(), (soundType.getVolume() + 1.0F) / 8.0F, soundType.getPitch() * 0.5F);
                    }
                    totalMiningTime++;
                    strikeProgress = (float) Math.abs(Math.sin(tickCount * 0.6F) * 1.2F - 0.2F);
                    float j = itemDestroySpeed / f / (float) (haste ? 8 : 10);
                    destroyBlockProgress += j;
                    this.level().destroyBlockProgress(player.getId(), lastSelectedBlock, (int) (destroyBlockProgress * 10F));
                    if (destroyBlockProgress >= 1.0F && !level().isClientSide) {
                        damageItem(1);
                        ItemStack itemStack = getItemStack();
                        itemStack.mineBlock(this.level(), miningState, miningBlock, player);
                        int fortuneLevel = itemStack.getEnchantmentLevel(Enchantments.BLOCK_FORTUNE);
                        int silkTouchLevel = itemStack.getEnchantmentLevel(Enchantments.SILK_TOUCH);
                        int exp = miningState.getExpDrop(level(), level().random, miningBlock, fortuneLevel, silkTouchLevel);
                        net.minecraftforge.event.ForgeEventFactory.onPlayerDestroyItem(player, itemStack, InteractionHand.MAIN_HAND);
                        boolean flag;
                        if (miningState.getBlock() instanceof ShulkerBoxBlock) {
                            flag = level().destroyBlock(miningBlock, true);
                            player.awardStat(Stats.BLOCK_MINED.get(miningState.getBlock()));
                            player.causeFoodExhaustion(0.005F);
                        }
                        else {
                            flag = level().destroyBlock(miningBlock, false);
                            miningState.getBlock().playerDestroy(level(), player, miningBlock, miningState, level().getBlockEntity(miningBlock), itemStack);
                        }
                        if (flag && exp > 0 && level() instanceof ServerLevel serverLevel) {
                            miningState.getBlock().popExperience(serverLevel, miningBlock, exp);
                        }
                        destroyBlockProgress = 0.0F;
                    }
                }
            }
        } else {
            if (returnProgress < 1F) {
                returnProgress = Math.min(1, returnProgress + 0.2F);
            }
            if (lastSelectedBlock != null) {
                this.level().destroyBlockProgress(player.getId(), lastSelectedBlock, -1);
                lastSelectedBlock = null;
            }
            moveTo = player.position().add(0, 1, 0);
            if (distanceTo(controller) < 1.4) {
                if (!this.isRemoved()) {
                    if(!spawnedItem && player.addItem(this.getItemStack())){
                        spawnedItem = true;
                        this.remove(RemovalReason.DISCARDED);
                    }else{
                        plopItem();
                    }
                }
            }
        }
        if (moveTo != null) {
            directMovementTowards(moveTo, speed);
        }
    }
    if (playerUseCooldown > 0) {
        playerUseCooldown--;
    }
    this.move(MoverType.SELF, this.getDeltaMovement());
    this.setDeltaMovement(this.getDeltaMovement().scale(0.9F));
}

public void onUnequip(IToolStackView tool, ModifierEntry modifier, EquipmentChangeContext context) {
  context.getEntity().removeEffect(TinkerEffects.selfDestructing.get());
}

public void afterBlockBreak(IToolStackView tool, ModifierEntry modifier, ToolHarvestContext context) {
  if (isAoe.test(context.isAOE()) && isProjectile.test(context.isProjectile()) && condition.matches(tool, modifier) && checkChance(modifier)) {
    effect.applyEffect(context.getLiving(), modifier, null);
  }
}

public void afterMeleeHit(IToolStackView tool, ModifierEntry modifier, ToolAttackContext context, float damageDealt) {
  if (context.isFullyCharged() && isAoe.test(context.isExtraAttack()) && isProjectile.test(context.isProjectile()) && condition.matches(tool, modifier) && checkChance(modifier)) {
    effect.applyEffect(context.getAttacker(), modifier, null);
  }
}

public void onToolEaten(IToolStackView tool, ModifierEntry modifier, Player player, EquipmentSlot eatenSlot, int hunger, float saturation, List<ItemStack> representativeItems) {
  if (condition.matches(tool, modifier) && this.holder.matches(player)) {
    effect.applyEffect(player, modifier, null);
  }
}

public void onFinishUsing(IToolStackView tool, ModifierEntry modifier, LivingEntity entity) {
  if (entity instanceof Player player) {
    player.getCooldowns().addCooldown(tool.getItem(), (int)(20 / tool.getStats().get(ToolStats.ATTACK_SPEED)));
  }
}

default void addCooldown(int cooldown) {
    if (cooldown > 0 && entity() instanceof Player player && !get().isEmpty()) {
        player.getCooldowns().addCooldown(get(), cooldown);
    }
}

default boolean onProjectileHitEntity(ModifierNBT modifiers, ModDataNBT persistentData, ModifierEntry modifier, Projectile projectile, EntityHitResult hit, @Nullable LivingEntity attacker, @Nullable LivingEntity target) {
  if (condition().modifierLevel().test(modifier.getLevel()) && TinkerPredicate.matches(holder(), attacker) && checkChance(modifier)) {
    effect().applyEffect(target, modifier, projectile.getEffectSource());
  }
  return false;
}

public void onProjectileLaunch(IToolStackView tool, ModifierEntry modifier, LivingEntity shooter, Projectile projectile, @Nullable AbstractArrow arrow, ModDataNBT persistentData, boolean primary) {
  // yes, we are launching a projectile, but the intention of that condition is are we a projectile that just hit
  if (isAoe.test(!primary) && isProjectile.test(false) && condition.matches(tool, modifier) && checkChance(modifier)) {
    effect.applyEffect(shooter, modifier, null);
  }
}

public boolean onProjectileHitEntity(ModifierNBT modifiers, ModDataNBT persistentData, ModifierEntry modifier, Projectile projectile, EntityHitResult hit, @Nullable LivingEntity attacker, @Nullable LivingEntity target, boolean notBlocked) {
  if (notBlocked && isAoe.test(false) && isProjectile.test(true) && condition.modifierLevel().test(modifier.getLevel()) && checkChance(modifier)) {
    effect.applyEffect(attacker, modifier, null);
  }
  return false;
}

public void onProjectileLaunch(IToolStackView tool, ModifierEntry modifier, LivingEntity shooter, Projectile projectile, @Nullable AbstractArrow arrow, ModDataNBT persistentData, boolean primary) {
  if (primary && (arrow == null || arrow.isCritArrow())) {
    // 10 arrows gets you to max
    applyEffect(shooter, ToolType.RANGED, 10*20, 9);
  }
}

public void onProjectileLaunch(IToolStackView tool, ModifierEntry modifier, LivingEntity shooter, Projectile projectile, @Nullable AbstractArrow arrow, ModDataNBT persistentData, boolean primary) {
  if (primary && (arrow == null || arrow.isCritArrow()) && RANDOM.nextInt(3) == 0) {
    // 25% chance to poison yourself
    shooter.addEffect(makeDecayEffect(modifier.getLevel()));
  }
}

public void afterMeleeHit(IToolStackView tool, ModifierEntry modifier, ToolAttackContext context, float damageDealt) {
  // 5 hits gets you to max
  if (!context.isExtraAttack() && context.isFullyCharged()) {
    applyEffect(context.getAttacker(), ToolType.MELEE, 5*20, 1, 4);
  }
}

public boolean onProjectileHitEntity(ModifierNBT modifiers, ModDataNBT persistentData, ModifierEntry modifier, Projectile projectile, EntityHitResult hit, @Nullable LivingEntity attacker, @Nullable LivingEntity target, boolean notBlocked) {
  if (notBlocked && attacker != null) {
    applyEffect(attacker, ToolType.RANGED, 10*20, 1, 4);
  }
  return false;
}

public void clearSlotModifiers() {

  for (Map.Entry<String, ICurioStacksHandler> entry : this.curioInventory.asMap().entrySet()) {
    entry.getValue().clearModifiers();
  }
}

static void afterStopUsing(IToolStackView tool, LivingEntity living, int timeLeft) {
  ModifierEntry activeModifier = GeneralInteractionModifierHook.getActiveModifier(tool);
  int duration = activeModifier.getHook(ModifierHooks.GENERAL_INTERACT).getUseDuration(tool, activeModifier);
  for (ModifierEntry entry : tool.getModifiers()) {
    entry.getHook(ModifierHooks.TOOL_USING).afterStopUsing(tool, entry, living, duration, timeLeft, activeModifier);
  }
}

public boolean onProjectileHitsBlock(ModifierNBT modifiers, ModDataNBT persistentData, ModifierEntry modifier, Projectile projectile, BlockHitResult hit, @Nullable LivingEntity owner) {
  // calling a miss an AOE
  if (isAoe.test(true) && isProjectile.test(true) && condition.modifierLevel().test(modifier.getLevel()) && checkChance(modifier)) {
    effect.applyEffect(owner, modifier, null);
  }
  return false;
}

public boolean onProjectileHitEntity(ModifierNBT modifiers, ModDataNBT persistentData, ModifierEntry modifier, Projectile projectile, EntityHitResult hit, @Nullable LivingEntity attacker, @Nullable LivingEntity target) {
  if (target != null && (!(projectile instanceof AbstractArrow arrow) || arrow.isCritArrow())) {
    // always poison the target, means it works twice as often as lacerating
    target.addEffect(makeDecayEffect(modifier.getLevel()), projectile.getEffectSource());
  }
  return false;
}

public void clearModifiers() {
  Set<Identifier> ids = new HashSet<>(this.modifiers.keySet());

  for (Identifier id : ids) {
    this.removeModifier(id);
  }
}

public void onUnequip(EquipmentAttributeModifier ability, LivingEntity entity) {
    AttributeInstance attributeInstance = entity.getAttribute(ability.attribute());
    if (attributeInstance != null && attributeInstance.hasModifier(ability.id())) {
        attributeInstance.removeModifier(ability.id());
        ability.onAttributeUpdated(entity);
    }
}

public static void onLivingDamaged(LivingEntity entity, DamageSource damageSource) {
    if (entity.level().isClientSide()) {
        ModDataComponents.POST_DAMAGE_COOLDOWN.on(entity)
                .filter(ability -> ability.tag().isEmpty() || damageSource.is(ability.tag().get()))
                .iterate((ability, slot) -> slot.addCooldown(ability.cooldown.get() * 20));
    }
}

public void addAttributes(IToolStackView tool, ModifierEntry modifier, EquipmentSlot slot, BiConsumer<Attribute,AttributeModifier> consumer) {
  if (condition.matches(tool, modifier)) {
    AttributeModifier attributeModifier = createModifier(tool, modifier, slot);
    if (attributeModifier != null) {
      consumer.accept(attribute, attributeModifier);
    }
  }
}

private void removeAttribute(@Nullable LivingEntity target) {
  if (target != null) {
    AttributeInstance instance = target.getAttribute(attribute);
    if (instance != null) {
      instance.removeModifier(uuid);
    }
  }
}

default void onMonsterMeleeHit(IToolStackView tool, ModifierEntry modifier, ToolAttackContext context, float damage) {
  if (context.isFullyCharged() && condition().matches(tool, modifier) && checkChance(modifier)) {
    LivingEntity attacker = context.getAttacker();
    if (holder().matches(attacker)) {
      effect().applyEffect(context.getLivingTarget(), modifier, attacker);
    }
  }
}

public void onDamageDealt(IToolStackView tool, ModifierEntry modifier, EquipmentContext context, EquipmentSlot slotType, LivingEntity target, DamageSource source, float amount, boolean isDirectDamage) {
  if (this.directDamage.test(isDirectDamage) && condition.matches(tool, modifier) && this.damageSource.matches(source) && checkChance(modifier)) {
    LivingEntity holder = context.getEntity();
    if (holder != target && this.holder.matches(holder)) {
      effect.applyEffect(target, modifier, holder);
    }
  }
}

public void afterBlockBreak(IToolStackView tool, ModifierEntry modifier, ToolHarvestContext context) {
  if (context.canHarvest() && context.isEffective() && !context.isAOE() && tool.hasTag(TinkerTags.Items.HARVEST)) {
    // grant the effect for 5 seconds, though grant a longer effect if the blocks hardness is particularly high compared to our mining speed
    int duration = Math.max(5*20, (int) (2.5f * 20f * context.getState().getDestroySpeed(context.getWorld(), context.getPos()) / tool.getStats().get(ToolStats.MINING_SPEED)));
    // 10 blocks gets you to max, effect is stronger at higher levels
    applyEffect(context.getLiving(), ToolType.HARVEST, duration, 9);
  }
}

public boolean startInteract(IToolStackView tool, ModifierEntry modifier, Player player, EquipmentSlot slot, TooltipKey keyModifier) {
  if (player.isShiftKeyDown()) {
    player.addEffect(new MobEffectInstance(TinkerEffects.selfDestructing.get(), 30, 2 * modifier.intEffectiveLevel()));
    player.playSound(SoundEvents.CREEPER_PRIMED, 1.0F, 0.5F);
    return true;
  }
  return false;
}

public void onDamageDealt(IToolStackView tool, ModifierEntry modifier, EquipmentContext context, EquipmentSlot slotType, LivingEntity target, DamageSource source, float amount, boolean isDirectDamage) {
  // drink milk for more power, but less duration
  if (isDirectDamage && !source.is(DamageTypeTags.IS_PROJECTILE)) {
    LivingEntity attacker = context.getEntity();
    boolean isCalcified = attacker.hasEffect(TinkerModifiers.calcifiedEffect.get());
    target.addEffect(new MobEffectInstance(MobEffects.WITHER, isCalcified ? 100 : 200, isCalcified ? 1 : 0), attacker);
  }
}

public void wornTick(EquipmentMobEffect ability, EquipmentSlotAccess slotAccess, LivingEntity entity, boolean isOnCooldown, boolean isDisabled) {
    MobEffectProvider provider = ability.provider;
    if (!isDisabled && !isOnCooldown) {
        if (provider.canApply(entity)) {
            entity.addEffect(provider.createEffect());
        }
    }
}

public int getUseDuration(IToolStackView tool, ModifierEntry modifier) {
  for (GeneralInteractionModifierHook module : modules) {
    int duration = module.getUseDuration(tool, modifier);
    if (duration > 0) {
      return duration;
    }
  }
  return 0;
}

public void addAttributes(IToolStackView tool, ModifierEntry modifier, EquipmentSlot slot, BiConsumer<Attribute,AttributeModifier> consumer) {
  if (slot == EquipmentSlot.MAINHAND) {
    double boost = getMultiplier(tool, modifier.getLevel());
    if (boost != 0) {
      // half boost for attack speed, its
      consumer.accept(Attributes.ATTACK_DAMAGE, new AttributeModifier(uuid.get(), attributeName.get(), boost / 2, Operation.MULTIPLY_TOTAL));
    }
  }
}

public void afterMeleeHit(IToolStackView tool, ModifierEntry modifier, ToolAttackContext context, float damageDealt) {
  // 50% chance of applying
  LivingEntity target = context.getLivingTarget();
  if (target != null && context.isFullyCharged() && target.isAlive()) {
    // set entity so the potion is attributed as a player kill
    target.setLastHurtMob(context.getAttacker());
    applyEffect(tool, context.getAttacker(), target, modifier.getLevel(), context.getSlotType());
  }
}

public void onDamageDealt(IToolStackView tool, ModifierEntry modifier, EquipmentContext context, EquipmentSlot slotType, LivingEntity target, DamageSource source, float amount, boolean isDirectDamage) {
  // must drink milk to melee slowness. Always can range slowness
  if (isDirectDamage) {
    boolean isCalcified = context.getEntity().hasEffect(TinkerModifiers.calcifiedEffect.get());
    if (isCalcified || source.is(DamageTypeTags.IS_PROJECTILE)) {
      target.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, 300, isCalcified ? 1 : 0), context.getEntity());
    }
  }
}

public void applyEffectTick(LivingEntity living, int amplifier) {
  // effect level is the explosion radius
  Level level = living.level();
  if (!level.isClientSide) {
    // TODO: is firing mob grief event with a player okay?
    level.explode(living, living.getX(), living.getY(), living.getZ(), amplifier + 1, ExplosionInteraction.MOB);
    living.hurt(TinkerDamageTypes.source(level.registryAccess(), TinkerDamageTypes.SELF_DESTRUCT), 99999);
  }
}

public void onDamageDealt(IToolStackView tool, ModifierEntry modifier, EquipmentContext context, EquipmentSlot slotType, LivingEntity target, DamageSource source, float amount, boolean isDirectDamage) {
  if (isDirectDamage && !source.is(DamageTypeTags.IS_PROJECTILE)) {
    int fire = context.getEntity().getRemainingFireTicks();
    if (fire > 0) {
      // copy fire duration, merge with their current duration, and a little extra to account for divide flooring
      target.setRemainingFireTicks((fire + target.getRemainingFireTicks()) / 20 + 1);
    }
  }
}

public void onAttacked(IToolStackView tool, ModifierEntry modifier, EquipmentContext context, EquipmentSlot slotType, DamageSource source, float amount, boolean isDirectDamage) {
  // require the damage to be entity caused, but does not strictly need to be melee damage
  if (source.getEntity() != null) {
    int level = SlotInChargeModule.getLevel(context.getTinkerData(), SLOT_IN_CHARGE, slotType);
    if (level > 0) {
      InsatiableModifier.applyEffect(context.getEntity(), ToolType.ARMOR, 10 * 20, 1, level - 1);
    }
  }
}

