public float apply(FluidStack fluid, EffectLevel level, Entity context, FluidAction action) {
  LivingEntity living = context.getLivingTarget();
  if (living != null && level.isFull()) {
    if (action.simulate()) {
      return living.hasEffect(effect) ? 1 : 0;
    }
    return living.removeEffect(effect) ? 1 : 0;
  }
  return 0;
}

public void updateValue(IToolStackView tool, ModifierEntry modifier, EquipmentChangeContext context, Holder data, float newLevel, float oldLevel) {
  AttributeInstance instance = context.getEntity().getAttribute(attribute);
  if (instance != null) {
    instance.removeModifier(uuid);
    float attributeValue = amount.computeForLevel(newLevel);
    if (attributeValue != 0) {
      instance.addTransientModifier(new AttributeModifier(uuid, unique, attributeValue, operation));
    }
  }
}

public InteractionResult onToolUse(IToolStackView tool, ModifierEntry modifier, Player player, InteractionHand hand, InteractionSource source) {
  if (canAttack(tool, player, hand)) {
    // target done in onEntityInteract, this is just for cooldown cause you missed
    applyCooldown(tool, player, source);
    // we handle swinging the arm, return consume to prevent resetting cooldown
    OffhandCooldownTracker.swingHand(player, InteractionHand.OFF_HAND, false);
    return InteractionResult.CONSUME;
  }
  return InteractionResult.PASS;
}

public void handleThreadsafe(Context context) {
  Level level = SafeClientAccess.getLevel();
  if (level != null) {
    Entity entity = level.getEntity(entityId);
    if (entity != null) {
      EntityModifierCapability.getCapability(entity).setModifiers(modifiers);
      PersistentDataCapability.getOrWarn(entity).copyFrom(persistentData);
    }
  }
}

public static <ACC> ACC reduceEquipment(@Nullable LivingEntity entity, boolean skipItemsOnCooldown, boolean skipDisabledItems, ACC init, BiFunction<ACC, EquipmentSlotAccess, ACC> f) {
    return reduceEquipment(entity, init, ((slotAccess, acc) -> {
        boolean checkCooldown = !skipItemsOnCooldown || !slotAccess.isOnCooldown(entity);
        boolean checkDisabled = !skipDisabledItems || !slotAccess.isDisabledOrBroken();
        if (checkCooldown && checkDisabled) {
            return f.apply(acc, slotAccess);
        }
        return acc;
    }));
}

static float getToolCharge(IToolStackView tool, float chargeTime) {
  if (chargeTime < 0) {
    return 0;
  }
  float charge = chargeTime / tool.getPersistentData().getInt(KEY_DRAWTIME);
  charge = (charge * charge + charge * 2) / 3;
  if (charge > 1) {
    charge = 1;
  }
  return charge;
}

