private void updateAttribute(LivingEntity living, int totalGold) {
  // update attribute
  AttributeInstance instance = living.getAttribute(attribute);
  if (instance != null) {
    if (instance.getModifier(uuid) != null) {
      instance.removeModifier(uuid);
    }
    instance.addTransientModifier(new AttributeModifier(uuid, unique, amount.compute(totalGold), operation));
    checkHealth(living, instance);
  }
}

public void copyModifiers(ICurioStacksHandler other) {
  this.modifiers.clear();
  this.modifiersByOperation.clear();
  this.persistentModifiers.clear();
  other.getModifiers().forEach((uuid, modifier) -> this.addTransientModifier(modifier));

  for (AttributeModifier persistentModifier : other.getPermanentModifiers()) {
    this.addPermanentModifier(persistentModifier);
  }
  this.update();
}

private static void applyCooldown(IToolStackView tool, Player player, InteractionSource source) {
  float attackSpeed;
  if (source == InteractionSource.ARMOR) {
    // for armor, always assume attack speed is 4.0, we cannot change the attack speed of the main hand and we want them to match
    attackSpeed = 4;
  } else {
    // if we get here, its always offhand
    // need to cancel out the base 4 attack speed in the tool attack speed, since we removed the main hand one doing it
    attackSpeed = ToolAttackUtil.getToolAttribute(tool, player, Attributes.ATTACK_SPEED, tool.getStats().get(ToolStats.ATTACK_SPEED) - 4);
  }
  OffhandCooldownTracker.applyCooldown(player, attackSpeed, 20);
}

private static void applyEffect(LivingEntity target, int level, int looting, @Nullable Entity cause) {
  int duration = level * 2 * 20;
  MobEffectInstance existing = target.getEffect(TinkerEffects.bleeding.get());
  if (existing != null && existing.getAmplifier() == looting) {
    duration += existing.getDuration();
  } else {
    // add a small delay so first damage happens in about a second
    // skip when already present so we continue on the same clock and don't repeat a damage
    duration += 19;
  }
  target.addEffect(new MobEffectInstance(TinkerEffects.bleeding.get(), duration, looting), cause);
}

public void afterMeleeHit(IToolStackView tool, ModifierEntry modifier, ToolAttackContext context, float damageDealt) {
  DamageSource source = TinkerDamageTypes.source(
    context.getLevel().registryAccess(),
    TinkerDamageTypes.PIERCING,
    Objects.requireNonNullElse(context.getPlayerAttacker(), context.getAttacker()));
  // deals 0.5 pierce damage per level, scaled, half of sharpness
  float secondaryDamage = (modifier.getEffectiveLevel() * tool.getMultiplier(ToolStats.ATTACK_DAMAGE)) * context.getCooldown();
  if (context.isCritical()) {
    secondaryDamage *= 1.5f;
  }
  ToolAttackUtil.attackEntitySecondary(source, secondaryDamage, context.getTarget(), context.getLivingTarget(), true);
}

public void onUnequip(EquipmentMobEffect ability, LivingEntity entity) {
    MobEffectProvider provider = ability.provider;
    MobEffectInstance instance = entity.getEffect(provider.mobEffect());
    if (instance != null
            && instance.getAmplifier() == provider.getAmplifier()
            && instance.isVisible() == provider.spawnParticles().get()
            && instance.showIcon() == provider.showIcon().get()
            && instance.endsWithin(provider.getDuration(1) * 20 + 19)
    ) {
        entity.removeEffect(provider.mobEffect());
    }
}

public void onEquip(IToolStackView tool, ModifierEntry modifier, EquipmentChangeContext context) {
  if (condition.matches(tool, modifier)) {
    AttributeInstance instance = context.getEntity().getAttribute(attribute);
    if (instance != null) {
      AttributeModifier attributeModifier = createModifier(tool, modifier, context.getChangedSlot());
      if (attributeModifier != null) {
        // for safety, remove it already there
        instance.removeModifier(attributeModifier.getId());
        instance.addTransientModifier(attributeModifier);
      }
    }
  }
}

public void onAttacked(IToolStackView tool, ModifierEntry modifier, EquipmentContext context, EquipmentSlot slotType, DamageSource source, float amount, boolean isDirectDamage) {
  // this works like vanilla, damage is capped due to the hurt immunity mechanics, so if multiple pieces apply thorns between us and vanilla, damage is capped at 4
  if (isDirectDamage && tool.hasTag(TinkerTags.Items.ARMOR) && source.getEntity() instanceof LivingEntity attacker) {
    // 25% chance of working, doubled chance on shields
    float chance = 0.25f;
    if (CounterModule.isBlocking(tool, slotType, context.getEntity())) {
      chance *= 2;
    }
    if (RANDOM.nextFloat() < chance) {
      applyEffect(tool, context.getEntity(), attacker, modifier.getLevel(), slotType);
    }
  }
}

public float beforeMeleeHit(IToolStackView tool, ModifierEntry modifier, ToolAttackContext context, float damage, float baseKnockback, float knockback) {
  if (condition.matches(tool, modifier)) {
    LivingEntity target = context.getLivingTarget();
    if (target != null) {
      AttributeInstance instance = target.getAttribute(attribute);
      if (instance != null) {
        // ensure we don't already have the modifier from someone misusing melee hooks or simultaneous attacks
        instance.removeModifier(uuid);
        instance.addTransientModifier(new AttributeModifier(uuid, unique, amount.compute(modifier.getEffectiveLevel()), operation));
      }
    }
  }
  return knockback;
}

static void onPotionStart(MobEffectEvent.Added event) {
  MobEffectInstance newEffect = event.getEffectInstance();
  if (!newEffect.isInfiniteDuration() && !newEffect.getCurativeItems().isEmpty()) {
    // use two different stats based on whether the effect is beneficial
    boolean beneficial = newEffect.getEffect().isBeneficial();
    LivingEntity entity = event.getEntity();
    double multiplier = entity.getAttributeValue(beneficial ? TinkerAttributes.GOOD_EFFECT_DURATION.get() : TinkerAttributes.BAD_EFFECT_DURATION.get())
                      + ArmorStatModule.getStat(entity, beneficial ? TinkerDataKeys.GOOD_EFFECT_DURATION : TinkerDataKeys.BAD_EFFECT_DURATION);
    if (multiplier != 1) {
      // adjust duration as requested
      newEffect.duration = Math.max(1, (int)(newEffect.getDuration() * multiplier));
    }
  }
}

public void onUnequip(IToolStackView tool, ModifierEntry modifier, EquipmentChangeContext context) {
  // remove boost when boots are removed
  LivingEntity livingEntity = context.getEntity();
  if (context.getChangedSlot() == EquipmentSlot.FEET) {
    IToolStackView newTool = context.getReplacementTool();
    // damaging the tool will trigger this hook, so ensure the new tool has the same level
    if (newTool == null || newTool.isBroken() || newTool.getModifier(modifier.getId()).getEffectiveLevel() != modifier.getEffectiveLevel()) {
      AttributeInstance attribute = livingEntity.getAttribute(this.attribute);
      if (attribute != null && attribute.getModifier(uuid) != null) {
        attribute.removeModifier(uuid);
      }
    }
  }
}

public void addTransientSlotModifiers(Multimap<String, AttributeModifier> modifiers) {

  for (Map.Entry<String, Collection<AttributeModifier>> entry : modifiers.asMap().entrySet()) {
    String id = entry.getKey();

    for (AttributeModifier attributeModifier : entry.getValue()) {
      ICurioStacksHandler stacksHandler = this.curioInventory.asMap().get(id);

      if (stacksHandler != null) {
        stacksHandler.addTransientModifier(attributeModifier);
      }
    }
  }
}

public void removeSlotModifiers(Multimap<String, AttributeModifier> modifiers) {

  for (Map.Entry<String, Collection<AttributeModifier>> entry : modifiers.asMap().entrySet()) {
    String id = entry.getKey();

    for (AttributeModifier attributeModifier : entry.getValue()) {
      ICurioStacksHandler stacksHandler = this.curioInventory.asMap().get(id);

      if (stacksHandler != null) {
        stacksHandler.removeModifier(attributeModifier.id());
      }
    }
  }
}

public void applyEffectTick(LivingEntity target, int level) {
  // attribute to player kill
  LivingEntity lastAttacker = target.getLastHurtMob();
  DamageSource source = TinkerDamageTypes.source(target.level().registryAccess(), TinkerDamageTypes.BLEEDING, lastAttacker);

  // perform damage
  int hurtResistantTime = target.invulnerableTime;
  ToolAttackUtil.attackEntitySecondary(source, 1, target, target, true);
  target.invulnerableTime = hurtResistantTime;

  // damage particles
  if (target.level() instanceof ServerLevel serverLevel) {
    serverLevel.sendParticles(ParticleTypes.DAMAGE_INDICATOR, target.getX(), target.getY(0.5), target.getZ(), 1, 0.1, 0, 0.1, 0.2);
  }
}

private static void applyEffect(IToolStackView tool, @Nullable LivingEntity holder, LivingEntity target, int level, @Nullable EquipmentSlot slot) {
  // determine looting
  int looting = 0;
  DamageSource source = CombatHelper.damageSource(TinkerDamageTypes.BLEEDING, target);
  if (holder != null) {
    LootingContext context = new LootingContext(holder, target, source, slot);
    // fetch slot looting for the melee hook
    looting = LootingModifierHook.getLooting(tool, context, looting);
    // fetch armor looting
    looting = ArmorLootingModifierHook.getLooting(null, context, looting);
  }

  // 81 ticks will do about 4 damage
  applyEffect(target, level, looting, holder);
}

public boolean onProjectileHitEntity(ModifierNBT modifiers, ModDataNBT persistentData, ModifierEntry modifier, Projectile projectile, EntityHitResult hit, @Nullable LivingEntity attacker, @Nullable LivingEntity target) {
  if (target != null && (!(projectile instanceof AbstractArrow arrow) || arrow.isCritArrow()) && target.isAlive()) {
    Entity owner = projectile.getOwner();
    if (owner != null) {
      target.setLastHurtMob(owner);
    }
    // can only use looting hook if we have an attacker living
    if (attacker != null) {
      applyEffect(new DummyToolStack(Items.AIR, modifiers, persistentData), attacker, target, modifier.getLevel(), null);
    } else {
      applyEffect(target, modifier.getLevel(), 0, projectile.getEffectSource());
    }
  }
  return false;
}

private void tick(LivingEntity entity) {
    AttributeInstance attributeInstance = entity.getAttribute(attribute);
    if (attributeInstance == null) {
        return;
    }
    if (shouldApply(entity)) {
        double amount = getAmount(entity);
        AttributeModifier modifier = attributeInstance.getModifier(id);
        if (modifier == null || modifier.amount() != amount) {
            attributeInstance.addOrUpdateTransientModifier(new AttributeModifier(id, amount, operation));
        }
    } else if (attributeInstance.hasModifier(id)) {
        attributeInstance.removeModifier(id);
    }
}

protected float getForce(IToolStackView tool, ModifierEntry entry, LivingEntity living, int timeLeft, boolean applyKnockback) {
  float charge = getCharge(tool, entry, timeLeft);
  // if using knockback, boost projectile damage by 0.5 per level, that is a 25% boost, same as power
  float knockback = 0;
  if (applyKnockback) {
    knockback = tool.getModifierLevel(TinkerModifiers.knockback.getId()) / 2f;
  }
  float force = charge
                * (ConditionalStatModifierHook.getModifiedStat(tool, living, ToolStats.PROJECTILE_DAMAGE) + knockback) / 2f
                * ConditionalStatModifierHook.getModifiedStat(tool, living, ToolStats.VELOCITY);
  // knockback also means we should apply padded, divide per level
  if (applyKnockback) {
    force /= Math.pow(2, tool.getModifierLevel(TinkerModifiers.padded.getId()));
  }
  return force;
}

public void applyEffect(@Nullable LivingEntity target, float scaledLevel, @Nullable Entity cause) {
  if (target == null || !this.target.matches(target)) {
    return;
  }
  int level = Math.round(this.level.computeValue(scaledLevel)) - 1;
  if (level < 0) {
    return;
  }
  float duration = this.time.computeValue(scaledLevel);
  if (duration > 0) {
    MobEffectInstance instance = new MobEffectInstance(effect, (int)duration, level);
    if (curativeItems != null) {
      instance.setCurativeItems(curativeItems.stream().map(ItemStack::new).collect(Collectors.toList()));
    }
    target.addEffect(new MobEffectInstance(effect, (int)duration, level), cause);
  }
}

public void removeModifier(Identifier id) {
  AttributeModifier modifier = this.modifiers.remove(id);

  if (modifier != null) {
    this.persistentModifiers.remove(modifier.id(), modifier);
    Collection<AttributeModifier> modifiers = this.getModifiersByOperation(modifier.operation());
    List<AttributeModifier> ops = new ArrayList<>(modifiers);

    for (AttributeModifier op : ops) {

      if (op.id().equals(id)) {
        modifiers.remove(op);
      }
    }
    this.flagUpdate();
  }
}

public InteractionResult beforeEntityUse(IToolStackView tool, ModifierEntry modifier, Player player, Entity target, InteractionHand hand, InteractionSource source) {
  if (canAttack(tool, player, hand)) {
    if (ToolAttackUtil.isAttackable(player, target)) {
      // if melee is disabled, squeak harmlessly
      if (EntityInteractionModifierHook.meleeDisabled(tool)) {
        player.playSound(Sounds.TOY_SQUEAK.getSound());
      }
      else if (!player.level().isClientSide()) {
        ToolAttackUtil.performAttack(tool, ToolAttackContext.attacker(player).target(target).offhandCooldown().slot(source.getSlot(hand), hand).toolAttributes(tool).build());
      }
    }
    applyCooldown(tool, player, source);
    // we handle swinging the arm, return consume to prevent resetting cooldown
    OffhandCooldownTracker.swingHand(player, InteractionHand.OFF_HAND, false);
    return InteractionResult.CONSUME;
  }
  return InteractionResult.PASS;
}

public void onUnequip(IToolStackView tool, ModifierEntry modifier, EquipmentChangeContext context) {
  if (context.getChangedSlot().isArmor()) {
    IToolStackView newTool = context.getReplacementTool();
    // when replacing with a helmet that lacks this modifier, remove bonus
    if (newTool == null || newTool.getModifierLevel(modifier.getId()) == 0) {
      TinkerDataCapability.Holder data = context.getDataHolder();
      if (data != null) {
        data.remove(dataKey);
      }
      LivingEntity living = context.getEntity();
      AttributeInstance instance = living.getAttribute(attribute);
      if (instance != null) {
        instance.removeModifier(uuid);
        checkHealth(living, instance);
      }
    }
  }
}

public float modifyDamageTaken(IToolStackView tool, ModifierEntry modifier, EquipmentContext context, EquipmentSlot slotType, DamageSource source, float amount, boolean isDirectDamage) {
  if (!source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
    int level = SlotInChargeModule.getLevel(context.getTinkerData(), SLOT_KEY, slotType);
    if (level > 0) {
      // step 1: reduce damage based on the current effect level
      MobEffect effect = TinkerModifiers.momentumEffect.get(ToolType.ARMOR);
      LivingEntity entity = context.getEntity();
      amount -= TinkerEffect.getLevel(entity, effect);

      // step 2: apply momentum based on damage taken
      int reduction = (int)(percent.compute(level) * amount);
      if (reduction > 0) {
        entity.addEffect(new MobEffectInstance(effect, duration.compute(level), reduction - 1, false, false, true));
      }
    }
  }
  return amount;
}

public void wornTick(EquipmentAttributeModifier ability, EquipmentSlotAccess slotAccess, LivingEntity entity, boolean isOnCooldown, boolean isDisabled) {
    AttributeInstance attributeInstance = entity.getAttribute(ability.attribute());
    if (attributeInstance == null) {
        return;
    }
    AttributeModifier existingModifier = attributeInstance.getModifier(ability.id());
    if (!ability.ignoreCooldown() && isOnCooldown) {
        if (!isDisabled && ability.isNonCosmetic()) {
            onUnequip(ability, entity);
        }
    } else if (!isDisabled) {
        if (existingModifier == null || !Mth.equal(ability.amount().get(), existingModifier.amount())) {
            attributeInstance.removeModifier(ability.id());
            attributeInstance.addPermanentModifier(ability.createModifier());
            ability.onAttributeUpdated(entity);
        }
    }
}

private static boolean accumulateSlotModifier(ServerPlayer player, String slot, int amount) {
  ICuriosItemHandler curiosInventory = CuriosApi.getCuriosInventoryOrNull(player);

  if (curiosInventory != null) {
    return curiosInventory.getStacksHandler(slot).map(stacks -> {
      double target = amount;
      AttributeModifier modifier = stacks.getModifiers().get(COMMAND);

      if (modifier != null) {
        target += modifier.amount();
        stacks.removeModifier(COMMAND);
      }
      stacks.addPermanentModifier(
          new AttributeModifier(COMMAND, target, AttributeModifier.Operation.ADD_VALUE));
      return true;
    }).orElse(false);
  }
  return false;
}

public void onAttacked(IToolStackView tool, ModifierEntry modifier, EquipmentContext context, EquipmentSlot slotType, DamageSource source, float amount, boolean isDirectDamage) {
  // this works like vanilla, effect is capped due to not being able to receive multiple instances
  if (isDirectDamage && tool.hasTag(TinkerTags.Items.ARMOR) && source.getEntity() instanceof LivingEntity attacker) {
    // 10% chance to poison yourself
    LivingEntity defender = context.getEntity();
    // 50% chance of working, doubled bonus on shields. Makes it twice lacerating
    float chance = 0.5f;
    if (CounterModule.isBlocking(tool, slotType, context.getEntity())) {
      chance *= 2;
    }
    if (chance >= 1 || RANDOM.nextFloat() < chance) {
      attacker.addEffect(makeDecayEffect(modifier.getLevel()), defender);
    }

    // 10% chance of poisoning you too, independently generated time
    if (RANDOM.nextInt(10) == 0) {
      defender.addEffect(makeDecayEffect(modifier.getLevel()));
    }
  }
}

public float modifyDamageTaken(IToolStackView tool, ModifierEntry modifier, EquipmentContext context, EquipmentSlot slotType, DamageSource source, float amount, boolean isDirectDamage) {
  LivingEntity entity = context.getEntity();
  // entity must not have enderference, and conditions must match
  if (!entity.hasEffect(TinkerEffects.enderference.get()) && this.defender.matches(entity) && damageSource.matches(source)) {
    // chance of applying is boosted when blocking with a shield
    float level = CounterModule.getLevel(tool, modifier, slotType, entity);
    if (entity.getRandom().nextFloat() < chance.compute(level) && TeleportHelper.randomNearbyTeleport(context.getEntity(), (e, x, y, z) -> new EnderdodgingTeleportEvent(e, x, y, z, modifier))) {
      // if we successfully teleport, apply the cooldown
      int cooldown = this.cooldown.compute(level);
      if (cooldown > 0) {
        entity.addEffect(new MobEffectInstance(TinkerEffects.enderference.get(), cooldown));
      }
      // damage tool based on how much damage we blocked
      ToolDamageUtil.damageAnimated(tool, (int)amount, entity, slotType, modifier.getId());
      // prevent said damage
      return 0;
    }
  }
  return amount;
}

default void onAttacked(IToolStackView tool, ModifierEntry modifier, EquipmentContext context, EquipmentSlot slotType, DamageSource source, float damageDealt, boolean isDirectDamage) {
  // must be direct damage, and must be armor (held or
  Entity attacker = source.getEntity();
  LivingEntity defender = context.getEntity();
  if (isDirectDamage && attacker != null && canApply(attacker) && TinkerPredicate.matches(attacker(), attacker) && defender().matches(defender) && condition().matches(tool, modifier)) {
    // level is doubled for shields that are actively blocking
    float level = getLevel(tool, modifier, slotType, defender);
    if (checkChance(level)) {
      float value = LevelingValue.applyRandom(level, constant(), random());
      if (value > 0) {
        applyEffect(tool, modifier, value, context, attacker, source, damageDealt);

        // damage the armor if requested
        int durabilityUsage = durabilityUsage();
        if (durabilityUsage > 0) {
          ToolDamageUtil.damageAnimated(tool, durabilityUsage, defender, slotType, modifier.getId());
        }
      }
    }
  }
}

private static int setSlotsForPlayer(CommandSourceStack source, ServerPlayer playerMP,
                                     String slot, int amount) {
  ICuriosItemHandler curiosInventory = CuriosApi.getCuriosInventoryOrNull(playerMP);

  if (curiosInventory != null) {
    curiosInventory.getStacksHandler(slot).ifPresent(stacks -> {
      int currentSize = stacks.getSlots();
      double diff = amount - currentSize;
      AttributeModifier modifier = stacks.getModifiers().get(COMMAND);

      if (modifier != null) {
        diff += modifier.amount();
        stacks.removeModifier(COMMAND);
      }
      stacks.addPermanentModifier(
          new AttributeModifier(COMMAND, diff, AttributeModifier.Operation.ADD_VALUE));
      source.sendSuccess(() -> Component.translatable("commands.curios.set.success", slot,
          CuriosSlotTypes.getSlotType(slot), playerMP.getDisplayName()), true);
    });
  }
  return Command.SINGLE_SUCCESS;
}

public void updateActiveState(int index) {
  NonNullList<Boolean> activeStates = this.getActiveStates();
  LivingEntity livingEntity = this.curioInventory.getOwner();

  if (livingEntity != null && !livingEntity.level().isClientSide()) {

    if (activeStates.size() <= index) {
      return;
    }
    boolean current = activeStates.get(index);
    boolean previous = this.stackHandler.getPreviousActive().get(index);

    if (current == previous) {
      return;
    }

    if (!previous) {
      activateSlot(index);
    } else {
      deactivateSlot(index);
    }
  }
}

public float apply(FluidStack fluid, EffectLevel level, FluidEffectContext.Block context, FluidAction action) {
  if (context.isOffsetReplaceable()) {
    float scale = level.value();
    if (action.execute()) {
      AreaEffectCloud cloud = makeCloud(context);
      boolean hasEffects = false;
      for (FluidMobEffect effect : effects) {
        int time = (int)(effect.time() * scale);
        if (time > 10) {
          cloud.addEffect(effect.effectWithTime(time));
          hasEffects = true;
        }
      }
      if (hasEffects) {
        context.getLevel().addFreshEntity(cloud);
      } else {
        cloud.discard();
        return 0;
      }
    }
    return scale;
  }
  return 0;
}

private static boolean drinkMilk(LivingEntity living, int flat, int eachLevel, FluidAction action) {
  // strong bones has to be the helmet as we use it for curing
  // TODO 1.20: can use the new cure effects to make this work in any slot
  ItemStack helmet = living.getItemBySlot(EquipmentSlot.HEAD);
  boolean didSomething = false;
  int level = ModifierUtil.getModifierLevel(helmet, TinkerModifiers.strongBones.getId());
  if (level > 0) {
    MobEffectInstance effect = new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, flat + eachLevel * level);
    effect.getCurativeItems().clear();
    effect.getCurativeItems().add(new ItemStack(helmet.getItem()));
    // on simulate, don't apply the effect, just ask if we can apply
    didSomething = action.execute() ? living.addEffect(effect) : living.canBeAffected(effect);
    // quick exit on simulate: no more information needed
    if (didSomething && action.simulate()) {
      return true;
    }
  }
  level = ArmorLevelModule.getLevel(living, CALCIFIABLE);
  if (level > 0) {
    MobEffectInstance effect = new MobEffectInstance(TinkerModifiers.calcifiedEffect.get(), flat + eachLevel * level, 0);
    didSomething |= action.execute() ? living.addEffect(effect) : living.canBeAffected(effect);
  }
  return didSomething;
}

public void applySyncTag(CompoundTag tag) {
  LivingEntity livingEntity = this.curioInventory.getOwner();
  try (
      ProblemReporter.ScopedCollector problemreporter$scopedcollector =
          new ProblemReporter.ScopedCollector(livingEntity.problemPath(), CuriosConstants.LOG)) {
    this.deserialize(
        TagValueInput.create(problemreporter$scopedcollector, livingEntity.registryAccess(),
            tag));
    this.modifiers.clear();
    this.persistentModifiers.clear();
    this.modifiersByOperation.clear();

    if (tag.contains("Modifiers")) {

      for (AttributeModifier modifier : tag.read("Modifiers",
              AttributeModifier.CODEC.listOf())
          .orElse(List.of())) {
        this.addTransientModifier(modifier);
      }
    }
  }
  this.flagUpdate();
  this.update();
}

public float apply(FluidStack fluid, EffectLevel level, FluidEffectContext.Entity context, FluidAction action) {
  Entity target = context.getTarget();
  if (!target.canFreeze()) {
    return 0;
  }
  if (this.action == TimeAction.ADD) {
    float value = level.value();
    if (action.execute()) {
      // ensure we have enough time to freeze after applying this
      target.setTicksFrozen(Math.max(target.getTicksRequiredToFreeze(), target.getTicksFrozen()) + Math.round(time * value));
      target.clearFire();
    }
    return value;
  } else {
    int freezeTicks = target.getTicksRequiredToFreeze();
    int frozen = target.getTicksFrozen();
    float existing = frozen < freezeTicks ? 0 : (frozen - freezeTicks) / (float) time;
    float effective = level.effective(existing);
    if (action.execute()) {
      target.setTicksFrozen(freezeTicks + Math.round(time * 2 * effective));
      target.setRemainingFireTicks(0);
    }
    return effective - existing;
  }
}

static void onCritical(CriticalHitEvent event) {
  if (event.getResult() != Result.DENY) {
    // force critical if not already critical and in the air
    LivingEntity living = event.getEntity();

    // critical boost is defined where the base value is 150%, setting smaller amounts can reduce the critical damage
    // this event however is defined in terms of adding or subtracting critical, so just treat it as additive
    Attribute attribute = TinkerAttributes.CRITICAL_DAMAGE.get();
    double criticalBoost = living.getAttributeValue(attribute) - attribute.getDefaultValue() + ArmorStatModule.getStat(living, TinkerDataKeys.CRITICAL_DAMAGE);
    if (criticalBoost > 0) {
      // make it critical if we meet our simpler conditions, note this does not boost attack damage
      boolean isCritical = event.isVanillaCritical() || event.getResult() == Result.ALLOW;
      if (!isCritical && TinkerPredicate.AIRBORNE.matches(living)) {
        isCritical = true;
        event.setResult(Result.ALLOW);
      }

      // if we either were or became critical, time to boost
      if (isCritical) {
        // adds +5% critical hit per level
        event.setDamageModifier((float) (event.getDamageModifier() + criticalBoost));
      }
    }
  }
}

public float modifyDamageTaken(IToolStackView tool, ModifierEntry modifier, EquipmentContext context, EquipmentSlot slotType, DamageSource source, float amount, boolean isDirectDamage) {
  // works like vanilla, if multiple pieces have it we get the highest effect
  LivingEntity defender = context.getEntity();
  if (condition.matches(tool, modifier) && this.defender.matches(defender) && TinkerPredicate.matches(this.attacker, source.getEntity())) {
    // no shield doubling as shields prevent the damage, better than any healing
    float level = modifier.getEffectiveLevel();
    int effectLevel = this.effectLevel.compute(level);
    if (effectLevel > 0 && defender.getRandom().nextFloat() < this.chance.compute(level)) {
      // heals slowly over time
      int heal = (int)(this.percent.compute(level) * amount);
      if (heal > 0) {
        // regen restores 1 health every 50 ticks at level 1, restores faster at higher levels
        defender.addEffect(new MobEffectInstance(MobEffects.REGENERATION, heal * (50 >> (effectLevel - 1))));
        defender.level().playSound(null, defender.getX(), defender.getY(), defender.getZ(), Sounds.NECROTIC_HEAL.getSound(), SoundSource.PLAYERS, 1.0f, 1.0f);

        // extra damage for running based on level
        int durabilityUsage = this.durabilityUsage.compute(level);
        if (durabilityUsage > 0) {
          ToolDamageUtil.damageAnimated(tool, durabilityUsage, defender, slotType, modifier.getId());
        }
      }
    }
  }
  return amount;
}

public void setSize(int size) {
  TransferPreconditions.checkNonNegative(size);
  int currentSize = this.size();

  if (currentSize != size) {
    NonNullList<ItemStack> resizedList = NonNullList.withSize(size, this.emptyStack);
    NonNullList<ItemStack> resizedPrevious = NonNullList.withSize(size, this.emptyStack);
    NonNullList<Boolean> resizedRenders = NonNullList.withSize(size, true);
    NonNullList<Boolean> resizedActives = NonNullList.withSize(size, true);
    NonNullList<Boolean> resizedPrevActives = NonNullList.withSize(size, true);

    for (int i = 0; i < size && i < currentSize; i++) {
      resizedList.set(i, ItemUtil.getStack(this, i));
      resizedPrevious.set(i, this.previousStacks.get(i));
      resizedRenders.set(i, this.renderable.get(i));
      resizedActives.set(i, this.active.get(i));
      resizedPrevActives.set(i, this.previousActive.get(i));
    }
    this.setStacks(resizedList);
    this.previousStacks = resizedPrevious;
    this.renderable = resizedRenders;
    this.active = resizedActives;
    this.previousActive = resizedPrevActives;
  }
}

default void onAttacked(IToolStackView tool, ModifierEntry modifier, EquipmentContext context, EquipmentSlot slotType, DamageSource source, float amount, boolean isDirectDamage) {
  if (directDamage().test(isDirectDamage) && condition().matches(tool, modifier) && damageSource().matches(source)) {
    LivingEntity defender = context.getEntity();
    Entity sourceEntity = source.getEntity();
    float scaledLevel = CounterModule.getLevel(tool, modifier, slotType, defender);
    if (sourceEntity != defender && checkChance(scaledLevel)) {
      // target self if requested
      boolean applied = false;
      if (targetSelf()) {
        // repurpose holder to refer to attacker, as target is now self. makes the JSON a bit weird, but is more flexible
        if (TinkerPredicate.matches(holder(), sourceEntity)) {
          effect().applyEffect(defender, modifier, null);
          applied = true;
        }
      } else if (holder().matches(defender) && sourceEntity instanceof LivingEntity attacker) {
        effect().applyEffect(attacker, scaledLevel, defender);
        applied = true;
      }
      // consume durability
      int durabilityUsage = this.durabilityUsage();
      if (applied && durabilityUsage > 0) {
        ToolDamageUtil.damageAnimated(tool, durabilityUsage, defender, slotType, modifier.getId());
      }
    }
  }
}

public void livingEquipmentChange(final LivingEquipmentChangeEvent evt) {
  CuriosApi.getCuriosInventory(evt.getEntity()).ifPresent(inv -> {
    ItemStack from = evt.getFrom();
    ItemStack to = evt.getTo();
    EquipmentSlot slot = evt.getSlot();

    if (!from.isEmpty()) {
      Multimap<String, AttributeModifier> slots = HashMultimap.create();
      from.forEachModifier(slot, (att, modifier) -> {
        if (att.value() instanceof SlotAttribute wrapper) {
          slots.putAll(wrapper.id(), Collections.singleton(modifier));
        }
      });
      inv.removeSlotModifiers(slots);
    }

    if (!to.isEmpty()) {
      Multimap<String, AttributeModifier> slots = HashMultimap.create();
      to.forEachModifier(slot, (att, modifier) -> {
        if (att.value() instanceof SlotAttribute wrapper) {
          slots.putAll(wrapper.id(), Collections.singleton(modifier));
        }
      });
      inv.addTransientSlotModifiers(slots);
    }
  });
}

public void onWalk(IToolStackView tool, ModifierEntry modifier, LivingEntity living, BlockPos prevPos, BlockPos newPos) {
  // no point trying if not on the ground
  Level level = living.level();
  if (tool.isBroken() || !living.onGround() || level.isClientSide) {
    return;
  }
  // must have speed
  AttributeInstance attribute = living.getAttribute(this.attribute);
  if (attribute == null) {
    return;
  }
  // start by removing the attribute, we are likely going to give it a new number
  if (attribute.getModifier(uuid) != null) {
    attribute.removeModifier(uuid);
  }

  // not above air
  Vec3 vecPos = living.position();
  BlockPos pos = BlockPos.containing(vecPos.x, vecPos.y + 0.5f, vecPos.z);
  int light = getLight(level, pos);
  if (light > minLight) {
    int scaledLight = light - minLight;
    attribute.addTransientModifier(new AttributeModifier(uuid, unique, scaledLight * amount * modifier.getEffectiveLevel(), operation));

    // damage boots
    if (level.random.nextFloat() < (damageChance * scaledLight)) {
      ToolDamageUtil.damageAnimated(tool, 1, living, EquipmentSlot.FEET, modifier.getId());
    }
  }
}

public Optional<SlotResult> findCurio(String identifier, int index, boolean includeInactive) {
  Map<String, ICurioStacksHandler> curios = this.getCurios();
  ICurioStacksHandler stacksHandler = curios.get(identifier);

  if (stacksHandler != null) {
    IDynamicStackHandler stackHandler = stacksHandler.getStacks();
    NonNullList<Boolean> activeStates = stacksHandler.getActiveStates();

    if (index < stackHandler.getSlots()) {

      if (!includeInactive && activeStates.size() > index && !activeStates.get(index)) {
        return Optional.empty();
      }
      ItemStack stack = stackHandler.getStackInSlot(index);

      if (!stack.isEmpty()) {
        NonNullList<Boolean> renderStates = stacksHandler.getRenders();
        return Optional.of(
            new SlotResult(
                new SlotContext(
                    identifier,
                    this.livingEntity,
                    index,
                    false,
                    renderStates.size() > index && renderStates.get(index)),
                stack));
      }
    }
  }
  return Optional.empty();
}

public static InteractionHand updateFishingRod(Projectile projectile, int damage, boolean applyCooldown, ModifierId cause) {
  if (projectile.getType() == TinkerTools.fishingHook.get() && projectile.getOwner() instanceof LivingEntity living) {
    ItemStack stack = living.getMainHandItem();
    InteractionHand hand = InteractionHand.MAIN_HAND;
    // must be able to cast
    if (!stack.canPerformAction(ToolActions.FISHING_ROD_CAST)) {
      stack = living.getOffhandItem();
      if (!stack.canPerformAction(ToolActions.FISHING_ROD_CAST)) {
        return null;
      }
      hand = InteractionHand.OFF_HAND;
    }
    // must be modifiable
    if (stack.is(TinkerTags.Items.MODIFIABLE)) {
      // skip making the tool stack object if not needed, might be asking just for the hand.
      if (applyCooldown || damage > 0) {
        IToolStackView tool = ToolStack.from(stack);
        // trigger cooldown on the item
        if (applyCooldown && living instanceof Player player) {
          addCooldown(tool, player);
        }
        // damage the rod
        if (damage > 0) {
          // if we are applying cooldown, means this is a full retraction from block so this was primary damage
          // no cooldown is done on secondary effects like entity hitting
          ToolDamageUtil.damageAnimated(tool, damage, living, hand, cause);
        }
      }
      return hand;
    }
  }
  return null;
}

private void loseStacks(IDynamicStackHandler stackHandler, String identifier, int amount) {
  List<ItemStack> drops = new ArrayList<>();

  for (int i = Math.max(0, stackHandler.getSlots() - amount);
       i >= 0 && i < stackHandler.getSlots();
       i++) {
    ItemStack stack = stackHandler.getStackInSlot(i);
    drops.add(stackHandler.getStackInSlot(i));
    LivingEntity entity = this.curioInventory.getOwner();
    SlotContext slotContext = new SlotContext(identifier, entity, i, false, this.visible);

    if (!stack.isEmpty()) {
      ICurioItem
          .forEachModifier(stack, slotContext,
              (attributeHolder, attributeModifier) -> {
                if (attributeHolder.value() instanceof SlotAttribute slotAttribute
                    && slotAttribute.id().equals(identifier)) {
                  this.removeModifier(attributeModifier.id());
                } else {
                  AttributeInstance instance =
                      entity.getAttributes().getInstance(attributeHolder);

                  if (instance != null) {
                    instance.removeModifier(attributeModifier);
                  }
                }
              });
      CuriosApi.getCurio(stack).ifPresent(curio -> curio.onUnequip(slotContext, ItemStack.EMPTY));
    }
    stackHandler.setStackInSlot(i, ItemStack.EMPTY);
  }
  drops.forEach(stack -> this.curioInventory.getDroppingStacks().add(stack));
}

public void deserialize(@Nonnull ValueInput input) {
  this.baseSize = input.getIntOr("BaseSize", this.getBaseSize());
  this.resize(input.getIntOr("Size", this.getSlots()));
  input.child("Stacks").ifPresent(stacks -> this.getStacks().deserialize(stacks));
  input.child("Cosmetics")
      .ifPresent(cosmetics -> this.getCosmeticStacks().deserialize(cosmetics));
  List<Boolean> renders = input.read("Renders", Codec.BOOL.listOf()).orElse(List.of());
  List<Boolean> currentRenders = this.getRenders();

  for (int i = 0; i < renders.size(); i++) {
    currentRenders.set(i, renders.get(i));
  }
  List<Boolean> activeStates = input.read("ActiveStates", Codec.BOOL.listOf()).orElse(List.of());
  List<Boolean> currentActiveStates = this.getActiveStates();

  for (int i = 0; i < activeStates.size(); i++) {
    currentActiveStates.set(i, activeStates.get(i));
  }
  this.cosmetic = input.getBooleanOr("Cosmetic", this.hasCosmetic());
  this.visible = input.getBooleanOr("Visible", this.isVisible());
  this.canToggleRender = input.getBooleanOr("ToggleRender", this.canToggleRendering());
  this.dropRule = input.read("DropRule", DropRule.CODEC).orElse(this.getDropRule());
  List<AttributeModifier> permanentModifiers =
      input.read("PermanentModifiers", AttributeModifier.CODEC.listOf()).orElse(List.of());

  for (AttributeModifier modifier : permanentModifiers) {
    this.addPermanentModifier(modifier);
  }
  List<AttributeModifier> modifiers =
      input.read("Modifiers", AttributeModifier.CODEC.listOf()).orElse(List.of());

  for (AttributeModifier modifier : modifiers) {
    this.addTransientModifier(modifier);
  }
}

public InteractionResult onToolUse(IToolStackView tool, ModifierEntry modifier, Player player, InteractionHand hand, InteractionSource source) {
  if (tool.getHook(ToolHooks.INTERACTION).canInteract(tool, modifier.getId(), source)) {
    if (!player.isCrouching()) {
      InventoryModifierHook inventory = modifier.getHook(ToolInventoryCapability.HOOK);
      int selected = tool.getPersistentData().getInt(SELECTED_SLOT);
      ItemStack ammo = inventory.getStack(tool, modifier, selected);
      // if we have nothing, fallback to the slot toggle
      if (!ammo.isEmpty()) {
        if (!player.getCooldowns().isOnCooldown(ammo.getItem())) {
          // to use the item, we need it in the hand, but something else might be there, so temporarily swap
          ItemStack held = player.getItemInHand(hand);
          player.setItemInHand(hand, ammo);
          // use the item
          InteractionResultHolder<ItemStack> result = ammo.use(player.level(), player, hand);
          // restore original hand item
          player.setItemInHand(hand, held);
          // ensure the use action did not start us using items
          if (player.isUsingItem()) {
            player.stopUsingItem();
          }
          // handle result
          inventory.setStack(tool, modifier, selected, result.getObject());
          return result.getResult();
        } else {
          // toggle if we just were unable to use the item
          return InteractionResult.PASS;
        }
        // don't toggle if set to disable
      } else if (selected == inventory.getSlots(tool, modifier)) {
        return InteractionResult.PASS;
      }
    }
    return selectNext(tool, modifier, player, SELECTED_SLOT) ? InteractionResult.SUCCESS : InteractionResult.PASS;
  }
  return InteractionResult.PASS;
}

public RecipeResult<LazyToolStack> getResult(ITinkerableContainer inv, ModifierEntry entry) {
  ToolStack original = inv.getTinkerable();

  // salvage
  ToolStack tool = original.copy();
  ModifierId modifierId = entry.getId();
  ItemStack originalStack = inv.getTinkerableStack();
  ModifierSalvage salvage = ModifierRecipeLookup.getSalvage(originalStack, tool, modifierId, entry.getLevel());

  // restore the slots
  if (salvage != null) {
    salvage.updateTool(tool);
  }

  // first remove hook, primarily for removing raw NBT which is highly discouraged using
  int newLevel = tool.getModifierLevel(modifierId) - 1;
  Modifier modifier = entry.getModifier();
  if (newLevel <= 0) {
    modifier.getHook(ModifierHooks.RAW_DATA).removeRawData(tool, modifier, tool.getRestrictedNBT());
  }

  // remove the actual modifier
  tool.removeModifier(modifierId, 1);

  // ensure the tool is still valid
  Component error = tool.tryValidate();
  if (error != null) {
    return RecipeResult.failure(error);
  }
  error = ModifierRemovalHook.onRemoved(original, tool);
  if (error != null) {
    return RecipeResult.failure(error);
  }
  // successfully removed
  return LazyToolStack.successCopy(tool, originalStack);
}

public ItemStack tryEquip(LivingEntity entity, ItemStack stack, boolean allowSwapping) {
    Optional<ICuriosItemHandler> optional = CuriosApi.getCuriosInventory(entity);
    if (optional.isEmpty()) {
        return stack;
    }

    Map<String, ICurioStacksHandler> curios = optional.get().getCurios();

    for (Map.Entry<String, ICurioStacksHandler> entry : curios.entrySet()) {
        IDynamicStackHandler stackHandler = entry.getValue().getStacks();
        NonNullList<Boolean> activeStates = entry.getValue().getActiveStates();

        for (int slot = 0; slot < stackHandler.getSlots(); slot++) {
            boolean active = activeStates.size() > slot && activeStates.get(slot);

            if (!active) {
                continue;
            }

            if (stackHandler.isItemValid(slot, stack)) {
                ItemStack existingStack = stackHandler.getStackInSlot(slot);

                if (existingStack.isEmpty()) {
                    stackHandler.setStackInSlot(slot, stack.copy());
                    return ItemStack.EMPTY;
                } else if (allowSwapping) {
                    if (stackHandler.extractItem(slot, existingStack.getMaxStackSize(), true).getCount() == existingStack.getCount()) {
                        ItemStack present = stackHandler.getStackInSlot(slot);
                        stackHandler.setStackInSlot(slot, stack.copy());
                        return present.copy();
                    }
                }
            }
        }
    }
    return stack;
}

static Multimap<Attribute,AttributeModifier> getHeldAttributeModifiers(IToolStackView tool, EquipmentSlot slot) {
  ImmutableMultimap.Builder<Attribute, AttributeModifier> builder = ImmutableMultimap.builder();
  if (!tool.isBroken()) {
    // base melee stats - skip if not melee
    StatsNBT statsNBT = tool.getStats();
    if (slot == EquipmentSlot.MAINHAND && EntityInteractionModifierHook.isMeleeWeapon(tool)) {
      builder.put(Attributes.ATTACK_DAMAGE, new AttributeModifier(Item.BASE_ATTACK_DAMAGE_UUID, "tconstruct.tool.attack_damage", statsNBT.get(ToolStats.ATTACK_DAMAGE), AttributeModifier.Operation.ADDITION));
      // base attack speed is 4, but our numbers start from 4
      builder.put(Attributes.ATTACK_SPEED, new AttributeModifier(Item.BASE_ATTACK_SPEED_UUID, "tconstruct.tool.attack_speed", statsNBT.get(ToolStats.ATTACK_SPEED) - 4d, AttributeModifier.Operation.ADDITION));
    }

    if (slot.getType() == Type.HAND) {
      // shields and slimestaffs can get armor
      if (tool.hasTag(TinkerTags.Items.ARMOR)) {
        UUID uuid = HELD_ARMOR_UUID[slot.getIndex()];
        double value = statsNBT.get(ToolStats.ARMOR);
        if (value != 0) {
          builder.put(Attributes.ARMOR, new AttributeModifier(uuid, "tconstruct.held.armor", value, AttributeModifier.Operation.ADDITION));
        }
        value = statsNBT.get(ToolStats.ARMOR_TOUGHNESS);
        if (value != 0) {
          builder.put(Attributes.ARMOR_TOUGHNESS, new AttributeModifier(uuid, "tconstruct.held.toughness", value, AttributeModifier.Operation.ADDITION));
        }
        value = statsNBT.get(ToolStats.KNOCKBACK_RESISTANCE);
        if (value != 0) {
          builder.put(Attributes.KNOCKBACK_RESISTANCE, new AttributeModifier(uuid, "tconstruct.held.knockback_resistance", value, AttributeModifier.Operation.ADDITION));
        }
      }

      // grab attributes from modifiers, only do for hands (other slots would just be weird)
      BiConsumer<Attribute,AttributeModifier> attributeConsumer = builder::put;
      for (ModifierEntry entry : tool.getModifierList()) {
        entry.getHook(ModifierHooks.ATTRIBUTES).addAttributes(tool, entry, slot, attributeConsumer);
      }
    }
  }
  return builder.build();
}

private void deactivateSlot(int index) {
  this.stackHandler.getPreviousActive().set(index, false);
  LivingEntity livingEntity = this.curioInventory.getOwner();
  PacketDistributor.sendToPlayersTrackingEntityAndSelf(livingEntity, new SPacketSyncActiveState(
      livingEntity.getId(), identifier, index, false));
  NonNullList<Boolean> renderStates = this.getRenders();
  SlotContext slotContext =
      new SlotContext(
          identifier,
          livingEntity,
          index,
          false,
          renderStates.size() > index && renderStates.get(index));
  IDynamicStackHandler stacks = this.getStacks();
  ItemStack stack = stacks.getStackInSlot(index);
  NeoForge.EVENT_BUS.post(
      new CurioChangeEvent.Item(livingEntity, slotContext, stack, ItemStack.EMPTY));
  AttributeMap attributeMap = livingEntity.getAttributes();

  if (!stack.isEmpty()) {
    ICurioItem
        .forEachModifier(stack, slotContext,
            (attributeHolder, attributeModifier) -> {
              if (attributeHolder.value() instanceof SlotAttribute slotAttribute
                  && slotAttribute.id().equals(this.identifier)) {
                this.removeModifier(attributeModifier.id());
              } else {
                AttributeInstance instance =
                    attributeMap.getInstance(attributeHolder);

                if (instance != null) {
                  instance.removeModifier(attributeModifier);
                }
              }
            });
    CuriosApi.getCurio(stack).ifPresent(curio -> curio.onUnequip(slotContext, stack));
  }
}

static boolean leftClickEntity(ItemStack stack, Player player, Entity target) {
  ToolStack tool = ToolStack.from(stack);
  boolean noMelee = meleeDisabled(tool);
  if (stack.is(TinkerTags.Items.INTERACTABLE_LEFT)) {
    if (!player.getCooldowns().isOnCooldown(stack.getItem())) {
      List<ModifierEntry> modifiers = tool.getModifierList();
      // TODO: should this be in the event?
      for (ModifierEntry entry : modifiers) {
        if (entry.getHook(ModifierHooks.ENTITY_INTERACT).beforeEntityUse(tool, entry, player, target, InteractionHand.MAIN_HAND, InteractionSource.LEFT_CLICK).consumesAction()) {
          return true;
        }
      }
      if (target instanceof LivingEntity living) {
        for (ModifierEntry entry : modifiers) {
          if (entry.getHook(ModifierHooks.ENTITY_INTERACT).afterEntityUse(tool, entry, player, living, InteractionHand.MAIN_HAND, InteractionSource.LEFT_CLICK).consumesAction()) {
            return true;
          }
        }
      }
      // if melee attacks are disabled, we don't actually end up running right click hooks so run them here
      // also run the hook if we are not a melee weapon, as we don't need to bother with the 1 damage hit then
      if (noMelee || !tool.hasTag(TinkerTags.Items.MELEE)) {
        for (ModifierEntry entry : modifiers) {
          if (entry.getHook(ModifierHooks.GENERAL_INTERACT).onToolUse(tool, entry, player, InteractionHand.MAIN_HAND, InteractionSource.LEFT_CLICK).consumesAction()) {
            return true;
          }
        }
      }
    }
  }
  // block vanilla left click when melee is disabled, not just our left click
  // block even on cooldown
  if (noMelee) {
    // when you fail to damage a target, squeak
    player.playSound(Sounds.TOY_SQUEAK.getSound());
    return true;
  }
  // no left click modifiers? fallback to standard attack
  return ToolAttackUtil.attackEntity(tool, player, target);
}

public float apply(FluidStack fluid, EffectLevel level, FluidEffectContext.Block context, FluidAction action) {
  CompoundTag tag = fluid.getTag();
  if (predicate.test(tag) && context.isOffsetReplaceable()) {
    Potion potion = PotionUtils.getPotion(fluid.getTag());
    List<MobEffectInstance> effects = potion.getEffects();
    if (!effects.isEmpty()) {
      float scale = level.value();
      if (action.execute()) {
        AreaEffectCloud cloud = MobEffectCloudFluidEffect.makeCloud(context);
        // not using set potion as we want to change the effect duration outself
        float effectScale = this.scale * scale;
        // keep track of how many effects are actually added
        boolean used = false;
        for (MobEffectInstance instance : effects) {
          if (instance.getEffect().isInstantenous()) {
            // only thing we have to scale on instant effects is the amplifier, though clouds automatically half instant effects for us
            int amplifier = (int)((instance.getAmplifier() + 1) * effectScale * 2) - 1;
            if (amplifier >= 0) {
              cloud.addEffect(new MobEffectInstance(instance.getEffect(), instance.getDuration(), amplifier, instance.isAmbient(), instance.isVisible(), instance.showIcon()));
              used = true;
            }
          } else {
            int duration = (int)(instance.getDuration() * effectScale);
            if (duration > 10) {
              cloud.addEffect(new MobEffectInstance(instance.getEffect(), duration, instance.getAmplifier(), instance.isAmbient(), instance.isVisible(), instance.showIcon()));
              used = true;
            }
          }
        }
        // TODO: custom effects from potion NBT?
        // TODO: custom color from potion NBT?
        if (used) {
          context.getLevel().addFreshEntity(cloud);
        } else {
          cloud.discard();
          return 0;
        }
      }
      return scale;
    }
  }
  return 0;
}

public List<SlotResult> findCurios(Predicate<ItemStack> filter, boolean includeInactive,
                                   String cacheKey) {
  // Check cached value first
  long gameTime = this.livingEntity.level().getGameTime();
  Cache<String, Pair<Long, List<SlotResult>>> cache = this.curioInventory.findCuriosCache;

  if (!cacheKey.isEmpty()) {
    Pair<Long, List<SlotResult>> cached = cache.getIfPresent(cacheKey);

    if (cached != null && cached.getFirst() == gameTime) {
      return cached.getSecond();
    }
  }
  List<SlotResult> result = new ArrayList<>();
  Map<String, ICurioStacksHandler> curios = this.getCurios();

  for (String id : curios.keySet()) {
    ICurioStacksHandler stacksHandler = curios.get(id);
    IDynamicStackHandler stackHandler = stacksHandler.getStacks();
    NonNullList<Boolean> activeStates = stacksHandler.getActiveStates();

    for (int i = 0; i < stackHandler.getSlots(); i++) {

      if (!includeInactive && activeStates.size() > i && !activeStates.get(i)) {
        continue;
      }
      ItemStack stack = stackHandler.getStackInSlot(i);

      if (!stack.isEmpty() && filter.test(stack)) {
        NonNullList<Boolean> renderStates = stacksHandler.getRenders();
        result.add(
            new SlotResult(
                new SlotContext(
                    id,
                    this.livingEntity,
                    i,
                    false,
                    renderStates.size() > i && renderStates.get(i)),
                stack));
      }
    }
  }
  cache.put(cacheKey, Pair.of(gameTime, result));
  return result;
}

private void activateSlot(int index) {
  this.stackHandler.getPreviousActive().set(index, true);
  LivingEntity livingEntity = this.curioInventory.getOwner();
  PacketDistributor.sendToPlayersTrackingEntityAndSelf(
      livingEntity,
      new SPacketSyncActiveState(livingEntity.getId(), identifier, index, true));
  NonNullList<Boolean> renderStates = this.getRenders();
  SlotContext slotContext =
      new SlotContext(
          identifier,
          livingEntity,
          index,
          false,
          renderStates.size() > index && renderStates.get(index));
  IDynamicStackHandler stacks = this.getStacks();
  ItemStack stack = stacks.getStackInSlot(index);
  NeoForge.EVENT_BUS.post(
      new CurioChangeEvent.Item(livingEntity, slotContext, ItemStack.EMPTY, stack));
  AttributeMap attributeMap = livingEntity.getAttributes();

  if (!stack.isEmpty()) {
    ICurioItem
        .forEachModifier(stack, slotContext,
            (attributeHolder, attributeModifier) -> {
              if (attributeHolder.value() instanceof SlotAttribute slotAttribute
                  && slotAttribute.id().equals(this.identifier)) {
                this.addTransientModifier(
                    new AttributeModifier(attributeModifier.id(), attributeModifier.amount(),
                        attributeModifier.operation()));
              } else {
                AttributeInstance instance =
                    attributeMap.getInstance(attributeHolder);

                if (instance != null) {
                  instance.addOrUpdateTransientModifier(
                      attributeModifier);
                }
              }
            });
    CuriosApi.getCurio(stack).ifPresent(curio -> curio.onEquip(slotContext, ItemStack.EMPTY));

    if (livingEntity instanceof ServerPlayer) {
      CuriosRegistry.EQUIP_TRIGGER.get().trigger(slotContext, (ServerPlayer) livingEntity, stack);
    }
  }
}

public void handleDestroyPacket(final CPacketDestroy data, final IPayloadContext ctx) {
  ctx.enqueueWork(() -> {
    Player player = ctx.player();
    CuriosApi.getCuriosInventory(player)
        .ifPresent(handler -> handler.getCurios().values().forEach(stacksHandler -> {
          IDynamicStackHandler stackHandler = stacksHandler.getStacks();
          IDynamicStackHandler cosmeticStackHandler = stacksHandler.getCosmeticStacks();
          String id = stacksHandler.getIdentifier();

          for (int i = stackHandler.getSlots() - 1; i >= 0; i--) {
            NonNullList<Boolean> renderStates = stacksHandler.getRenders();
            SlotContext slotContext = new SlotContext(id, player, i, false,
                                                      renderStates.size() > i && renderStates.get(
                                                          i));
            ItemStack stack = stackHandler.getStackInSlot(i);
            ICurioItem
                .forEachModifier(stack, slotContext,
                                 (attributeHolder, attributeModifier) -> {
                                   if (attributeHolder.value() instanceof SlotAttribute slotAttribute) {
                                     handler.removeSlotModifier(
                                         slotAttribute.id(),
                                         attributeModifier.id());
                                   } else {
                                     AttributeInstance instance =
                                         player.getAttributes().getInstance(attributeHolder);

                                     if (instance != null) {
                                       instance.removeModifier(attributeModifier);
                                     }
                                   }
                                 });
            CuriosApi.getCurio(stack)
                .ifPresent(curio -> curio.onUnequip(slotContext, stack));
            stackHandler.setStackInSlot(i, ItemStack.EMPTY);
            PacketDistributor.sendToPlayersTrackingEntityAndSelf(player,
                                                                 new SPacketSyncStack(
                                                                     player.getId(), id, i,
                                                                     ItemStack.EMPTY,
                                                                     SPacketSyncStack.HandlerType.EQUIPMENT.ordinal(),
                                                                     new CompoundTag()));
            cosmeticStackHandler.setStackInSlot(i, ItemStack.EMPTY);
            PacketDistributor.sendToPlayersTrackingEntityAndSelf(player,
                                                                 new SPacketSyncStack(
                                                                     player.getId(), id, i,
                                                                     ItemStack.EMPTY,
                                                                     SPacketSyncStack.HandlerType.COSMETIC.ordinal(),
                                                                     new CompoundTag()));
          }
        }));
  });
}

public float apply(LivingEntity target, EffectLevel scale, TimeAction timeAction, FluidAction action, @Nullable Entity source) {
  // infinite requires a full level
  if (isInfinite() && !scale.isFull()) {
    return 0;
  }
  float used;
  int time;
  // infinite costs 1 and sets the full time
  if (isInfinite()) {
    time = this.time;
    used = 1;
  } else {
    // add and set both have distinct behavior under an existing effect, same otherwise
    MobEffectInstance existingInstance = target.getEffect(effect);
    int amplifier = amplifier();
    if (existingInstance != null && existingInstance.getAmplifier() >= amplifier) {
      // if the existing level is larger, just skip, would be a cheese to increase said level
      // lower levels we treat as not having the effect, must be exact match to extend
      if (existingInstance.getAmplifier() > amplifier) {
        return 0;
      }
      if (timeAction == TimeAction.ADD) {
        int extraTime = (int) (this.time * scale.value());
        if (extraTime <= 0) {
          return 0;
        }
        // add simply sums existing time with the desired time. If the level is higher than ours, it produces a hidden effect
        time = existingInstance.getDuration() + extraTime;
        used = scale.value();
      } else {
        // set can produce time up to the maximum allowed by scale,
        float existing = existingInstance.getDuration() / (float) this.time;
        float effective = scale.effective(existing);
        // no change? means we skip applying entirely
        if (effective < existing) {
          return 0;
        }
        used = effective - existing;
        time = (int) (this.time * effective);
      }
    } else {
      // if no existing, time and set behave the same way, use maximum amount to compute time
      time = (int) (this.time * scale.value());
      used = scale.value();
    }
  }
  // if we got time, add the effect
  if (time != 0) {
    MobEffectInstance newInstance = effectWithTime(time);
    // if simulating, just ask if it's applicable. Won't handle event canceling, but thats acceptable.
    if (action.simulate()) {
      return target.canBeAffected(newInstance) ? used : 0;
    }
    return target.addEffect(newInstance, source) ? used : 0;
  }
  return 0;
}

public float apply(FluidStack fluid, EffectLevel level, FluidEffectContext.Entity context, FluidAction action) {
  LivingEntity target = context.getLivingTarget();
  // must match the tag predicate
  if (target != null && predicate.test(fluid.getTag())) {
    List<MobEffectInstance> effects = PotionUtils.getPotion(fluid.getTag()).getEffects();
    if (!effects.isEmpty()) {
      LivingEntity attacker = context.getEntity();
      Entity directSource = context.getDirectSource();
      Entity effectSource = context.getEffectSource();
      // prevent effects like instant damage from hitting hurt resistance
      int oldInvulnerableTime = target.invulnerableTime;
      // report whichever effect used the most
      float used = 0;
      for (MobEffectInstance instance : effects) {
        MobEffect effect = instance.getEffect();
        if (effect.isInstantenous()) {
          // instant effects just apply full value always
          used = level.value();
          if (action.execute()) {
            target.invulnerableTime = 0;
            effect.applyInstantenousEffect(directSource, attacker, target, instance.getAmplifier(), used * scale);
          }
        } else {
          // if the potion already exists, we scale up the existing time
          MobEffectInstance existingEffect = target.getEffect(effect);
          int duration;
          if (existingEffect != null && existingEffect.getAmplifier() >= instance.getAmplifier()) {
            // if the existing level is larger, just skip, would be a cheese to increase said level
            // lower levels we treat as not having the effect, must be exact match to extend
            if (existingEffect.getAmplifier() > instance.getAmplifier()) {
              continue;
            }
            float existingLevel = existingEffect.getDuration() / scale / instance.getDuration();
            float effective = level.effective(existingLevel);
            // no potion to add? just save effort and stop here
            if (effective <= existingLevel) {
              continue;
            }
            duration = (int) (instance.getDuration() * scale * effective);
            // update how much we used, which is likely less than our max possible
            used = Math.max(used, effective - existingLevel);
          } else {
            // no relevant effect? just compute duration directly
            used = level.value();
            duration = (int) (instance.getDuration() * scale * used);
          }
          if (action.execute()) {
            target.addEffect(new MobEffectInstance(effect, duration, instance.getAmplifier(), instance.isAmbient(), instance.isVisible(), instance.showIcon()), effectSource);
          }
        }
      }
      target.invulnerableTime = oldInvulnerableTime;
      return used;
    }
  }
  return 0;
}

public void curioRightClick(PlayerInteractEvent.RightClickItem evt) {
  Player player = evt.getEntity();
  ItemStack stack = evt.getItemStack();
  CuriosApi.getCurio(stack).ifPresent(
      curio -> CuriosApi.getCuriosInventory(player).ifPresent(handler -> {
        Map<String, ICurioStacksHandler> curios = handler.getCurios();
        Pair<IDynamicStackHandler, SlotContext> firstSlot = null;

        for (Map.Entry<String, ICurioStacksHandler> entry : curios.entrySet()) {
          IDynamicStackHandler stackHandler = entry.getValue().getStacks();
          NonNullList<Boolean> activeStates = entry.getValue().getActiveStates();

          for (int i = 0; i < stackHandler.getSlots(); i++) {
            boolean active = activeStates.size() > i && activeStates.get(i);

            if (!active) {
              continue;
            }
            String id = entry.getKey();
            NonNullList<Boolean> renderStates = entry.getValue().getRenders();
            SlotContext slotContext = new SlotContext(id, player, i, false,
                renderStates.size() > i && renderStates.get(
                    i));

            if (stackHandler.isValid(i, ItemResource.of(stack)) && curio.canEquipFromUse(slotContext)) {
              ItemStack present = stackHandler.getStackInSlot(i);

              if (present.isEmpty()) {
                stackHandler.setStackInSlot(i, stack.copy());
                curio.onEquipFromUse(slotContext);

                if (!player.isCreative()) {
                  int count = stack.getCount();
                  stack.shrink(count);
                }
                evt.setCancellationResult(
                    player.level().isClientSide() ? InteractionResult.SUCCESS :
                        InteractionResult.SUCCESS_SERVER);
                evt.setCanceled(true);
                return;
              } else if (firstSlot == null) {

                if (stackHandler.extract(i, ItemResource.of(stack), stack.getMaxStackSize(), Transaction.open(null)) ==
                    stack.getCount()) {
                  firstSlot = new Pair<>(stackHandler, slotContext);
                }
              }
            }
          }
        }

        if (firstSlot != null) {
          IDynamicStackHandler stackHandler = firstSlot.getFirst();
          SlotContext slotContext = firstSlot.getSecond();
          int i = slotContext.index();
          ItemStack present = stackHandler.getStackInSlot(i);
          stackHandler.setStackInSlot(i, stack.copy());
          curio.onEquipFromUse(slotContext);
          player.setItemInHand(evt.getHand(), present.copy());
          evt.setCancellationResult(
              player.level().isClientSide() ? InteractionResult.SUCCESS :
                  InteractionResult.SUCCESS_SERVER);
          evt.setCanceled(true);
        }
      }));
}

public void loadInventoryConfiguration() {
  Map<ISlotType, ICurioStacksHandler> defaultInventory = this.createDefaultInventory();
  SortedMap<ISlotType, ICurioStacksHandler> sortedCurios = new TreeMap<>(defaultInventory);

  for (Map.Entry<String, ICurioStacksHandler> entry : this.curios.entrySet()) {
    String id = entry.getKey();
    ISlotType slotType = CuriosSlotTypes.getSlotType(id, this.owner.level().isClientSide());
    ICurioStacksHandler prevStacksHandler = entry.getValue();

    if (slotType != null && defaultInventory.containsKey(slotType)) {
      ICurioStacksHandler curioStacksHandler = defaultInventory.get(slotType);
      int defaultSize = curioStacksHandler.getSlots();
      int oldSize = prevStacksHandler.getSlots();
      curioStacksHandler.copyModifiers(prevStacksHandler);

      if (oldSize != defaultSize) {
        curioStacksHandler.addTransientModifier(
            new AttributeModifier(SIZE_SHIFT, oldSize - defaultSize,
                AttributeModifier.Operation.ADD_VALUE));
      }
      int index = 0;

      while (index < curioStacksHandler.getSlots() && index < prevStacksHandler.getSlots()) {
        ItemStack prevStack = prevStacksHandler.getStacks().getStackInSlot(index);

        if (!prevStack.isEmpty()) {

          if (curioStacksHandler.getStacks().isItemValid(index, prevStack)) {
            curioStacksHandler.getStacks().setStackInSlot(index, prevStack);
          } else {
            this.invalidStacks.add(prevStack);
          }
        }
        ItemStack prevCosmetic =
            prevStacksHandler.getCosmeticStacks().getStackInSlot(index);

        if (!prevCosmetic.isEmpty()) {

          if (curioStacksHandler.getStacks().isItemValid(index, prevCosmetic)) {
            curioStacksHandler
                .getCosmeticStacks()
                .setStackInSlot(
                    index, prevStacksHandler.getCosmeticStacks().getStackInSlot(index));
          } else {
            this.invalidStacks.add(prevCosmetic);
          }
        }
        index++;
      }

      while (index < prevStacksHandler.getSlots()) {
        this.invalidStacks.add(prevStacksHandler.getStacks().getStackInSlot(index));
        this.invalidStacks.add(prevStacksHandler.getCosmeticStacks().getStackInSlot(index));
        index++;
      }
      sortedCurios.put(slotType, curioStacksHandler);

      for (int j = 0;
           j < curioStacksHandler.getRenders().size()
               && j < prevStacksHandler.getRenders().size();
           j++) {
        curioStacksHandler.getRenders().set(j, prevStacksHandler.getRenders().get(j));
      }

      for (int j = 0;
           j < curioStacksHandler.getActiveStates().size()
               && j < prevStacksHandler.getActiveStates().size();
           j++) {
        curioStacksHandler.getActiveStates()
            .set(j, prevStacksHandler.getActiveStates().get(j));
      }
    } else {
      IDynamicStackHandler stackHandler = prevStacksHandler.getStacks();
      IDynamicStackHandler cosmeticStackHandler = prevStacksHandler.getCosmeticStacks();

      for (int j = 0; j < stackHandler.getSlots(); j++) {
        ItemStack stack = stackHandler.getStackInSlot(j);

        if (!stack.isEmpty()) {
          this.invalidStacks.add(stack);
        }

        ItemStack cosmeticStack = cosmeticStackHandler.getStackInSlot(j);

        if (!cosmeticStack.isEmpty()) {
          this.invalidStacks.add(cosmeticStack);
        }
      }
    }
  }
  this.curios.clear();

  for (Map.Entry<ISlotType, ICurioStacksHandler> entry : sortedCurios.entrySet()) {
    ICurioStacksHandler stacksHandler = entry.getValue();

    if (stacksHandler instanceof CurioStacksHandler curioStacksHandler) {
      curioStacksHandler.setDataLoaded();
    }
    this.curios.put(entry.getKey().getId(), stacksHandler);
  }
}

public float apply(FluidStack fluid, EffectLevel level, FluidEffectContext.Block context, FluidAction action) {
  // inside world border?
  Level world = context.getLevel();
  BlockPos pos = context.getBlockPos();
  if (!world.getWorldBorder().isWithinBounds(pos)) {
    return 0;
  }
  // block usable?
  BlockState state = context.getBlockState();
  FeatureFlagSet enabled = world.enabledFeatures();
  if (!state.getBlock().isEnabled(enabled)) {
    return 0;
  }
  // we have no way of checking if clicking the block does anything without actually clicking, so just always charge the full amount
  if (action.simulate()) {
    return 1;
  }

  // determine if sneak bypass is enabled
  LivingEntity entity = context.getEntity();
  Player player = context.getPlayer();
  boolean skipBlock = false;
  if (player != null) {
    skipBlock = player.isSecondaryUseActive() && (!player.getMainHandItem().doesSneakBypassUse(world, pos, player) || !player.getOffhandItem().doesSneakBypassUse(player.level(), pos, player));
  } else if (entity != null) {
    skipBlock = entity.isShiftKeyDown() && (!entity.getMainHandItem().isEmpty() || !entity.getOffhandItem().isEmpty());
  }

  // interact with both hands if we have an entity, just main hand otherwise
  BlockHitResult hitResult = context.getHitResult();
  for (InteractionHand hand : entity == null ? new InteractionHand[] {InteractionHand.MAIN_HAND} : InteractionHand.values()) {
    // find what item to use
    ItemStack heldItem = context.getStack();
    if (entity != null) {
      heldItem = entity.getItemInHand(hand);
    }
    // if the item is not enabled, give up entirely. Not sure why, its just what vanilla does
    if (!heldItem.isItemEnabled(enabled)) {
      return 0;
    }

    // try the event
    Result useItem = Result.DEFAULT;
    Result useBlock = Result.DEFAULT;
    if (player != null) {
      PlayerInteractEvent.RightClickBlock event = ForgeHooks.onRightClickBlock(player, hand, pos, hitResult);
      if (event.isCanceled()) {
        // if successful, swing hand
        if (event.getCancellationResult().consumesAction()) {
          if (entity != null) {
            entity.swing(hand, true);
          }
          return 1;
        }
        return 0;
      }
      useItem = event.getUseItem();
      useBlock = event.getUseBlock();
    }
    // skipped: never spectator mode if we made it this far

    // use the item
    UseOnContext useContext = new UseOnContext(world, player, hand, heldItem, hitResult);
    if (useItem != Result.DENY && !heldItem.isEmpty()) {
      InteractionResult result = heldItem.onItemUseFirst(useContext);
      if (result != InteractionResult.PASS) {
        if (result.consumesAction()) {
          if (entity != null) {
            entity.swing(hand, true);
          }
          damageIfNeeded(useContext);
          return 1;
        }
        return 0; // failure exits the loop
      }
    }

    // click the block
    ItemStack original = heldItem.copy();
    if (player != null && (useBlock == Result.ALLOW || (useItem == Result.DEFAULT && !skipBlock))) {
      InteractionResult result = state.use(world, player, hand, hitResult);
      if (result.consumesAction()) {
        if (player instanceof ServerPlayer serverPlayer) {
          CriteriaTriggers.ITEM_USED_ON_BLOCK.trigger(serverPlayer, pos, original);
        }
        player.swing(hand, true);
        return 1;
      }
    }

    // post block item usage
    if (useItem == Result.ALLOW || (useItem == Result.DEFAULT && !heldItem.isEmpty() && (player == null || !player.getCooldowns().isOnCooldown(heldItem.getItem())))) {
      InteractionResult result;
      if (player != null && player.isCreative()) {
        int oldCount = heldItem.getCount();
        result = heldItem.useOn(useContext);
        heldItem.setCount(oldCount);
      } else {
        result = heldItem.useOn(useContext);
        damageIfNeeded(useContext);
      }
      if (result != InteractionResult.PASS) {
        if (result.consumesAction()) {
          if (player instanceof ServerPlayer serverPlayer) {
            CriteriaTriggers.ITEM_USED_ON_BLOCK.trigger(serverPlayer, pos, heldItem);
          }
          if (entity != null) {
            entity.swing(hand, true);
          }
          return 1;
        }
        return 0; // failure exits the loop
      }
    }
  }
  return 0;
}

public void tick(EntityTickEvent.Post evt) {
  Entity entity = evt.getEntity();
  MinecraftServer server = ServerLifecycleHooks.getCurrentServer();

  if (server != null && !server.isDedicatedServer()) {

    if (CuriosSlotResources.CLIENT.getSlots().isEmpty()) {
      return;
    }
  }

  if (entity instanceof LivingEntity livingEntity) {
    if (livingEntity instanceof Player player
        && player.containerMenu instanceof CuriosMenu curiosMenu) {
      curiosMenu.checkQuickMove();
    }

    CuriosApi.getCuriosInventory(livingEntity).ifPresent(handler -> {
      handler.handleInvalidStacks();
      Map<String, ICurioStacksHandler> curios = handler.getCurios();

      for (Map.Entry<String, ICurioStacksHandler> entry : curios.entrySet()) {
        ICurioStacksHandler stacksHandler = entry.getValue();
        String identifier = entry.getKey();
        IDynamicStackHandler stackHandler = stacksHandler.getStacks();
        IDynamicStackHandler cosmeticStackHandler = stacksHandler.getCosmeticStacks();
        NonNullList<Boolean> renderStates = stacksHandler.getRenders();

        for (int i = 0; i < stacksHandler.getSlots(); i++) {
          stacksHandler.updateActiveState(i);
          NonNullList<Boolean> activeStates = stacksHandler.getActiveStates();
          boolean functional = activeStates.size() > i && activeStates.get(i);
          SlotContext slotContext = new SlotContext(identifier, livingEntity, i, false,
              renderStates.size() > i && renderStates.get(
                  i));
          ItemStack stack = stackHandler.getStackInSlot(i);
          Optional<ICurio> currentCurio = CuriosApi.getCurio(stack);

          if (functional && !stack.isEmpty()) {
            stack.inventoryTick(livingEntity.level(), livingEntity, null);
            currentCurio.ifPresent(curio -> curio.curioTick(slotContext));
          }

          if (!livingEntity.level().isClientSide()) {
            ItemStack prevStack = stackHandler.getPreviousStackInSlot(i);

            if (!ItemStack.matches(stack, prevStack)) {
              boolean flag = false;
              Optional<ICurio> prevCurio = CuriosApi.getCurio(prevStack);
              syncCurios(livingEntity, stack, currentCurio, prevCurio, identifier, i, false,
                  renderStates.size() > i && renderStates.get(i), HandlerType.EQUIPMENT);

              if (functional) {
                CurioChangeEvent changeEvent;

                if (ItemStack.isSameItem(stack, prevStack)) {
                  flag = true;
                  changeEvent =
                      new CurioChangeEvent.State(livingEntity, slotContext, prevStack, stack);
                } else {
                  changeEvent =
                      new CurioChangeEvent.Item(livingEntity, slotContext, prevStack, stack);
                }
                NeoForge.EVENT_BUS.post(changeEvent);
                AttributeMap attributeMap = livingEntity.getAttributes();
                final boolean isStateChange = flag;

                if (!prevStack.isEmpty()) {
                  ICurioItem
                      .forEachModifier(prevStack, slotContext,
                          (attributeHolder, attributeModifier) -> {
                            if (attributeHolder.value() instanceof SlotAttribute slotAttribute) {
                              handler.removeSlotModifier(
                                  slotAttribute.id(),
                                  attributeModifier.id());
                            } else {
                              AttributeInstance instance =
                                  attributeMap.getInstance(attributeHolder);

                              if (instance != null) {
                                instance.removeModifier(attributeModifier);
                              }
                            }
                          });
                  prevCurio.ifPresent(curio -> {

                    if (!isStateChange) {
                      curio.onUnequip(slotContext, stack);
                    }
                  });
                }

                if (!stack.isEmpty()) {
                  ICurioItem
                      .forEachModifier(stack, slotContext,
                          (attributeHolder, attributeModifier) -> {
                            if (attributeHolder.value() instanceof SlotAttribute slotAttribute) {
                              handler.addTransientSlotModifier(
                                  slotAttribute.id(),
                                  attributeModifier.id(), attributeModifier.amount(),
                                  attributeModifier.operation());
                            } else {
                              AttributeInstance instance =
                                  attributeMap.getInstance(attributeHolder);

                              if (instance != null) {
                                instance.addOrUpdateTransientModifier(
                                    attributeModifier);
                              }
                            }
                          });
                  currentCurio.ifPresent(curio -> {

                    if (isStateChange) {
                      curio.onStateChange(slotContext, prevStack);
                    } else {
                      curio.onEquip(slotContext, prevStack);
                    }
                  });

                  if (livingEntity instanceof ServerPlayer) {
                    CuriosRegistry.EQUIP_TRIGGER.get()
                        .trigger(slotContext, (ServerPlayer) livingEntity, stack);
                  }
                }
              }
              stackHandler.setPreviousStackInSlot(i, stack.copy());
            }
            ItemStack cosmeticStack = cosmeticStackHandler.getStackInSlot(i);
            ItemStack prevCosmeticStack = cosmeticStackHandler.getPreviousStackInSlot(i);

            if (!ItemStack.matches(cosmeticStack, prevCosmeticStack)) {
              syncCurios(livingEntity, cosmeticStack, CuriosApi.getCurio(cosmeticStack),
                  CuriosApi.getCurio(prevCosmeticStack), identifier, i, true, true,
                  HandlerType.COSMETIC);
              cosmeticStackHandler.setPreviousStackInSlot(i, cosmeticStack.copy());
            }
          }
        }
      }

      if (!livingEntity.level().isClientSide()) {
        handler.clearCachedSlotModifiers();
        Set<ICurioStacksHandler> updates = handler.getUpdatingInventories();

        if (!updates.isEmpty()) {
          PacketDistributor.sendToPlayersTrackingEntityAndSelf(livingEntity,
              new SPacketSyncModifiers(
                  livingEntity.getId(),
                  updates));
          updates.clear();
        }
      }
    });
  }
}

static void projectileImpact(ProjectileImpactEvent event) {
  Entity entity = event.getEntity();
  Level level = entity.level();
  Projectile projectile = event.getProjectile();
  HitResult hit = event.getRayTraceResult();
  if (hit.getType() == Type.ENTITY && ((EntityHitResult) hit).getEntity() instanceof LivingEntity target) {
    // reflecting //
    // handle blacklist for projectiles
    if (!level.isClientSide && !RegistryHelper.contains(TinkerTags.EntityTypes.REFLECTING_BLACKLIST, projectile.getType()) && target != projectile.getOwner() && target.isUsingItem()) {
      ItemStack stack = target.getUseItem();
      // living entity must be using one of our shields
      if (stack.is(TinkerTags.Items.SHIELDS)) {
        ToolStack tool = ToolStack.from(stack);
        // make sure we actually have the modifier
        int reflectingTime = tool.getVolatileData().getInt(REFLECTING);
        if (reflectingTime > 0) {
          ModifierEntry activeModifier = GeneralInteractionModifierHook.getActiveModifier(tool);
          if (activeModifier != ModifierEntry.EMPTY) {
            GeneralInteractionModifierHook hook = activeModifier.getHook(ModifierHooks.GENERAL_INTERACT);
            int time = hook.getUseDuration(tool, activeModifier) - target.getUseItemRemainingTicks();
            // must be blocking, started blocking within the last 2*level seconds, and be within the block angle
            if (hook.getUseAction(tool, activeModifier) == UseAnim.BLOCK
              && (time >= 5 && time < reflectingTime)
              && InteractionHandler.canBlock(target, projectile.position(), tool)) {

              // time to actually reflect, this code is strongly based on code from the Parry mod
              // take ownership of the projectile so it counts as a player kill, except in the case of fishing bobbers
              if (!RegistryHelper.contains(TinkerTags.EntityTypes.REFLECTING_PRESERVE_OWNER, projectile.getType())) {
                // arrows are dumb and mutate their pickup status when owner is set, so disagree and set it back
                if (projectile instanceof AbstractArrow arrow) {
                  Pickup pickup = arrow.pickup;
                  arrow.setOwner(target);
                  arrow.pickup = pickup;
                } else {
                  projectile.setOwner(target);
                }
                projectile.leftOwner = true;
              }

              Vec3 reboundAngle = target.getLookAngle();
              // use the shield accuracy and velocity stats when reflecting
              float velocity = ConditionalStatModifierHook.getModifiedStat(tool, target, ToolStats.VELOCITY) * 1.1f;
              projectile.shoot(reboundAngle.x, reboundAngle.y, reboundAngle.z, velocity, ModifierUtil.getInaccuracy(tool, target));
              if (projectile instanceof AbstractHurtingProjectile hurting) {
                hurting.xPower = reboundAngle.x * 0.1;
                hurting.yPower = reboundAngle.y * 0.1;
                hurting.zPower = reboundAngle.z * 0.1;
              }
              if (target.getType() == EntityType.PLAYER) {
                TinkerNetwork.getInstance().sendVanillaPacket(new ClientboundSetEntityMotionPacket(projectile), target);
              }
              level.playSound(null, target.blockPosition(), SoundEvents.SHIELD_BLOCK, SoundSource.PLAYERS, 1.0F, 1.5F + level.random.nextFloat() * 0.4F);
              event.setImpactResult(ImpactResult.SKIP_ENTITY);
              // damage the shield, and stop using it if needed
              if (ToolDamageUtil.damageAnimated(tool, 3, target, target.getUsedItemHand())) {
                target.stopUsingItem();
                entity.playSound(SoundEvents.SHIELD_BREAK, 0.8F, 0.8F + entity.level().random.nextFloat() * 0.4F);
              }
            }
          }
        }
      }
    }

    // enderference //
    // TODO: this is a lot of code to make enderference work. A mixin would likely be better and provide better compatability
    // endermen are hardcoded to not take arrow damage, so disagree by reimplementing arrow damage right here
    // blacklist lets us not run on tridents or thrown tools. Former does not work with enderference, latter does so internally
    EntityType<?> projectileType = projectile.getType();
    if (TinkerEffects.needsEnderferenceOverride(target) && !projectileType.is(TinkerTags.EntityTypes.ENDERFERENCE_ARROW_BLACKLIST) && projectile instanceof AbstractArrow arrow) {
      // first, give up if we reached pierce capacity, and ensure list are created
      int pierce = arrow.getPierceLevel();
      if (pierce > 0) {
        if (arrow.piercingIgnoreEntityIds == null) {
          arrow.piercingIgnoreEntityIds = new IntOpenHashSet(5);
        }
        if (arrow.piercedAndKilledEntities == null) {
          arrow.piercedAndKilledEntities = Lists.newArrayListWithCapacity(5);
        }
        if (arrow.piercingIgnoreEntityIds.size() >= pierce + 1) {
          ReusableProjectile.discard(projectile);
          event.setCanceled(true);
          return;
        }
        arrow.piercingIgnoreEntityIds.add(target.getId());
      }

      // calculate damage, bonus on crit
      int damage = Mth.ceil(Mth.clamp(arrow.getDeltaMovement().length() * arrow.getBaseDamage(), 0.0D, Integer.MAX_VALUE));
      if (arrow.isCritArrow()) {
        damage = (int) Math.min(target.getRandom().nextInt(damage / 2 + 2) + (long) damage, Integer.MAX_VALUE);
      }

      // create damage source, don't use projectile sources as that makes endermen ignore it
      Entity owner = arrow.getOwner();
      DamageSource damageSource = CombatHelper.damageSource(TinkerDamageTypes.MELEE_ARROW, projectile, owner);
      LivingEntity livingOwner = ModifierUtil.asLiving(owner);
      if (livingOwner != null) {
        livingOwner.setLastHurtMob(target);
      }

      // handle fire
      int remainingFire = target.getRemainingFireTicks();
      if (arrow.isOnFire()) {
        target.setSecondsOnFire(5);
      }

      // hurt the enderman
      if (target.hurt(damageSource, (float) damage)) {
        if (!level.isClientSide && pierce <= 0) {
          target.setArrowCount(target.getArrowCount() + 1);
        }

        // knockback from punch
        int knockback = arrow.getKnockback();
        if (knockback > 0) {
          Vec3 knockbackVec = arrow.getDeltaMovement().multiply(1.0D, 0.0D, 1.0D).normalize().scale(knockback * 0.6D);
          if (knockbackVec.lengthSqr() > 0.0D) {
            target.push(knockbackVec.x, 0.1D, knockbackVec.z);
          }
        }

        if (!level.isClientSide && livingOwner != null) {
          EnchantmentHelper.doPostHurtEffects(target, livingOwner);
          EnchantmentHelper.doPostDamageEffects(livingOwner, target);
        }

        arrow.doPostHurtEffects(target);

        if (!target.isAlive() && arrow.piercedAndKilledEntities != null) {
          arrow.piercedAndKilledEntities.add(target);
        }

        if (!level.isClientSide && arrow.shotFromCrossbow() && owner instanceof ServerPlayer player) {
          if (arrow.piercedAndKilledEntities != null) {
            CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(player, arrow.piercedAndKilledEntities);
          } else if (!target.isAlive()) {
            CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(player, List.of(target));
          }
        }

        arrow.playSound(arrow.soundEvent, 1.0F, 1.2F / (target.getRandom().nextFloat() * 0.2F + 0.9F));
        if (pierce <= 0) {
          ReusableProjectile.discard(projectile);
        }
      } else {
        // reset fire and drop the arrow
        target.setRemainingFireTicks(remainingFire);
        arrow.setDeltaMovement(arrow.getDeltaMovement().scale(-0.1D));
        arrow.setYRot(arrow.getYRot() + 180.0F);
        arrow.yRotO += 180.0F;
        if (!level.isClientSide && arrow.getDeltaMovement().lengthSqr() < 1.0E-7D) {
          if (arrow.pickup == AbstractArrow.Pickup.ALLOWED) {
            arrow.spawnAtLocation(arrow.getPickupItem(), 0.1F);
          }

          ReusableProjectile.discard(projectile);
        }
      }
      // cancel event so arrow does not bounce
      event.setCanceled(true);
    }
  }
}

public static void enableKnockback(@Nullable AttributeInstance instance) {
  if (instance != null) {
    instance.removeModifier(ANTI_KNOCKBACK_MODIFIER);
  }
}

public void afterMeleeHit(IToolStackView tool, ModifierEntry modifier, ToolAttackContext context, float damageDealt) {
  if (damageDealt > 0 && context.isFullyCharged()) {
    applyEffect(tool, modifier, context.getAttacker(), context.getPlayerAttacker(), context.getTarget(), context.getLivingTarget(), context.getProjectile());
  }
}

private static void setMissed(ItemStack stack, boolean state) {
    stack.set(RelicsDataComponents.SHIELD_OF_RETALIATION_MISSED, state);

    if (!state)
        setMissedTicks(stack, 0);
}

public static boolean addHarmfulEffect(LivingEntity target, MobEffectInstance effect, @Nullable Entity source, ItemStack stack, String ability) {
    if (!canHarm(source, target, stack, ability))
        return false;

    return target.addEffect(effect, source);
}

public static boolean addBeneficialEffect(LivingEntity target, MobEffectInstance effect, @Nullable Entity source, ItemStack stack, String ability) {
    if (!canBenefit(source, target, stack, ability))
        return false;

    return target.addEffect(effect, source);
}

public static DoubleSupplier getCooldownFunction(Player player, InteractionHand hand) {
  if (hand == InteractionHand.OFF_HAND) {
    return () -> OffhandCooldownTracker.getCooldown(player);
  }
  return () -> player.getAttackStrengthScale(0.5f);
}

public static InteractionResult onLeftClickInteraction(Player player, ItemStack held, InteractionHand hand) {
  if (player.getCooldowns().isOnCooldown(held.getItem())) {
    return InteractionResult.PASS;
  }
  return onLeftClickInteraction(ToolStack.from(held), player, hand);
}

public void onUnequip(IToolStackView tool, ModifierEntry modifier, EquipmentChangeContext context) {
  LivingEntity entity = context.getEntity();
  if (!entity.level().isClientSide && condition.matches(tool, modifier) && EquipmentChangeModifierHook.didUnequip(tool, context)) {
    entity.removeEffect(effect);
  }
}

private void freeze(ModifierEntry modifier, Entity target) {
  if (target.canFreeze()) {
    target.setTicksFrozen(Math.max(target.getTicksRequiredToFreeze(), target.getTicksFrozen()) + (int)(time.compute(modifier.getEffectiveLevel()) * 40));
    target.setRemainingFireTicks(0);
  }
}

public void beforeReleaseUsing(IToolStackView tool, ModifierEntry modifier, LivingEntity entity, int useDuration, int timeLeft, ModifierEntry activeModifier) {
  // when using a tool that doesn't fire right click hooks, allow throwing here provided its out of ammo
  if (activeModifier == ModifierEntry.EMPTY && !tool.getPersistentData().contains(ModifiableLauncherItem.KEY_DRAWBACK_AMMO)) {
    onStoppedUsing(tool, modifier, entity, timeLeft);
  }
}

public static void addSlotAttribute(AccessoryAttributeBuilder builder, String targetSlot, ResourceLocation location, double amount, AttributeModifier.Operation operation, boolean isStackable) {
    if(isStackable) {
        builder.addStackable(SlotAttribute.getAttributeHolder(targetSlot), location, amount, operation);
    } else {
        builder.addExclusive(SlotAttribute.getAttributeHolder(targetSlot), location, amount, operation);
    }
}

private int getCooldownTicks(Player player, ItemStack stack) {
    var ability = this.getRelicData(player, stack).getAbilitiesData().getAbilityData("retaliation");

    if (!ability.canPlayerUse(player))
        return 0;

    return Math.max(1, (int) Math.round(ability.getStatData("cooldown").getValue() * 20D));
}

public void onUnequip(SlotContext slotContext, ItemStack newStack, ItemStack stack) {
    super.onUnequip(slotContext, newStack, stack);

    if (stack.getItem() == newStack.getItem())
        return;

    EntityUtils.removeAttribute(slotContext.entity(), Attributes.MOVEMENT_SPEED, AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL, getMovementSpeedAttributeId(stack, slotContext));
}

public void inventoryTick(ItemStack stack, Level level, Entity entity, int slotId, boolean isSelected) {
    super.inventoryTick(stack, level, entity, slotId, isSelected);

    var timer = this.getHurtTimer(stack);

    if (timer > 0)
        this.setHurtTimer(stack, timer - 1);
}

public void handle(IPayloadContext ctx) {
    ctx.enqueueWork(() -> {
        var level = ctx.player().getCommandSenderWorld();

        if (level.getEntity(this.sourceId) instanceof ITargetableEntity source && level.getEntity(this.targetId) instanceof LivingEntity target)
            source.setTarget(target);
    });
}

public static void applyAttribute(LivingEntity entity, Holder<Attribute> attributeHolder, float value, AttributeModifier.Operation operation, ResourceLocation id) {
    var instance = entity.getAttribute(attributeHolder);

    if (hasAttribute(entity, attributeHolder, id))
        return;

    instance.addTransientModifier(new AttributeModifier(id, value, operation));
}

public static void removeAttribute(LivingEntity entity, Holder<Attribute> attributeHolder, net.minecraft.world.entity.ai.attributes.AttributeModifier.Operation operation, ResourceLocation id) {
    var instance = entity.getAttribute(attributeHolder);

    if (!hasAttribute(entity, attributeHolder, id))
        return;

    instance.removeModifier(new AttributeModifier(id, instance.getValue(), operation));
}

public static void resetAttribute(LivingEntity entity, Holder<Attribute> attributeHolder, float value, AttributeModifier.Operation operation, ResourceLocation id) {
    var attribute = entity.getAttribute(attributeHolder);

    if (attribute == null || attribute.getValue() != value) {
        EntityUtils.removeAttribute(entity, attributeHolder, operation, id);
        EntityUtils.applyAttribute(entity, attributeHolder, value, operation, id);
    }
}

public float beforeMeleeHit(IToolStackView tool, ModifierEntry modifier, ToolAttackContext context, float damage, float baseKnockback, float knockback) {
  // vanilla hack: apply fire so the entity drops the proper items on instant kill
  LivingEntity target = context.getLivingTarget();
  if (target != null && !target.isOnFire()) {
    target.setRemainingFireTicks(1);
  }
  return knockback;
}

public void onStoppedUsing(IToolStackView tool, ModifierEntry modifier, LivingEntity entity, int timeLeft) {
  if (!entity.level().isClientSide) {
    int chargeTime = getUseDuration(tool, modifier) - timeLeft;
    if (chargeTime > 0) {
      spit(tool, modifier, entity, chargeTime);
    }
  }
}

default void beforeReleaseUsing(IToolStackView tool, ModifierEntry modifier, LivingEntity entity, int useDuration, int timeLeft, ModifierEntry activeModifier) {
  if (!tool.isBroken() && condition().matches(tool, modifier)) {
    int chargeTime = getUseDuration(tool, modifier) - timeLeft;
    if (chargeTime > 0) {
      sling(tool, modifier, entity, chargeTime, activeModifier);
    }
  }
}

public int getUseDuration(ItemStack stack, LivingEntity entity) {
    var duration = super.getUseDuration(stack, entity);
    var multiplier = ChefHatItem.getMeatballConsumptionSpeedMultiplier(entity);

    if (multiplier <= 1D)
        return duration;

    return Math.max(1, (int) Math.ceil(duration / multiplier));
}

public void inventoryTick(ItemStack stack, Level level, Entity entity, int slotId, boolean isSelected) {
    super.inventoryTick(stack, level, entity, slotId, isSelected);

    if (level.isClientSide() || !(entity instanceof LivingEntity livingEntity) || livingEntity.tickCount % ((int) this.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("blink").getStatData("cooldown").getValue() * 20) != 0
            || this.getCharge(livingEntity, stack) >= this.getMaxCharge(livingEntity, stack))
        return;

    this.addCharge(livingEntity, stack, 1);
}

public static boolean attackEntity(IToolStackView tool, Player attacker, Entity target) {
  if (!canPerformAttack(tool)) {
    return false;
  }
  if (isAttackable(attacker, target)) {
    performAttack(tool, ToolAttackContext.attacker(attacker).target(target).defaultCooldown().applyAttributes().build());
  }
  return true;
}

public void removeModifier(ModifierId modifier, int level) {
  if (level <= 0) {
    throw new IllegalArgumentException("Invalid level, must be above 0");
  }
  ModifierNBT newModifiers = getUpgrades().withoutModifier(modifier, level);
  this.upgrades = newModifiers;
  nbt.put(TAG_UPGRADES, newModifiers.serializeToNBT());
  rebuildStats();
}

public InteractionResult onToolUse(IToolStackView tool, ModifierEntry modifier, Player player, InteractionHand hand, InteractionSource source) {
  if (condition.matches(tool, modifier) && !tool.isBroken() && tool.getHook(ToolHooks.INTERACTION).canInteract(tool, modifier.getId(), source)) {
    if (shoot(tool, modifier, player, player, Util.getSlotType(hand))) {
      GeneralInteractionModifierHook.addCooldown(tool, player, 1);
      return InteractionResult.sidedSuccess(player.level().isClientSide);
    }
  }
  return InteractionResult.PASS;
}

public void onLivingHurt(LivingEntity entity, EquipmentSlotAccess slot, DamageSource damageSource) {
    LivingEntity attacker = DamageSourceHelper.getAttacker(damageSource);
    if (attacker != null && !slot.isDisabledOrBroken() && entity.getRandom().nextDouble() < activationParams.strikeChance.get()) {
        if (applyEffect(entity, attacker)) {
            slot.addCooldown(activationParams.cooldown.get() * 20);
            slot.hurtAndBreak(activationParams.itemDamage.get());
        }
    }
}

public void removeModifier(ResourceLocation location) {
    var modifier = this.modifiers.remove(location);

    if(modifier == null) return;

    this.persistentModifiers.remove(modifier);
    this.getModifiersForOperation(modifier.operation()).remove(modifier);
    this.markChanged();
}

public void onUnequip(SlotContext slotContext, ItemStack newStack, ItemStack stack) {
    super.onUnequip(slotContext, newStack, stack);

    if (stack.getItem() == newStack.getItem())
        return;

    var entity = slotContext.entity();

    EntityUtils.removeAttribute(entity, Attributes.MAX_ABSORPTION, AttributeModifier.Operation.ADD_VALUE, CommonEvents.ATTRIBUTE);
}

public static AttributeInstance disableKnockback(@Nullable LivingEntity living) {
  if (living != null) {
    AttributeInstance instance = living.getAttribute(Attributes.KNOCKBACK_RESISTANCE);
    if (instance != null && !instance.hasModifier(ANTI_KNOCKBACK_MODIFIER)) {
      instance.addTransientModifier(ANTI_KNOCKBACK_MODIFIER);
      return instance;
    }
  }
  return null;
}

private static void extendShieldWindow(ItemStack stack, ShieldOfRetaliationItem relic, Player player) {
    var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("retaliation");

    if (!ability.getRankModifierData("projectile").isEnabled())
        return;

    var extension = Math.max(1, (int) Math.round(ability.getStatData("extension").getValue() * 20D));

    setActiveTicks(stack, getActiveTicks(stack) + extension);
    setActiveDuration(stack, getActiveDuration(stack) + extension);
}

public void onUnequip(SlotContext slotContext, ItemStack newStack, ItemStack stack) {
    super.onUnequip(slotContext, newStack, stack);

    if (stack.getItem() == newStack.getItem())
        return;

    var entity = slotContext.entity();

    for (var instance : entity.getAttributes().attributes.values())
        EntityUtils.removeAttribute(entity, instance.getAttribute(), AttributeModifier.Operation.ADD_MULTIPLIED_TOTAL, getGluttonyAttributeId(stack, instance.getAttribute(), slotContext));
}

public boolean startInteract(IToolStackView tool, ModifierEntry modifier, Player player, EquipmentSlot slot, TooltipKey keyModifier) {
  if (keyModifier == TooltipKey.NORMAL && condition.matches(tool, modifier) && !tool.isBroken() && !player.hasEffect(TinkerModifiers.fireballCooldownEffect.get())) {
    if (shoot(tool, modifier, player, player, slot)) {
      if (!player.level().isClientSide) {
        player.addEffect(new MobEffectInstance(TinkerModifiers.fireballCooldownEffect.get(), GeneralInteractionModifierHook.getDrawtime(tool, player, 1)));
      }
      return true;
    }
  }
  return false;
}

public static void onAbilityModeSwitch(AbilityModeSwitchEvent event) {
    var entity = event.getBearer();

    for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.MIDNIGHT_MANTLE.get())) {
        var relic = (MidnightMantleItem) stack.getItem();

        if (!relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("phase").canPlayerUse(entity) || !relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("phase").getRankModifierData("switch").isEnabled())
            continue;

        relic.setPhaseDuration(stack, (int) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("phase").getStatData("duration").getValue() * 20);
    }
}

public static void onLivingHurt(LivingEntity target, DamageSource damageSource) {
    LivingEntity attacker = DamageSourceHelper.getAttacker(damageSource);
    if (attacker != null && DamageSourceHelper.isMeleeAttack(damageSource) && !attacker.level().isClientSide()) {
        ModDataComponents.ATTACK_EFFECTS.on(attacker).iterate((effect, slot) -> {
            if (effect.chance().get() > attacker.getRandom().nextDouble()) {
                target.addEffect(effect.provider().createEffect(), attacker);
                slot.addCooldown(effect.cooldown.get() * 20);
                slot.hurtAndBreak(effect.itemDamage.get());
            }
        });
    }
}

private static void onInteract(LivingEntity entity) {
    if (entity.getCommandSenderWorld().isClientSide())
        return;

    for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.LEAFY_MANTLE.get())) {
        var relic = (LeafyMantleItem) stack.getItem();

        if (!relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("camouflage").canPlayerUse(entity) || !relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("camouflage").getRankModifierData("disappearance").isEnabled())
            continue;

        ServerScheduler.schedule(1, () -> relic.setInvisibilityCooldown(stack, (int) (relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("camouflage").getStatData("cooldown").getValue() * 20)));
    }
}

public void applyEffectTick(LivingEntity living, int amplifier) {
  ModDataNBT data = PersistentDataCapability.getOrWarn(living);
  if (data.contains(KEY, Tag.TAG_COMPOUND)) {
    CompoundTag tag = data.getCompound(KEY);
    ResourceLocation dimension = ResourceLocation.tryParse(tag.getString("dimension"));
    // no teleporting if you switched dimensions
    // TODO: look into cross dimensional teleport, its doable with entity#teleportTo
    if (dimension != null && dimension.equals(living.level().dimension().location())) {
      BlockPos pos = NbtUtils.readBlockPos(tag);
      TeleportHelper.tryTeleport(new ReturningTeleportEvent(living, pos.getX(), pos.getY(), pos.getZ()));
    }
  }
}

public void wornTick(ReplenishHungerOnGrass ability, EquipmentSlotAccess slot, LivingEntity entity, boolean isOnCooldown, boolean isDisabled) {
    if (!isDisabled && !isOnCooldown && ability.isNonCosmetic() && entity instanceof ServerPlayer player
            && player.onGround()
            && player.getFoodData().needsFood()
            && entity.tickCount % (Math.max(1, ability.replenishingDuration().get()) * 20) == 0
            && entity.getBlockStateOn().is(ModTags.ROOTED_BOOTS_GRASS)
    ) {
        player.getFoodData().eat(1, 0.5F);
        PostEatingEffect.applyEffects(entity, 1);
        PlaySoundAtPlayerPacket.sendSound(player, SoundEvents.GENERIC_EAT, 0.5F, 0.8F + entity.getRandom().nextFloat() * 0.4F);
        slot.hurtAndBreak(ability.itemDamage.get());
    }
}

public static void updateHasTickingAbilities(LivingEntity entity) {
    boolean shouldTick = EquipmentSlotManager.reduceEquipment(entity, false, false, false, (hasTickingAbilities, slotAccess) -> {
        for (ModDataComponents.TickingAbility<?, ?> entry : ModDataComponents.TICKING_ABILITIES) {
            // abilities are tracked as ticking even when they're cosmetic,
            // since updating the config does not trigger onItemChanged
            if (slotAccess.get().has(entry.type().get())) {
                return true;
            }
        }
        return hasTickingAbilities;
    });
    ((LivingEntityExtensions) entity).artifacts$setTickingAbilities(shouldTick);
}

public void handleReapplyingEffects(LivingEntity livingEntity, long time) {
    for (var i : delayedMobEffects.keySet()) {
        var lastApply = delayToTimer.getOrDefault(i, null);

        if ((lastApply == null) || time - lastApply > i) {
            for (var mobEffectInstance : delayedMobEffects.get(i)) {
                livingEntity.addEffect(mobEffectInstance);
            }
        }

        delayToTimer.put(i, time);
    }
}

public void handleRemovingEffects(LivingEntity livingEntity) {
    for (List<MobEffectInstance> value : delayedMobEffects.values()) {
        for (MobEffectInstance mobEffectInstance : value) {
            livingEntity.removeEffect(mobEffectInstance.getEffect());
        }
    }

    for (MobEffectInstance mobEffectInstance : this.constantMobEffects) {
        livingEntity.removeEffect(mobEffectInstance.getEffect());
    }

    delayToTimer.clear();
}

public void handle(IPayloadContext ctx) {
    ctx.enqueueWork(() -> {
        var player = ctx.player();

        CuriosApi.getCuriosInventory(player).flatMap(inventory -> inventory.findCurio(this.getIdentifier(), this.getIndex())).ifPresent(slot -> {
            var stack = slot.stack();

            if (!(stack.getItem() instanceof KineticBeltItem relic))
                return;

            relic.setActive(stack, active);
        });
    });
}

public static InteractionResult onChestplateUse(Player player, ItemStack chestplate, InteractionHand hand) {
  if (player.getCooldowns().isOnCooldown(chestplate.getItem())) {
    return InteractionResult.PASS;
  }

  // first, run the modifier hook
  ToolStack tool = ToolStack.from(chestplate);
  for (ModifierEntry entry : tool.getModifierList()) {
    InteractionResult result = entry.getHook(ModifierHooks.GENERAL_INTERACT).onToolUse(tool, entry, player, hand, InteractionSource.ARMOR);
    if (result.consumesAction()) {
      return result;
    }
  }
  return InteractionResult.PASS;
}

public void onUnequip(IToolStackView tool, ModifierEntry modifier, EquipmentChangeContext context) {
  // must actually be removing, and run on both sides so we don't need to sync
  if (condition.matches(tool, modifier) && EquipmentChangeModifierHook.didUnequip(tool, context)) {
    LivingEntity entity = context.getEntity();
    float percent = this.percent.compute(modifier);
    if (percent != 0) {
      // iterate all matching effects, updating the duration
      for (MobEffectInstance instance : entity.getActiveEffects()) {
        if (!instance.isInfiniteDuration() && instance.getEffect().getCategory() == this.category && !instance.getCurativeItems().isEmpty()) {
          instance.duration = Math.max(1, (int) (instance.duration * (1 - percent)));
        }
      }
    }
  }
}

private void applyEffect(IToolStackView tool, ModifierEntry modifier, LivingEntity attacker, @Nullable Player playerAttacker, Entity target, @Nullable LivingEntity livingTarget, @Nullable Projectile projectile) {
  if (condition.matches(tool, modifier)) {
    FluidStack fluid = TANK_HELPER.getFluid(tool);
    if (!fluid.isEmpty()) {
      FluidEffects recipe = FluidEffectManager.INSTANCE.find(fluid.getFluid());
      if (recipe.hasEntityEffects()) {
        int consumed = recipe.applyToEntity(fluid, this.level.compute(modifier.getEffectiveLevel()), FluidEffectContext.builder(attacker.level()).user(attacker, playerAttacker).projectile(projectile).target(target, livingTarget), FluidAction.EXECUTE);
        if (consumed > 0 && ModifierUtil.consumesResources(playerAttacker)) {
          spawnParticles(target, fluid);
          fluid.shrink(consumed);
          TANK_HELPER.setFluid(tool, fluid);
        }
      }
    }
  }
}

public void toggleSwimFlying(Player player) {
    if (isSwimFlying || SwimInAir.canSwim(player)) {
        isSwimFlying = !isSwimFlying;
        if (!isSwimFlying && !player.level().isClientSide() && !player.onGround()) {
            if (!player.isSilent()) {
                player.level().playSound(null, player.getX(), player.getY(), player.getZ(),
                        ModSoundEvents.POP.value(), player.getSoundSource(), 1F, 1F
                );
            }
            // Add minimum 0.25s cooldown to prevent player from immediately entering fly state again
            ModDataComponents.SWIM_IN_AIR.on(player).iterate((ability, slot) ->
                    slot.addCooldown(Math.max(5, ability.cooldown().get() * 20))
            );
        }
    }
}

public Multimap<Holder<Attribute>, AttributeModifier> getAttributeModifiers(SlotContext slotContext, ResourceLocation id, ItemStack stack) {
    Multimap<Holder<Attribute>, AttributeModifier> modifiers = LinkedHashMultimap.create();

    var attributes = this.getRelicAttributeModifiers(slotContext.entity(), stack);
    var slots = this.getSlotModifiers(slotContext.entity(), stack);

    if (attributes != null)
        attributes.getAttributes().forEach(attribute ->
                modifiers.put(attribute.getAttribute(), new AttributeModifier(
                        ResourceLocation.fromNamespaceAndPath(Relics.MODID, BuiltInRegistries.ITEM.getKey(stack.getItem()).getPath() + "_" + BuiltInRegistries.ATTRIBUTE.getKey(attribute.getAttribute().value()).getPath() + "_" + slotContext.identifier() + "_" + slotContext.index()),
                        attribute.getMultiplier(), attribute.getOperation())));

    if (slots != null)
        slots.getModifiers().forEach((slot, count) -> CuriosApi.addSlotModifier(modifiers, slot, id, count, AttributeModifier.Operation.ADD_VALUE));

    return modifiers;
}

public boolean cycleMode(Player player) {
    var template = getTemplate();

    if (template == null || template.getModes().isEmpty())
        return false;

    var stack = this.getAbilitiesData().getRelicData().getStack();
    var event = new AbilityModeSwitchEvent(player, stack, this.getId(), getMode(), getNextMode());

    NeoForge.EVENT_BUS.post(event);

    if (event.isCanceled())
        return false;

    setMode(event.getToMode());

    return true;
}

public void handle(IPayloadContext ctx) {
    ctx.enqueueWork(() -> {
        var player = ctx.player();

        CuriosApi.getCuriosInventory(player).flatMap(inventory -> inventory.findCurio(this.getIdentifier(), this.getIndex())).ifPresent(slot -> {
            var stack = slot.stack();

            if (!(stack.getItem() instanceof RingOfTheSevenDeadlySinsItem relic))
                return;

            if (player.hurt(player.level().damageSources().magic(), 1F)) {
                relic.addHurtTimer(stack, 40);

                relic.getRelicData(player, stack).getStatisticData().getMetricData("unequip_attempts").addValue(1);
            }
        });
    });
}

static void onChestplateAttack(AttackEntityEvent event) {
  // Carry On is dumb and fires the attack entity event when they are not attacking entities, causing us to punch instead
  // they should not be doing that, but the author has not done anything to fix it, so just use a hacky check
  if (event.getClass() == AttackEntityEvent.class) {
    Player attacker = event.getEntity();
    if (attacker.getMainHandItem().isEmpty()) {
      ItemStack chestplate = attacker.getItemBySlot(EquipmentSlot.CHEST);
      if (chestplate.is(TinkerTags.Items.UNARMED)) {
        ToolStack tool = ToolStack.from(chestplate);
        Entity target = event.getTarget();
        if (!tool.isBroken() && ToolAttackUtil.isAttackable(attacker, target)) {
          ToolAttackUtil.performAttack(tool, ToolAttackContext.attacker(attacker).target(target).slot(EquipmentSlot.CHEST, InteractionHand.MAIN_HAND).defaultCooldown().toolAttributes(tool).build());
          event.setCanceled(true);
        }
      }
    }
  }
}

public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
    var stack = player.getItemInHand(hand);
    var ticks = this.getParryTicks(player, stack);

    if (ticks <= 0 || isReleaseLocked(stack) || player.getCooldowns().isOnCooldown(this))
        return InteractionResultHolder.pass(stack);

    if (!level.isClientSide()) {
        setActiveTicks(stack, ticks);
        setActiveDuration(stack, ticks);
        setSucceeded(stack, false);
        setMissed(stack, false);
        setReleaseLocked(stack, false);
        setCapturedProjectiles(stack, List.of());
    }

    player.startUsingItem(hand);

    return InteractionResultHolder.consume(stack);
}

private void detonate(@Nullable LivingEntity owner, boolean byOwner) {
    if (this.level().isClientSide())
        return;

    var radius = this.getStunRadius();
    var radiusSqr = radius * radius;
    var stunnedTargets = 0;

    for (var target : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(radius), entity -> this.canAffectTarget(entity, owner))) {
        if (target.distanceToSqr(this) <= radiusSqr) {
            TargetingUtils.addHarmfulEffect(target, new MobEffectInstance(RelicsMobEffects.STUN, this.getStunDuration(), 0, false, false), owner, this.getStack(), "illusion");
            TargetingUtils.addHarmfulEffect(target, new MobEffectInstance(RelicsMobEffects.GLITCH, this.getStunDuration(), 0, false, false), owner, this.getStack(), "illusion");

            stunnedTargets++;
        }
    }

    this.addDetonationExperience(owner, byOwner, stunnedTargets);
    this.spawnGlitchBurst();
    this.discard();
}

public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
    var stack = player.getItemInHand(hand);

    if (this.getRememberedTicks(player, stack) <= 0 || stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_PATH, List.<PathPointData>of()).size() < 2 || this.getCooldown(stack) > 0)
        return InteractionResultHolder.pass(stack);

    if (!level.isClientSide()) {
        setRewindCursor(stack, -1D);

        this.setCooldown(stack, 0);

        var ability = this.getRelicData(player, stack).getAbilitiesData().getAbilityData("rewind");

        if (ability.canPlayerUse(player))
            ability.getStatisticData().getMetricData("activations").addValue(1D);
    }

    player.startUsingItem(hand);

    return InteractionResultHolder.consume(stack);
}

public void handle(IPayloadContext ctx) {
    ctx.enqueueWork(() -> {
        var player = ctx.player();
        var stack = this.resolveStack(player);

        if (!(stack.getItem() instanceof IRelicItem relic))
            return;

        var synergyData = relic.getRelicData(player, stack).getAbilitiesData().getSynergyData(this.synergy);

        if (synergyData == null || !synergyData.isUnlocked() || !synergyData.getTemplate().getModes().contains(this.mode))
            return;

        var event = new SynergyModeSwitchEvent(player, stack, this.synergy, synergyData.getMode(), this.mode);

        NeoForge.EVENT_BUS.post(event);

        if (!event.isCanceled())
            synergyData.setMode(event.getToMode());
    });
}

public static boolean attackEntity(IToolStackView tool, LivingEntity attackerLiving, InteractionHand hand,
                                   Entity targetEntity, DoubleSupplier cooldownFunction, boolean isExtraAttack, EquipmentSlot sourceSlot) {
  // false to defer to vanilla
  if (!canPerformAttack(tool)) {
    return false;
  }
  // return true to indicate we wish to cancel the attack
  if (!isAttackable(attackerLiving, targetEntity)) {
    return true;
  }
  ToolAttackContext.Builder builder = ToolAttackContext.attacker(attackerLiving).target(targetEntity).slot(sourceSlot, hand).cooldown((float)cooldownFunction.getAsDouble());
  if (sourceSlot == EquipmentSlot.MAINHAND) {
    builder.applyAttributes();
  } else {
    builder.toolAttributes(tool);
  }
  if (isExtraAttack) {
    builder.extraAttack();
  }
  boolean success = performAttack(tool, builder.build());
  return success || !isExtraAttack;
}

public void curioTick(SlotContext slotContext, ItemStack stack) {
    super.curioTick(slotContext, stack);

    var entity = slotContext.entity();

    if (entity.level().isClientSide())
        return;

    this.tickFogTrail(entity, stack);
    this.tickGaze(entity, stack);

    if (this.getEscapeCooldown(stack) > 0)
        this.setEscapeCooldown(stack, this.getEscapeCooldown(stack) - 1);

    var spectralEscape = this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("spectral_escape");

    if (spectralEscape.canPlayerUse(entity)
            && entity.hasEffect(RelicsMobEffects.FLIGHT)
            && entity.hasEffect(RelicsMobEffects.IMMORTALITY)) {
        spectralEscape.getStatisticData().getMetricData("spectral_form_duration").addValue(1D / 20D);
        this.getRelicData(entity, stack).getLevelingData().addExperience("spectral_escape", "spectral_form", 1D / 20D);
    }
}

public boolean onProjectileHitEntity(ModifierNBT modifiers, ModDataNBT persistentData, ModifierEntry modifier, Projectile projectile, EntityHitResult hit, @Nullable LivingEntity attacker, @Nullable LivingEntity target) {
  ResourceLocation key = modifier.getId();
  if (target != null && persistentData.contains(key, Tag.TAG_STRING)) {
    ResourceLocation id = ResourceLocation.tryParse(persistentData.getString(key));
    if (id != null) {
      Entity source = projectile.getEffectSource();
      int divisor = getDivisor(modifier);
      int oldHurtTime = target.invulnerableTime;
      target.invulnerableTime = 0;
      // not a problem if the ID is invalid, will just do nothing
      for (MobEffectInstance instance : BuiltInRegistries.POTION.get(id).getEffects()) {
        MobEffect effect = instance.getEffect();
        if (effect.isInstantenous()) {
          effect.applyInstantenousEffect(projectile, projectile.getOwner(), target, instance.getAmplifier(), 1f / (divisor * 0.75f));
        } else {
          target.addEffect(new MobEffectInstance(instance.getEffect(), Math.max(instance.mapDuration(i -> i / divisor), 1), instance.getAmplifier(), instance.isAmbient(), instance.isVisible()), source);
        }
      }
      target.invulnerableTime = oldHurtTime;
    }
  }
  return false;
}

public static ItemStack applySmeltOresAbility(ItemStack original, @Nullable Entity entity, @Nullable BlockState state, Consumer<Integer> experienceConsumer) {
    if (entity instanceof LivingEntity livingEntity
            && livingEntity.level() instanceof ServerLevel serverLevel
            && ModDataComponents.AUTO_SMELT.on(livingEntity).findAny()
            && state != null
            && state.is(ModTags.ORES)
    ) {
        if (original.is(ModTags.RAW_MATERIALS)) {
            SingleRecipeInput input = new SingleRecipeInput(original);
            Optional<RecipeHolder<SmeltingRecipe>> recipe = serverLevel
                    .recipeAccess()
                    .getRecipeFor(RecipeType.SMELTING, input, livingEntity.level());
            if (recipe.isPresent()) {
                ItemStack smeltingResult = recipe.get().value().assemble(input);
                if (!smeltingResult.isEmpty()) {
                    experienceConsumer.accept(getExperience(recipe.get().value().experience()));
                    return smeltingResult.copyWithCount(smeltingResult.getCount() * original.getCount());
                }
            }
        }
    }
    return original;
}

