public void releaseUsing(ItemStack stack, Level world, LivingEntity living, int durationRemaining) {

    if (!world.isClientSide && durationRemaining < 0 && getLoadedAmmoCount(stack) < maxCharges && loadAmmo(living, stack)) {
        setCharged(stack, true);
        world.playSound(null, living.getX(), living.getY(), living.getZ(), SoundEvents.CROSSBOW_LOADING_END, living instanceof Player ? SoundSource.PLAYERS : SoundSource.HOSTILE, 1.0F, 1.0F / (world.random.nextFloat() * 0.5F + 1.0F) + 0.2F);
    }
}

public static void updateInsulationAttributeModifiers(LivingEntity entity, ItemStack from, ItemStack to, Insulation.Slot slot)
{
    for (InsulatorData insulatorData : ItemInsulationManager.getInsulatorsForStack(from, slot))
    {   entity.getAttributes().removeAttributeModifiers(insulatorData.attributes().getMap());
    }
    for (InsulatorData insulatorData : RequirementHolder.filterValid(ItemInsulationManager.getInsulatorsForStack(to, slot), to, entity))
    {   entity.getAttributes().addTransientAttributeModifiers(insulatorData.attributes().getMap());
    }
}

public boolean hurtEnemy(ItemStack stack, LivingEntity target, LivingEntity attacker) {

    if (useEnergy(stack, isEmpowered(stack), attacker) && isEmpowered(stack)) {
        attacker.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED, 40, 0));
        if (attacker.hasEffect(MobEffects.DAMAGE_BOOST)) {
            attacker.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, attacker.getEffect(MobEffects.DAMAGE_BOOST).getDuration() + 10, 0));
        }
        attacker.setSprinting(true);
    }
    return true;
}

public void updateEntity(LivingEntity entity, Data extraData) {
    modifiers.forEach((uuid, data) -> {
        AttributeModifier newMod = data.modifierFunc.apply(entity, extraData);
        AttributeInstance attribute = entity.getAttribute(data.attribute.get());
        if (attribute == null) return;
        attribute.removeModifier(uuid);
        if (newMod != null) {
            attribute.addTransientModifier(newMod);
        }
    });
}

public InteractionResultHolder<ItemStack> use(Level world, Player player, InteractionHand hand) {

    ItemStack stack = player.getItemInHand(hand);
    ItemStack chest = player.getItemBySlot(EquipmentSlot.CHEST);
    if (chest.getItem() instanceof FluxElytraItem elytra) {
        elytra.setMode(chest, getMode(stack));
        if (elytra.boost(chest, player)) {
            return InteractionResultHolder.sidedSuccess(stack, world.isClientSide());
        }
    }
    return InteractionResultHolder.fail(stack);
}

public void onModeChange(Player player, ItemStack stack) {

    ItemStack chest = player.getItemBySlot(EquipmentSlot.CHEST);
    if (chest.getItem() instanceof FluxElytraItem elytra) {
        elytra.setMode(chest, getMode(stack));
        if (isEmpowered(stack)) {
            player.level.playSound(null, player.blockPosition(), SOUND_EMPOWER.get(), SoundSource.PLAYERS, 0.4F, 1.0F);
        } else {
            player.level.playSound(null, player.blockPosition(), SOUND_QUELL.get(), SoundSource.PLAYERS, 0.2F, 0.6F);
        }
    } else {
        setMode(stack, isEmpowered(stack) ? 0 : 1);
    }
}

public InteractionResultHolder<ItemStack> use(Level world, Player player, InteractionHand hand) {

    ItemStack stack = player.getItemInHand(hand);
    if (hasEnergy(stack, false)) {
