public void onLeftClick(Player player, ItemStack stack) {

    if (isCharged(stack)) {
        if (isEmpowered(stack)) {
            float xRot = player.xRot;
            int count = getLoadedAmmoCount(stack);
            for (int i = (1 - count) / 2; i <= count / 2; ++i) {
                player.xRot = xRot - 10 * i;
                shootLoadedAmmo(player.level, player, InteractionHand.MAIN_HAND, stack);
            }
            player.xRot = xRot;
            setCharged(stack, false);
        } else if (shootLoadedAmmo(player.level, player, InteractionHand.MAIN_HAND, stack) && getLoadedAmmoCount(stack) <= 0) {
            setCharged(stack, false);
        }
    }
}

public ItemStack finishUsingItem(ItemStack stack, Level level, LivingEntity entity)
{   double amount = stack.getOrCreateTag().getDouble(FilledWaterskinItem.NBT_TEMPERATURE) * (ConfigSettings.WATERSKIN_CONSUME_STRENGTH.get() / 50d);
    Temperature.addModifier(entity, new WaterskinTempModifier(amount / (100 * stack.getMaxDamage())).expires(100), Temperature.Trait.CORE, Placement.LAST);
    if (entity instanceof Player player && player.isCreative())
    {   return stack;
    }
    else
    {
        if (getDurability(stack) <= 1)
        {   return consumeWaterskin(stack, entity, entity.getUsedItemHand());
        }
        else
        {   stack.setDamageValue(stack.getDamageValue() + 1);
            return stack;
        }
    }
}

public InteractionResult useOn(UseOnContext context) {

    Player player = context.getPlayer();
    ItemStack stack = context.getItemInHand();
    int energy = getEnergyPerUse(true) * 2;
    if (player == null || !player.onGround() || !isEmpowered(stack) || !(hasEnergy(stack, energy) || player.abilities.instabuild)) {
        return InteractionResult.FAIL;
    }
    Level world = context.getLevel();
    BlockPos pos = context.getClickedPos();
    BlockState state = world.getBlockState(pos);
    if (world.isClientSide) {
        world.playSound(player, pos, state.getSoundType(world, pos, player).getBreakSound(), SoundSource.BLOCKS, 1.0F, 1.0F);
    } else if (world.addFreshEntity(new FluxHammerShockwave(world, Vec3.atBottomCenterOf(pos.above()), player))) {
        useEnergy(stack, energy, player.abilities.instabuild);
        player.getCooldowns().addCooldown(this, getSlamCooldown(stack));
    }
    return InteractionResult.SUCCESS;
}

public boolean onLeftClickEntity(ItemStack stack, Player player, Entity entity) {
    if (entity instanceof Player && !(this instanceof DislocatorAdvanced)) {
        messageUser(player, Component.translatable("dislocate.draconicevolution.player_need_advanced").withStyle(ChatFormatting.RED));
        return true;
    }

    if (!(player.level() instanceof ServerLevel serverLevel) || !(entity instanceof LivingEntity) || player.getCooldowns().getCooldownPercent(this, 0) > 0) {
        return true;
    }
    TargetPos location = getTargetPos(stack, player.level());
    ServerLevel targetLevel = serverLevel.getServer().getLevel(location.getDimension());
    if (entity.level() != targetLevel && !entity.canChangeDimensions(entity.level(), targetLevel)) {
        return true;
    }

    player.getCooldowns().addCooldown(this, 20);
    dislocateEntity(stack, player, entity, location);
    stack.hurtAndBreak(1, serverLevel, player, e -> {});
    if (location != null) {
        messageUser(player, Component.translatable("dislocate.draconicevolution.entity_sent_to").append(" "+ location.getReadableName(false)).withStyle(ChatFormatting.GREEN));
    }

    return true;
}

public static void handleFillWaterskin(Player player, ItemStack thisStack, InteractionHand usedHand, BlockPos filledAtPos, FluidStack filledFluid)
{
    Level level = player.level();
    ItemStack filledWaterskin = getFilledItem(thisStack, level, filledAtPos);
    WaterskinEvent.Fill event = new WaterskinEvent.Fill(thisStack, filledWaterskin, player, level, filledAtPos, filledFluid);
    MinecraftForge.EVENT_BUS.post(event);
    filledWaterskin = event.getResultWaterskin();

    //Replace 1 of the stack with a FilledWaterskinItem
    if (thisStack.getCount() > 1 || player.getAbilities().instabuild)
    {
        if (!player.addItem(filledWaterskin))
        {
            ItemEntity itementity = player.drop(filledWaterskin, false);
            if (itementity != null)
            {   itementity.setNoPickUpDelay();
                itementity.setThrower(player.getUUID());
            }
        }
        thisStack.shrink(1);
    }
    else
    {   player.setItemInHand(usedHand, filledWaterskin);
    }
    player.swing(usedHand);
    player.getCooldowns().addCooldown(ModItems.FILLED_WATERSKIN, 10);
    player.awardStat(Stats.ITEM_USED.get(thisStack.getItem()));
    WorldHelper.playEntitySound(ModSounds.WATERSKIN_FILL, player, SoundSource.PLAYERS, 2f, (float) Math.random() / 5 + 0.9f);
}

public boolean plungeAttack(Level world, LivingEntity attacker, ItemStack stack) {

    if (attacker.fallDistance <= attacker.getMaxFallDistance() || !isEmpowered(stack) || !useEnergy(stack, true, attacker)) {
        return false;
    }
    float range = getPlungeRange(attacker.fallDistance);
    if (world.isClientSide) {
        // TODO circle particle
        world.addParticle(new CylindricalParticleOptions(CoreParticles.BLAST_WAVE.get(), range * 2.0F, range * 3.0F, 0, VFXHelper.windColor(world.random).toRGBA(), 1.5F), attacker.getX(), attacker.getY(), attacker.getZ(), 0, 0, 0);
        return true;
    }
    if (Utils.getItemEnchantmentLevel(Enchantments.CHANNELING, stack) > 0) {
        if (world.canSeeSky(attacker.blockPosition()) && world instanceof ServerLevel && world.isThundering()) {
            attacker.addEffect(new MobEffectInstance(LIGHTNING_RESISTANCE.get(), 40, 0, false, false));
            Utils.spawnLightningBolt(world, attacker.blockPosition(), attacker);
        }
    }
    double r2 = range * range;
    boolean hit = false;
    for (Entity target : world.getEntities(attacker, attacker.getBoundingBox().inflate(range, 1, range), EntitySelector.NO_CREATIVE_OR_SPECTATOR)) {
        if (attacker.distanceToSqr(target) <= r2) {
            hit |= target.hurt(IFluxItem.fluxDirectDamage(attacker), getPlungeAttackDamage(attacker, stack));
        }
    }
    if (hit) {
        world.playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(), SoundEvents.TRIDENT_RETURN, SoundSource.PLAYERS, 10.0F, 1.0F);
    } else {
        world.playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(), SoundEvents.TRIDENT_HIT_GROUND, SoundSource.PLAYERS, 3.0F, 1.0F);
    }
    return hit;
}

public InteractionResult useOn(UseOnContext context)
{
    Level level = context.getLevel();
    BlockPos pos = context.getClickedPos();
    BlockState state = level.getBlockState(pos);
    Player player = context.getPlayer();

    if (state.is(Blocks.CAULDRON) || state.is(Blocks.WATER_CAULDRON))
    {
        boolean hasWater = state.is(Blocks.WATER_CAULDRON);
        // Fill cauldron
        int waterLevel = hasWater ? state.getValue(LayeredCauldronBlock.LEVEL) : 0;
        if (waterLevel >= 3) return InteractionResult.PASS;
        state = hasWater
                ? state.setValue(LayeredCauldronBlock.LEVEL, waterLevel + 1)
                : Blocks.WATER_CAULDRON.defaultBlockState().setValue(LayeredCauldronBlock.LEVEL, 1);
        level.setBlock(pos, state, 3);
        // Pouring sound / visuals
        if (!level.isClientSide)
        {   level.playSound(null, pos, ModSounds.WATERSKIN_FILL, SoundSource.BLOCKS, 2f, (float) Math.random() / 5 + 0.9f);
            WorldHelper.spawnParticleBatch(level, ParticleTypes.SPLASH, pos.getX() + 0.5, pos.getY() + 0.65, pos.getZ() + 0.5, 0.5, 0.5, 0.5, 10, 0);
        }
        // Consume waterskin
        if (player != null)
        {   consumeWaterskin(context.getItemInHand(), player, context.getHand());
            player.getCooldowns().addCooldown(ModItems.WATERSKIN, 10);
        }
        return InteractionResult.SUCCESS;
    }
    return InteractionResult.PASS;
}

public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
    ItemStack stack = player.getItemInHand(hand);
    if (!(level instanceof ServerLevel serverLevel)) {
        return new InteractionResultHolder<>(InteractionResult.PASS, stack);
    }

    TargetPos targetPos = getTargetPos(stack, level);

    if (player.isShiftKeyDown()) {
        if (targetPos == null) {
            setLocation(stack, targetPos = TargetPos.of(player));
            messageUser(player, Component.translatable("dislocate.draconicevolution.bound_to").append("{" + targetPos.getReadableName(false) + "}").withStyle(ChatFormatting.GREEN));
        } else {
            messageUser(player, Component.translatable("dislocate.draconicevolution.already_bound").withStyle(ChatFormatting.RED));
        }
        return new InteractionResultHolder<>(InteractionResult.PASS, stack);
    } else {
        if (targetPos == null) {
            messageUser(player, Component.translatable("dislocate.draconicevolution.not_set").withStyle(ChatFormatting.RED));
            return new InteractionResultHolder<>(InteractionResult.PASS, stack);
        }
        if (player.getHealth() > 2 || player.getAbilities().instabuild) {
            player.getCooldowns().addCooldown(this, 20);
            dislocateEntity(stack, player, player, targetPos);
            stack.hurtAndBreak(1, serverLevel, player, e -> {});

            if (!player.getAbilities().instabuild) {
                player.setHealth(player.getHealth() - 2);
            }
        } else {
            messageUser(player, Component.translatable("dislocate.draconicevolution.low_health").withStyle(ChatFormatting.RED));
        }
        return new InteractionResultHolder<>(InteractionResult.PASS, stack);
    }
}

public static void onEatFood(LivingEntityUseItemEvent.Finish event)
{
    ItemStack item = event.getItem();
    if (event.getEntity() instanceof Player player
    && (item.getUseAnimation() == UseAnim.DRINK || item.getUseAnimation() == UseAnim.EAT)
    && !event.getEntity().level().isClientSide)
    {
        // If food item defined in config
        for (FoodData foodData : ConfigSettings.FOOD_TEMPERATURES.get().get(item.getItem()))
        {
            if (foodData != null && foodData.test(item))
            {
                double temperature = foodData.temperature(item, player);
                int duration = foodData.duration(item, player);
                Trait modTrait = duration > 0 ? Trait.BASE : Trait.CORE;
                // Custom class for soul sprouts
                FoodTempModifier foodModifier = item.getItem() == ModItems.SOUL_SPROUT
                                                ? new SoulSproutTempModifier(temperature)
                                                : new FoodTempModifier(temperature);
                // Store the item ID & duration of the TempModifier
                foodModifier.getNBT().putString("item", ForgeRegistries.ITEMS.getKey(item.getItem()).toString());
                foodModifier.getNBT().putInt("duration", duration);
                // Set duration & tick rate
                foodModifier.expires(duration).tickRate(duration);
                // Add the TempModifier
                Placement placement = Placement.LAST.limitDuplicates(Matcher.EQUALS, foodData.stackLimit(item, player))
                                      .orElse(Placement.of(Mode.REPLACE, Order.FIRST, foodModifier::equals));
                Temperature.addModifier(player, foodModifier, modTrait, placement);
                foodData.modifiers().forEach((trait, modifiers) ->
                {   modifiers.forEach(modifier -> Temperature.addModifier(player, modifier.get(), trait, placement));
                });
            }
        }
    }
}

public static void handleWaterFreezingFire(TickEvent.PlayerTickEvent event)
{
    Player player = event.player;

    // Water / Rain
    if (!player.level().isClientSide && event.phase == TickEvent.Phase.START)
    {
        if (player.tickCount % 5 == 0)
        {
            if (!player.isSpectator() && (WorldHelper.isInWater(player) || player.tickCount % 40 == 0
            && WorldHelper.isRainingAt(player.level(), player.blockPosition())))
            {   Temperature.addModifier(player, new WaterTempModifier().tickRate(5), Trait.WORLD, Placement.LAST.noDuplicates(Matcher.SAME_CLASS));
            }

            if (player.isFreezing())
            {   Temperature.replaceOrAddModifier(player, new FreezingTempModifier(), Trait.BASE, Matcher.SAME_CLASS);
            }
        }

        if (player.isFreezing() && player.getTicksFrozen() > 0)
        {
            AtomicReference<Double> insulation = new AtomicReference<>((double) 0);
            boolean hasIcePotion = player.hasEffect(ModEffects.ICE_RESISTANCE) && ConfigSettings.ICE_RESISTANCE_ENABLED.get();

            if (!hasIcePotion)
            {
                Temperature.getModifier(player, Trait.RATE, ArmorInsulationTempModifier.class).ifPresent(insulModifier ->
                {   insulation.updateAndGet(v -> (v + insulModifier.getNBT().getDouble("Hot") + insulModifier.getNBT().getDouble("Cold")));
                });
            }

            if (!(hasIcePotion || insulation.get() > 0) && (player.tickCount % Math.max(1, 37 - insulation.get())) == 0)
            {   player.setTicksFrozen(player.getTicksFrozen() - 1);
            }
        }
    }
}

public void onTick(TickEvent.LevelTickEvent event)
{
    if (event.level.isClientSide == level.isClientSide && event.phase == TickEvent.Phase.START)
    {
        // Temperature of waterskin weakens over time
        double waterTemp = CSMath.blend(itemTemp, itemTemp / 5, tick, 20, 100);
        double effectAmount = waterTemp * (ConfigSettings.WATERSKIN_CONSUME_STRENGTH.get() / 50d);
        double wetnessTemp = 0.05 * CSMath.sign(waterTemp+0.01);

        // Move the box down at the speed of gravity
        aabb = aabb.move(0, -acceleration, 0);

        // If there's ground, stop
        BlockPos pos = BlockPos.containing(aabb.minX, aabb.minY, aabb.minZ);
        if (WorldHelper.isSpreadBlocked(level, chunk.getBlockState(pos), pos, Direction.DOWN, Direction.DOWN))
        {   MinecraftForge.EVENT_BUS.unregister(this);
            return;
        }

        // Apply the waterskin modifier to all entities in the box
        WorldHelper.getEntitiesOfClass(Player.class, level, aabb, e -> true).forEach(player ->
        {
            if (!affectedPlayers.contains(player))
            {   // Apply the effect and store the player
                Temperature.addModifier(player, new WaterskinTempModifier(effectAmount).expires(0), Temperature.Trait.CORE, Placement.LAST);
                Temperature.replaceOrAddModifier(player, new WaterTempModifier(wetnessTemp).tickRate(5), Temperature.Trait.WORLD, Matcher.SAME_CLASS);
                affectedPlayers.add(player);
            }
        });

        // Increase the speed of the box
        acceleration += 0.0052;
        tick++;

        // Expire after 5 seconds
        if (tick > 100)
        {   MinecraftForge.EVENT_BUS.unregister(this);
        }
    }
}

public static boolean performPourAction(ItemStack stack, LivingEntity entity, InteractionHand hand)
{
    if (!(entity instanceof Player player && stack.is(ModItems.FILLED_WATERSKIN))) return false;

    // Play empty sound
    if (!player.level().isClientSide)
    {
        double temperature = stack.getOrCreateTag().getDouble(FilledWaterskinItem.NBT_TEMPERATURE);
        double wetnessTemp = 0.05 * CSMath.sign(temperature == 0 ? 1 : temperature);
        // Replace or add water temp modifier
        Placement modPlacement = Placement.of(Mode.REPLACE, Order.FIRST, mod -> mod instanceof WaterTempModifier).orElse(Placement.LAST);
        Temperature.addModifier(player, new WaterTempModifier(wetnessTemp).tickRate(5), Temperature.Trait.WORLD, modPlacement);

        WorldHelper.playEntitySound(ModSounds.WATERSKIN_POUR, player, player.getSoundSource(), 2f, (float) ((Math.random() / 5) + 0.9));
    }

    consumeWaterskin(stack, player, hand);
    MinecraftForge.EVENT_BUS.post(new LivingEntityUseItemEvent.Finish(player, stack, 1, stack.getCraftingRemainingItem()));
    player.swing(hand, true);

    // spawn falling water particles
    Random rand = new Random();
    for (int i = 0; i < 6; i++)
    {
        TaskScheduler.scheduleServer(() ->
        {
            ParticleBatchMessage particleBatch = new ParticleBatchMessage(2);
            for (int p = 0; p < 10; p++)
            {
                AABB playerBB = player.getDimensions(player.getPose()).makeBoundingBox(player.position()).inflate(0.2);
                particleBatch.addParticle(ParticleTypes.FALLING_WATER,
                                          Mth.lerp(rand.nextFloat(), playerBB.minX, playerBB.maxX),
                                          playerBB.maxY,
                                          Mth.lerp(rand.nextFloat(), playerBB.minZ, playerBB.maxZ),
                                          0.3, 0.3, 0.3);
            }
            particleBatch.sendEntity(player);
        }, i);
    }
    player.getCooldowns().addCooldown(ModItems.FILLED_WATERSKIN, 10);
    player.getCooldowns().addCooldown(ModItems.WATERSKIN, 10);

    return true;
}

private void handleBlink(ServerPlayer player, ItemStack stack, boolean showFuel) {
    if (!player.getAbilities().instabuild) {
        if (player.getCooldowns().isOnCooldown(stack.getItem())) {
            return;
        }
        int blinkFuel = getFuel(stack);
        if (blinkFuel <= 0) {
            if (!useFuel(stack, player)) {
                messageUser(player, Component.translatable("dislocate.draconicevolution.no_fuel").withStyle(ChatFormatting.RED));
                return;
            } else {
                blinkFuel = DEConfig.dislocatorBlinksPerPearl;
            }
        }

        blinkFuel--;
        setFuel(stack, blinkFuel);
        if (showFuel) {
            player.displayClientMessage(Component.translatable("dislocate.draconicevolution.teleport_fuel").append(" " + getFuel(stack)).withStyle(ChatFormatting.WHITE), true);
        }
        player.getCooldowns().addCooldown(stack.getItem(), 5);
    }

    Vec3 playerVec = player.getEyePosition(1);
    double range = DEConfig.dislocatorBlinkRange;
    Vec3 endVec = playerVec.add(player.getLookAngle().multiply(range, range, range));
    ClipContext context = new ClipContext(playerVec, endVec, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, player);
    BlockHitResult result = player.level().clip(context);

    player.level().playSound(null, playerVec.x, playerVec.y, playerVec.z, DESounds.BLINK.get(), SoundSource.PLAYERS, 1F, 1F);

    DraconicNetwork.sendBlinkEffect(player, (float) (playerVec.distanceTo(endVec) / range));

    if (result.getType() == HitResult.Type.MISS) {
        if (player.isFallFlying()) { //Maintain momentum if elytra flying
            player.connection.teleport(endVec.x, endVec.y, endVec.z, player.getYRot(), player.getXRot(), Sets.newHashSet(RelativeMovement.X, RelativeMovement.Y, RelativeMovement.Z));
            player.setYHeadRot(player.getYRot());
        } else {
            TeleportUtils.teleportEntity(player, player.level().dimension(), endVec.x, endVec.y, endVec.z);
        }
    } else {
        BlockPos pos = result.getBlockPos().relative(result.getDirection());
        Vec3D vec = new Vec3D(pos).add(0.5, 0, 0.5);
        switch (result.getDirection()) {
            case DOWN:
            case UP:
                break;
            default:
                if (player.level().getBlockState(pos.below()).isPathfindable(PathComputationType.AIR)) {
                    vec.y -= 1;
                }
        }
        TeleportUtils.teleportEntity(player, player.level().dimension(), vec.x, vec.y, vec.z);
    }

    player.level().playSound(null, player.getX(), player.getY(), player.getZ(), DESounds.BLINK.get(), SoundSource.PLAYERS, 1F, 1F);

}

public void inventoryTick(ItemStack stack, Level level, Entity entity, int itemSlot, boolean isSelected)
{
    if (!level.isClientSide && entity instanceof LivingEntity living && living.tickCount % 5 == 0)
    {
        boolean shouldBeOn = false;
        try
        {
            if (!(isSelected || living.getOffhandItem() == stack || CompatManager.Curios.hasCurio(living, stack)))
            {   return;
            }
            double max = Temperature.get(living, Temperature.Trait.BURNING_POINT);

            double temp = Temperature.getModifier(living, Temperature.Trait.WORLD, SoulLampTempModifier.class)
                          .map(mod -> mod.getLastInput(Temperature.Trait.WORLD)).orElseGet(() -> Temperature.get(living, Temperature.Trait.WORLD));

            // Is in valid dimension
            if ((ConfigSettings.LAMP_DIMENSIONS.get(level.registryAccess()).contains(level.dimensionType()))
            // Is world temp more than max
            && temp > max && getFuel(stack) > 0)
            {
                shouldBeOn = true;
                // Drain fuel
                if (!(living instanceof Player player && player.isCreative() || living.isSpectator()))
                {   addFuel(stack, -0.005 * CSMath.clamp(temp - max, 1, 3));
                }

                // Affect nearby players
                double radius = 5d;
                AABB bb = new AABB(living.getX() - radius, living.getY() + (living.getBbHeight() / 2) - radius, living.getZ() - radius,
                                   living.getX() + radius, living.getY() + (living.getBbHeight() / 2) + radius, living.getZ() + radius);

                if (Math.random() < 0.6)
                {
                    AABB bb2 = bb.inflate(-3);
                    double x = bb2.minX + (bb2.maxX - bb2.minX) * Math.random();
                    double y = bb2.minY + (bb2.maxY - bb2.minY) * Math.random();
                    double z = bb2.minZ + (bb2.maxZ - bb2.minZ) * Math.random();
                    double xSpeed = (Math.random() - 0.5) * 0.02;
                    double zSpeed = (Math.random() - 0.5) * 0.02;
                    new ParticleBatchMessage(0).addParticle(ParticleTypes.SOUL_FIRE_FLAME, x, y, z, xSpeed, 0, zSpeed)
                                               .sendEntity(living);
                }

                for (LivingEntity ent : WorldHelper.getEntitiesOfClass(LivingEntity.class, level, bb, e -> true))
                {
                    if (!EntityTempManager.isTemperatureEnabled(ent))
                    {   continue;
                    }
                    // Extend modifier time if it is present
                    Optional<SoulLampTempModifier> mod = Temperature.getModifier(ent, Temperature.Trait.WORLD, SoulLampTempModifier.class);
                    if (mod.isPresent())
                    {   mod.get().setTicksExisted(0);
                    }
                    else
                    {   Temperature.replaceOrAddModifier(ent, new SoulLampTempModifier().expires(5).tickRate(5), Temperature.Trait.WORLD, Matcher.SAME_CLASS);
                    }
                }
            }
        }
        finally
        {
            // If the conditions are not met, turn off the lamp
            if (isLit(stack) != shouldBeOn)
            {
                setLit(stack, shouldBeOn);
                if (getFuel(stack) < 0.5)
                {   setFuel(stack, 0);
                }
                WorldHelper.playEntitySound(shouldBeOn ? ModSounds.SOUL_LAMP_ON : ModSounds.SOUL_LAMP_OFF, living, living.getSoundSource(), 1.5f, (float) Math.random() / 5f + 0.9f);
            }
        }
    }
}

public static void tickTemperature(LivingEvent.LivingTickEvent event)
{
    LivingEntity entity = event.getEntity();
    boolean isServer = !entity.level().isClientSide;
    if (!TEMPERATURE_ENABLED_ENTITIES.contains(entity.getType())) return;

    getTemperatureCap(entity).ifPresent(cap ->
    {
        // Tick modifiers serverside
        if (isServer)
        {   cap.tick(entity);
        }

        // Tick modifiers & removed expired
        AtomicBoolean sync = new AtomicBoolean(false);
        for (Trait trait : VALID_MODIFIER_TRAITS)
        {
            List<TempModifier> modifiers = cap.getModifiers(trait);
            for (int i = 0; i < modifiers.size(); i++)
            {
                TempModifier modifier = modifiers.get(i);
                // Tick modifier
                if (modifier.getTicksExisted() % modifier.getTickRate() == 0)
                {   modifier.tick(entity);
                }
                if (isServer)
                {
                    // Sync if the modifier is dirty
                    if (modifier.isDirty())
                    {   sync.set(true);
                        modifier.markClean();
                    }
                    // Remove expired modifiers
                    int expireTime = modifier.getExpireTime();
                    modifier.setTicksExisted(modifier.getTicksExisted() + 1);
                    if (modifier.getTicksExisted() > expireTime && expireTime != -1)
                    {
                        modifier.onRemoved(entity, trait);
                        Temperature.updateSiblingsRemove(modifiers, entity, trait, modifier);
                        modifiers.remove(i);
                        sync.set(true);
                        i--;
                    }
                }
            }
        }
        if (isServer && sync.get())
        {   Temperature.updateModifiers(entity, cap);
        }

        // Spawn particles for uninhabitable entities
        if (isServer && hasClimateData(entity))
        {
            if (entity.tickCount % 5 == 0 && entity.getRandom().nextDouble() < 0.1)
            {
                double worldTemp = cap.getTrait(Trait.WORLD);
                double entityX = entity.getX();
                double entityY = entity.getY() + entity.getBbHeight();
                double entityZ = entity.getZ();

                if (worldTemp < cap.getTrait(Trait.FREEZING_POINT))
                {
                    WorldHelper.spawnParticleBatch(entity.level(), ParticleTypesInit.MOB_COLD.get(), entityX, entityY, entityZ, 0.5, 0.5, 0.5,
                                                   entity.getRandom().nextInt(2, 4), 0);
                }
                else if (worldTemp > cap.getTrait(Trait.BURNING_POINT))
                {
                    WorldHelper.spawnParticleBatch(entity.level(), ParticleTypesInit.MOB_HOT.get(), entityX, entityY, entityZ, 0.5, 0.5, 0.5,
                                                   entity.getRandom().nextInt(2, 4), 0);
                }
            }
        }
    });
}

