}

public void onPlayerStoppedUsing(ItemStack itemStack, World worldIn, LivingEntity entityLiving, int timeLeft) {
    int chargeTicks = (int) MathUtils.clampDouble(itemStack.getUseDuration() - timeLeft, 10, 50);

    if (!worldIn.isRemote && entityLiving instanceof PlayerEntity) {
        double chargePercent = chargeTicks * 0.02; // chargeticks/50
        double energyConsumption = getEnergyUsage() * chargePercent;
        PlayerEntity player = (PlayerEntity) entityLiving;
        if (ElectricItemUtils.getPlayerEnergy(player) > energyConsumption) {
            HeatUtils.heatPlayer(player, energyConsumption / 5000F * chargePercent);
            ElectricItemUtils.drainPlayerEnergy(player, (int) energyConsumption);
            float explosiveness = (float) (applyPropertyModifiers(MPAConstants.PLASMA_CANNON_EXPLOSIVENESS) * chargePercent);
            float damagingness = (float) (applyPropertyModifiers(MPAConstants.PLASMA_CANNON_DAMAGE_AT_FULL_CHARGE) * chargePercent);
            PlasmaBallEntity plasmaBolt = new PlasmaBallEntity(worldIn, player, explosiveness, damagingness, (float) chargePercent);
            worldIn.addEntity(plasmaBolt);
        }
    }
}

public void onPlayerTickActive(PlayerEntity player, ItemStack itemStack) {
    World world = player.world;
    boolean isRaining, canRain = true;
    if (world.getGameTime() % 20 == 0) {
        canRain = !(world.getBiome(player.getPosition()).getPrecipitation() == Biome.RainType.NONE);
    }

    isRaining = canRain && (world.isRaining() || world.isThundering());
    boolean sunVisible = world.isDaytime() && !isRaining && world.canBlockSeeSky(player.getPosition().add(0, 1, 0));
    boolean moonVisible = !world.isDaytime() && !isRaining && world.canBlockSeeSky(player.getPosition().add(0, 1, 0));
    if (!world.isRemote && world.getDimensionType().hasSkyLight() && (world.getGameTime() % 80) == 0) {
        double lightLevelScaled = (world.getLightFor(LightType.SKY, player.getPosition().up()) - world.getSkylightSubtracted())/15D;
        if (sunVisible) {
            ElectricItemUtils.givePlayerEnergy(player, (int) (applyPropertyModifiers(MPAConstants.ENERGY_GENERATION_DAY) * lightLevelScaled));
        } else if (moonVisible) {
            ElectricItemUtils.givePlayerEnergy(player, (int) (applyPropertyModifiers(MPAConstants.ENERGY_GENERATION_NIGHT) * lightLevelScaled));
        }
    }
}

public void onPlayerTickActive(PlayerEntity player, @Nonnull ItemStack itemStackIn) {
    if (player.abilities.isFlying || player.isPassenger() || player.isElytraFlying() || !player.isOnGround())
        onPlayerTickInactive(player, itemStackIn);

    // really hate running this check on every tick but needed for player speed adjustments
    if (ElectricItemUtils.getPlayerEnergy(player) < ElectricItemUtils.getMaxPlayerEnergy(player)) {
        itemStackIn.getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY).ifPresent(h->{
            if(h instanceof IModularItem && !((IModularItem) h).isModuleOnline(MPARegistryNames.SPRINT_ASSIST_MODULE_REGNAME));
            // only fires if the sprint assist module isn't installed and active
            MovementManager.INSTANCE.setMovementModifier(itemStackIn, 0, player);
        });

        // server side
        if (!player.world.isRemote &&
                // every 20 ticks
                (player.world.getGameTime() % 20) == 0 &&
                // player not jumping, flying, or riding
                player.isOnGround()) {
            double distance = player.distanceWalkedModified - player.prevDistanceWalkedModified;
            ElectricItemUtils.givePlayerEnergy(player, (int) (distance * 10 * applyPropertyModifiers(MPAConstants.ENERGY_GENERATION)));
        }
    }
}

public boolean hitEntity(ItemStack itemStack, LivingEntity target, LivingEntity attacker) {
    if (attacker instanceof PlayerEntity) {
        itemStack.getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY).ifPresent(iItemHandler -> {
            if (iItemHandler instanceof IModeChangingItem) {
                ((IModeChangingItem) iItemHandler).getOnlineModuleOrEmpty(MPARegistryNames.MELEE_ASSIST_MODULE_REGNAME)
                        .getCapability(PowerModuleCapability.POWER_MODULE).ifPresent(pm->{
                    PlayerEntity player = (PlayerEntity) attacker;
                    double drain = pm.applyPropertyModifiers(MPAConstants.PUNCH_ENERGY);
                    if (ElectricItemUtils.getPlayerEnergy(player) > drain) {
                        ElectricItemUtils.drainPlayerEnergy(player, (int) drain);
                        double damage = pm.applyPropertyModifiers(MPAConstants.PUNCH_DAMAGE);
                        double knockback = pm.applyPropertyModifiers(MPAConstants.PUNCH_KNOCKBACK);
                        DamageSource damageSource = DamageSource.causePlayerDamage(player);
                        if (target.attackEntityFrom(damageSource, (float) (int) damage)) {
                            Vector3d lookVec = player.getLookVec();
                            target.addVelocity(lookVec.x * knockback, Math.abs(lookVec.y + 0.2f) * knockback, lookVec.z * knockback);
                        }
                    }
                });
            }
        });
    }
    return true;
}

    public void handleFallEvent(LivingFallEvent event) {
        if (event.getEntityLiving() instanceof PlayerEntity && event.getDistance() > 3.0) {
            PlayerEntity player = (PlayerEntity) event.getEntityLiving();
            ItemStack boots = player.getItemStackFromSlot(EquipmentSlotType.FEET);
            boots.getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY).ifPresent(iModularItem -> {
                if (!(iModularItem instanceof IModularItem)) {
                    return;
                }

                ItemStack shockAbsorbers = ((IModularItem) iModularItem).getOnlineModuleOrEmpty(MPARegistryNames.SHOCK_ABSORBER_MODULE_REGNAME);
                shockAbsorbers.getCapability(PowerModuleCapability.POWER_MODULE).ifPresent(sa -> {
                    double distanceAbsorb = event.getDistance() * sa.applyPropertyModifiers(MPAConstants.MULTIPLIER);
                    if (player.world.isRemote && MPALibSettings.useSounds()) {
                        Musique.playerSound(player, SoundDictionary.SOUND_EVENT_GUI_INSTALL, SoundCategory.PLAYERS, (float) (distanceAbsorb), (float) 1, false);
                    }
                    double drain = distanceAbsorb * sa.applyPropertyModifiers(MPAConstants.ENERGY_CONSUMPTION);
                    int avail = ElectricItemUtils.getPlayerEnergy(player);
                    if (drain < avail) {
                        ElectricItemUtils.drainPlayerEnergy(player, (int) drain);
                        event.setDistance((float) (event.getDistance() - distanceAbsorb));
//                        event.getEntityLiving().sendMessage(new TextComponentString("modified fall settings: [ damage : " + event.getDamageMultiplier() + " ], [ distance : " + event.getDistance() + " ]"));
                    }
                });
            });
        }
    }

public void onPlayerTickActive(PlayerEntity player, ItemStack chestPlate) {
    Vector3d playerHorzFacing = player.getLookVec();
    playerHorzFacing = new Vector3d(playerHorzFacing.x, 0, playerHorzFacing.z);
    playerHorzFacing.normalize();
    PlayerMovementInputWrapper.PlayerMovementInput playerInput = PlayerMovementInputWrapper.get(player);

    PlayerUtils.resetFloatKickTicks(player);
    boolean hasParachute = chestPlate.getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY)
            .map(m-> m instanceof IModularItem && ((IModularItem) m).isModuleOnline(MPARegistryNames.PARACHUTE_MODULE_REGNAME)).orElse(false);

    if (playerInput.sneakKey && player.getMotion().y < 0 && (!hasParachute || playerInput.moveForward > 0)) {
        Vector3d motion = player.getMotion();
        if (motion.y < -0.1) {
            double motionYchange = Math.min(0.08, -0.1 - motion.y);

            player.setMotion(motion.add(
                    playerHorzFacing.x * motionYchange,
                    motionYchange,
                    playerHorzFacing.z * motionYchange
            ));

            // sprinting speed
            player.jumpMovementFactor += 0.03f;
        }
    }
}

public void onPlayerTickActive(PlayerEntity player, @Nonnull ItemStack itemStack) {
    if (player.abilities.isFlying || player.isPassenger() || player.isElytraFlying())
        onPlayerTickInactive(player, itemStack);

    double horzMovement = player.distanceWalkedModified - player.prevDistanceWalkedModified;
    double totalEnergy = ElectricItemUtils.getPlayerEnergy(player);
    if (horzMovement > 0) { // stop doing drain calculations when player hasn't moved
        if (player.isSprinting()) {
            double exhaustion = Math.round(horzMovement * 100.0F) * 0.01;
            double sprintCost = applyPropertyModifiers(MPAConstants.SPRINT_ENERGY_CONSUMPTION);
            if (sprintCost < totalEnergy) {
                double sprintMultiplier = applyPropertyModifiers(MPAConstants.SPRINT_SPEED_MULTIPLIER);
                double exhaustionComp = applyPropertyModifiers(MPAConstants.FOOD_COMPENSATION);
                ElectricItemUtils.drainPlayerEnergy(player, (int) (sprintCost * horzMovement * 5));
                MovementManager.INSTANCE.setMovementModifier(itemStack, sprintMultiplier, player);
                player.getFoodStats().addExhaustion((float) (-0.01 * exhaustion * exhaustionComp));
                player.jumpMovementFactor = player.getAIMoveSpeed() * .2f;
            }
        } else {
            double cost = applyPropertyModifiers(MPAConstants.WALKING_ENERGY_CONSUMPTION);
            if (cost < totalEnergy) {
                double walkMultiplier = applyPropertyModifiers(MPAConstants.WALKING_SPEED_MULTIPLIER);
                ElectricItemUtils.drainPlayerEnergy(player, (int) (cost * horzMovement * 5));
                MovementManager.INSTANCE.setMovementModifier(itemStack, walkMultiplier, player);
                player.jumpMovementFactor = player.getAIMoveSpeed() * .2f;
            }
        }
    }
}

public void handleLivingJumpEvent(LivingJumpEvent event) {
    if (event.getEntityLiving() instanceof PlayerEntity) {
        PlayerEntity player = (PlayerEntity) event.getEntityLiving();
        player.getItemStackFromSlot(EquipmentSlotType.LEGS).getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY).ifPresent(iModularItem -> {
            if (!(iModularItem instanceof IModularItem)) {
                return;
            }

            ((IModularItem) iModularItem).getOnlineModuleOrEmpty(MPARegistryNames.JUMP_ASSIST_MODULE_REGNAME).getCapability(PowerModuleCapability.POWER_MODULE).ifPresent(jumper -> {
                double jumpAssist = jumper.applyPropertyModifiers(MPAConstants.MULTIPLIER) * 2;
                double drain = jumper.applyPropertyModifiers(MPAConstants.ENERGY_CONSUMPTION);
                int avail = ElectricItemUtils.getPlayerEnergy(player);
                if ((player.world.isRemote()) && MPALibSettings.useSounds()) {
                    Musique.playerSound(player, MPASoundDictionary.JUMP_ASSIST, SoundCategory.PLAYERS, (float) (jumpAssist / 8.0), (float) 1, false);
                }

                if (drain < avail) {
                    ElectricItemUtils.drainPlayerEnergy(player, (int) drain);
                    setPlayerJumpTicks(player, jumpAssist);
                    double jumpCompensationRatio = jumper.applyPropertyModifiers(MPAConstants.FOOD_COMPENSATION);
                    if (player.isSprinting()) {
                        player.getFoodStats().addExhaustion((float) (-0.2F * jumpCompensationRatio));
                    } else {
                        player.getFoodStats().addExhaustion((float) (-0.05F * jumpCompensationRatio));
                    }
                }
            });
        });
    }
}

public void onPlayerTickActive(PlayerEntity player, ItemStack item) {
    if (player.isInWater())
        return;

    ItemStack helmet = player.getItemStackFromSlot(EquipmentSlotType.HEAD);
    boolean hasFlightControl = helmet.getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY).map(m->
            m instanceof IModularItem && ((IModularItem) m).isModuleOnline(MPARegistryNames.FLIGHT_CONTROL_MODULE_REGNAME)).orElse(false);

    double jetEnergy = applyPropertyModifiers(MPAConstants.ENERGY_CONSUMPTION);
    double thrust = applyPropertyModifiers(MPAConstants.JETBOOTS_THRUST);

    PlayerMovementInputWrapper.PlayerMovementInput playerInput = PlayerMovementInputWrapper.get(player);
    // if player has enough energy to fly
    if (jetEnergy < ElectricItemUtils.getPlayerEnergy(player)) {
        if (hasFlightControl && thrust > 0) {
            thrust = MovementManager.INSTANCE.thrust(player, thrust, true);
            if ((player.world.isRemote) && MPALibSettings.useSounds()) {
                Musique.playerSound(player, MPASoundDictionary.JETBOOTS, SoundCategory.PLAYERS, (float) (thrust * 12.5), 1.0f, true);
            }
            ElectricItemUtils.drainPlayerEnergy(player, (int) (thrust * jetEnergy));
        } else if (playerInput.jumpKey && player.getMotion().y < 0.5) {
            thrust = MovementManager.INSTANCE.thrust(player, thrust, false);
            if ((player.world.isRemote) && MPALibSettings.useSounds()) {
                Musique.playerSound(player, MPASoundDictionary.JETBOOTS, SoundCategory.PLAYERS, (float) (thrust * 12.5), 1.0f, true);
            }
            ElectricItemUtils.drainPlayerEnergy(player, (int) (thrust * jetEnergy));
        } else {
            if ((player.world.isRemote) && MPALibSettings.useSounds()) {
                Musique.stopPlayerSound(player, MPASoundDictionary.JETBOOTS);
            }
        }
    } else {
        if (player.world.isRemote && MPALibSettings.useSounds()) {
            Musique.stopPlayerSound(player, MPASoundDictionary.JETBOOTS);
        }
    }
}

public void onPlayerTickActive(PlayerEntity player, ItemStack item) {
