            public void onPlayerTickActive(PlayerEntity player, ItemStack itemX) {
                float foodLevel = getFoodLevel(module);
                float saturationLevel = getSaturationLevel(module);
                IInventory inv = player.inventory;
                double eatingEnergyConsumption = applyPropertyModifiers(MPAConstants.ENERGY_CONSUMPTION);
                double efficiency = applyPropertyModifiers(MPAConstants.EATING_EFFICIENCY);

                FoodStats foodStats = player.getFoodStats();
                int foodNeeded = 20 - foodStats.getFoodLevel();
                float saturationNeeded = 20 - foodStats.getSaturationLevel();

                // this consumes all food in the player's inventory and stores the stats in a buffer
//        if (MPASettings::getModuleConfig.useOldAutoFeeder()) { // FIXME!!!!!
                if (true) {

                    for (int i = 0; i < inv.getSizeInventory(); i++) {
                        ItemStack stack = inv.getStackInSlot(i);
                        if (stack.isFood()) {
                            for (int a = 0; a < stack.getCount(); a++) {
                                foodLevel += stack.getItem().getFood().getHealing() * efficiency / 100.0F;
                                //  copied this from FoodStats.addStats()
                                saturationLevel += Math.min(stack.getItem().getFood().getHealing() * stack.getItem().getFood().getSaturation() * 2.0F, 20F) * efficiency / 100.0;
                            }
                            player.inventory.setInventorySlotContents(i, ItemStack.EMPTY);
                        }
                    }
                    setFoodLevel(module, foodLevel);
                    setSaturationLevel(module, saturationLevel);
                } else {
                    for (int i = 0; i < inv.getSizeInventory(); i++) {
                        if (foodNeeded < foodLevel)
                            break;
                        ItemStack stack = inv.getStackInSlot(i);
                        if (stack.isFood()) {
                            while (true) {
                                if (foodNeeded > foodLevel) {
                                    foodLevel += stack.getItem().getFood().getHealing() * efficiency / 100.0;
                                    //  copied this from FoodStats.addStats()
                                    saturationLevel += Math.min(stack.getItem().getFood().getHealing() * stack.getItem().getFood().getSaturation() * 2.0D, 20D) * efficiency / 100.0;
                                    stack.setCount(stack.getCount() - 1);
                                    if (stack.getCount() == 0) {
                                        player.inventory.setInventorySlotContents(i, ItemStack.EMPTY);
                                        break;
                                    } else
                                        player.inventory.setInventorySlotContents(i, stack);
                                } else
                                    break;
                            }
                        }
                    }
                    setFoodLevel(module, foodLevel);
                    setSaturationLevel(module, saturationLevel);
                }

                CompoundNBT foodStatNBT = new CompoundNBT();

                // only consume saturation if food is consumed. This keeps the food buffer from overloading with food while the
                //   saturation buffer drains completely.
                if (foodNeeded > 0 && getFoodLevel(module) >= 1) {
                    int foodUsed = 0;
                    // if buffer has enough to fill player stat
                    if (getFoodLevel(module) >= foodNeeded && foodNeeded * eatingEnergyConsumption * 0.5 < ElectricItemUtils.getPlayerEnergy(player)) {
                        foodUsed = foodNeeded;
                        // if buffer has some but not enough to fill the player stat
                    } else if ((foodNeeded - getFoodLevel(module)) > 0 && getFoodLevel(module) * eatingEnergyConsumption * 0.5 < ElectricItemUtils.getPlayerEnergy(player)) {
                        foodUsed = (int) getFoodLevel(module);
                        // last resort where using just 1 unit from buffer
                    } else if (eatingEnergyConsumption * 0.5 < ElectricItemUtils.getPlayerEnergy(player) && getFoodLevel(module) >= 1) {
                        foodUsed = 1;
                    }
                    if (foodUsed > 0) {
                        // populate the tag with the nbt data
                        foodStats.write(foodStatNBT);
                        foodStatNBT.putInt("foodLevel", foodStatNBT.getInt("foodLevel") + foodUsed);
                        // put the values back into foodstats
                        foodStats.read(foodStatNBT);
                        // update getValue stored in buffer
                        setFoodLevel(module, getFoodLevel(module) - foodUsed);
                        // split the cost between using food and using saturation
                        ElectricItemUtils.drainPlayerEnergy(player, (int) (eatingEnergyConsumption * 0.5 * foodUsed));

                        if (saturationNeeded >= 1.0D) {
                            // using int for better precision
                            int saturationUsed = 0;
                            // if buffer has enough to fill player stat
                            if (getSaturationLevel(module) >= saturationNeeded && saturationNeeded * eatingEnergyConsumption * 0.5 < ElectricItemUtils.getPlayerEnergy(player)) {
                                saturationUsed = (int) saturationNeeded;
                                // if buffer has some but not enough to fill the player stat
                            } else if ((saturationNeeded - getSaturationLevel(module)) > 0 && getSaturationLevel(module) * eatingEnergyConsumption * 0.5 < ElectricItemUtils.getPlayerEnergy(player)) {
                                saturationUsed = (int) getSaturationLevel(module);
                                // last resort where using just 1 unit from buffer
                            } else if (eatingEnergyConsumption * 0.5 < ElectricItemUtils.getPlayerEnergy(player) && getSaturationLevel(module) >= 1) {
                                saturationUsed = 1;
                            }

                            if (saturationUsed > 0) {
                                // populate the tag with the nbt data
                                foodStats.write(foodStatNBT);
                                foodStatNBT.putFloat("foodSaturationLevel", foodStatNBT.getFloat("foodSaturationLevel") + saturationUsed);
                                // put the values back into foodstats
                                foodStats.read(foodStatNBT);
                                // update getValue stored in buffer
                                setSaturationLevel(module, getSaturationLevel(module) - saturationUsed);
                                // split the cost between using food and using saturation
                                ElectricItemUtils.drainPlayerEnergy(player, (int) (eatingEnergyConsumption * 0.5 * saturationUsed));
                            }
                        }
                    }
                }
            }

    public double thrust(PlayerEntity player, double thrust, boolean flightControl) {
        PlayerMovementInputWrapper.PlayerMovementInput playerInput = PlayerMovementInputWrapper.get(player);
        double thrustUsed = 0;
        if (flightControl) {
            Vector3d desiredDirection = player.getLookVec().normalize();
            double strafeX = desiredDirection.z;
            double strafeZ = -desiredDirection.x;
            ItemStack helm = player.getItemStackFromSlot(EquipmentSlotType.HEAD);
            double flightVerticality = helm.getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY).map(iModularItem -> {
                if (iModularItem instanceof IModularItem) {
                    return ((IModularItem) iModularItem)
                            .getOnlineModuleOrEmpty(MPARegistryNames.FLIGHT_CONTROL_MODULE_REGNAME)
                            .getCapability(PowerModuleCapability.POWER_MODULE)
                            .map(pm -> pm.applyPropertyModifiers(MPAConstants.FLIGHT_VERTICALITY)).orElse(0D);
                } else {
                    return 0D;
                }
            }).orElse(0D);

            desiredDirection = new Vector3d(
                    (desiredDirection.x * Math.signum(playerInput.moveForward) + strafeX * Math.signum(playerInput.moveStrafe)),
                    (flightVerticality * desiredDirection.y * Math.signum(playerInput.moveForward) + (playerInput.jumpKey ? 1 : 0) - (playerInput.downKey ? 1 : 0)),
                    (desiredDirection.z * Math.signum(playerInput.moveForward) + strafeZ * Math.signum(playerInput.moveStrafe)));

            desiredDirection = desiredDirection.normalize();

            // Brakes
            if (player.getMotion().y < 0 && desiredDirection.y >= 0) {
                if (-player.getMotion().y > thrust) {
                    player.setMotion(player.getMotion().add(0, thrust,0));
                    thrustUsed += thrust;
                    thrust = 0;
                } else {
                    thrust -= player.getMotion().y;
                    thrustUsed += player.getMotion().y;
                    player.setMotion(player.getMotion().x, 0, player.getMotion().z);
                }
            }
            if (player.getMotion().y < -1) {
                thrust += 1 + player.getMotion().y;
                thrustUsed -= 1 + player.getMotion().y;
                player.setMotion(player.getMotion().x, -1, player.getMotion().z);
            }
            if (Math.abs(player.getMotion().x) > 0 && desiredDirection.length() == 0) {
                if (Math.abs(player.getMotion().x) > thrust) {
                    player.setMotion(player.getMotion().add(
                            - Math.signum(player.getMotion().x) * thrust, 0, 0));
                    thrustUsed += thrust;
                    thrust = 0;
                } else {
                    thrust -= Math.abs(player.getMotion().x);
                    thrustUsed += Math.abs(player.getMotion().x);
                    player.setMotion(0, player.getMotion().y, player.getMotion().z);
                }
            }
            if (Math.abs(player.getMotion().z) > 0 && desiredDirection.length() == 0) {
                if (Math.abs(player.getMotion().z) > thrust) {
                    player.setMotion(
                            player.getMotion().add(
                                    0, 0, Math.signum(player.getMotion().z) * thrust
                            )

                    );
                    thrustUsed += thrust;
                    thrust = 0;
                } else {
                    thrustUsed += Math.abs(player.getMotion().z);
                    thrust -= Math.abs(player.getMotion().z);
                    player.setMotion(player.getMotion().x, player.getMotion().y, 0);
                }
            }

            // Thrusting, finally :V
            player.setMotion(player.getMotion().add(
                    thrust * desiredDirection.x,
                    thrust * desiredDirection.y,
                    thrust * desiredDirection.z
            ));
            thrustUsed += thrust;

        } else {
            Vector3d playerHorzFacing = player.getLookVec();
            playerHorzFacing = new Vector3d(playerHorzFacing.x, 0, playerHorzFacing.z);
            playerHorzFacing.normalize();
            if (playerInput.moveForward == 0) {
                player.setMotion(player.getMotion().add(0, thrust, 0));
            } else {
                player.setMotion(player.getMotion().add(
                        playerHorzFacing.x * thrust / root2 * Math.signum(playerInput.moveForward),
                        thrust / root2,
                        playerHorzFacing.z * thrust / root2 * Math.signum(playerInput.moveForward)
                ));
            }
            thrustUsed += thrust;
        }

        // Slow the player if they are going too fast
        double horzm2 = player.getMotion().x * player.getMotion().x + player.getMotion().z * player.getMotion().z;

        // currently comes out to 0.0625
        double horizontalLimit = MPASettings.getMaxFlyingSpeed() * MPASettings.getMaxFlyingSpeed() / 400;

//        double playerVelocity = Math.abs(player.getMotion().x) + Math.abs(player.getMotion().y) + Math.abs(player.getMotion().z);

        if (playerInput.sneakKey && horizontalLimit > 0.05) {
            horizontalLimit = 0.05;
        }

        if (horzm2 > horizontalLimit) {
            double ratio = Math.sqrt(horizontalLimit / horzm2);
            player.setMotion(
                    player.getMotion().x * ratio,
                    player.getMotion().y,
                    player.getMotion().z * ratio);
        }
        PlayerUtils.resetFloatKickTicks(player);
        return thrustUsed;
    }

public void cycleMode(ItemStack stack, EntityPlayer player, int dMode) {
    List<String> modes = this.getValidModes(stack);
    if (modes.size() > 0) {
        int newindex = clampMode(modes.indexOf(this.getActiveMode(stack)) + dMode, modes.size());
        String newmode = (String)modes.get(newindex);
        this.setActiveMode(stack, newmode);
        PacketSender.sendToServer(new MusePacketModeChangeRequest(player, newmode, player.inventory.currentItem));
    }
}

public static double computeModularProperty(ItemStack stack, String propertyName) {
    double propertyValue = 0;
    NBTTagCompound itemTag = MuseItemTag.getMuseItemTag(stack);
    for (IPowerModule module : moduleList) {
        if (itemHasActiveModule(stack, module.getDataName())) {
            propertyValue = module.applyPropertyModifiers(itemTag, propertyName, propertyValue);
        }
    }
    return propertyValue;
}

